  const classId = req.params.id;
  const { memberId } = req.body;

  if (!memberId) {
    return res.status(400).json({ error: "Member ID is required" });
  }

  const cls = classes.find(c => c.id === classId);

  if (!cls) {
    return res.status(404).json({ error: "Class not found" });
  }

  // Check if class is full
  const currentEnrollments = enrollments.filter(e => e.classId === classId);

  if (currentEnrollments.length >= cls.maxEnrollment) {
    return res.status(400).json({ error: "Class is full" });
  }

  // Check if member is already enrolled
  const existingEnrollment = enrollments.find(e => e.classId === classId && e.memberId === memberId);

  if (existingEnrollment) {
    return res.status(400).json({ error: "Member already enrolled" });
  }

  const newEnrollment = { classId, memberId };
  enrollments.push(newEnrollment);

  res.status(201).json(newEnrollment);
});

