import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

const SESSION_TIMEOUT = 30 * 60 * 1000; // 30 minutes

interface SessionData {
  userId: string;
  sessionId: string;
  createdAt: number;
}

// In-memory session store (in production, use Redis or database)
const activeSessions = new Map<string, SessionData>();

function getSessionIdFromHeader(authHeader: string | undefined): string | null {
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    return null;
  }
  return authHeader.substring(7);
}

function verifyTokenSignature(token: string, secret: string): boolean {
  const [payload, signature] = token.split(".");
  if (!payload || !signature) return false;

  const expectedSignature = createHmac("sha256", secret)
    .update(payload)
    .digest("base64url");

  try {
    const signatureBuffer = Buffer.from(signature, "base64url");
    const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");
    return timingSafeEqual(signatureBuffer, expectedSignatureBuffer);
  } catch {
    return false;
  }
}

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only handle POST requests to /login endpoint
  if (req.method !== "POST" || req.path !== "/login") {
    next();
    return;
  }

  const jwtSecret = process.env.JWT_SECRET;
  if (!jwtSecret) {
    res.status(500).json({ error: "Server configuration error" });
    return;
  }

  const authHeader = req.header("Authorization");
  const sessionId = getSessionIdFromHeader(authHeader);

  if (!sessionId) {
    res.status(401).json({ error: "Missing session token" });
    return;
  }

  const session = activeSessions.get(sessionId);
  if (!session) {
    res.status(401).json({ error: "Invalid session token" });
    return;
  }

  // Check if session has timed out
  if (Date.now() - session.createdAt > SESSION_TIMEOUT) {
    activeSessions.delete(sessionId);
    res.status(401).json({ error: "Session expired" });
    return;
  }

  // Verify token signature
  const token = sessionId;
  if (!verifyTokenSignature(token, jwtSecret)) {
    res.status(401).json({ error: "Invalid token signature" });
    return;
  }

  // Update session timestamp
  session.createdAt = Date.now();
  activeSessions.set(sessionId, session);

  next();
}

