import { useEffect, useState } from "react";

interface ClassSchedule {
  id: number;
  className: string;
  instructor: string;
  date: string;
  time: string;
  duration: number;
  maxParticipants: number;
  registeredParticipants: number;
}

export function ClassScheduling() {
  const [classes, setClasses] = useState<ClassSchedule[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchClasses();
  }, []);

  const fetchClasses = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/classes');
      if (!response.ok) {
        throw new Error('Failed to fetch classes');
      }
      const data = await response.json();
      setClasses(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  const handleRegister = async (classId: number) => {
    try {
      const response = await fetch(`/api/classes/${classId}/register`, {
        method: 'POST',
      });
      if (!response.ok) {
        throw new Error('Failed to register for class');
      }
      // Refresh the class list after registration
      fetchClasses();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>{error}</div>;
  }

  if (classes.length === 0) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>No classes available.</div>;
  }

  return (
    <div style={{ maxWidth: '800px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1 style={{ textAlign: 'center' }}>Fitness Classes</h1>
      <div style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
        {classes.map((cls) => (
          <div 
            key={cls.id} 
            style={{ 
              border: '1px solid #ccc', 
              borderRadius: '8px', 
              padding: '15px', 
              display: 'flex', 
              justifyContent: 'space-between', 
              alignItems: 'center'
            }}
          >
            <div>
              <h3>{cls.className}</h3>
              <p>Instructor: {cls.instructor}</p>
              <p>Date: {cls.date} at {cls.time}</p>
              <p>Duration: {cls.duration} minutes</p>
              <p>Participants: {cls.registeredParticipants}/{cls.maxParticipants}</p>
            </div>
            <button 
              onClick={() => handleRegister(cls.id)}
              disabled={cls.registeredParticipants >= cls.maxParticipants}
              style={{ 
                backgroundColor: '#4CAF50', 
                color: 'white', 
                border: 'none', 
                borderRadius: '4px', 
                padding: '10px 15px', 
                cursor: 'pointer', 
                fontSize: '16px'
              }}
            >
              {cls.registeredParticipants >= cls.maxParticipants ? 'Full' : 'Register'}
            </button>
          </div>
        ))}
      </div>
    </div>
  );
}

