import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock database functions - in a real app these would connect to a database
const mockDatabase = {
  getRooms: async () => [
    { id: 1, type: "single", price: 100, available: true },
    { id: 2, type: "double", price: 150, available: true },
    { id: 3, type: "suite", price: 300, available: false }
  ],
  getRoomById: async (id: number) => {
    const rooms = await mockDatabase.getRooms();
    return rooms.find(room => room.id === id) || null;
  },
  createRoom: async (roomData: { type: string; price: number }) => {
    const rooms = await mockDatabase.getRooms();
    const newRoom = {
      id: rooms.length + 1,
      type: roomData.type,
      price: roomData.price,
      available: true
    };
    return newRoom;
  },
  updateRoom: async (id: number, roomData: Partial<{ type: string; price: number; available: boolean }>) => {
    const rooms = await mockDatabase.getRooms();
    const roomIndex = rooms.findIndex(room => room.id === id);
    if (roomIndex === -1) return null;

    const updatedRoom = { ...rooms[roomIndex], ...roomData };
    return updatedRoom;
  },
  deleteRoom: async (id: number) => {
    const rooms = await mockDatabase.getRooms();
    const roomIndex = rooms.findIndex(room => room.id === id);
    if (roomIndex === -1) return false;

    rooms.splice(roomIndex, 1);
    return true;
  }
};

// GET /rooms - List all rooms
router.get("/rooms", async (req: Request, res: Response) => {
  try {
    const rooms = await mockDatabase.getRooms();
    return res.json(rooms);
  } catch (error) {
    return res.status(500).json({ error: "Internal server error" });
  }
});

// GET /rooms/:id - Get a specific room by ID
