  try {
    const { type, price } = req.body;

    if (!type || typeof price !== "number") {
      return res.status(400).json({ error: "Invalid room data. Type required and price must be a number." });
    }

    const newRoom = await mockDatabase.createRoom({ type, price });
    return res.status(201).json(newRoom);
