    const roomData: Partial<{ type: string; price: number; available: boolean }> = {};

    if (type !== undefined) roomData.type = type;
    if (price !== undefined) roomData.price = price;
    if (available !== undefined) roomData.available = available;

    const updatedRoom = await mockDatabase.updateRoom(id, roomData);

    if (!updatedRoom) {
      return res.status(404).json({ error: "Room not found" });
    }

    return res.json(updatedRoom);
