import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";
import jwt from "jsonwebtoken";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process POST requests to /login endpoint
  if (!(req.method === "POST" && req.path === "/login")) {
    next();
    return;
  }

  const authHeader = req.headers.authorization;

  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    return res.status(401).json({ error: "Missing or invalid authorization header" });
  }

  const token = authHeader.substring(7);

  try {
    // Verify token signature using HMAC-SHA256
    const secret = process.env.JWT_SECRET;
    if (!secret) {
      return res.status(500).json({ error: "JWT secret not configured" });
    }

    const payload = jwt.decode(token);
    if (!payload || typeof payload !== "object") {
      return res.status(401).json({ error: "Invalid token format" });
    }

    const expectedSignature = createHmac("sha256", secret)
      .update(token.split(".")[0] + "." + token.split(".")[1])
      .digest();

    const actualSignature = Buffer.from(token.split(".")[2], "base64");

    if (actualSignature.length !== expectedSignature.length) {
      return res.status(401).json({ error: "Invalid token signature" });
    }

    const isEqual = timingSafeEqual(expectedSignature, actualSignature);
    if (!isEqual) {
      return res.status(401).json({ error: "Invalid token signature" });
    }

    // If we get here, the token is valid
    next();
  } catch (err) {
    return res.status(401).json({ error: "Token verification failed" });
  }
}

import type { Request, Response, NextFunction } from "express";
import { createHash, scrypt, randomBytes, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // This middleware runs on every request, but we only process password hashing for POST /auth/register
  if (req.method !== "POST" || req.path !== "/auth/register") {
    next();
    return;
  }

  // Check if password exists in request body
  if (!req.body || typeof req.body.password !== "string") {
    next();
    return;
  }

  const password = req.body.password;

  // Generate salt
  const salt = randomBytes(16).toString("hex");

  // Hash password with scrypt
  scrypt(password, salt, 64, (err, derivedKey) => {
    if (err) {
      next(err);
      return;
    }

    // Store hashed password and salt
    req.body.hashedPassword = derivedKey.toString("hex");
    req.body.salt = salt;

    next();
  });
}

import type { Request, Response, NextFunction } from "express";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply role-based access control to specific routes
  const protectedPaths = ["/admin", "/staff"];
  const isProtectedPath = protectedPaths.some(path =>
    req.path.startsWith(path)
  );

  // Skip validation for non-protected paths
  if (!isProtectedPath) {
    next();
    return;
  }

  // For protected paths, check if user has proper role
  // This is a simplified example - in practice, you'd extract
  // user role from a JWT or session
  const userRole = req.headers["x-user-role"] as string || "guest";

  // Define role hierarchy
  const allowedRoles = {
    "/admin": ["admin"],
    "/staff": ["admin", "staff"]
  };

  // Check if path requires specific role
  let requiredRoles: string[] = [];
  for (const [path, roles] of Object.entries(allowedRoles)) {
    if (req.path.startsWith(path)) {
      requiredRoles = roles;
      break;
    }
  }

  // If no specific role required, allow guest access
  if (requiredRoles.length === 0) {
    next();
    return;
  }

  // Check if user has required role
  if (requiredRoles.includes(userRole)) {
    next();
  } else {
    res.status(403).json({ message: "Access denied" });
  }
}

import type { Request, Response, NextFunction } from "express";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Skip validation for GET requests without a body
  if (req.method === "GET" && !req.body) {
    return next();
  }

  // Only validate POST, PUT, PATCH requests
  if (!['POST', 'PUT', 'PATCH'].includes(req.method)) {
    return next();
  }

  // Validate request body structure
  if (req.body) {
    try {
      // Check if body is a valid JSON object
      if (typeof req.body !== 'object' || req.body === null) {
        return res.status(400).json({ error: "Invalid input format" });
      }

      // Sanitize and validate fields
      const sanitizedBody = sanitizeInput(req.body);

      // If sanitization changed the input, update req.body
      if (sanitizedBody !== req.body) {
        req.body = sanitizedBody;
      }
    } catch (error) {
      return res.status(400).json({ error: "Invalid input format" });
    }
  }

  next();
}

function sanitizeInput(input: any): any {
  if (input === null || input === undefined) {
    return input;
  }

  if (typeof input === 'object') {
    if (Array.isArray(input)) {
      return input.map(item => sanitizeInput(item));
    } else {
      const sanitized: any = {};
      for (const [key, value] of Object.entries(input)) {
        // Skip keys that might cause issues
        if (typeof key === 'string' && key.includes('$')) {
          continue;
        }
        sanitized[key] = sanitizeInput(value);
      }
      return sanitized;
    }
  }

  // For primitive types, return as-is (they're already safe)
  return input;
}

