};

// Helper to find user by ID
const findUserById = (id: string) => {
  return users.find(user => user.id === id);
};

// Registration endpoint
router.post("/register", (req: Request, res: Response) => {
  const { email, password, profile } = req.body;

  if (!email || !password || !profile) {
    return res.status(400).json({ error: "Email, password, and profile are required" });
  }

  if (findUserByEmail(email)) {
    return res.status(400).json({ error: "User already exists" });
  }

  const newUser = {
    id: `${users.length + 1}`,
    email,
    password,
    role: "student",
    profile
  };

  users.push(newUser);
  return res.status(201).json(newUser);
});

// Login endpoint
router.post("/login", (req: Request, res: Response) => {
  const { email, password } = req.body;

  if (!email || !password) {
    return res.status(400).json({ error: "Email and password are required" });
  }

  const user = findUserByEmail(email);

  if (!user) {
    return res.status(404).json({ error: "User not found" });
  }

  // In a real app, we'd verify password hash here
  if (user.password !== password) {
    return res.status(401).json({ error: "Invalid credentials" });
  }

  return res.json({
    id: user.id,
    email: user.email,
    role: user.role,
    profile: user.profile
  });
});

// Get user profile
router.get("/profile/:id", (req: Request, res: Response) => {
  const { id } = req.params;

  const user = findUserById(id);

  if (!user) {
    return res.status(404).json({ error: "User not found" });
  }

  return res.json({
    id: user.id,
    email: user.email,
    role: user.role,
    profile: user.profile
  });
});

// Update user profile
router.put("/profile/:id", (req: Request, res: Response) => {
  const { id } = req.params;
  const { profile } = req.body;

  if (!profile) {
    return res.status(400).json({ error: "Profile is required" });
  }

  const userIndex = users.findIndex(user => user.id === id);

  if (userIndex === -1) {
    return res.status(404).json({ error: "User not found" });
  }

  users[userIndex].profile = { ...users[userIndex].profile, ...profile };

  return res.json(users[userIndex]);
});

// Delete user account
router.delete("/profile/:id", (req: Request, res: Response) => {
  const { id } = req.params;

  const userIndex = users.findIndex(user => user.id === id);

  if (userIndex === -1) {
    return res.status(404).json({ error: "User not found" });
  }

  users.splice(userIndex, 1);

  return res.json({ message: "User deleted successfully" });
});

