import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

const ADMIN_ROLE = "admin";
const SELLER_ROLE = "seller";
const BUYER_ROLE = "buyer";

function isValidRole(role: string): role is "admin" | "seller" | "buyer" {
  return role === ADMIN_ROLE || role === SELLER_ROLE || role === BUYER_ROLE;
}

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply role-based access control to specific routes and methods
  const protectedPaths = ["/products", "/messages"];
  const protectedMethods = ["DELETE", "PUT"];

  const isProtectedPath = protectedPaths.some(path =>
    req.path.startsWith(path)
  );

  if (!isProtectedPath || !protectedMethods.includes(req.method)) {
    next();
    return;
  }

  // Extract role from request headers or session
  const userRole = req.headers["x-user-role"] as string;

  if (!userRole || !isValidRole(userRole)) {
    res.status(403).json({ error: "Forbidden: Invalid or missing role" });
    return;
  }

  // Define role permissions
  const allowedRoles: Record<string, string[]> = {
    DELETE: [ADMIN_ROLE],
    PUT: [ADMIN_ROLE, SELLER_ROLE]
  };

  const requiredRoles = allowedRoles[req.method] || [];

  if (!requiredRoles.includes(userRole)) {
    res.status(403).json({ error: "Forbidden: Insufficient role" });
    return;
  }

  next();
}

