import { useEffect, useState } from "react";

interface Product {
  id: number;
  title: string;
  description: string;
  price: number;
  category: string;
  condition: string;
}

interface FilterOptions {
  category: string;
  minPrice: number;
  maxPrice: number;
  condition: string;
}

export function ProductListingPage() {
  const [products, setProducts] = useState<Product[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [filters, setFilters] = useState<FilterOptions>({
    category: "",
    minPrice: 0,
    maxPrice: 1000,
    condition: "",
  });

  useEffect(() => {
    const fetchProducts = async () => {
      try {
        setLoading(true);
        // In a real app, this would be an API call
        // For demo purposes, we'll simulate with mock data
        await new Promise(resolve => setTimeout(resolve, 500));

        const mockProducts: Product[] = [
          {
            id: 1,
            title: "Used Laptop",
            description: "Good condition laptop",
            price: 250,
            category: "Electronics",
            condition: "Good",
          },
          {
            id: 2,
            title: "Textbook",
            description: "Mathematics textbook",
            price: 45,
            category: "Books",
            condition: "Excellent",
          },
          {
            id: 3,
            title: "Desk Lamp",
            description: "LED desk lamp",
            price: 20,
            category: "Furniture",
            condition: "Fair",
          },
        ];

        setProducts(mockProducts);
      } catch (err) {
        setError("Failed to load products");
      } finally {
        setLoading(false);
      }
    };

    fetchProducts();
  }, []);

  const handleFilterChange = (e: React.ChangeEvent<HTMLSelectElement | HTMLInputElement>) => {
    const { name, value } = e.target;
    setFilters(prev => ({
      ...prev,
      [name]: name === "minPrice" || name === "maxPrice" ? Number(value) : value
    }));
  };

  const filteredProducts = products.filter(product => {
    const matchesCategory = filters.category ? product.category === filters.category : true;
    const matchesPrice = product.price >= filters.minPrice && product.price <= filters.maxPrice;
    const matchesCondition = filters.condition ? product.condition === filters.condition : true;
    return matchesCategory && matchesPrice && matchesCondition;
  });

  const categories = [...new Set(products.map(p => p.category))];
  const conditions = [...new Set(products.map(p => p.condition))];

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
