export function ProductDetailPage({ productId }: { productId: string }) {
  const [product, setProduct] = useState<Product | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const fetchProduct = async () => {
      try {
        const response = await fetch(`/api/products/${productId}`);
        if (!response.ok) {
          throw new Error(`Failed to fetch product: ${response.status}`);
        }
        const data = await response.json();
        setProduct(data);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
      } finally {
        setLoading(false);
      }
    };

    fetchProduct();
  }, [productId]);

  if (loading) return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;

  if (error) return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;

  if (!product) return <div style={{ textAlign: "center", padding: "20px" }}>Product not found</div>;

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ fontSize: "24px", marginBottom: "10px" }}>{product.title}</h1>
      <p style={{ fontSize: "18px", color: "#333", marginBottom: "20px" }}>${product.price.toFixed(2)}</p>

      <div style={{ display: "flex", flexDirection: "column", gap: "20px" }}>
        <div style={{ display: "flex", flexWrap: "wrap", gap: "10px" }}>
          {product.images.map((image, index) => (
            <img 
              key={index} 
              src={image} 
              alt={`Product ${index + 1}`} 
              style={{ width: "100%", maxWidth: "200px", height: "auto", borderRadius: "8px" }} 
            />
          ))}
        </div>

        <div style={{ border: "1px solid #ddd", borderRadius: "8px", padding: "15px" }}>
          <h2 style={{ fontSize: "20px", marginBottom: "10px" }}>Description</h2>
          <p style={{ fontSize: "16px", lineHeight: "1.5" }}>{product.description}</p>
        </div>

        <div style={{ border: "1px solid #ddd", borderRadius: "8px", padding: "15px" }}>
          <h2 style={{ fontSize: "20px", marginBottom: "10px" }}>Seller Information</h2>
          <p style={{ fontSize: "16px", marginBottom: "5px" }}><strong>Name:</strong> {product.seller.name}</p>
          <p style={{ fontSize: "16px", marginBottom: "5px" }}><strong>Email:</strong> {product.seller.email}</p>
          <p style={{ fontSize: "16px", marginBottom: "5px" }}><strong>Phone:</strong> {product.seller.phone}</p>
        </div>

        <div style={{ border: "1px solid #ddd", borderRadius: "8px", padding: "15px" }}>
          <h2 style={{ fontSize: "20px", marginBottom: "10px" }}>Contact Options</h2>
          <button 
            style={{ 
              backgroundColor: "#007bff", 
              color: "white", 
              border: "none", 
              borderRadius: "4px", 
              padding: "10px 15px", 
              cursor: "pointer", 
              fontSize: "16px"
            }}
            onClick={() => window.location.href = `mailto:${product.seller.email}`}
          >
            Email Seller
          </button>
          <button 
            style={{ 
              backgroundColor: "#28a745", 
              color: "white", 
              border: "none", 
              borderRadius: "4px", 
              padding: "10px 15px", 
              cursor: "pointer", 
              fontSize: "16px", 
              marginLeft: "10px"
            }}
            onClick={() => window.location.href = `tel:${product.seller.phone}`}
          >
            Call Seller
          </button>
        </div>
      </div>
    </div>
  );
