import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock tournament data storage
let tournaments = [
  { id: 1, name: "Weekly Chess Match", location: "Central Hall", startDate: "2023-06-01", endDate: "2023-06-07", maxPlayers: 32 },
  { id: 2, name: "Monthly Tournament", location: "City Arena", startDate: "2023-06-15", endDate: "2023-06-20", maxPlayers: 64 }
];

let nextId = 3;

// GET /tournaments - List all tournaments
router.get("/tournaments", (req: Request, res: Response) => {
  res.json(tournaments);
});

// GET /tournaments/:id - Get a specific tournament by ID
router.get("/tournaments/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const tournament = tournaments.find(t => t.id === id);

  if (!tournament) {
    return res.status(404).json({ error: "Tournament not found" });
  }

  res.json(tournament);
});

// POST /tournaments - Create a new tournament
router.post("/tournaments", (req: Request, res: Response) => {
  const { name, location, startDate, endDate, maxPlayers } = req.body;

  // Validate required fields
  if (!name || !location || !startDate || !endDate || maxPlayers === undefined) {
    return res.status(400).json({ error: "Missing required fields" });
  }

  const newTournament = {
    id: nextId++,
    name,
    location,
    startDate,
    endDate,
    maxPlayers
  };

  tournaments.push(newTournament);
  res.status(201).json(newTournament);
});

// PUT /tournaments/:id - Update a tournament
router.put("/tournaments/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const index = tournaments.findIndex(t => t.id === id);

  if (index === -1) {
    return res.status(404).json({ error: "Tournament not found" });
  }

  const { name, location, startDate, endDate, maxPlayers } = req.body;

  // Validate required fields
  if (!name || !location || !startDate || !endDate || maxPlayers === undefined) {
    return res.status(400).json({ error: "Missing required fields" });
  }

  tournaments[index] = {
    id,
    name,
    location,
    startDate,
    endDate,
    maxPlayers
  };

  res.json(tournaments[index]);
});

// DELETE /tournaments/:id - Delete a tournament
router.delete("/tournaments/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const index = tournaments.findIndex(t => t.id === id);

  if (index === -1) {
    return res.status(404).json({ error: "Tournament not found" });
  }

  tournaments.splice(index, 1);
  res.json({ message: "Tournament deleted successfully" });
});

