import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply role-based access control to protected routes
  const protectedPaths = ["/admin", "/organizer", "/player"];
  const isProtectedPath = protectedPaths.some(path =>
    req.path.startsWith(path)
  );

  if (!isProtectedPath) {
    next();
    return;
  }

  // Check for authorization header
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized: Missing or invalid token" });
    return;
  }

  const token = authHeader.substring(7); // Remove 'Bearer '
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: "Server configuration error: JWT_SECRET not set" });
    return;
  }

  // Simple token validation (in a real app, you'd decode and verify properly)
  try {
    const [userId, role] = token.split(":");
    if (!userId || !role) {
      res.status(401).json({ error: "Unauthorized: Invalid token format" });
      return;
    }

    // Validate role
    const validRoles = ["admin", "organizer", "player"];
    if (!validRoles.includes(role)) {
      res.status(403).json({ error: "Forbidden: Invalid role" });
      return;
    }

    // Check path permissions
    const requiredRole = getRequiredRole(req.path);
    if (!requiredRole) {
      next();
      return;
    }

    if (role !== requiredRole && role !== "admin") {
      res.status(403).json({ error: "Forbidden: Insufficient permissions" });
      return;
    }

    // Attach user info to request
    (req as any).user = { id: userId, role };
    next();
  } catch (error) {
    res.status(401).json({ error: "Unauthorized: Invalid token" });
  }
}

function getRequiredRole(path: string): string | null {
  if (path.startsWith("/admin")) return "admin";
  if (path.startsWith("/organizer")) return "organizer";
  if (path.startsWith("/player")) return "player";
  return null;
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process POST requests to /login endpoint
  if (req.method !== "POST" || req.path !== "/login") {
    next();
    return;
  }

  // Check if JWT_SECRET is set
  const secret = process.env.JWT_SECRET;
  if (!secret) {
    res.status(500).json({ error: "Server configuration error" });
    return;
  }

  // For demonstration purposes, we'll just check if the request has a valid body
  // In a real implementation, this would verify a JWT token signature
  if (!req.body || !req.body.token) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  // Simulate token verification (in reality, this would use HMAC-SHA256)
  const token = req.body.token;
  const expectedSignature = createHmac("sha256", secret)
    .update(token.split(".")[0] + "." + token.split(".")[1])
    .digest("hex");

  // This is a simplified check - in practice, you'd compare the actual signature
  // using timingSafeEqual to prevent timing attacks
  const providedSignature = token.split(".")[2];

  try {
    const expectedBuffer = Buffer.from(expectedSignature, "hex");
    const providedBuffer = Buffer.from(providedSignature, "hex");

    if (expectedBuffer.length !== providedBuffer.length) {
      res.status(401).json({ error: "Unauthorized" });
      return;
    }

    const isValid = timingSafeEqual(expectedBuffer, providedBuffer);

    if (!isValid) {
      res.status(401).json({ error: "Unauthorized" });
      return;
    }
  } catch (err) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  next();
}

