    fetchData();
  }, []);

  const handleTournamentSelect = (tournamentId: number) => {
    setSelectedTournamentId(tournamentId);
  };

  const getPlayersForMatch = (match: Match) => {
    const player1 = players.find(p => p.id === match.player1Id);
    const player2 = players.find(p => p.id === match.player2Id);
    return {
      player1Name: player1 ? player1.name : "Unknown",
      player2Name: player2 ? player2.name : "Unknown"
    };
  };

  const handleRecordResult = (matchId: number, result: string) => {
    // In a real app, this would make an API call
    setMatches(matches.map(match => 
      match.id === matchId ? { ...match, result } : match
    ));
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Match Management</h1>

      <div style={{ marginBottom: "20px" }}>
        <h2>Select Tournament</h2>
        <div style={{ display: "flex", flexWrap: "wrap", gap: "10px" }}>
          {tournaments.map(tournament => (
            <button
              key={tournament.id}
              onClick={() => handleTournamentSelect(tournament.id)}
              style={{
                padding: "10px 15px",
                borderRadius: "5px",
                border: "1px solid #ccc",
                backgroundColor: selectedTournamentId === tournament.id ? "#007bff" : "white",
                color: selectedTournamentId === tournament.id ? "white" : "black",
                cursor: "pointer"
              }}
            >
              {tournament.name}
            </button>
          ))}
        </div>
      </div>

      {selectedTournamentId && (
        <div>
          <h2>Matches for Selected Tournament</h2>
          {matches
            .filter(match => match.tournamentId === selectedTournamentId)
            .length === 0 ? (
            <p>No matches found for this tournament.</p>
          ) : (
            <div style={{ display: "flex", flexDirection: "column", gap: "15px" }}>
              {matches
                .filter(match => match.tournamentId === selectedTournamentId)
                .map(match => {
                  const { player1Name, player2Name } = getPlayersForMatch(match);
                  return (
                    <div 
                      key={match.id} 
                      style={{ 
                        border: "1px solid #ddd", 
                        borderRadius: "8px", 
                        padding: "15px", 
                        backgroundColor: "#f9f9f9"
                      }}
                    >
                      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                        <div>
                          <strong>{player1Name}</strong> vs <strong>{player2Name}</strong>
                        </div>
                        <div>
                          {match.result ? (
                            <span style={{ color: "green" }}>Result: {match.result}</span>
                          ) : (
                            <select 
                              onChange={(e) => handleRecordResult(match.id, e.target.value)}
                              style={{ padding: "5px", borderRadius: "4px", border: "1px solid #ccc" }}
                            >
                              <option value="">Record Result</option>
                              <option value="Player 1 Wins">Player 1 Wins</option>
                              <option value="Player 2 Wins">Player 2 Wins</option>
                              <option value="Draw">Draw</option>
                            </select>
                          )}
                        </div>
                      </div>
                    </div>
                  );
                })}
            </div>
          )}
        </div>
      )}

      <div style={{ marginTop: "30px", borderTop: "1px solid #eee", paddingTop: "20px" }}>
        <h2>Add New Match</h2>
        <form 
          onSubmit={(e) => {
            e.preventDefault();
            // In a real app, this would make an API call
            const formData = new FormData(e.target as HTMLFormElement);
            const player1Id = Number(formData.get("player1Id"));
            const player2Id = Number(formData.get("player2Id"));

            if (player1Id && player2Id && selectedTournamentId) {
              const newMatch: Match = {
                id: matches.length + 1,
                player1Id,
                player2Id,
                tournamentId: selectedTournamentId
              };
              setMatches([...matches, newMatch]);
              (e.target as HTMLFormElement).reset();
            }
          }}
          style={{ display: "flex", flexDirection: "column", gap: "10px" }}
        >
          <div>
            <label htmlFor="player1Id" style={{ display: "block", marginBottom: "5px" }}>Player 1:</label>
            <select 
              id="player1Id"
              name="player1Id"
              required
              style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
            >
              <option value="">Select Player 1</option>
              {players.map(player => (
                <option key={player.id} value={player.id}>{player.name}</option>
              ))}
            </select>
          </div>

          <div>
            <label htmlFor="player2Id" style={{ display: "block", marginBottom: "5px" }}>Player 2:</label>
            <select 
              id="player2Id"
