import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock database functions - in a real app these would come from a database module
const mockProblems = [
  { id: 1, title: "Two Sum", description: "Given an array of integers, return indices of the two numbers such that they add up to a specific target.", difficulty: "Easy" },
  { id: 2, title: "Reverse Linked List", description: "Given the head of a singly linked list, reverse the list, and return the reversed list.", difficulty: "Easy" }
];

const findProblemById = (id: number) => {
  return mockProblems.find(problem => problem.id === id);
};

const createProblem = (title: string, description: string, difficulty: string) => {
  const newId = Math.max(0, ...mockProblems.map(p => p.id)) + 1;
  const newProblem = { id: newId, title, description, difficulty };
  mockProblems.push(newProblem);
  return newProblem;
};

const updateProblem = (id: number, title: string, description: string, difficulty: string) => {
  const index = mockProblems.findIndex(problem => problem.id === id);
  if (index === -1) return null;

  mockProblems[index] = { id, title, description, difficulty };
  return mockProblems[index];
};

const deleteProblem = (id: number) => {
  const index = mockProblems.findIndex(problem => problem.id === id);
  if (index === -1) return false;

  mockProblems.splice(index, 1);
  return true;
};

// GET /problems - List all problems
router.get("/problems", (req: Request, res: Response) => {
  res.json(mockProblems);
});

// GET /problems/:id - Get a specific problem by ID
router.get("/problems/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid problem ID" });
  }

  const problem = findProblemById(id);

  if (!problem) {
    return res.status(404).json({ error: "Problem not found" });
  }

  res.json(problem);
});

// POST /problems - Create a new problem
router.post("/problems", (req: Request, res: Response) => {
  const { title, description, difficulty } = req.body;

  if (!title || !description || !difficulty) {
    return res.status(400).json({ error: "Title, description, and difficulty are required" });
  }

  const newProblem = createProblem(title, description, difficulty);

  res.status(201).json(newProblem);
});

// PUT /problems/:id - Update a problem
router.put("/problems/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const { title, description, difficulty } = req.body;

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid problem ID" });
  }

  if (!title || !description || !difficulty) {
    return res.status(400).json({ error: "Title, description, and difficulty are required" });
  }

  const updatedProblem = updateProblem(id, title, description, difficulty);

  if (!updatedProblem) {
    return res.status(404).json({ error: "Problem not found" });
  }

  res.json(updatedProblem);
});

// DELETE /problems/:id - Delete a problem
router.delete("/problems/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid problem ID" });
  }

  const deleted = deleteProblem(id);

  if (!deleted) {
    return res.status(404).json({ error: "Problem not found" });
  }

  res.json({ message: "Problem deleted successfully" });
});

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only protect POST, PUT, DELETE requests to /problems
  if (!(req.method === "POST" || req.method === "PUT" || req.method === "DELETE") || !req.path.startsWith("/problems")) {
    next();
    return;
  }

  const authHeader = req.headers.authorization;

  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const token = authHeader.substring(7); // Remove "Bearer " prefix

  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: "Server configuration error" });
    return;
  }

  // Simple token validation - in a real app, you'd decode and verify the JWT signature
  // For this exercise, we'll just check if it matches a known pattern
  const expectedSignature = createHmac("sha256", secret)
    .update(token.split(".")[0] || "")
    .digest("hex");

  const tokenSignature = token.split(".")[1] || "";

  try {
    const expectedBuffer = Buffer.from(expectedSignature, "hex");
    const actualBuffer = Buffer.from(tokenSignature, "hex");

    if (expectedBuffer.length !== actualBuffer.length || !timingSafeEqual(expectedBuffer, actualBuffer)) {
      res.status(401).json({ error: "Invalid token" });
      return;
    }
  } catch (err) {
    res.status(401).json({ error: "Invalid token" });
    return;
  }

  next();
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply authorization checks to protected routes
  if (!req.path.startsWith("/api/problems") && !req.path.startsWith("/api/submissions")) {
    next();
    return;
  }

  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized: Missing or invalid token" });
    return;
  }

  const token = authHeader.substring(7);
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: "Server configuration error: JWT_SECRET not set" });
    return;
  }

  try {
    // Basic token structure validation
    const parts = token.split(".");
    if (parts.length !== 3) {
      res.status(401).json({ error: "Unauthorized: Invalid token format" });
      return;
    }

    const [header, payload, signature] = parts;
    const expectedSignature = createHmac("sha256", secret)
      .update(`${header}.${payload}`)
      .digest();

    const actualSignature = Buffer.from(signature, "base64");

    if (actualSignature.length !== expectedSignature.length || 
        !timingSafeEqual(expectedSignature, actualSignature)) {
      res.status(401).json({ error: "Unauthorized: Invalid token signature" });
      return;
    }

    // Decode payload to extract role and permissions
    const decodedPayload = JSON.parse(Buffer.from(payload, "base64").toString());
    const userRole = decodedPayload.role || "user";
    const userPermissions = decodedPayload.permissions || [];

    // Check if user has required permissions for the route
    const requiredPermission = getRequiredPermission(req.method, req.path);

    if (requiredPermission && !userPermissions.includes(requiredPermission)) {
      res.status(403).json({ error: "Forbidden: Insufficient permissions" });
      return;
    }

    // Attach user info to request for downstream middleware/routes
    (req as any).user = {
      role: userRole,
      permissions: userPermissions
    };

    next();
  } catch (error) {
    res.status(401).json({ error: "Unauthorized: Invalid token" });
  }
}

function getRequiredPermission(method: string, path: string): string | null {
  if (path.startsWith("/api/problems")) {
    switch (method) {
      case "GET":
        return "read:problems";
      case "POST":
        return "write:problems";
      case "PUT":
      case "DELETE":
        return "manage:problems";
      default:
        return null;
    }
  }

  if (path.startsWith("/api/submissions")) {
    switch (method) {
      case "GET":
        return "read:submissions";
      case "POST":
        return "write:submissions";
      default:
        return null;
    }
  }

  return null;
}

import { useEffect, useState } from "react";

interface Problem {
  id: number;
  title: string;
  difficulty: "Easy" | "Medium" | "Hard";
  description: string;
}

export function ProblemListPage() {
  const [problems, setProblems] = useState<Problem[]>([]);
  const [filteredProblems, setFilteredProblems] = useState<Problem[]>([]);
  const [searchTerm, setSearchTerm] = useState("");
  const [difficultyFilter, setDifficultyFilter] = useState<"All" | "Easy" | "Medium" | "Hard">("All");
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const fetchProblems = async () => {
      try {
        // In a real app, this would be an actual API call
        // For now, we'll simulate with mock data
        await new Promise(resolve => setTimeout(resolve, 500));

        const mockProblems: Problem[] = [
          {
            id: 1,
            title: "Two Sum",
            difficulty: "Easy",
            description: "Given an array of integers nums and an integer target, return indices of the two numbers such that they add up to target."
          },
          {
            id: 2,
            title: "Reverse Linked List",
            difficulty: "Easy",
            description: "Given the head of a singly linked list, reverse the list, and return the reversed list."
          },
          {
            id: 3,
            title: "Merge Intervals",
            difficulty: "Medium",
            description: "Given an array of intervals where intervals[i] = [start_i, end_i], merge all overlapping intervals."
          },
          {
            id: 4,
            title: "Binary Tree Maximum Path Sum",
            difficulty: "Hard",
            description: "A path in a binary tree is a sequence of nodes where each pair of adjacent nodes in the sequence has an edge connecting them."
          }
        ];

        setProblems(mockProblems);
        setFilteredProblems(mockProblems);
      } catch (err) {
        setError("Failed to load problems");
      } finally {
        setLoading(false);
      }
    };

    fetchProblems();
  }, []);

  useEffect(() => {
    let result = problems;

    if (searchTerm) {
      const term = searchTerm.toLowerCase();
      result = result.filter(problem => 
        problem.title.toLowerCase().includes(term) || 
        problem.description.toLowerCase().includes(term)
      );
    }

    if (difficultyFilter !== "All") {
      result = result.filter(problem => problem.difficulty === difficultyFilter);
    }

    setFilteredProblems(result);
  }, [searchTerm, difficultyFilter, problems]);

  const handleSearchChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setSearchTerm(e.target.value);
  };

  const handleDifficultyChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    setDifficultyFilter(e.target.value as "All" | "Easy" | "Medium" | "Hard");
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Coding Problems</h1>

      <div style={{ marginBottom: "20px", display: "flex", flexDirection: "column", gap: "10px" }}>
        <input
          type="text"
          placeholder="Search problems..."
          value={searchTerm}
          onChange={handleSearchChange}
          style={{ width: "100%", padding: "10px", borderRadius: "4px", border: "1px solid #ccc" }}
        />

        <select
          value={difficultyFilter}
          onChange={handleDifficultyChange}
          style={{ width: "100%", padding: "10px", borderRadius: "4px", border: "1px solid #ccc" }}
        >
          <option value="All">All Difficulties</option>
          <option value="Easy">Easy</option>
          <option value="Medium">Medium</option>
          <option value="Hard">Hard</option>
        </select>
      </div>

      {filteredProblems.length === 0 ? (
        <div style={{ textAlign: "center", padding: "20px" }}>
          No problems found.
        </div>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: "15px" }}>
          {filteredProblems.map(problem => (
            <div 
              key={problem.id} 
              style={{ 
                border: "1px solid #ddd", 
                borderRadius: "8px", 
                padding: "15px", 
                backgroundColor: "#f9f9f9"
              }}
            >
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start" }}>
                <h3 style={{ margin: "0 0 10px 0", color: "#333" }}>{problem.title}</h3>
                <span 
                  style={{ 
                    backgroundColor: 
                      problem.difficulty === "Easy" ? "#d4edda" : 
                      problem.difficulty === "Medium" ? "#fff3cd" : "#f8d7da",
                    color: 
                      problem.difficulty === "Easy" ? "#155724" : 
                      problem.difficulty === "Medium" ? "#856404" : "#721c24",
                    padding: "4px 8px", 
                    borderRadius: "4px", 
                    fontSize: "0.9em"
                  }}
                >
                  {problem.difficulty}
                </span>
              </div>
              <p style={{ margin: "0", color: "#666" }}>{problem.description}</p>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

