    await new Promise(resolve => setTimeout(resolve, 500));

    setIsSubmitting(false);
    setSubmitSuccess(true);

    // Reset form
    setTitle("");
    setDescription("");
    setDifficulty("easy");
    setTags("");

    // Reset success message after 3 seconds
    setTimeout(() => setSubmitSuccess(false), 3000);
