import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock ticket data structure
interface Ticket {
  id: number;
  title: string;
  description: string;
  status: 'open' | 'in-progress' | 'resolved' | 'closed';
  priority: 'low' | 'medium' | 'high' | 'urgent';
  assignee: string;
  createdAt: Date;
  updatedAt: Date;
}

// Mock database - in a real app this would be a proper database
let tickets: Ticket[] = [];
let nextId = 1;

// GET /tickets - List all tickets
router.get('/tickets', (req: Request, res: Response) => {
  res.json(tickets);
});

// GET /tickets/:id - Get a specific ticket by ID
router.get('/tickets/:id', (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const ticket = tickets.find(t => t.id === id);

  if (!ticket) {
    return res.status(404).json({ error: 'Ticket not found' });
  }

  res.json(ticket);
});

// POST /tickets - Create a new ticket
router.post('/tickets', (req: Request, res: Response) => {
  const { title, description, status, priority, assignee } = req.body;

  // Validate required fields
  if (!title || !description || !status || !priority || !assignee) {
    return res.status(400).json({ error: 'Missing required fields' });
  }

  // Validate status
  const validStatuses: Ticket['status'][] = ['open', 'in-progress', 'resolved', 'closed'];
  if (!validStatuses.includes(status)) {
    return res.status(400).json({ error: 'Invalid status' });
  }

  // Validate priority
  const validPriorities: Ticket['priority'][] = ['low', 'medium', 'high', 'urgent'];
  if (!validPriorities.includes(priority)) {
    return res.status(400).json({ error: 'Invalid priority' });
  }

  const newTicket: Ticket = {
    id: nextId++,
    title,
    description,
    status,
    priority,
    assignee,
    createdAt: new Date(),
    updatedAt: new Date()
  };

  tickets.push(newTicket);

  res.status(201).json(newTicket);
});

// PUT /tickets/:id - Update a ticket
router.put('/tickets/:id', (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const ticketIndex = tickets.findIndex(t => t.id === id);

  if (ticketIndex === -1) {
    return res.status(404).json({ error: 'Ticket not found' });
  }

  const { title, description, status, priority, assignee } = req.body;

  // Validate status
  const validStatuses: Ticket['status'][] = ['open', 'in-progress', 'resolved', 'closed'];
  if (status && !validStatuses.includes(status)) {
    return res.status(400).json({ error: 'Invalid status' });
  }

  // Validate priority
  const validPriorities: Ticket['priority'][] = ['low', 'medium', 'high', 'urgent'];
  if (priority && !validPriorities.includes(priority)) {
    return res.status(400).json({ error: 'Invalid priority' });
  }

  // Update ticket
  const updatedTicket: Ticket = {
    ...tickets[ticketIndex],
    ...(title && { title }),
    ...(description && { description }),
    ...(status && { status }),
    ...(priority && { priority }),
    ...(assignee && { assignee }),
    updatedAt: new Date()
  };

  tickets[ticketIndex] = updatedTicket;

  res.json(updatedTicket);
});

// DELETE /tickets/:id - Delete a ticket
router.delete('/tickets/:id', (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const ticketIndex = tickets.findIndex(t => t.id === id);

  if (ticketIndex === -1) {
    return res.status(404).json({ error: 'Ticket not found' });
  }

  tickets.splice(ticketIndex, 1);

  res.json({ message: 'Ticket deleted successfully' });
});

// GET /tickets/search - Search tickets by criteria
router.get('/tickets/search', (req: Request, res: Response) => {
  const { status, priority, assignee } = req.query;

  let filteredTickets = [...tickets];

  if (status) {
    filteredTickets = filteredTickets.filter(t => t.status === status);
  }

  if (priority) {
    filteredTickets = filteredTickets.filter(t => t.priority === priority);
  }

  if (assignee) {
    filteredTickets = filteredTickets.filter(t => t.assignee === assignee);
  }

  res.json(filteredTickets);
});

