        <div style={{ display: "flex", gap: "10px", flexWrap: "wrap" }}>
          <select
            value={statusFilter}
            onChange={(e) => setStatusFilter(e.target.value as "all" | Ticket["status"])}
            style={{ padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
          >
