        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ status, assignee }),
      });

      if (!response.ok) {
        throw new Error(`Failed to update ticket: ${response.status}`);
      }

      // Refresh data after update
      const updatedResponse = await fetch(`/api/tickets/${ticket.id}`);
      const updatedTicket: Ticket = await updatedResponse.json();
      setTicket(updatedTicket);

      // Reset form
      setStatus("open");
      setAssignee("");
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleAddComment = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!ticket || !newComment.trim()) return;

    try {
      const response = await fetch(`/api/tickets/${ticket.id}/comments`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ content: newComment }),
      });

      if (!response.ok) {
        throw new Error(`Failed to add comment: ${response.status}`);
      }

      // Refresh comments after adding
      const commentsResponse = await fetch(`/api/tickets/${ticket.id}/comments`);
      const commentsData: Comment[] = await commentsResponse.json();
      setComments(commentsData);

      // Reset comment input
      setNewComment("");
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ color: "red", textAlign: "center", padding: "20px" }}>{error}</div>;
  }

  if (!ticket) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Ticket not found</div>;
  }

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Ticket Details</h1>

      <div style={{ backgroundColor: "#f5f5f5", borderRadius: "8px", padding: "16px", marginBottom: "20px" }}>
        <h2>{ticket.title}</h2>
        <p><strong>Description:</strong> {ticket.description}</p>
        <p><strong>Status:</strong> {ticket.status}</p>
        <p><strong>Assignee:</strong> {ticket.assignee || "Unassigned"}</p>
        <p><strong>Created:</strong> {new Date(ticket.createdAt).toLocaleString()}</p>
        <p><strong>Last Updated:</strong> {new Date(ticket.updatedAt).toLocaleString()}</p>
      </div>

      <div style={{ marginBottom: "20px" }}>
        <h3>Add Comment</h3>
        <form onSubmit={handleAddComment}>
          <textarea
            value={newComment}
            onChange={(e) => setNewComment(e.target.value)}
            placeholder="Enter your comment..."
            style={{ width: "100%", padding: "8px", marginBottom: "10px", borderRadius: "4px", border: "1px solid #ccc" }}
            rows={3}
          />
          <button type="submit" style={{ backgroundColor: "#007bff", color: "white", padding: "8px 16px", border: "none", borderRadius: "4px", cursor: "pointer" }}>
            Add Comment
          </button>
        </form>
      </div>

      <div style={{ marginBottom: "20px" }}>
        <h3>Comments</h3>
        {comments.length === 0 ? (
          <p>No comments yet.</p>
        ) : (
          <div>
            {comments.map((comment) => (
              <div key={comment.id} style={{ backgroundColor: "#fff", border: "1px solid #ddd", borderRadius: "4px", padding: "10px", marginBottom: "10px" }}>
