import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check authorization for requests that modify data
  const isWriteRequest = req.method === "POST" || 
                        req.method === "PUT" || 
                        req.method === "DELETE" ||
                        req.method === "PATCH";

  // Check if this is a request to playlist or song endpoints
  const isPlaylistOrSongRequest = req.path.startsWith("/playlists/") || 
                                req.path.startsWith("/songs/");

  // If not a write request or not related to playlists/songs, skip auth
  if (!isWriteRequest || !isPlaylistOrSongRequest) {
    next();
    return;
  }

  // Get the token from headers
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const token = authHeader.substring(7);

  // Verify JWT signature
  const secret = process.env.JWT_SECRET;
  if (!secret) {
    res.status(500).json({ error: "Server configuration error" });
    return;
  }

  // Simple verification - in a real app, use a proper JWT library
  const parts = token.split(".");
  if (parts.length !== 3) {
    res.status(401).json({ error: "Invalid token format" });
    return;
  }

  const [header, payload, signature] = parts;

  // Create expected signature
  const expectedSignature = createHmac("sha256", secret)
    .update(`${header}.${payload}`)
    .digest("base64url");

  // Use timingSafeEqual to prevent timing attacks
  const expectedBuffer = Buffer.from(expectedSignature, "base64url");
  const actualBuffer = Buffer.from(signature, "base64url");

  try {
    if (!timingSafeEqual(expectedBuffer, actualBuffer)) {
      res.status(401).json({ error: "Invalid token" });
      return;
    }
  } catch {
    res.status(401).json({ error: "Invalid token" });
    return;
  }

  // In a real implementation, we would decode the payload to get user info
  // For now, we'll just proceed assuming valid token
  next();
}

import { useEffect, useState } from "react";

interface Playlist {
  id: string;
  name: string;
  description: string;
}

export function PlaylistPage() {
  const [playlists, setPlaylists] = useState<Playlist[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [newPlaylist, setNewPlaylist] = useState({
    name: "",
    description: "",
  });

  useEffect(() => {
    fetchPlaylists();
  }, []);

  const fetchPlaylists = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/playlists");
      if (!response.ok) {
        throw new Error(`Failed to fetch playlists: ${response.status}`);
      }
      const data = await response.json();
      setPlaylists(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleCreate = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const response = await fetch("/api/playlists", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(newPlaylist),
      });
      if (!response.ok) {
        throw new Error(`Failed to create playlist: ${response.status}`);
      }
      setNewPlaylist({ name: "", description: "" });
      fetchPlaylists();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleDelete = async (id: string) => {
    try {
      const response = await fetch(`/api/playlists/${id}`, {
        method: "DELETE",
      });
      if (!response.ok) {
        throw new Error(`Failed to delete playlist: ${response.status}`);
      }
      fetchPlaylists();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return (
      <div style={{ textAlign: "center", padding: "20px", color: "red" }}>
        Error: {error}
      </div>
    );
  }

  return (
    <div
      style={{
        fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif",
        maxWidth: "800px",
        margin: "0 auto",
        padding: "20px",
      }}
    >
      <h1>My Playlists</h1>

      <form
        onSubmit={handleCreate}
        style={{ marginBottom: "30px", display: "flex", flexDirection: "column", gap: "10px" }}
      >
        <input
          type="text"
          placeholder="Playlist Name"
          value={newPlaylist.name}
          onChange={(e) => setNewPlaylist({ ...newPlaylist, name: e.target.value })}
          style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
        />
        <textarea
          placeholder="Description"
          value={newPlaylist.description}
          onChange={(e) => setNewPlaylist({ ...newPlaylist, description: e.target.value })}
          style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
        />
        <button
          type="submit"
