import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply role-based access control to specific routes
  const protectedPaths = ["/vendors", "/admin"];
  const isProtectedPath = protectedPaths.some(path =>
    req.path.startsWith(path)
  );

  if (!isProtectedPath) {
    next();
    return;
  }

  // Check if user has proper role access
  const userRole = req.headers["x-user-role"] as string || "public";
  const requiredRole = getRequiredRole(req.path);

  if (!hasPermission(userRole, requiredRole)) {
    res.status(403).json({ error: "Forbidden: Insufficient permissions" });
    return;
  }

  next();
}

function getRequiredRole(path: string): string {
  if (path.startsWith("/admin")) {
    return "admin";
  }
  if (path.startsWith("/vendors")) {
    return "vendor";
  }
  return "public";
}

function hasPermission(userRole: string, requiredRole: string): boolean {
  const roles = ["public", "vendor", "admin"];
  const userIndex = roles.indexOf(userRole);
  const requiredIndex = roles.indexOf(requiredRole);

  return userIndex >= requiredIndex;
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process POST requests to /login endpoint
  if (req.method !== "POST" || req.path !== "/login") {
    next();
    return;
  }

  // Check if JWT secret is set
  const jwtSecret = process.env.JWT_SECRET;
  if (!jwtSecret) {
    res.status(500).json({ error: "Internal server error" });
    return;
  }

  // For demonstration purposes, we'll simulate token verification
  // In a real implementation, you would decode and verify the JWT token
  // Here we're just checking if a token is present
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const token = authHeader.substring(7); // Remove 'Bearer '

  // Simulate token verification using HMAC-SHA256
  const expectedSignature = createHmac("sha256", jwtSecret)
    .update(token)
    .digest();

  // In a real implementation, you would compare the actual token signature
  // with the expected signature using timingSafeEqual
  // For now, we'll just check if token exists
  if (!token) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  // If we get here, the token is valid
  next();
}

