    { id: 1, distance: 5.2, duration: 2400 },
    { id: 2, distance: 3.1, duration: 1800 }
  ]),
  updateRunSession: (id: number, session: any) => Promise.resolve({ id, ...session }),
  deleteRunSession: (id: number) => Promise.resolve(true)
};

// Helper function to calculate pace (minutes per kilometer)
const calculatePace = (distance: number, duration: number): number => {
  if (distance <= 0 || duration <= 0) return 0;
  // duration is in seconds, convert to minutes
  const minutes = duration / 60;
  return distance > 0 ? minutes / distance : 0;
};

// Validation helper
const validateRunSession = (session: any): boolean => {
  return (
    typeof session.distance === 'number' &&
    session.distance > 0 &&
    typeof session.duration === 'number' &&
    session.duration > 0
  );
};

// GET /runs - Get all run sessions
router.get('/runs', async (req: Request, res: Response) => {
  try {
    const runs = await mockDatabase.getAllRunSessions();
    res.json(runs);
  } catch (error) {
    res.status(500).json({ error: 'Failed to fetch run sessions' });
  }
});

// GET /runs/:id - Get a specific run session by ID
router.get('/runs/:id', async (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: 'Invalid run ID' });
  }

  try {
    const run = await mockDatabase.getRunSession(id);
    if (!run) {
      return res.status(404).json({ error: 'Run session not found' });
    }

    // Calculate pace
    const pace = calculatePace(run.distance, run.duration);
    res.json({ ...run, pace });
  } catch (error) {
    res.status(500).json({ error: 'Failed to fetch run session' });
  }
});

// POST /runs - Create a new run session
router.post('/runs', async (req: Request, res: Response) => {
  const { distance, duration } = req.body;

  if (!validateRunSession({ distance, duration })) {
    return res.status(400).json({ error: 'Invalid run session data. Distance and duration must be positive numbers.' });
  }

  try {
    const newRun = await mockDatabase.createRunSession({ distance, duration });
    const pace = calculatePace(distance, duration);
    res.status(201).json({ ...newRun, pace });
  } catch (error) {
    res.status(500).json({ error: 'Failed to create run session' });
  }
});

// PUT /runs/:id - Update a run session
router.put('/runs/:id', async (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const { distance, duration } = req.body;

  if (isNaN(id)) {
    return res.status(400).json({ error: 'Invalid run ID' });
  }

  if (!validateRunSession({ distance, duration })) {
    return res.status(400).json({ error: 'Invalid run session data. Distance and duration must be positive numbers.' });
  }

  try {
    const updatedRun = await mockDatabase.updateRunSession(id, { distance, duration });
    if (!updatedRun) {
      return res.status(404).json({ error: 'Run session not found' });
    }

    const pace = calculatePace(distance, duration);
    res.json({ ...updatedRun, pace });
  } catch (error) {
    res.status(500).json({ error: 'Failed to update run session' });
  }
});

// DELETE /runs/:id - Delete a run session
router.delete('/runs/:id', async (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: 'Invalid run ID' });
  }

  try {
    const deleted = await mockDatabase.deleteRunSession(id);
    if (!deleted) {
      return res.status(404).json({ error: 'Run session not found' });
    }

    res.json({ message: 'Run session deleted successfully' });
  } catch (error) {
    res.status(500).json({ error: 'Failed to delete run session' });
  }
});

