import { useEffect, useState } from "react";

interface Counsellor {
  id: number;
  name: string;
  specialty: string;
}

interface TimeSlot {
  id: number;
  date: string;
  time: string;
  counsellorId: number;
}

interface Booking {
  id: number;
  date: string;
  time: string;
  counsellorName: string;
}

export function BookingPage() {
  const [counsellors, setCounsellors] = useState<Counsellor[]>([]);
  const [timeSlots, setTimeSlots] = useState<TimeSlot[]>([]);
  const [bookings, setBookings] = useState<Booking[]>([]);
  const [selectedCounsellor, setSelectedCounsellor] = useState<number | null>(null);
  const [selectedDate, setSelectedDate] = useState<string>("");
  const [selectedTime, setSelectedTime] = useState<string>("");
  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const fetchData = async () => {
      try {
        // In a real app, these would be actual API calls
        // For now, we'll simulate with mock data

        // Mock counsellors
        const mockCounsellors: Counsellor[] = [
          { id: 1, name: "Dr. Sarah Johnson", specialty: "Anxiety" },
          { id: 2, name: "Mr. Michael Chen", specialty: "Depression" },
          { id: 3, name: "Ms. Emily Davis", specialty: "Relationships" },
        ];

        // Mock time slots
        const mockTimeSlots: TimeSlot[] = [
          { id: 1, date: "2023-06-15", time: "09:00", counsellorId: 1 },
          { id: 2, date: "2023-06-15", time: "10:00", counsellorId: 1 },
          { id: 3, date: "2023-06-15", time: "11:00", counsellorId: 2 },
          { id: 4, date: "2023-06-16", time: "14:00", counsellorId: 2 },
          { id: 5, date: "2023-06-16", time: "15:00", counsellorId: 3 },
        ];

        // Mock existing bookings
        const mockBookings: Booking[] = [
          { id: 1, date: "2023-06-14", time: "10:00", counsellorName: "Dr. Sarah Johnson" },
        ];

        setCounsellors(mockCounsellors);
        setTimeSlots(mockTimeSlots);
        setBookings(mockBookings);
        setLoading(false);
      } catch (err) {
        setError("Failed to load data");
        setLoading(false);
      }
    };

    fetchData();
  }, []);

  const handleBookAppointment = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!selectedCounsellor || !selectedDate || !selectedTime) {
      setError("Please select all fields");
      return;
    }

    try {
      // In a real app, this would be an actual API call
      // For now, we'll just update the UI

      const newBooking: Booking = {
        id: bookings.length + 1,
        date: selectedDate,
        time: selectedTime,
        counsellorName: counsellors.find(c => c.id === selectedCounsellor)?.name || "",
      };

      setBookings([...bookings, newBooking]);

      // Reset form
      setSelectedCounsellor(null);
      setSelectedDate("");
      setSelectedTime("");

      setError(null);
    } catch (err) {
      setError("Failed to book appointment");
    }
  };

  const availableSlots = timeSlots.filter(slot => 
    !bookings.some(booking => 
      booking.date === slot.date && 
      booking.time === slot.time
    )
  );

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center", marginBottom: "30px" }}>Book an Appointment</h1>

      <form onSubmit={handleBookAppointment} style={{ marginBottom: "40px", padding: "20px", border: "1px solid #ddd", borderRadius: "8px" }}>
        <div style={{ marginBottom: "15px" }}>
          <label style={{ display: "block", marginBottom: "5px" }}>Counsellor:</label>
          <select
            value={selectedCounsellor || ""}
            onChange={(e) => setSelectedCounsellor(Number(e.target.value))}
            style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
          >
            <option value="">Select a counsellor</option>
            {counsellors.map(counsellor => (
              <option key={counsellor.id} value={counsellor.id}>
                {counsellor.name} ({counsellor.specialty})
              </option>
            ))}
          </select>
        </div>

        <div style={{ marginBottom: "15px" }}>
          <label style={{ display: "block", marginBottom: "5px" }}>Date:</label>
          <input
            type="date"
            value={selectedDate}
            onChange={(e) => setSelectedDate(e.target.value)}
            style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
          />
        </div>

        <div style={{ marginBottom: "15px" }}>
          <label style={{ display: "block", marginBottom: "5px" }}>Time:</label>
          <select
            value={selectedTime}
            onChange={(e) => setSelectedTime(e.target.value)}
            style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
          >
            <option value="">Select a time</option>
            {availableSlots.map(slot => (
              <option key={slot.id} value={slot.time}>
                {slot.time}
              </option>
            ))}
          </select>
        </div>

        <button 
          type="submit" 
          style={{ 
            backgroundColor: "#007bff", 
            color: "white", 
            border: "none", 
            padding: "10px 20px", 
            borderRadius: "4px", 
            cursor: "pointer" 
          }}
        >
          Book Appointment
        </button>
      </form>

      <h2 style={{ marginBottom: "20px" }}>Available Time Slots</h2>

      {availableSlots.length === 0 ? (
        <p style={{ textAlign: "center", padding: "20px" }}>No available time slots.</p>
      ) : (
        <div style={{ display: "flex", flexWrap: "wrap", gap: "15px" }}>
          {availableSlots.map(slot => {
            const counsellor = counsellors.find(c => c.id === slot.counsellorId);
            return (
              <div 
                key={slot.id} 
                style={{ 
                  border: "1px solid #ddd", 
                  borderRadius: "8px", 
                  padding: "15px", 
                  width: "200px", 
                  boxSizing: "border-box" 
                }}
              >
                <h3 style={{ margin: "0 0 10px 0" }}>
                  {counsellor?.name}
                </h3>
                <p style={{ margin: "5px 0" }}>
                  <strong>Date:</strong> {slot.date}
                </p>
                <p style={{ margin: "5px 0" }}>
                  <strong>Time:</strong> {slot.time}
                </p>
              </div>
            );
          })}
        </div>
      )}

      <h2 style={{ marginBottom: "20px", marginTop: "40px" }}>Your Appointments</h2>

      {bookings.length === 0 ? (
        <p style={{ textAlign: "center", padding: "20px" }}>You have no upcoming appointments.</p>
      ) : (
        <div style={{ display: "flex", flexWrap: "wrap", gap: "15px" }}>
          {bookings.map(booking => (
            <div 
              key={booking.id} 
              style={{ 
                border: "1px solid #ddd", 
                borderRadius: "8px", 
                padding: "15px", 
                width: "200px", 
                boxSizing: "border-box" 
              }}
            >
              <h3 style={{ margin: "0 0 10px 0" }}>
                {booking.counsellorName}
              </h3>
              <p style={{ margin: "5px 0" }}>
                <strong>Date:</strong> {booking.date}
              </p>
              <p style={{ margin: "5px 0" }}>
                <strong>Time:</strong> {booking.time}
              </p>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

