import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

const SESSION_TIMEOUT = 30 * 60 * 1000; // 30 minutes
const ACTIVE_SESSIONS = new Map<string, { expiresAt: number }>();

function getSessionIdFromRequest(req: Request): string | null {
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    return null;
  }

  const token = authHeader.substring(7);
  return token;
}

function verifyTokenSignature(token: string): boolean {
  const secret = process.env.JWT_SECRET;
  if (!secret) {
    return false;
  }

  try {
    const [payload, signature] = token.split(".");
    if (!payload || !signature) {
      return false;
    }

    const expectedSignature = createHmac("sha256", secret)
      .update(payload)
      .digest("base64url");

    const signatureBuffer = Buffer.from(signature, "base64url");
    const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");

    return timingSafeEqual(signatureBuffer, expectedSignatureBuffer);
  } catch {
    return false;
  }
}

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only handle POST /logout requests
  if (req.method !== "POST" || req.path !== "/logout") {
    next();
    return;
  }

  const sessionId = getSessionIdFromRequest(req);
  if (!sessionId) {
    return res.status(401).json({ error: "No active session" });
  }

  if (!verifyTokenSignature(sessionId)) {
    return res.status(401).json({ error: "Invalid session" });
  }

  const session = ACTIVE_SESSIONS.get(sessionId);
  if (!session) {
    return res.status(401).json({ error: "Invalid session" });
  }

  if (Date.now() > session.expiresAt) {
    ACTIVE_SESSIONS.delete(sessionId);
    return res.status(401).json({ error: "Session expired" });
  }

  ACTIVE_SESSIONS.delete(sessionId);
  return res.json({ message: "Logged out successfully" });
}

import type { Request, Response, NextFunction } from "express";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Skip validation for GET requests without body
  if (req.method === "GET" && !req.body) {
    return next();
  }

  // Only validate POST, PUT, PATCH requests
  if (!['POST', 'PUT', 'PATCH'].includes(req.method)) {
    return next();
  }

  // Basic input sanitization and validation
  const sanitizeInput = (input: any): any => {
    if (typeof input === 'string') {
      // Remove potentially dangerous characters
      return input.replace(/[<>'"&]/g, '');
    }
    if (Array.isArray(input)) {
      return input.map(sanitizeInput);
    }
    if (typeof input === 'object' && input !== null) {
      const sanitized: any = {};
      for (const [key, value] of Object.entries(input)) {
        sanitized[key] = sanitizeInput(value);
      }
      return sanitized;
    }
    return input;
  };

  // Sanitize request body
  if (req.body) {
    req.body = sanitizeInput(req.body);
  }

  // Sanitize query parameters
  if (req.query) {
    req.query = sanitizeInput(req.query);
  }

  // Sanitize URL parameters
  if (req.params) {
    req.params = sanitizeInput(req.params);
  }

  next();
}

import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock user database
const users: { id: number; username: string; password: string }[] = [];
let nextId = 1;

// Mock session storage
const sessions: { sessionId: string; userId: number }[] = [];

// Helper to generate session ID
const generateSessionId = (): string => {
  return Math.random().toString(36).substring(2, 15);
};

// Registration endpoint
router.post("/register", (req: Request, res: Response): void => {
  const { username, password } = req.body;

  // Validate input
  if (!username || !password) {
    res.status(400).json({ error: "Username and password are required" });
    return;
  }

  // Check if user already exists
  const existingUser = users.find(user => user.username === username);
  if (existingUser) {
    res.status(400).json({ error: "User already exists" });
    return;
  }

  // Create new user
  const newUser = {
    id: nextId++,
    username,
    password
  };

  users.push(newUser);

  res.status(201).json({ message: "User registered successfully" });
});

// Login endpoint
router.post("/login", (req: Request, res: Response): void => {
  const { username, password } = req.body;

  // Validate input
  if (!username || !password) {
    res.status(400).json({ error: "Username and password are required" });
    return;
  }

  // Find user
  const user = users.find(u => u.username === username && u.password === password);
  if (!user) {
    res.status(401).json({ error: "Invalid credentials" });
    return;
  }

  // Generate session
  const sessionId = generateSessionId();
  sessions.push({ sessionId, userId: user.id });

  res.json({ sessionId });
});

// Session management endpoint
router.get("/session", (req: Request, res: Response): void => {
  const sessionId = req.headers["x-session-id"] as string;

  if (!sessionId) {
    res.status(401).json({ error: "No session ID provided" });
    return;
  }

  const session = sessions.find(s => s.sessionId === sessionId);
  if (!session) {
    res.status(401).json({ error: "Invalid session" });
    return;
  }

  res.json({ userId: session.userId });
});

