// Get a specific show by ID
router.get("/:id", (req: Request, res: Response) => {
  const showId = req.params.id;
  const show = shows.find(s => s.id === showId);

  if (!show) {
    return res.status(404).json({ error: "Show not found" });
  }

  res.json(show);
});

// Create a new show
router.post("/", (req: Request, res: Response) => {
  const { title, venue, date, time, totalSeats, availableSeats } = req.body;

  // Basic validation
  if (!title || !venue || !date || !time || !totalSeats || !availableSeats) {
    return res.status(400).json({ error: "Missing required fields" });
  }

  const newShow = {
    id: String(shows.length + 1),
    title,
    venue,
    date,
    time,
    totalSeats: Number(totalSeats),
    availableSeats: Number(availableSeats)
  };

  shows.push(newShow);
  res.status(201).json(newShow);
});

// Update a show
router.put("/:id", (req: Request, res: Response) => {
  const showId = req.params.id;
  const { title, venue, date, time, totalSeats, availableSeats } = req.body;

  const showIndex = shows.findIndex(s => s.id === showId);

  if (showIndex === -1) {
    return res.status(404).json({ error: "Show not found" });
  }

  // Basic validation
  if (!title || !venue || !date || !time || !totalSeats || !availableSeats) {
    return res.status(400).json({ error: "Missing required fields" });
  }

  shows[showIndex] = {
    id: showId,
    title,
    venue,
    date,
    time,
    totalSeats: Number(totalSeats),
    availableSeats: Number(availableSeats)
  };

  res.json(shows[showIndex]);
});

// Delete a show
router.delete("/:id", (req: Request, res: Response) => {
  const showId = req.params.id;
  const showIndex = shows.findIndex(s => s.id === showId);

  if (showIndex === -1) {
    return res.status(404).json({ error: "Show not found" });
  }

  shows.splice(showIndex, 1);
  res.json({ message: "Show deleted successfully" });
});

