import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

const JWT_SECRET = process.env.JWT_SECRET;

function decodeJwt(token: string): Record<string, unknown> | null {
  try {
    const payload = token.split('.')[1];
    const decoded = Buffer.from(payload, 'base64').toString('utf-8');
    return JSON.parse(decoded);
  } catch {
    return null;
  }
}

function verifySignature(token: string, secret: string): boolean {
  const [header, payload, signature] = token.split('.');

  if (!header || !payload || !signature) {
    return false;
  }

  const expectedSignature = createHmac('sha256', secret)
    .update(`${header}.${payload}`)
    .digest('base64url');

  const actualSignature = signature;

  try {
    return timingSafeEqual(
      Buffer.from(actualSignature, 'base64url'),
      Buffer.from(expectedSignature, 'base64url')
    );
  } catch {
    return false;
  }
}

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process POST requests to /login endpoint
  if (!(req.method === 'POST' && req.path === '/login')) {
    next();
    return;
  }

  // Check if JWT_SECRET is set
  if (!JWT_SECRET) {
    res.status(500).json({ error: 'Server configuration error' });
    return;
  }

  // Get token from Authorization header
  const authHeader = req.headers.authorization;

  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    res.status(401).json({ error: 'Missing or invalid authorization header' });
    return;
  }

  const token = authHeader.substring(7); // Remove 'Bearer '

  // Verify token structure
  if (!token.includes('.')) {
    res.status(401).json({ error: 'Invalid token format' });
    return;
  }

  // Decode token
  const decoded = decodeJwt(token);

  if (!decoded) {
    res.status(401).json({ error: 'Invalid token' });
    return;
  }

  // Verify signature
  if (!verifySignature(token, JWT_SECRET)) {
    res.status(401).json({ error: 'Invalid token signature' });
    return;
  }

  // Token is valid, proceed
  next();
}

import type { Request, Response, NextFunction } from "express";
import { createHash } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process POST requests to the /users endpoint
  if (req.method !== "POST" || req.path !== "/users") {
    next();
    return;
  }

  // Check if password exists in request body
  if (!req.body || typeof req.body.password !== "string") {
    next();
    return;
  }

  // Hash the password using SHA-256
  const hashedPassword = createHash("sha256").update(req.body.password).digest("hex");

  // Replace the plain text password with the hashed one
  req.body.password = hashedPassword;

  next();
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply role-based access control to POST requests to /book-seat
  if (req.method !== "POST" || req.path !== "/book-seat") {
    next();
    return;
  }

  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized: Missing or invalid token" });
    return;
  }

  const token = authHeader.substring(7);
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: "Internal Server Error: JWT_SECRET not configured" });
    return;
  }

  // Simple token validation - in a real app, you'd decode and verify the JWT properly
  const [payload, signature] = token.split(".");
  if (!payload || !signature) {
    res.status(401).json({ error: "Unauthorized: Invalid token format" });
    return;
  }

  // Recreate the signature using the same algorithm (HMAC-SHA256)
  const expectedSignature = createHmac("sha256", secret)
    .update(payload)
    .digest("base64url");

  // Use timingSafeEqual to prevent timing attacks
  const expectedBuffer = Buffer.from(expectedSignature);
  const actualBuffer = Buffer.from(signature);

  if (actualBuffer.length !== expectedBuffer.length || !timingSafeEqual(actualBuffer, expectedBuffer)) {
    res.status(401).json({ error: "Unauthorized: Invalid token signature" });
    return;
  }

  // Parse payload to extract role (simplified)
  try {
    const decodedPayload = Buffer.from(payload, "base64url").toString("utf-8");
    const payloadObj = JSON.parse(decodedPayload);

    if (!payloadObj.role) {
      res.status(403).json({ error: "Forbidden: Role not specified in token" });
      return;
    }

    // Check if user has required role
    if (payloadObj.role === "admin" || payloadObj.role === "booking-agent") {
      next();
    } else {
      res.status(403).json({ error: "Forbidden: Insufficient permissions" });
    }
  } catch (err) {
    res.status(401).json({ error: "Unauthorized: Invalid token payload" });
  }
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process POST, PUT, PATCH, DELETE requests
  if (!['POST', 'PUT', 'PATCH', 'DELETE'].includes(req.method)) {
    next();
    return;
  }

  // Validate and sanitize input data
  if (req.body) {
    sanitizeInput(req.body);
  }

  // Validate query parameters
  if (req.query) {
    sanitizeQuery(req.query);
  }

  next();
}

function sanitizeInput(input: any): void {
  if (typeof input === 'object' && input !== null) {
    for (const [key, value] of Object.entries(input)) {
      if (typeof value === 'string') {
        // Remove potentially dangerous characters
        input[key] = value.replace(/[<>'"&]/g, '');
      } else if (typeof value === 'object') {
        sanitizeInput(value);
      }
    }
  }
}

function sanitizeQuery(query: Record<string, any>): void {
  for (const [key, value] of Object.entries(query)) {
    if (typeof value === 'string') {
      // Remove potentially dangerous characters
      query[key] = value.replace(/[<>'"&]/g, '');
    }
  }
}

