import { useEffect, useState } from "react";

interface Show {
  id: string;
  title: string;
  description: string;
  date: string;
  time: string;
  venue: string;
  price: number;
}

interface Seat {
  id: string;
  row: string;
  number: number;
  isAvailable: boolean;
}

export function ShowDetailsPage({ showId }: { showId: string }) {
  const [show, setShow] = useState<Show | null>(null);
  const [seats, setSeats] = useState<Seat[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [selectedSeats, setSelectedSeats] = useState<string[]>([]);

  useEffect(() => {
    async function fetchShowDetails() {
      try {
        const response = await fetch(`/api/shows/${showId}`);
        if (!response.ok) {
          throw new Error(`Failed to fetch show details: ${response.status}`);
        }
        const showData: Show = await response.json();
        setShow(showData);

        const seatsResponse = await fetch(`/api/shows/${showId}/seats`);
        if (!seatsResponse.ok) {
          throw new Error(`Failed to fetch seats: ${seatsResponse.status}`);
        }
        const seatsData: Seat[] = await seatsResponse.json();
        setSeats(seatsData);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
      } finally {
        setLoading(false);
      }
    }

    fetchShowDetails();
  }, [showId]);

  const handleSeatSelect = (seatId: string) => {
    setSelectedSeats(prev => 
      prev.includes(seatId) 
        ? prev.filter(id => id !== seatId) 
        : [...prev, seatId]
    );
  };

  const handleBooking = async () => {
    if (selectedSeats.length === 0) return;

    try {
      const response = await fetch(`/api/bookings`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          showId,
          seatIds: selectedSeats
        })
      });

      if (!response.ok) {
        throw new Error("Failed to book seats");
      }

      // Reset selection after successful booking
      setSelectedSeats([]);

      // Refresh seat data
      const seatsResponse = await fetch(`/api/shows/${showId}/seats`);
      if (seatsResponse.ok) {
        const seatsData: Seat[] = await seatsResponse.json();
        setSeats(seatsData);
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
  }

  if (!show) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Show not found</div>;
  }

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>{show.title}</h1>
      <p style={{ textAlign: "center" }}>{show.description}</p>
      <div style={{ textAlign: "center", marginBottom: "20px" }}>
        <p><strong>Date:</strong> {show.date}</p>
        <p><strong>Time:</strong> {show.time}</p>
        <p><strong>Venue:</strong> {show.venue}</p>
        <p><strong>Price:</strong> ${show.price.toFixed(2)}</p>
      </div>

      <h2 style={{ textAlign: "center" }}>Seating Chart</h2>
      <div style={{ display: "flex", flexWrap: "wrap", justifyContent: "center", gap: "10px", marginBottom: "20px" }}>
        {seats.map(seat => (
          <div
            key={seat.id}
            onClick={() => handleSeatSelect(seat.id)}
            style={{
              width: "40px",
              height: "40px",
              border: "1px solid #ccc",
              borderRadius: "5px",
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              cursor: "pointer",
              backgroundColor: selectedSeats.includes(seat.id) 
                ? "#007bff" 
                : seat.isAvailable 
                  ? "#f8f9fa" 
                  : "#dc3545",
              color: selectedSeats.includes(seat.id) || !seat.isAvailable ? "white" : "black"
            }}
          >
            {seat.row}{seat.number}
          </div>
        ))}
      </div>

      <div style={{ textAlign: "center" }}>
        <button
          onClick={handleBooking}
          disabled={selectedSeats.length === 0}
          style={{
            backgroundColor: selectedSeats.length === 0 ? "#6c757d" : "#28a745",
            color: "white",
            border: "none",
            padding: "10px 20px",
            borderRadius: "5px",
            cursor: selectedSeats.length === 0 ? "default" : "pointer",
            fontSize: "16px"
          }}
        >
          Book Selected Seats (${(selectedSeats.length * show.price).toFixed(2)})
        </button>
      </div>
    </div>
  );
}

