export function BookingForm() {
  const [selectedSeats, setSelectedSeats] = useState<number[]>([]);
  const [isLoading, setIsLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);

  // Mock data for demonstration
  const mockSeats = Array.from({ length: 50 }, (_, i) => i + 1);

  useEffect(() => {
    // Simulate API call
    const timer = setTimeout(() => {
      setIsLoading(false);
    }, 500);

    return () => clearTimeout(timer);
  }, []);

  const handleSeatSelect = (seatNumber: number) => {
    if (selectedSeats.includes(seatNumber)) {
      setSelectedSeats(selectedSeats.filter(id => id !== seatNumber));
    } else {
      setSelectedSeats([...selectedSeats, seatNumber]);
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    // In a real app, this would make an API call
    alert(`Booking confirmed for seats: ${selectedSeats.join(', ')}`);
  };

  if (isLoading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ color: 'red', textAlign: 'center', padding: '20px' }}>{error}</div>;
  }

  return (
    <div style={{
      maxWidth: '800px',
      margin: '0 auto',
      padding: '20px',
      fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif'
    }}>
      <h1 style={{ textAlign: 'center' }}>Book Your Seats</h1>

      <div style={{ marginBottom: '20px' }}>
        <h2>Available Seats</h2>
        <div style={{ display: 'flex', flexWrap: 'wrap', gap: '10px' }}>
          {mockSeats.map(seat => (
            <button
              key={seat}
              onClick={() => handleSeatSelect(seat)}
              style={{
                padding: '10px 15px',
                border: '1px solid #ccc',
                borderRadius: '5px',
                backgroundColor: selectedSeats.includes(seat) ? '#4CAF50' : '#f0f0f0',
                color: selectedSeats.includes(seat) ? 'white' : 'black',
                cursor: 'pointer',
                flex: '1 1 calc(20% - 10px)',
                minWidth: '60px',
                textAlign: 'center'
              }}
            >
              {seat}
            </button>
          ))}
        </div>
      </div>

      <form onSubmit={handleSubmit} style={{ marginTop: '20px' }}>
        <div style={{ marginBottom: '15px' }}>
          <label htmlFor="name" style={{ display: 'block', marginBottom: '5px' }}>
            Full Name
          </label>
          <input
            type="text"
            id="name"
            required
            style={{
              width: '100%',
              padding: '10px',
              border: '1px solid #ccc',
              borderRadius: '5px',
              boxSizing: 'border-box'
            }}
          />
        </div>

        <div style={{ marginBottom: '15px' }}>
          <label htmlFor="email" style={{ display: 'block', marginBottom: '5px' }}>
            Email Address
          </label>
          <input
            type="email"
            id="email"
            required
            style={{
              width: '100%',
              padding: '10px',
              border: '1px solid #ccc',
              borderRadius: '5px',
              boxSizing: 'border-box'
            }}
          />
        </div>

        <div style={{ marginBottom: '15px' }}>
          <label htmlFor="phone" style={{ display: 'block', marginBottom: '5px' }}>
            Phone Number
          </label>
          <input
            type="tel"
            id="phone"
            required
            style={{
              width: '100%',
              padding: '10px',
              border: '1px solid #ccc',
              borderRadius: '5px',
              boxSizing: 'border-box'
            }}
          />
        </div>

        <div style={{ marginBottom: '20px' }}>
          <p style={{ fontWeight: 'bold' }}>
            Selected Seats: {selectedSeats.length > 0 ? selectedSeats.join(', ') : 'None'}
          </p>
        </div>

        <button
          type="submit"
          disabled={selectedSeats.length === 0}
          style={{
            backgroundColor: selectedSeats.length > 0 ? '#2196F3' : '#ccc',
            color: 'white',
            border: 'none',
            padding: '12px 20px',
            borderRadius: '5px',
            cursor: selectedSeats.length > 0 ? 'pointer' : 'default',
            fontSize: '16px',
            width: '100%'
          }}
        >
          Confirm Booking
        </button>
      </form>
    </div>
  );
}

