import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock database functions - in a real app these would connect to a database
const mockFreelancerDB = {
  getAll: (): Promise<any[]> => Promise.resolve([
    { id: 1, name: "John Doe", skills: ["JavaScript", "TypeScript"], portfolio: [], rating: 4.8, availability: true },
    { id: 2, name: "Jane Smith", skills: ["Python", "Django"], portfolio: [], rating: 4.9, availability: false }
  ]),
  getById: (id: number): Promise<any | null> => Promise.resolve(
    id === 1 ? { id: 1, name: "John Doe", skills: ["JavaScript", "TypeScript"], portfolio: [], rating: 4.8, availability: true } : null
  ),
  create: (freelancer: any): Promise<any> => Promise.resolve({ id: 3, ...freelancer }),
  update: (id: number, updates: any): Promise<any | null> => Promise.resolve(
    id === 1 ? { id: 1, ...updates } : null
  ),
  delete: (id: number): Promise<boolean> => Promise.resolve(true)
};

// GET /freelancers - List all freelancers
router.get("/freelancers", async (req: Request, res: Response) => {
  try {
    const freelancers = await mockFreelancerDB.getAll();
    return res.json(freelancers);
  } catch (error) {
    return res.status(500).json({ error: "Internal server error" });
  }
});

// GET /freelancers/:id - Get a specific freelancer by ID
router.get("/freelancers/:id", async (req: Request, res: Response) => {
  const id = Number(req.params.id);
  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid freelancer ID" });
  }

  try {
    const freelancer = await mockFreelancerDB.getById(id);
    if (!freelancer) {
      return res.status(404).json({ error: "Freelancer not found" });
    }
    return res.json(freelancer);
  } catch (error) {
    return res.status(500).json({ error: "Internal server error" });
  }
});

// POST /freelancers - Create a new freelancer
router.post("/freelancers", async (req: Request, res: Response) => {
  const { name, skills, portfolio, rating, availability } = req.body;

  if (!name || !skills || !Array.isArray(skills)) {
    return res.status(400).json({ error: "Name and skills are required" });
  }

  try {
    const newFreelancer = await mockFreelancerDB.create({
      name,
      skills,
      portfolio: portfolio || [],
      rating: rating || 0,
      availability: availability !== undefined ? availability : true
    });
    return res.status(201).json(newFreelancer);
  } catch (error) {
    return res.status(500).json({ error: "Internal server error" });
  }
});

// PUT /freelancers/:id - Update a freelancer
router.put("/freelancers/:id", async (req: Request, res: Response) => {
  const id = Number(req.params.id);
  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid freelancer ID" });
  }

  const { name, skills, portfolio, rating, availability } = req.body;

  try {
    const updatedFreelancer = await mockFreelancerDB.update(id, {
      name,
      skills,
      portfolio,
      rating,
      availability
    });

    if (!updatedFreelancer) {
      return res.status(404).json({ error: "Freelancer not found" });
