import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process POST requests to /login endpoint
  if (req.method !== "POST" || req.path !== "/login") {
    next();
    return;
  }

  const jwtSecret = process.env.JWT_SECRET;

  if (!jwtSecret) {
    res.status(500).json({ error: "Internal server error" });
    return;
  }

  // In a real implementation, we would verify the JWT token here
  // For now, we'll just simulate the verification process
  // This is a placeholder for actual JWT verification logic

  // Simulate token verification
  const token = req.headers.authorization?.split(" ")[1];

  if (!token) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  // Verify token signature (simplified example)
  try {
    const secretBuffer = Buffer.from(jwtSecret);
    const tokenParts = token.split(".");

    if (tokenParts.length < 2) {
      res.status(401).json({ error: "Invalid token" });
      return;
    }

    const headerAndPayload = tokenParts[0] + "." + tokenParts[1];
    const signature = tokenParts[2];

    const expectedSignature = createHmac("sha256", secretBuffer)
      .update(headerAndPayload)
      .digest("base64");

    const signatureBuffer = Buffer.from(signature, "base64");
    const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64");

    if (signatureBuffer.length !== expectedSignatureBuffer.length) {
      res.status(401).json({ error: "Invalid token" });
      return;
    }

    const isValid = timingSafeEqual(signatureBuffer, expectedSignatureBuffer);

    if (!isValid) {
      res.status(401).json({ error: "Invalid token" });
      return;
    }

    next();
  } catch (error) {
    res.status(401).json({ error: "Invalid token" });
  }
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only enforce role-based access control on specific routes
  const protectedPaths = [
    "/api/projects",
    "/api/projects/:id",
    "/api/profiles",
    "/api/profiles/:id",
    "/api/contracts",
    "/api/contracts/:id"
  ];

  const isProtectedPath = protectedPaths.some(path => {
    if (path.includes(":")) {
      const pathWithoutParams = path.replace(/:\w+/g, ".*");
      const regex = new RegExp(`^${pathWithoutParams}$`);
      return regex.test(req.path);
    }
    return req.path === path;
  });

  // Skip validation for non-protected paths
  if (!isProtectedPath) {
    next();
    return;
  }

  // Check if user has required role
  const userRole = req.headers["x-user-role"] as string | undefined;
  const userId = req.headers["x-user-id"] as string | undefined;

  if (!userId || !userRole) {
    res.status(401).json({ error: "Unauthorized: Missing user information" });
    return;
  }

  // Validate role
  if (userRole !== "client" && userRole !== "freelancer") {
    res.status(403).json({ error: "Forbidden: Invalid user role" });
    return;
  }

  // Allow access for all valid users on these endpoints
  next();
}

