import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only protect POST /login endpoint
  if (req.method !== "POST" || req.path !== "/login") {
    next();
    return;
  }

  // Check if JWT_SECRET is set
  const secret = process.env.JWT_SECRET;
  if (!secret) {
    res.status(500).json({ error: "Server configuration error" });
    return;
  }

  // Check if request has authorization header
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Missing or invalid authorization header" });
    return;
  }

  const token = authHeader.substring(7); // Remove 'Bearer '

  // Simple token validation (in a real app, you'd decode and verify JWT)
  try {
    // This is a simplified example - in practice, you'd verify the JWT signature
    const expectedSignature = createHmac("sha256", secret)
      .update(token.split(".")[0] + "." + token.split(".")[1])
      .digest();

    const actualSignature = Buffer.from(token.split(".")[2], "base64");

    if (actualSignature.length !== expectedSignature.length) {
      res.status(401).json({ error: "Invalid token" });
      return;
    }

    const isValid = timingSafeEqual(expectedSignature, actualSignature);

    if (!isValid) {
      res.status(401).json({ error: "Invalid token" });
      return;
    }
  } catch (err) {
    res.status(401).json({ error: "Invalid token" });
    return;
  }

  next();
}

import type { Request, Response, NextFunction } from "express";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply role-based access control to complaint management routes
  const isComplaintRoute = req.path.startsWith('/complaints') && 
                          (req.method === 'POST' || 
                           req.method === 'PUT' || 
                           req.method === 'DELETE');

  if (!isComplaintRoute) {
    next();
    return;
  }

  // Check if user has required role
  const userRole = req.headers['x-user-role'] as string | undefined;

  if (!userRole) {
    res.status(401).json({ error: 'Unauthorized: Missing role header' });
    return;
  }

  // Allow only admin and staff roles to access complaint management
  if (userRole !== 'admin' && userRole !== 'staff') {
    res.status(403).json({ error: 'Forbidden: Insufficient permissions' });
    return;
  }

  next();
}

import type { Request, Response, NextFunction } from "express";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process POST, PUT, PATCH requests with a body
  if (!req.body || (req.method !== 'POST' && req.method !== 'PUT' && req.method !== 'PATCH')) {
    next();
    return;
  }

  // Sanitize input fields
  const sanitizeInput = (input: any): any => {
    if (typeof input === 'string') {
      // Remove potentially dangerous HTML tags
      let sanitized = input
        .replace(/<form[^<]*(?:(?!<\/form>)<[^<]*)*<\/form>/gi, '')
        .replace(/<meta[^<]*(?:(?!<\/meta>)<[^<]*)*<\/meta>/gi, '')
        .replace(/<link[^<]*(?:(?!<\/link>)<[^<]*)*<\/link>/gi, '')
        .replace(/<base[^<]*(?:(?!<\/base>)<[^<]*)*<\/base>/gi, '')
        .replace(/<style[^<]*(?:(?!<\/style>)<[^<]*)*<\/style>/gi, '')
        .replace(/<script[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>/gi, '')
        .replace(/on\w+\s*=\s*["'][^"']*?["']/gi, '');

      // Additional sanitization for common XSS patterns
      sanitized = sanitized
        .replace(/<script[^>]*>.*?<\/script>/gi, '')
        .replace(/<iframe[^>]*>.*?<\/iframe>/gi, '')
        .replace(/<object[^>]*>.*?<\/object>/gi, '')
        .replace(/<embed[^>]*>.*?<\/embed>/gi, '')
        .replace(/<applet[^>]*>.*?<\/applet>/gi, '');

      return sanitized;
    } else if (Array.isArray(input)) {
      return input.map(sanitizeInput);
    } else if (typeof input === 'object' && input !== null) {
      const sanitizedObj: any = {};
      for (const key in input) {
        if (Object.prototype.hasOwnProperty.call(input, key)) {
          sanitizedObj[key] = sanitizeInput(input[key]);
        }
      }
      return sanitizedObj;
    }

    return input;
  };

  // Apply sanitization to request body
  req.body = sanitizeInput(req.body);

  next();
}

