import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock user data storage
const users = [
  { id: 1, username: "admin", password: "admin123", role: "admin" },
  { id: 2, username: "staff", password: "staff123", role: "staff" },
  { id: 3, username: "customer", password: "customer123", role: "customer" }
];

// Mock session storage
const sessions = new Map<string, { userId: number; role: string; expiresAt: Date }>();

// Login endpoint
router.post("/login", (req: Request, res: Response) => {
  const { username, password } = req.body;

  if (!username || !password) {
    return res.status(400).json({ error: "Username and password are required" });
  }

  const user = users.find(u => u.username === username && u.password === password);

  if (!user) {
    return res.status(401).json({ error: "Invalid credentials" });
  }

  // Generate session token
  const token = Math.random().toString(36).substring(2, 15);
  const expiresAt = new Date(Date.now() + 24 * 60 * 60 * 1000); // 24 hours

  sessions.set(token, {
    userId: user.id,
    role: user.role,
    expiresAt
  });

  return res.status(200).json({
    token,
    user: {
      id: user.id,
      username: user.username,
      role: user.role
    }
  });
});

// Logout endpoint
router.post("/logout", (req: Request, res: Response) => {
  const token = req.headers.authorization?.split(" ")[1];

  if (!token) {
    return res.status(400).json({ error: "Token is required" });
  }

  if (!sessions.has(token)) {
    return res.status(401).json({ error: "Invalid token" });
  }

  sessions.delete(token);
  return res.status(200).json({ message: "Logged out successfully" });
});

// Middleware to verify session
const authenticateSession = (req: Request, res: Response, next: Function) => {
  const token = req.headers.authorization?.split(" ")[1];

  if (!token) {
    return res.status(401).json({ error: "Authorization token is required" });
  }

  const session = sessions.get(token);

  if (!session) {
    return res.status(401).json({ error: "Invalid or expired token" });
  }

  // Check if session has expired
  if (new Date() > session.expiresAt) {
    sessions.delete(token);
    return res.status(401).json({ error: "Session expired" });
  }

  // Attach user info to request
  (req as any).user = {
    id: session.userId,
    role: session.role
  };

  next();
};

// Get current user info
router.get("/me", authenticateSession, (req: Request, res: Response) => {
  return res.status(200).json({
    id: (req as any).user.id,
    username: users.find(u => u.id === (req as any).user.id)?.username,
    role: (req as any).user.role
  });
});

// Role-based access control middleware
const requireRole = (requiredRole: string) => {
  return (req: Request, res: Response, next: Function) => {
    const userRole = (req as any).user?.role;

    if (!userRole || userRole !== requiredRole) {
      return res.status(403).json({ error: "Insufficient permissions" });
    }

    next();
  };
};

// Admin-only route example
router.get("/admin", authenticateSession, requireRole("admin"), (req: Request, res: Response) => {
  return res.status(200).json({ message: "Admin access granted" });
});

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

const SECRET = process.env.JWT_SECRET;

function getBearerToken(req: Request): string | null {
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    return null;
  }
  return authHeader.substring(7);
}

function verifyToken(token: string): boolean {
  if (!SECRET) return false;

  const expectedSignature = createHmac("sha256", SECRET)
    .update(token.split(".")[0] + "." + token.split(".")[1])
    .digest();

  const actualSignature = Buffer.from(token.split(".")[2], "base64");

  try {
    return timingSafeEqual(expectedSignature, actualSignature);
  } catch {
    return false;
  }
}

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only protect POST /sessions and PUT /sessions routes
  if (!(req.method === "POST" && req.path === "/sessions") && 
      !(req.method === "PUT" && req.path === "/sessions")) {
    next();
    return;
  }

  const token = getBearerToken(req);
  if (!token || !verifyToken(token)) {
    res.status(403).json({ error: "Forbidden" });
    return;
  }

  next();
}

