import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

const JWT_SECRET = process.env.JWT_SECRET;

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check session timeout for routes that require authentication
  // This middleware should only run on protected routes
  const protectedPaths = ["/dashboard", "/profile", "/billing"];
  const isProtectedRoute = protectedPaths.some(path =>
    req.path.startsWith(path)
  );

  if (!isProtectedRoute) {
    next();
    return;
  }

  // Check if user is authenticated via JWT token in Authorization header
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const token = authHeader.substring(7); // Remove "Bearer " prefix

  if (!JWT_SECRET) {
    res.status(500).json({ error: "Server configuration error" });
    return;
  }

  try {
    // Basic token structure validation
    const parts = token.split(".");
    if (parts.length !== 3) {
      res.status(401).json({ error: "Invalid token format" });
      return;
    }

    // Verify token signature
    const [header, payload, signature] = parts;
    const expectedSignature = createHmac("sha256", JWT_SECRET)
      .update(`${header}.${payload}`)
      .digest("base64url");

    const signatureBuffer = Buffer.from(signature, "base64url");
    const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");

    if (!timingSafeEqual(signatureBuffer, expectedSignatureBuffer)) {
      res.status(401).json({ error: "Invalid token signature" });
      return;
    }

    // Decode payload to check expiration
    const decodedPayload = JSON.parse(
      Buffer.from(payload, "base64url").toString()
    );

    const currentTime = Math.floor(Date.now() / 1000);
    if (decodedPayload.exp < currentTime) {
      res.status(401).json({ error: "Session expired" });
      return;
    }

    // If we get here, the session is valid
    next();
  } catch (error) {
    res.status(401).json({ error: "Invalid token" });
  }
}

