import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply role-based access control to protected routes
  if (!req.path.startsWith('/api/')) {
    next();
    return;
  }

  // Check if user is authenticated via Authorization header
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    res.status(401).json({ error: 'Unauthorized' });
    return;
  }

  const token = authHeader.substring(7);
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: 'Server configuration error' });
    return;
  }

  // Simple token validation (in a real app, you'd decode and verify properly)
  try {
    const [payload, signature] = token.split('.');
    if (!payload || !signature) {
      res.status(401).json({ error: 'Invalid token format' });
      return;
    }

    // Reconstruct signature for verification
    const expectedSignature = createHmac('sha256', secret)
      .update(payload)
      .digest('base64url');

    // Use timingSafeEqual to prevent timing attacks
    const isValid = timingSafeEqual(
      Buffer.from(signature, 'base64url'),
      Buffer.from(expectedSignature, 'base64url')
    );

    if (!isValid) {
      res.status(401).json({ error: 'Invalid token' });
      return;
    }

    // Parse payload to get user role and ID
    const payloadBuffer = Buffer.from(payload, 'base64url');
    const payloadStr = payloadBuffer.toString('utf8');
    const payloadObj = JSON.parse(payloadStr);

    const { role, userId } = payloadObj;

    if (!role || !userId) {
      res.status(401).json({ error: 'Invalid token payload' });
      return;
    }

    // Store user info in request for later use
    (req as any).user = { role, userId };

    // Apply role-based access control
    if (role === 'parent') {
      // Parents can only access their own children's meetings
      if (req.path.includes('/meetings/') && req.params.childId) {
        // In a real implementation, we would check if the parent owns this child
        // For now, we'll just allow the request to proceed
        // This is a simplified version - in practice, you'd need to verify
        // that the parent ID matches the child's parent ID
      }

      // Allow parents to access their own data
      if (req.path.includes('/children/') && req.params.childId) {
        // Additional validation would go here
      }
    } else if (role === 'teacher') {
      // Teachers can access all meetings
      // No additional restrictions needed
    } else {
      res.status(403).json({ error: 'Forbidden' });
      return;
    }

    next();
  } catch (error) {
    res.status(401).json({ error: 'Invalid token' });
  }
}

import type { Request, Response, NextFunction } from "express";
import { createHash, scryptSync, randomBytes, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // This middleware is designed to hash passwords during user registration
  // It should only process POST requests to the /register endpoint
  if (req.method !== "POST" || req.path !== "/register") {
    next();
    return;
  }

  // Check if password exists in request body
  if (!req.body || typeof req.body.password !== "string") {
    next();
    return;
  }

  // Hash the password using scrypt
  const salt = randomBytes(16).toString("hex");
  const key = scryptSync(req.body.password, salt, 32);
  const hashedPassword = key.toString("hex");

  // Replace the password with the hashed version
  req.body.password = hashedPassword;
  req.body.salt = salt;

  next();
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only handle POST requests to /logout
  if (req.method !== "POST" || req.path !== "/logout") {
    next();
    return;
  }

  const token = req.headers.authorization?.split(" ")[1];

  if (!token) {
    return res.status(401).json({ error: "Unauthorized" });
  }

  const secret = process.env.JWT_SECRET;

  if (!secret) {
    return res.status(500).json({ error: "Server configuration error" });
  }

  try {
    const [payload, signature] = token.split(".");
    const expectedSignature = createHmac("sha256", secret)
      .update(payload)
      .digest("base64url");

    const signatureBuffer = Buffer.from(signature, "base64url");
    const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");

    if (signatureBuffer.length !== expectedSignatureBuffer.length) {
      return res.status(401).json({ error: "Invalid token" });
    }

    const isValid = timingSafeEqual(signatureBuffer, expectedSignatureBuffer);

    if (!isValid) {
      return res.status(401).json({ error: "Invalid token" });
    }

    next();
  } catch (error) {
    return res.status(401).json({ error: "Invalid token" });
  }
}

