  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const fetchMeetings = async () => {
      try {
        // Simulate API call
        await new Promise(resolve => setTimeout(resolve, 500));

        // Mock data
        const mockMeetings: Meeting[] = [
          { id: "1", date: "2023-06-15", parentName: "John Smith", childName: "Emma Smith" },
          { id: "2", date: "2023-06-16", parentName: "Sarah Johnson", childName: "Michael Johnson" },
          { id: "3", date: "2023-06-17", parentName: "Robert Brown", childName: "Olivia Brown" },
          { id: "4", date: "2023-06-18", parentName: "Emily Davis", childName: "William Davis" },
        ];

        setMeetings(mockMeetings);
        setFilteredMeetings(mockMeetings);
        setLoading(false);
      } catch (err) {
        setError("Failed to load meetings");
        setLoading(false);
      }
