    fetchMeetings();
  }, []);

  useEffect(() => {
    let result = meetings;

    if (searchTerm) {
      const term = searchTerm.toLowerCase();
      result = result.filter(meeting => 
        meeting.parentName.toLowerCase().includes(term) ||
        meeting.childName.toLowerCase().includes(term)
      );
    }

    if (dateFilter) {
      result = result.filter(meeting => meeting.date === dateFilter);
    }

    setFilteredMeetings(result);
  }, [searchTerm, dateFilter, meetings]);

  const handleSearchChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setSearchTerm(e.target.value);
  };

  const handleDateFilterChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setDateFilter(e.target.value);
  };

  const clearFilters = () => {
    setSearchTerm("");
    setDateFilter("");
