import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock database functions - in a real app these would be actual database calls
const mockCampaigns = [
  { id: 1, name: "Summer Sale", subject: "Great Summer Deals", status: "sent", sentDate: "2023-06-15" },
  { id: 2, name: "New Product Launch", subject: "Introducing Our Latest Product", status: "draft", sentDate: null }
];

const getCampaignById = (id: number) => {
  return mockCampaigns.find(campaign => campaign.id === id);
};

const createCampaign = (campaignData: any) => {
  const newCampaign = {
    id: mockCampaigns.length > 0 ? Math.max(...mockCampaigns.map(c => c.id)) + 1 : 1,
    name: campaignData.name,
    subject: campaignData.subject,
    status: campaignData.status || "draft",
    sentDate: null
  };
  mockCampaigns.push(newCampaign);
  return newCampaign;
};

const updateCampaign = (id: number, campaignData: any) => {
  const index = mockCampaigns.findIndex(campaign => campaign.id === id);
  if (index === -1) return null;

  mockCampaigns[index] = {
    ...mockCampaigns[index],
    ...campaignData
  };

  return mockCampaigns[index];
};

const deleteCampaign = (id: number) => {
  const index = mockCampaigns.findIndex(campaign => campaign.id === id);
  if (index === -1) return false;

  mockCampaigns.splice(index, 1);
  return true;
};

// GET /api/campaigns - List all campaigns
router.get("/", (req: Request, res: Response) => {
  res.json(mockCampaigns);
});

// GET /api/campaigns/:id - Get a specific campaign by ID
router.get("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid campaign ID" });
  }

  const campaign = getCampaignById(id);

  if (!campaign) {
    return res.status(404).json({ error: "Campaign not found" });
  }

  res.json(campaign);
});

// POST /api/campaigns - Create a new campaign
router.post("/", (req: Request, res: Response) => {
  const { name, subject, status } = req.body;

  if (!name || !subject) {
    return res.status(400).json({ error: "Name and subject are required" });
  }

  const newCampaign = createCampaign({ name, subject, status });

  res.status(201).json(newCampaign);
});

// PUT /api/campaigns/:id - Update a campaign
router.put("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const { name, subject, status, sentDate } = req.body;

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid campaign ID" });
  }

  const updatedCampaign = updateCampaign(id, { name, subject, status, sentDate });

  if (!updatedCampaign) {
    return res.status(404).json({ error: "Campaign not found" });
  }

  res.json(updatedCampaign);
});

// DELETE /api/campaigns/:id - Delete a campaign
router.delete("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid campaign ID" });
  }

  const deleted = deleteCampaign(id);

  if (!deleted) {
    return res.status(404).json({ error: "Campaign not found" });
  }

  res.json({ message: "Campaign deleted successfully" });
});

