import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only protect POST requests to /campaigns endpoint
  if (!(req.method === "POST" && req.path.startsWith("/campaigns"))) {
    next();
    return;
  }

  const authHeader = req.headers.authorization;

  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    return res.status(401).json({ error: "Unauthorized" });
  }

  const token = authHeader.substring(7);

  const secret = process.env.JWT_SECRET;

  if (!secret) {
    return res.status(500).json({ error: "Server configuration error" });
  }

  try {
    const [payload, signature] = token.split(".");

    if (!payload || !signature) {
      return res.status(401).json({ error: "Invalid token" });
    }

    const expectedSignature = createHmac("sha256", secret)
      .update(payload)
      .digest("base64url");

    const signatureBuffer = Buffer.from(signature, "base64url");
    const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");

    if (!timingSafeEqual(signatureBuffer, expectedSignatureBuffer)) {
      return res.status(401).json({ error: "Invalid token" });
    }

    // Basic payload validation - expecting role in the payload
    const decodedPayload = JSON.parse(Buffer.from(payload, "base64url").toString());

    if (!decodedPayload.role) {
      return res.status(401).json({ error: "Invalid token" });
    }

    // Check if user has required role
    if (decodedPayload.role !== "admin" && decodedPayload.role !== "manager") {
      return res.status(401).json({ error: "Unauthorized" });
    }

    next();
  } catch (error) {
    return res.status(401).json({ error: "Invalid token" });
  }
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

const SESSION_TIMEOUT = 30 * 60 * 1000; // 30 minutes
const TOKEN_HEADER = "x-auth-token";

interface SessionData {
  userId: string;
  sessionId: string;
  expiresAt: number;
}

function isValidToken(token: string): boolean {
  const secret = process.env.JWT_SECRET;
  if (!secret) return false;

  try {
    const [header, payload, signature] = token.split(".");
    if (!header || !payload || !signature) return false;

    const expectedSignature = createHmac("sha256", secret)
      .update(`${header}.${payload}`)
      .digest("base64url");

    const actualSignature = Buffer.from(signature, "base64url");
    const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");

    return timingSafeEqual(actualSignature, expectedSignatureBuffer);
  } catch {
    return false;
  }
}

function parseToken(token: string): SessionData | null {
  try {
    const [header, payload] = token.split(".");
    if (!header || !payload) return null;

    const decodedPayload = Buffer.from(payload, "base64url").toString();
    return JSON.parse(decodedPayload);
  } catch {
    return null;
  }
}

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process requests that require session validation
  if (req.method === "GET" && req.path === "/") {
    next();
    return;
  }

  const token = req.header(TOKEN_HEADER);
  if (!token) {
    res.status(401).json({ error: "No token provided" });
    return;
  }

  if (!isValidToken(token)) {
    res.status(401).json({ error: "Invalid token" });
    return;
  }

  const sessionData = parseToken(token);
  if (!sessionData) {
    res.status(401).json({ error: "Invalid token format" });
    return;
  }

  if (Date.now() > sessionData.expiresAt) {
    res.status(401).json({ error: "Session expired" });
    return;
  }

  // Attach session data to request object
  (req as any).session = sessionData;
  next();
}

