import { useEffect, useState } from "react";

interface Recipient {
  id: string;
  email: string;
  name: string;
  group: string;
}

interface Group {
  id: string;
  name: string;
}

export function RecipientsListPage() {
  const [recipients, setRecipients] = useState<Recipient[]>([]);
  const [groups, setGroups] = useState<Group[]>([]);
  const [searchTerm, setSearchTerm] = useState("");
  const [selectedGroup, setSelectedGroup] = useState("");
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  useEffect(() => {
    const fetchData = async () => {
      try {
        const [recipientsRes, groupsRes] = await Promise.all([
          fetch('/api/recipients'),
          fetch('/api/groups')
        ]);

        if (!recipientsRes.ok || !groupsRes.ok) {
          throw new Error('Failed to fetch data');
        }

        const recipientsData = await recipientsRes.json();
        const groupsData = await groupsRes.json();

        setRecipients(recipientsData);
        setGroups(groupsData);
      } catch (err) {
        setError('Failed to load recipients and groups');
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, []);

  const filteredRecipients = recipients.filter(recipient => {
    const matchesSearch = recipient.email.toLowerCase().includes(searchTerm.toLowerCase()) || 
                          recipient.name.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesGroup = selectedGroup === '' || recipient.group === selectedGroup;
    return matchesSearch && matchesGroup;
  });

  const handleDelete = async (id: string) => {
    try {
      const res = await fetch(`/api/recipients/${id}`, { method: 'DELETE' });
      if (res.ok) {
        setRecipients(recipients.filter(r => r.id !== id));
      }
    } catch (err) {
      setError('Failed to delete recipient');
    }
  };

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: '800px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1 style={{ textAlign: 'center' }}>Email Recipients</h1>

      <div style={{ marginBottom: '20px', display: 'flex', flexDirection: 'column', gap: '10px' }}>
        <input
          type="text"
          placeholder="Search recipients..."
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          style={{ width: '100%', padding: '8px', borderRadius: '4px', border: '1px solid #ccc' }}
        />

        <select
          value={selectedGroup}
          onChange={(e) => setSelectedGroup(e.target.value)}
          style={{ width: '100%', padding: '8px', borderRadius: '4px', border: '1px solid #ccc' }}
        >
          <option value="">All Groups</option>
          {groups.map(group => (
            <option key={group.id} value={group.id}>{group.name}</option>
          ))}
        </select>
      </div>

      {filteredRecipients.length === 0 ? (
        <p style={{ textAlign: 'center', padding: '20px' }}>No recipients found.</p>
      ) : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
          {filteredRecipients.map(recipient => (
            <div 
              key={recipient.id} 
              style={{ 
                border: '1px solid #ddd', 
                borderRadius: '8px', 
                padding: '15px', 
                display: 'flex', 
                justifyContent: 'space-between', 
                alignItems: 'center'
              }}
            >
              <div>
                <strong>{recipient.name}</strong><br />
                {recipient.email}<br />
                <small>Group: {recipient.group}</small>
              </div>
              <button 
                onClick={() => handleDelete(recipient.id)}
                style={{ 
                  backgroundColor: '#ff4d4d', 
                  color: 'white', 
                  border: 'none', 
                  borderRadius: '4px', 
                  padding: '8px 12px', 
                  cursor: 'pointer'
                }}
              >
                Remove
              </button>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

