export const router = Router();

// Mock database functions - in a real app these would connect to a database
const mockDatabase = {
  getAllClasses: async () => [
    { id: 1, name: "Yoga", schedule: "Mon 6PM", capacity: 15, instructor: "Jane Smith" },
    { id: 2, name: "Weight Training", schedule: "Tue 7PM", capacity: 10, instructor: "John Doe" }
  ],
  getClassById: async (id: number) => {
    const classes = await mockDatabase.getAllClasses();
    return classes.find(c => c.id === id) || null;
  },
  createClass: async (classData: Omit<Class, 'id'>) => {
    const classes = await mockDatabase.getAllClasses();
    const newClass = {
      id: classes.length > 0 ? Math.max(...classes.map(c => c.id)) + 1 : 1,
      ...classData
    };
    return newClass;
  },
  updateClass: async (id: number, classData: Partial<Omit<Class, 'id'>>) => {
    const classes = await mockDatabase.getAllClasses();
    const index = classes.findIndex(c => c.id === id);
    if (index === -1) return null;
    classes[index] = { ...classes[index], ...classData };
    return classes[index];
  },
  deleteClass: async (id: number) => {
    const classes = await mockDatabase.getAllClasses();
    const index = classes.findIndex(c => c.id === id);
    if (index === -1) return false;
    classes.splice(index, 1);
    return true;
  }
};

