import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply role-based access control to specific routes and methods
  const protectedPaths = ["/classes", "/bookings"];
  const protectedMethods = ["POST", "PUT", "DELETE"];

  const isProtectedPath = protectedPaths.some(path =>
    req.path.startsWith(path)
  );

  if (!isProtectedPath || !protectedMethods.includes(req.method)) {
    next();
    return;
  }

  // Check for authorization header
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized: Missing or invalid token" });
    return;
  }

  const token = authHeader.substring(7); // Remove 'Bearer '

  // Verify JWT signature
  const secret = process.env.JWT_SECRET;
  if (!secret) {
    res.status(500).json({ error: "Server configuration error: JWT_SECRET not set" });
    return;
  }

  try {
    // Simple verification - in a real app, use a proper JWT library
    const [header, payload, signature] = token.split(".");

    if (!header || !payload || !signature) {
      res.status(401).json({ error: "Unauthorized: Invalid token format" });
      return;
    }

    // Create expected signature
    const expectedSignature = createHmac("sha256", secret)
      .update(`${header}.${payload}`)
      .digest("base64url");

    // Use timingSafeEqual to prevent timing attacks
    const signatureBuffer = Buffer.from(signature, "base64url");
    const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");

    if (!timingSafeEqual(signatureBuffer, expectedSignatureBuffer)) {
      res.status(401).json({ error: "Unauthorized: Invalid token signature" });
      return;
    }

    // Decode payload to get user role
    const payloadStr = Buffer.from(payload, "base64url").toString();
    const payloadObj = JSON.parse(payloadStr);

    // Check if user has required role
    const userRole = payloadObj.role;
    if (!userRole) {
      res.status(403).json({ error: "Forbidden: User role not specified" });
      return;
    }

    // Allow only staff members to access protected routes
    if (userRole !== "staff") {
      res.status(403).json({ error: "Forbidden: Staff access required" });
      return;
    }

    // If we reach here, user is authorized
    next();
  } catch (error) {
    res.status(401).json({ error: "Unauthorized: Invalid token" });
  }
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process POST requests to /login endpoint
  if (req.method !== "POST" || req.path !== "/login") {
    next();
    return;
  }

  const jwtSecret = process.env.JWT_SECRET;

  if (!jwtSecret) {
    res.status(500).json({ error: "Server configuration error" });
    return;
  }

  // In a real implementation, we would verify the JWT token here
  // For now, we'll just check that the secret exists
  // This is a placeholder for actual JWT verification logic

  // Simulate token verification (in reality, this would decode and verify)
  const token = req.headers.authorization?.split(" ")[1];

  if (!token) {
    res.status(401).json({ error: "No token provided" });
    return;
  }

  // Verify token signature using HMAC-SHA256
  try {
    const expectedSignature = createHmac("sha256", jwtSecret)
      .update(token.split(".")[0] + "." + token.split(".")[1])
      .digest("hex");

    const actualSignature = token.split(".")[2];

    const isValid = timingSafeEqual(
      Buffer.from(expectedSignature),
      Buffer.from(actualSignature)
    );

    if (!isValid) {
      res.status(401).json({ error: "Invalid token" });
      return;
    }
  } catch (error) {
    res.status(401).json({ error: "Token verification failed" });
    return;
  }

  next();
}

