const findRoomTypeById = (hostelId: string, roomTypeId: string) => {
  const hostel = findHostelById(hostelId);
  if (!hostel) return undefined;
  return hostel.roomTypes.find(rt => rt.id === roomTypeId);
};

// Get all hostels
router.get("/", (req: Request, res: Response) => {
  res.json(hostels);
});

// Get a specific hostel by ID
router.get("/:id", (req: Request, res: Response) => {
  const hostel = findHostelById(req.params.id);
  if (!hostel) {
    return res.status(404).json({ error: "Hostel not found" });
  }
  res.json(hostel);
});

// Create a new hostel
router.post("/", (req: Request, res: Response) => {
  const { name, location } = req.body;
  if (!name || !location) {
    return res.status(400).json({ error: "Name and location are required" });
  }

  const newHostel = {
    id: `${Date.now()}`,
    name,
    location,
    roomTypes: []
  };

  hostels.push(newHostel);
  res.status(201).json(newHostel);
});

// Update a hostel
router.put("/:id", (req: Request, res: Response) => {
  const hostel = findHostelById(req.params.id);
  if (!hostel) {
    return res.status(404).json({ error: "Hostel not found" });
  }

  const { name, location } = req.body;
  if (name) hostel.name = name;
  if (location) hostel.location = location;

  res.json(hostel);
});

// Delete a hostel
router.delete("/:id", (req: Request, res: Response) => {
  const index = hostels.findIndex(h => h.id === req.params.id);
  if (index === -1) {
    return res.status(404).json({ error: "Hostel not found" });
  }

  hostels.splice(index, 1);
  res.json({ message: "Hostel deleted successfully" });
});

// Add a room type to a hostel
router.post("/:hostelId/room-types", (req: Request, res: Response) => {
  const hostel = findHostelById(req.params.hostelId);
  if (!hostel) {
    return res.status(404).json({ error: "Hostel not found" });
  }

  const { name, pricePerNight, maxOccupancy } = req.body;
  if (!name || pricePerNight === undefined || maxOccupancy === undefined) {
    return res.status(400).json({ error: "Name, pricePerNight, and maxOccupancy are required" });
  }

  const newRoomType = {
    id: `rt${Date.now()}`,
    name,
    pricePerNight: Number(pricePerNight),
    maxOccupancy: Number(maxOccupancy),
    availability: {}
  };

  hostel.roomTypes.push(newRoomType);
  res.status(201).json(newRoomType);
});

// Update room type availability
router.put("/:hostelId/room-types/:roomTypeId/availability", (req: Request, res: Response) => {
  const hostel = findHostelById(req.params.hostelId);
  if (!hostel) {
    return res.status(404).json({ error: "Hostel not found" });
  }

  const roomType = findRoomTypeById(req.params.hostelId, req.params.roomTypeId);
  if (!roomType) {
    return res.status(404).json({ error: "Room type not found" });
  }

  const { date, available } = req.body;
  if (!date || available === undefined) {
    return res.status(400).json({ error: "Date and availability status are required" });
  }

  roomType.availability[date] = Boolean(available);
  res.json(roomType);
});

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only protect POST requests to /login endpoint
  if (!(req.method === "POST" && req.path === "/login")) {
    next();
    return;
  }

  const authHeader = req.headers.authorization;

  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    return res.status(401).json({ error: "Unauthorized: Missing or invalid token" });
  }

  const token = authHeader.substring(7);

  const secret = process.env.JWT_SECRET;

  if (!secret) {
    return res.status(500).json({ error: "Internal Server Error: JWT_SECRET not configured" });
  }

  try {
    // Basic format validation
    const parts = token.split(".");
    if (parts.length !== 3) {
      return res.status(401).json({ error: "Unauthorized: Invalid token format" });
    }

    const [header, payload, signature] = parts;

    // Verify signature using HMAC-SHA256
    const expectedSignature = createHmac("sha256", secret)
      .update(`${header}.${payload}`)
      .digest("base64url");

    const signatureBuffer = Buffer.from(signature, "base64url");
    const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");

    if (signatureBuffer.length !== expectedSignatureBuffer.length ||
        !timingSafeEqual(signatureBuffer, expectedSignatureBuffer)) {
