import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

// Define role hierarchy for access control
const roleHierarchy = {
  guest: 1,
  staff: 2,
  admin: 3,
};

// Type definition for user role
export type UserRole = keyof typeof roleHierarchy;

// Middleware function for role-based access control
export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply role checking to protected routes
  const protectedPaths = ["/bookings", "/users", "/admin"];
  const isProtectedPath = protectedPaths.some(path =>
    req.path.startsWith(path)
  );

  // Skip role validation for non-protected paths
  if (!isProtectedPath) {
    next();
    return;
  }

  // Check if user is authenticated (simplified for this example)
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const token = authHeader.substring(7); // Remove "Bearer " prefix

  // In a real app, you'd decode and verify the JWT here
  // For now, we'll simulate verification
  const secret = process.env.JWT_SECRET;
  if (!secret) {
    res.status(500).json({ error: "Server configuration error" });
    return;
  }

  // Simulate token verification (in practice, use a proper JWT library)
  const expectedSignature = createHmac("sha256", secret)
    .update(token.split(".")[0] + "." + token.split(".")[1])
    .digest("hex");

  const actualSignature = token.split(".")[2];

  // Use timingSafeEqual to prevent timing attacks
  const isValid = timingSafeEqual(
    Buffer.from(expectedSignature),
    Buffer.from(actualSignature)
  );

  if (!isValid) {
    res.status(401).json({ error: "Invalid token" });
    return;
  }

  // Extract role from token (assuming it's in the payload)
  // This is a simplified example - in reality, decode the JWT properly
  const decodedToken = JSON.parse(
    Buffer.from(token.split(".")[1], "base64").toString()
  );

  const role: UserRole = decodedToken.role;

  // Validate role exists in hierarchy
  if (!(role in roleHierarchy)) {
    res.status(403).json({ error: "Forbidden" });
    return;
  }

  // Define required role for this path (example logic)
  let requiredRole: UserRole = "guest";
  if (req.path.startsWith("/admin")) {
    requiredRole = "admin";
  } else if (req.path.startsWith("/users")) {
    requiredRole = "staff";
  }

  // Check role hierarchy
  if (roleHierarchy[role] < roleHierarchy[requiredRole]) {
    res.status(403).json({ error: "Insufficient permissions" });
    return;
  }

  // If all checks pass, proceed
  next();
}

