import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process POST, PUT, DELETE requests to protected routes
  const isProtectedMethod = req.method === "POST" || req.method === "PUT" || req.method === "DELETE";
  const isProtectedPath = req.path.startsWith("/admin/") || req.path.startsWith("/seller/");

  if (!isProtectedMethod || !isProtectedPath) {
    next();
    return;
  }

  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized: Missing or invalid authorization header" });
    return;
  }

  const token = authHeader.substring(7);
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: "Internal Server Error: JWT_SECRET not configured" });
    return;
  }

  try {
    // Basic token structure validation
    const parts = token.split(".");
    if (parts.length !== 3) {
      res.status(401).json({ error: "Unauthorized: Invalid token format" });
      return;
    }

    const [header, payload, signature] = parts;
    const expectedSignature = createHmac("sha256", secret)
      .update(`${header}.${payload}`)
      .digest("base64url");

    const expectedBuffer = Buffer.from(expectedSignature, "base64url");
    const actualBuffer = Buffer.from(signature, "base64url");

    if (!timingSafeEqual(expectedBuffer, actualBuffer)) {
      res.status(401).json({ error: "Unauthorized: Invalid token signature" });
      return;
    }

    // Decode payload to extract role
    const payloadJson = Buffer.from(payload, "base64url").toString("utf-8");
    const payloadObj = JSON.parse(payloadJson);

    if (!payloadObj.role) {
      res.status(401).json({ error: "Unauthorized: Token missing role" });
      return;
    }

    const userRole = payloadObj.role;

    // Check role permissions
    if (req.path.startsWith("/admin/") && userRole !== "admin") {
      res.status(403).json({ error: "Forbidden: Admin access required" });
      return;
    }

    if (req.path.startsWith("/seller/") && userRole !== "seller") {
      res.status(403).json({ error: "Forbidden: Seller access required" });
      return;
    }

    next();
  } catch (error) {
    res.status(401).json({ error: "Unauthorized: Invalid token" });
  }
}

