  }

  // Check if JWT secret is set
  const jwtSecret = process.env.JWT_SECRET;
  if (!jwtSecret) {
    res.status(500).json({ error: "Internal server error" });
    return;
  }

  // Check if authorization header exists
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const token = authHeader.substring(7);

  // Verify token signature
  const secretBuffer = Buffer.from(jwtSecret);
  const tokenParts = token.split(".");
  if (tokenParts.length !== 3) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const [header, payload, signature] = tokenParts;
  const expectedSignature = createHmac("sha256", secretBuffer)
    .update(`${header}.${payload}`)
    .digest();

  try {
    const signatureBuffer = Buffer.from(signature, "base64");
    const isEqual = timingSafeEqual(expectedSignature, signatureBuffer);
    if (!isEqual) {
      res.status(401).json({ error: "Unauthorized" });
      return;
    }
  } catch {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  // If we get here, the token is valid
  next();
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply security checks to payment-related routes
  if (!req.path.startsWith("/payment")) {
    next();
    return;
  }

  // Check for required headers
  const contentType = req.get("Content-Type");
  const userAgent = req.get("User-Agent");

  // Ensure Content-Type is application/json for payment requests
  if (req.method === "POST" && contentType !== "application/json") {
    res.status(400).json({ error: "Content-Type must be application/json" });
    return;
  }

  // Validate User-Agent for known payment clients
  const allowedUserAgents = [
    "PaymentClient/1.0",
    "SecurePay/2.0"
  ];

  if (userAgent && !allowedUserAgents.includes(userAgent)) {
    res.status(403).json({ error: "Unauthorized client" });
    return;
  }

  // For POST requests to payment endpoints, validate request integrity
  if (req.method === "POST" && req.path.startsWith("/payment/charge")) {
    // Basic validation of required fields
    if (!req.body || !req.body.amount || !req.body.currency || !req.body.token) {
      res.status(400).json({ error: "Missing required payment fields" });
      return;
    }

    // Validate amount format
    if (typeof req.body.amount !== "number" || req.body.amount <= 0) {
      res.status(400).json({ error: "Invalid amount" });
      return;
    }

    // Validate currency format (ISO 4217)
    if (!req.body.currency || !/^[A-Z]{3}$/.test(req.body.currency)) {
      res.status(400).json({ error: "Invalid currency code" });
      return;
    }

    // Validate token format (basic check)
    if (!req.body.token || typeof req.body.token !== "string" || req.body.token.length < 10) {
      res.status(400).json({ error: "Invalid token" });
      return;
    }
  }

  // All payment-related checks passed
  next();
}

