export function ShoppingCart() {
  const [cartItems, setCartItems] = useState<CartItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    // Simulate fetching cart items
    const fetchCartItems = async () => {
      try {
        // In a real app, this would be an API call
        // const response = await fetch('/api/cart');
        // const items = await response.json();

        // Mock data
        const mockItems: CartItem[] = [
          { id: 1, name: "Handwoven Basket", price: 25.99, quantity: 1 },
          { id: 2, name: "Wooden Cutting Board", price: 18.50, quantity: 2 },
        ];

        setCartItems(mockItems);
        setLoading(false);
      } catch (err) {
        setError("Failed to load cart items");
        setLoading(false);
      }
    };

    fetchCartItems();
  }, []);

  const updateQuantity = (id: number, newQuantity: number) => {
    if (newQuantity <= 0) {
      removeItem(id);
      return;
    }

    setCartItems(items => 
      items.map(item => 
        item.id === id ? { ...item, quantity: newQuantity } : item
      )
    );
  };

  const removeItem = (id: number) => {
    setCartItems(items => items.filter(item => item.id !== id));
  };

  const totalAmount = cartItems.reduce(
    (sum, item) => sum + (item.price * item.quantity),
    0
  );

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
  }

  return (
    <div style={{
      maxWidth: "800px",
      margin: "0 auto",
      padding: "20px",
      fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif"
    }}>
      <h1 style={{ textAlign: "center" }}>Your Shopping Cart</h1>

      {cartItems.length === 0 ? (
        <p style={{ textAlign: "center", padding: "20px" }}>Your cart is empty.</p>
      ) : (
        <>
          <div style={{ marginBottom: "20px" }}>
            {cartItems.map(item => (
              <div 
                key={item.id} 
                style={{
                  display: "flex",
                  justifyContent: "space-between",
                  alignItems: "center",
                  padding: "10px",
                  borderBottom: "1px solid #eee",
                  marginBottom: "10px",
                  borderRadius: "8px",
                  backgroundColor: "#f9f9f9"
                }}
              >
                <div style={{ flex: 1 }}>
                  <h3>{item.name}</h3>
                  <p>${item.price.toFixed(2)}</p>
                </div>

                <div style={{ display: "flex", alignItems: "center", gap: "10px" }}>
                  <button 
                    onClick={() => updateQuantity(item.id, item.quantity - 1)}
                    style={{
                      padding: "5px 10px",
                      border: "1px solid #ccc",
                      borderRadius: "4px",
                      cursor: "pointer"
                    }}
                  >
                    -
                  </button>

                  <span style={{ minWidth: "30px", textAlign: "center" }}>
                    {item.quantity}
                  </span>

