}

import { useEffect, useState } from "react";

interface AttendanceRecord {
  id: string;
  studentId: string;
  studentName: string;
  date: string;
  period: string;
  status: "present" | "absent" | "late";
}

interface DateRange {
  startDate: string;
  endDate: string;
}

export function AttendanceReportPage() {
  const [records, setRecords] = useState<AttendanceRecord[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [dateRange, setDateRange] = useState<DateRange>({ 
    startDate: "", 
    endDate: "" 
  });
  const [selectedStudent, setSelectedStudent] = useState<string>("");
  const [selectedPeriod, setSelectedPeriod] = useState<string>("");

  // Mock data for demonstration
  const mockRecords: AttendanceRecord[] = [
    { id: "1", studentId: "s1", studentName: "Alice Johnson", date: "2023-05-01", period: "1", status: "present" },
    { id: "2", studentId: "s2", studentName: "Bob Smith", date: "2023-05-01", period: "1", status: "absent" },
    { id: "3", studentId: "s3", studentName: "Carol Davis", date: "2023-05-02", period: "2", status: "late" },
    { id: "4", studentId: "s1", studentName: "Alice Johnson", date: "2023-05-02", period: "2", status: "present" },
  ];

  const fetchAttendanceData = () => {
    setLoading(true);
    setError(null);

    // Simulate API call
    setTimeout(() => {
      try {
        setRecords(mockRecords);
        setLoading(false);
      } catch (err) {
        setError("Failed to load attendance data");
        setLoading(false);
      }
    }, 500);
  };

  useEffect(() => {
    fetchAttendanceData();
  }, []);

  const handleDateRangeChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setDateRange(prev => ({ ...prev, [name]: value }));
  };

  const handleFilter = () => {
    // In a real app, this would make an API call with filters
    fetchAttendanceData();
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case "present": return "#4caf50";
      case "absent": return "#f44336";
      case "late": return "#ff9800";
      default: return "#9e9e9e";
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
  }

  const filteredRecords = records.filter(record => {
    const matchesDate = (!dateRange.startDate || record.date >= dateRange.startDate) &&
                        (!dateRange.endDate || record.date <= dateRange.endDate);
    const matchesStudent = !selectedStudent || record.studentId === selectedStudent;
    const matchesPeriod = !selectedPeriod || record.period === selectedPeriod;

    return matchesDate && matchesStudent && matchesPeriod;
  });

  const students = Array.from(new Set(records.map(r => r.studentId)));
  const periods = Array.from(new Set(records.map(r => r.period)));

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Attendance Report</h1>

      <div style={{ marginBottom: "20px", padding: "15px", backgroundColor: "#f5f5f5", borderRadius: "8px" }}>
        <h2>Filters</h2>
        <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
          <div style={{ display: "flex", flexDirection: "row", gap: "10px", flexWrap: "wrap" }}>
            <div style={{ flex: "1", minWidth: "200px" }}>
              <label style={{ display: "block", marginBottom: "5px" }}>Start Date:</label>
              <input
                type="date"
                name="startDate"
                value={dateRange.startDate}
                onChange={handleDateRangeChange}
                style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
              />
            </div>
            <div style={{ flex: "1", minWidth: "200px" }}>
              <label style={{ display: "block", marginBottom: "5px" }}>End Date:</label>
              <input
                type="date"
                name="endDate"
                value={dateRange.endDate}
                onChange={handleDateRangeChange}
                style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
              />
            </div>
          </div>

          <div style={{ display: "flex", flexDirection: "row", gap: "10px", flexWrap: "wrap" }}>
            <div style={{ flex: "1", minWidth: "200px" }}>
              <label style={{ display: "block", marginBottom: "5px" }}>Student:</label>
              <select
                value={selectedStudent}
                onChange={(e) => setSelectedStudent(e.target.value)}
                style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
              >
                <option value="">All Students</option>
                {students.map(studentId => (
                  <option key={studentId} value={studentId}>Student {studentId}</option>
                ))}
              </select>
            </div>

            <div style={{ flex: "1", minWidth: "200px" }}>
              <label style={{ display: "block", marginBottom: "5px" }}>Period:</label>
              <select
                value={selectedPeriod}
                onChange={(e) => setSelectedPeriod(e.target.value)}
                style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
              >
                <option value="">All Periods</option>
                {periods.map(period => (
                  <option key={period} value={period}>Period {period}</option>
                ))}
              </select>
            </div>
          </div>

          <button 
            onClick={handleFilter}
            style={{ 
              padding: "10px 15px", 
              backgroundColor: "#2196f3", 
              color: "white", 
              border: "none", 
              borderRadius: "4px", 
              cursor: "pointer", 
              fontWeight: "bold" 
            }}
          >
            Apply Filters
          </button>
        </div>
      </div>

      <div>
        <h2>Attendance Records</h2>

        {filteredRecords.length === 0 ? (
          <p style={{ textAlign: "center", padding: "20px" }}>No attendance records found.</p>
        ) : (
          <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
            {filteredRecords.map(record => (
              <div 
                key={record.id} 
                style={{ 
                  padding: "15px", 
                  border: "1px solid #ddd", 
                  borderRadius: "8px", 
                  display: "flex", 
                  justifyContent: "space-between", 
                  alignItems: "center" 
                }}
              >
                <div>
                  <strong>{record.studentName}</strong> - {record.date}
                  <br />
                  <span style={{ fontSize: "0.9em" }}>Period {record.period} - </span>
                  <span style={{ color: getStatusColor(record.status), fontWeight: "bold" }}>
                    {record.status.charAt(0).toUpperCase() + record.status.slice(1)}
                  </span>
                </div>
                <div>
                  <button 
                    style={{ 
                      padding: "5px 10px", 
                      backgroundColor: "#4caf50", 
                      color: "white", 
                      border: "none", 
                      borderRadius: "4px", 
                      cursor: "pointer" 
                    }}
                  >
                    View Details
                  </button>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

