    return res.status(404).json({ error: "Attendance record not found" });
  }

  res.json(record);
});

// POST /api/attendance - Create a new attendance record
router.post("/", (req: Request, res: Response) => {
  const { studentId, date, status } = req.body;

  if (!studentId || !date || !status) {
    return res.status(400).json({ error: "Student ID, date, and status are required" });
  }

  const newRecord = {
    id: nextId++,
    studentId,
    date,
    status
  };

  attendanceRecords.push(newRecord);
  res.status(201).json(newRecord);
});

// PUT /api/attendance/:id - Update an existing attendance record
router.put("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const recordIndex = attendanceRecords.findIndex(r => r.id === id);

  if (recordIndex === -1) {
    return res.status(404).json({ error: "Attendance record not found" });
  }

  const { studentId, date, status } = req.body;

  // Build updates object with only provided fields
  const updates: Partial<{ studentId: number; date: string; status: string }> = {};

  if (studentId !== undefined) updates.studentId = studentId;
  if (date !== undefined) updates.date = date;
  if (status !== undefined) updates.status = status;

  // Apply updates to the record
  Object.assign(attendanceRecords[recordIndex], updates);

  res.json(attendanceRecords[recordIndex]);
});

