  { id: 2, title: "Quarterly Budget Analysis", period: "2023-Q1", totalSpent: 3500.00, categoryBreakdown: { food: 800.00, transport: 500.00, entertainment: 400.00 } }
];

// GET /reports - Get all reports
router.get("/reports", (req: Request, res: Response) => {
  res.json(mockReports);
});

// GET /reports/:id - Get a specific report by ID
router.get("/reports/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const report = mockReports.find(r => r.id === id);

  if (!report) {
    return res.status(404).json({ error: "Report not found" });
  }

  res.json(report);
});

// POST /reports - Create a new report
router.post("/reports", (req: Request, res: Response) => {
  const { title, period, totalSpent, categoryBreakdown } = req.body;

  // Basic validation
  if (!title || !period || totalSpent === undefined || !categoryBreakdown) {
    return res.status(400).json({ error: "Missing required fields" });
  }

  const newReport = {
    id: mockReports.length > 0 ? Math.max(...mockReports.map(r => r.id)) + 1 : 1,
    title,
    period,
    totalSpent,
    categoryBreakdown
  };

  mockReports.push(newReport);
  res.status(201).json(newReport);
});

// PUT /reports/:id - Update a report
router.put("/reports/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const reportIndex = mockReports.findIndex(r => r.id === id);

  if (reportIndex === -1) {
    return res.status(404).json({ error: "Report not found" });
  }

  const { title, period, totalSpent, categoryBreakdown } = req.body;

  // Basic validation
  if (!title || !period || totalSpent === undefined || !categoryBreakdown) {
    return res.status(400).json({ error: "Missing required fields" });
  }

  mockReports[reportIndex] = {
    id,
    title,
    period,
    totalSpent,
    categoryBreakdown
  };

  res.json(mockReports[reportIndex]);
});

// DELETE /reports/:id - Delete a report
router.delete("/reports/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const reportIndex = mockReports.findIndex(r => r.id === id);

  if (reportIndex === -1) {
    return res.status(404).json({ error: "Report not found" });
  }

  mockReports.splice(reportIndex, 1);
  res.json({ message: "Report deleted successfully" });
});

import type { Request, Response, NextFunction } from "express";
import { createHash, randomBytes, scryptSync } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // This middleware is designed to handle password hashing for user registration
  // It should only process POST requests to the /register endpoint
  if (req.method !== "POST" || req.path !== "/register") {
    next();
    return;
  }

  // Check if the request has a body with password
  if (!req.body || typeof req.body.password !== "string") {
    next();
    return;
  }

  // Hash the password using scrypt with a salt
  const salt = randomBytes(16).toString("hex");
  const hashedPassword = scryptSync(req.body.password, salt, 64).toString("hex");

  // Replace the plain text password with the hashed version
  req.body.password = `${hashedPassword}:${salt}`;

  next();
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

const TOKEN_HEADER = "x-auth-token";
const SESSION_TIMEOUT_MS = 30 * 60 * 1000; // 30 minutes

interface SessionData {
  userId: string;
  issuedAt: number;
}

function isValidToken(token: string): boolean {
  const secret = process.env.JWT_SECRET;
  if (!secret) {
    return false;
  }

  try {
    const [header, payload, signature] = token.split(".");
    if (!header || !payload || !signature) {
      return false;
    }

    const expectedSignature = createHmac("sha256", secret)
      .update(`${header}.${payload}`)
      .digest("base64url");

    const actualSignature = Buffer.from(signature, "base64url");
    const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");

    return timingSafeEqual(actualSignature, expectedSignatureBuffer);
  } catch {
    return false;
  }
}

function getSessionData(token: string): SessionData | null {
  try {
    const payload = token.split(".")[1];
    const decoded = Buffer.from(payload, "base64url").toString("utf8");
    return JSON.parse(decoded);
  } catch {
    return null;
  }
}

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only handle requests that require session validation
  if (req.method !== "POST" && req.method !== "PUT" && req.method !== "DELETE") {
    next();
    return;
  }

  const token = req.header(TOKEN_HEADER);

  if (!token) {
    res.status(401).json({ error: "Missing authentication token" });
    return;
  }

  if (!isValidToken(token)) {
    res.status(401).json({ error: "Invalid authentication token" });
    return;
  }

  const sessionData = getSessionData(token);
  if (!sessionData) {
    res.status(401).json({ error: "Invalid session data" });
    return;
  }

  // Check if session has timed out
  const now = Date.now();
  if (now - sessionData.issuedAt > SESSION_TIMEOUT_MS) {
    res.status(401).json({ error: "Session has expired" });
    return;
  }

  // Attach user ID to request for downstream middleware/route handlers
  (req as any).userId = sessionData.userId;
  next();
}

