import { useEffect, useState } from "react";

interface Category {
  id: number;
  name: string;
  budget: number;
}

export function CategoriesPage() {
  const [categories, setCategories] = useState<Category[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [formData, setFormData] = useState({
    name: "",
    budget: "",
  });
  const [editingId, setEditingId] = useState<number | null>(null);

  // Fetch categories
  useEffect(() => {
    const fetchCategories = async () => {
      try {
        const response = await fetch("/api/categories");
        if (!response.ok) {
          throw new Error(`HTTP error! status: ${response.status}`);
        }
        const data = await response.json();
        setCategories(data);
        setLoading(false);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
        setLoading(false);
      }
    };

    fetchCategories();
  }, []);

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setFormData({
      ...formData,
      [name]: value,
    });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    const categoryData = {
      name: formData.name,
      budget: Number(formData.budget),
    };

    try {
      if (editingId !== null) {
        // Update existing category
        const response = await fetch(`/api/categories/${editingId}`, {
          method: "PUT",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(categoryData),
        });

        if (!response.ok) {
          throw new Error(`HTTP error! status: ${response.status}`);
        }

        // Refresh the list
        const updatedResponse = await fetch("/api/categories");
        const updatedData = await updatedResponse.json();
        setCategories(updatedData);
        setEditingId(null);
      } else {
        // Create new category
        const response = await fetch("/api/categories", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(categoryData),
        });

        if (!response.ok) {
          throw new Error(`HTTP error! status: ${response.status}`);
        }

        // Refresh the list
        const newResponse = await fetch("/api/categories");
        const newData = await newResponse.json();
        setCategories(newData);
      }

      // Reset form
      setFormData({ name: "", budget: "" });
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleEdit = (category: Category) => {
    setFormData({
      name: category.name,
      budget: category.budget.toString(),
    });
    setEditingId(category.id);
  };

  const handleDelete = async (id: number) => {
    try {
      const response = await fetch(`/api/categories/${id}`, {
        method: "DELETE",
      });

      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      // Refresh the list
      const newResponse = await fetch("/api/categories");
      const newData = await newResponse.json();
      setCategories(newData);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const formStyle: React.CSSProperties = {
    display: "flex",
    flexDirection: "column",
    gap: "10px",
    marginBottom: "20px",
    maxWidth: "500px",
    margin: "0 auto",
  };

  const inputStyle: React.CSSProperties = {
    padding: "10px",
    borderRadius: "4px",
    border: "1px solid #ccc",
    fontSize: "16px",
  };

  const buttonStyle: React.CSSProperties = {
    padding: "10px 15px",
    backgroundColor: "#007bff",
    color: "white",
    border: "none",
    borderRadius: "4px",
    cursor: "pointer",
    fontSize: "16px",
  };

  const listStyle: React.CSSProperties = {
    display: "flex",
    flexDirection: "column",
    gap: "10px",
    maxWidth: "500px",
    margin: "0 auto",
  };

  const categoryInfoStyle: React.CSSProperties = {
    display: "flex",
    flexDirection: "row",
    justifyContent: "space-between",
    alignItems: "center",
    padding: "10px",
    border: "1px solid #ccc",
    borderRadius: "4px",
    backgroundColor: "#f9f9f9",
  };

  const buttonGroupStyle: React.CSSProperties = {
    display: "flex",
    gap: "5px",
  };

  if (loading) return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;

  if (error) return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;

  return (
    <div style={{ maxWidth: "600px", margin: "0 auto", padding: "20px", fontFamily: "Arial, sans-serif" }}>
      <h1>Expense Categories</h1>

      <form onSubmit={handleSubmit} style={formStyle}>
        <input
          type="text"
          name="name"
          placeholder="Category Name"
          value={formData.name}
          onChange={handleInputChange}
          style={inputStyle}
        />
        <input
          type="number"
          name="budget"
          placeholder="Budget Amount"
          value={formData.budget}
          onChange={handleInputChange}
          style={inputStyle}
        />
        <button type="submit" style={buttonStyle}>
          {editingId ? "Update Category" : "Add Category"}
        </button>
      </form>

      <div style={listStyle}>
        {categories.length === 0 ? (
          <p>No categories found.</p>
        ) : (
          categories.map((category) => (
            <div key={category.id} style={categoryInfoStyle}>
              <div>
                <strong>{category.name}</strong> - ${category.budget.toFixed(2)}
              </div>
              <div style={buttonGroupStyle}>
                <button onClick={() => handleEdit(category)} style={{ ...buttonStyle, backgroundColor: "#ffc107" }}>
                  Edit
                </button>
                <button onClick={() => handleDelete(category.id)} style={{ ...buttonStyle, backgroundColor: "#dc3545" }}>
                  Delete
                </button>
              </div>
            </div>
          ))
        )}
      </div>
    </div>
  );
