import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply RBAC to specific routes and methods
  const isProtectedRoute = /^\/api\/(customers|opportunities)/.test(req.path);
  const isProtectedMethod = req.method === "GET" || req.method === "POST" || req.method === "PUT" || req.method === "DELETE";

  if (!isProtectedRoute || !isProtectedMethod) {
    next();
    return;
  }

  // Check for authorization header
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized: Missing or invalid token" });
    return;
  }

  const token = authHeader.substring(7); // Remove 'Bearer '
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: "Server configuration error: JWT_SECRET not set" });
    return;
  }

  try {
    // Simple token validation - in a real app, you'd decode and verify properly
    const [userId, role] = token.split(":");

    if (!userId || !role) {
      res.status(401).json({ error: "Unauthorized: Invalid token format" });
      return;
    }

    // Validate role permissions
    const userRole = role.trim();
    const allowedRoles = ["sales_rep", "sales_manager", "admin"];

    if (!allowedRoles.includes(userRole)) {
      res.status(403).json({ error: "Forbidden: Invalid role" });
      return;
    }

    // Store user info in request for downstream middleware/routes
    (req as any).user = { id: userId, role: userRole };

    // Allow access
    next();
  } catch (error) {
    res.status(401).json({ error: "Unauthorized: Invalid token" });
  }
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check authentication for login POST requests
  if (req.method !== "POST" || req.path !== "/login") {
    next();
    return;
  }

  // Check if JWT secret is set
  const jwtSecret = process.env.JWT_SECRET;
  if (!jwtSecret) {
    res.status(500).json({ error: "Internal server error" });
    return;
  }

  // Simulate token verification (in a real implementation, you'd decode and verify the JWT)
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const token = authHeader.substring(7);

  // This is a simplified example - in reality, you'd verify the JWT signature
  // using HMAC-SHA256 with the secret from process.env.JWT_SECRET
  try {
    // For demonstration purposes, we'll just check if token has expected format
    const expectedToken = createHmac("sha256", jwtSecret).update("valid-token").digest("hex");
    const tokenBuffer = Buffer.from(token);
    const expectedBuffer = Buffer.from(expectedToken);

    if (tokenBuffer.length !== expectedBuffer.length || !timingSafeEqual(tokenBuffer, expectedBuffer)) {
      res.status(401).json({ error: "Unauthorized" });
      return;
    }
  } catch (error) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  next();
}

