import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock database - in a real app this would be a proper database
const mockDatabase = {
  customers: [
    { id: 1, name: "John Doe", email: "john@example.com", phone: "123-456-7890" },
    { id: 2, name: "Jane Smith", email: "jane@example.com", phone: "098-765-4321" }
  ],
  nextId: 3
};

// Get all customers
router.get("/customers", (req: Request, res: Response) => {
  res.json(mockDatabase.customers);
});

// Get a customer by ID
router.get("/customers/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const customer = mockDatabase.customers.find(c => c.id === id);

  if (!customer) {
    return res.status(404).json({ error: "Customer not found" });
  }

  res.json(customer);
});

// Create a new customer
router.post("/customers", (req: Request, res: Response) => {
  const { name, email, phone } = req.body;

  // Basic validation
  if (!name || !email || !phone) {
    return res.status(400).json({ error: "Name, email, and phone are required" });
  }

  const newCustomer = {
    id: mockDatabase.nextId,
    name,
    email,
    phone
  };

  mockDatabase.customers.push(newCustomer);
  mockDatabase.nextId++;

  res.status(201).json(newCustomer);
});

// Update a customer
router.put("/customers/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const { name, email, phone } = req.body;

  // Basic validation
  if (!name || !email || !phone) {
    return res.status(400).json({ error: "Name, email, and phone are required" });
  }

  const customerIndex = mockDatabase.customers.findIndex(c => c.id === id);

  if (customerIndex === -1) {
    return res.status(404).json({ error: "Customer not found" });
  }

  const updatedCustomer = {
    id,
    name,
    email,
    phone
  };

  mockDatabase.customers[customerIndex] = updatedCustomer;

  res.json(updatedCustomer);
});

// Delete a customer
router.delete("/customers/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const customerIndex = mockDatabase.customers.findIndex(c => c.id === id);

  if (customerIndex === -1) {
    return res.status(404).json({ error: "Customer not found" });
  }

  mockDatabase.customers.splice(customerIndex, 1);

  res.json({ message: "Customer deleted successfully" });
});

