  }

  const clientIP = getClientIP(req);
  const now = Date.now();

  // Initialize or update request count for this IP
  const stored = requestCounts.get(clientIP) || { count: 0, resetTime: now + TIME_WINDOW_MS };

  // Reset counter if time window has passed
  if (now >= stored.resetTime) {
    stored.count = 0;
    stored.resetTime = now + TIME_WINDOW_MS;
  }

  // Check if limit exceeded
  if (stored.count >= MAX_REQUESTS) {
    res.status(429).json({
      error: "Too Many Requests",
      message: "You have exceeded the maximum number of requests allowed in a 15-minute window."
    });
    return;
  }

  // Increment and store count
  stored.count += 1;
  requestCounts.set(clientIP, stored);

  next();
}

function getClientIP(req: Request): string {
  // Try different headers/properties for IP detection
  return (
    req.headers["x-forwarded-for"] ||
    req.headers["x-real-ip"] ||
    req.connection.remoteAddress ||
    req.socket.remoteAddress ||
    (req.connection as any).socket?.remoteAddress ||
    "127.0.0.1"
  ).toString();
}

