    </div>
  );
}

import { useEffect, useState } from "react";

interface Movie {
  id: number;
  title: string;
  year: number;
  rating: number;
}

export function WatchlistPage() {
  const [movies, setMovies] = useState<Movie[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [sortField, setSortField] = useState<keyof Movie>("title");
  const [sortDirection, setSortDirection] = useState<'asc' | 'desc'>('asc');

  useEffect(() => {
    const fetchWatchlist = async () => {
      try {
        // In a real app, this would be an API call
        // For demo purposes, we'll simulate data
        await new Promise(resolve => setTimeout(resolve, 500));

        const mockMovies: Movie[] = [
          { id: 1, title: "Inception", year: 2010, rating: 8.8 },
          { id: 2, title: "The Shawshank Redemption", year: 1994, rating: 9.3 },
          { id: 3, title: "The Dark Knight", year: 2008, rating: 9.0 },
          { id: 4, title: "Pulp Fiction", year: 1994, rating: 8.9 },
          { id: 5, title: "Forrest Gump", year: 1994, rating: 8.8 },
        ];

        setMovies(mockMovies);
        setLoading(false);
      } catch (err) {
        setError("Failed to load watchlist");
        setLoading(false);
      }
    };

    fetchWatchlist();
  }, []);

  const sortedMovies = [...movies].sort((a, b) => {
    if (sortField === 'title') {
      return sortDirection === 'asc' 
        ? a.title.localeCompare(b.title)
        : b.title.localeCompare(a.title);
    } else if (sortField === 'year') {
      return sortDirection === 'asc' 
        ? a.year - b.year
        : b.year - a.year;
    } else {
      return sortDirection === 'asc' 
        ? a.rating - b.rating
        : b.rating - a.rating;
    }
  });

  const handleSort = (field: keyof Movie) => {
    if (sortField === field) {
      setSortDirection(sortDirection === 'asc' ? 'desc' : 'asc');
    } else {
      setSortField(field);
      setSortDirection('asc');
    }
  };

  const getSortIcon = (field: keyof Movie) => {
    if (sortField !== field) return '';
    return sortDirection === 'asc' ? ' ↑' : ' ↓';
  };

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>{error}</div>;
  }

  if (movies.length === 0) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Your watchlist is empty.</div>;
  }

  return (
    <div style={{ maxWidth: '800px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1 style={{ textAlign: 'center' }}>My Watchlist</h1>

      <div style={{ marginBottom: '20px', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
        <span style={{ fontSize: '18px', fontWeight: 'bold' }}>
          {movies.length} movie{movies.length !== 1 ? 's' : ''} in watchlist
        </span>

        <div style={{ display: 'flex', gap: '10px' }}>
          <button 
            onClick={() => setSortDirection(sortDirection === 'asc' ? 'desc' : 'asc')}
            style={{ padding: '8px 12px', borderRadius: '4px', border: '1px solid #ccc', cursor: 'pointer' }}
          >
            Reverse Sort
          </button>
        </div>
      </div>

      <table style={{ width: '100%', borderCollapse: 'collapse', marginBottom: '20px' }}>
        <thead>
          <tr style={{ borderBottom: '2px solid #ddd' }}>
            <th 
              style={{ padding: '10px', textAlign: 'left', cursor: 'pointer' }}
              onClick={() => handleSort('title')}
            >
              Title{getSortIcon('title')}
            </th>
            <th 
              style={{ padding: '10px', textAlign: 'left', cursor: 'pointer' }}
              onClick={() => handleSort('year')}
            >
              Year{getSortIcon('year')}
            </th>
            <th 
              style={{ padding: '10px', textAlign: 'left', cursor: 'pointer' }}
              onClick={() => handleSort('rating')}
            >
              Rating{getSortIcon('rating')}
            </th>
            <th style={{ padding: '10px', textAlign: 'left' }}>Actions</th>
          </tr>
        </thead>
        <tbody>
          {sortedMovies.map(movie => (
            <tr key={movie.id} style={{ borderBottom: '1px solid #eee' }}>
              <td style={{ padding: '10px' }}>{movie.title}</td>
              <td style={{ padding: '10px' }}>{movie.year}</td>
              <td style={{ padding: '10px' }}>{movie.rating}</td>
              <td style={{ padding: '10px' }}>
                <button 
                  style={{ 
                    padding: '6px 10px', 
                    marginRight: '8px', 
                    borderRadius: '4px', 
                    border: '1px solid #007bff', 
                    backgroundColor: '#007bff', 
                    color: 'white', 
                    cursor: 'pointer' 
                  }}
                >
                  Remove
                </button>
                <button 
                  style={{ 
                    padding: '6px 10px', 
                    borderRadius: '4px', 
                    border: '1px solid #28a745', 
                    backgroundColor: '#28a745', 
                    color: 'white', 
                    cursor: 'pointer' 
                  }}
                >
                  Review
                </button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>

      <div style={{ textAlign: 'center', marginTop: '20px' }}>
        <button 
          style={{ 
            padding: '10px 20px', 
            borderRadius: '4px', 
            border: '1px solid #007bff', 
            backgroundColor: '#007bff', 
            color: 'white', 
            cursor: 'pointer', 
            fontSize: '16px' 
          }}
        >
          Add New Movie
        </button>
      </div>
    </div>
  );
}

