import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply role-based access control to POST, PUT, DELETE requests
  if (!['POST', 'PUT', 'DELETE'].includes(req.method)) {
    next();
    return;
  }

  // Define protected routes
  const protectedRoutes = [
    '/crops',
    '/farms',
    '/activities',
    '/users'
  ];

  // Check if current path is protected
  const isProtectedRoute = protectedRoutes.some(route => 
    req.path.startsWith(route)
  );

  if (!isProtectedRoute) {
    next();
    return;
  }

  // Get authorization header
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    res.status(401).json({ error: 'Unauthorized: Missing or invalid token' });
    return;
  }

  const token = authHeader.substring(7); // Remove 'Bearer '

  // Verify JWT signature
  const secret = process.env.JWT_SECRET;
  if (!secret) {
    res.status(500).json({ error: 'Server configuration error: JWT_SECRET not set' });
    return;
  }

  try {
    // Simple verification - in a real app, use a proper JWT library
    const [header, payload, signature] = token.split('.');
    if (!header || !payload || !signature) {
      res.status(401).json({ error: 'Unauthorized: Invalid token format' });
      return;
    }

    // Create expected signature
    const expectedSignature = createHmac('sha256', secret)
      .update(`${header}.${payload}`)
      .digest('base64url');

    // Use timingSafeEqual to prevent timing attacks
    const isValid = timingSafeEqual(
      Buffer.from(signature, 'base64url'),
      Buffer.from(expectedSignature, 'base64url')
    );

    if (!isValid) {
      res.status(401).json({ error: 'Unauthorized: Invalid token signature' });
      return;
    }

    // Decode payload to get user role
    const decodedPayload = JSON.parse(Buffer.from(payload, 'base64').toString());
    const userRole = decodedPayload.role;

    // Validate role permissions
    if (!userRole) {
      res.status(403).json({ error: 'Forbidden: User role not specified' });
      return;
    }

    // Farmer can only access certain endpoints
    if (userRole === 'farmer') {
      // Allow farmer access to read-only endpoints
      const readOnlyEndpoints = ['/crops/:id', '/farms/:id'];
      const isReadOnly = readOnlyEndpoints.some(endpoint => 
        req.path.includes(endpoint.replace(':id', ''))
      );

      if (!isReadOnly && req.method !== 'GET') {
        res.status(403).json({ error: 'Forbidden: Farmers can only view data' });
        return;
      }
    }

    // Staff can access all endpoints
    if (userRole === 'staff') {
      // Staff has full access
    }

    // If we reach here, user is authorized
    next();
  } catch (error) {
    res.status(401).json({ error: 'Unauthorized: Invalid token' });
  }
}

import type { Request, Response, NextFunction } from "express";
import { createHash, scryptSync, randomBytes, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // This middleware is designed to handle password hashing for user registration
  // It should only process POST requests to the /register endpoint
  if (req.method !== "POST" || req.path !== "/register") {
    next();
    return;
  }

  // Check if password exists in request body
  if (!req.body || typeof req.body.password !== "string") {
    next();
    return;
  }

  // Hash the password using scrypt
  const salt = randomBytes(16).toString("hex");
  const key = scryptSync(req.body.password, salt, 32);
  const hashedPassword = key.toString("hex");

  // Replace the password with the hashed version
  req.body.password = hashedPassword;
  req.body.salt = salt;

  next();
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

const TOKEN_HEADER = "x-auth-token";
const TIMEOUT_MINUTES = 30;

interface SessionData {
  userId: string;
  expiresAt: Date;
}

function isValidToken(token: string): boolean {
  const secret = process.env.JWT_SECRET;
  if (!secret) return false;

  try {
    const [header, payload, signature] = token.split(".");
    if (!header || !payload || !signature) return false;

    const expectedSignature = createHmac("sha256", secret)
      .update(`${header}.${payload}`)
      .digest("base64url");

    const actualSignature = Buffer.from(signature, "base64url");
    const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");

    return timingSafeEqual(actualSignature, expectedSignatureBuffer);
  } catch {
    return false;
  }
}

function parseToken(token: string): SessionData | null {
  try {
    const [header, payload] = token.split(".");
    if (!header || !payload) return null;

    const decodedPayload = Buffer.from(payload, "base64url").toString();
    return JSON.parse(decodedPayload);
  } catch {
    return null;
  }
}

function isTokenExpired(session: SessionData): boolean {
  return new Date() > session.expiresAt;
}

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process requests that require session validation
  if (req.method === "GET" && req.path === "/") {
    next();
    return;
  }

  const token = req.header(TOKEN_HEADER);
  if (!token) {
    res.status(401).json({ error: "No token provided" });
    return;
  }

  if (!isValidToken(token)) {
    res.status(401).json({ error: "Invalid token" });
    return;
  }

  const session = parseToken(token);
  if (!session) {
    res.status(401).json({ error: "Invalid token format" });
    return;
  }

  if (isTokenExpired(session)) {
    res.status(401).json({ error: "Token expired" });
    return;
  }

  // Token is valid and not expired
  next();
}

