import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

const JWT_SECRET = process.env.JWT_SECRET;

function decodeJwt(token: string): Record<string, unknown> | null {
  try {
    const payload = token.split('.')[1];
    const decoded = Buffer.from(payload, 'base64').toString('utf-8');
    return JSON.parse(decoded);
  } catch {
    return null;
  }
}

function verifySignature(token: string, secret: string): boolean {
  const [header, payload, signature] = token.split('.');

  if (!header || !payload || !signature) {
    return false;
  }

  const expectedSignature = createHmac('sha256', secret)
    .update(`${header}.${payload}`)
    .digest('base64url');

  const actualSignature = signature;

  try {
    return timingSafeEqual(
      Buffer.from(actualSignature, 'base64url'),
      Buffer.from(expectedSignature, 'base64url')
    );
  } catch {
    return false;
  }
}

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process POST requests to /login endpoint
  if (!(req.method === 'POST' && req.path === '/login')) {
    next();
    return;
  }

  // Check if JWT_SECRET is set
  if (!JWT_SECRET) {
    res.status(500).json({ error: 'Server configuration error' });
    return;
  }

  // Check if Authorization header exists
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    res.status(401).json({ error: 'Missing or invalid authorization header' });
    return;
  }

  const token = authHeader.substring(7); // Remove 'Bearer '

  // Verify token structure
  if (!token.includes('.')) {
    res.status(401).json({ error: 'Invalid token format' });
    return;
  }

  // Decode token
  const decoded = decodeJwt(token);
  if (!decoded) {
    res.status(401).json({ error: 'Invalid token' });
    return;
  }

  // Verify signature
  if (!verifySignature(token, JWT_SECRET)) {
    res.status(401).json({ error: 'Invalid token signature' });
    return;
  }

  // Token is valid, proceed
  next();
}

import type { Request, Response, NextFunction } from "express";
import { createHash, scrypt, randomBytes, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // This middleware is designed to hash and salt passwords during user registration
  // It should only process POST requests to the /register endpoint
  if (req.method !== "POST" || req.path !== "/register") {
    next();
    return;
  }

  // Check if password exists in request body
  if (!req.body || typeof req.body.password !== "string") {
    next();
    return;
  }

  const password = req.body.password;

  // Generate a salt
  const salt = randomBytes(16).toString("hex");

  // Hash the password with salt using scrypt (industry standard)
  scrypt(password, salt, 64, (err, derivedKey) => {
    if (err) {
      next(err);
      return;
    }

    // Store the salt and hashed password in the request body
    req.body.salt = salt;
    req.body.hashedPassword = derivedKey.toString("hex");

    next();
  });
}

