import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync("./canteen.db");

interface UserRow {
  id: number;
  patient_id: string | null;
  username: string;
  password_hash: string;
  role: "patient" | "staff" | "admin";
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS users (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    patient_id TEXT,
    username TEXT UNIQUE NOT NULL,
    password_hash TEXT NOT NULL,
    role TEXT NOT NULL CHECK(role IN ('patient', 'staff', 'admin'))
  )
`;

db.exec(createTableSql);

export function getAllUsers(): UserRow[] {
  const stmt = db.prepare("SELECT * FROM users");
  return stmt.all() as unknown as UserRow[];
}

export function getUserById(id: number): UserRow | undefined {
  const stmt = db.prepare("SELECT * FROM users WHERE id = ?");
  return stmt.get(id) as unknown as UserRow | undefined;
}

export function insertUser(
  patientId: string | null,
  username: string,
  passwordHash: string,
  role: "patient" | "staff" | "admin"
): number {
  const stmt = db.prepare(
    "INSERT INTO users (patient_id, username, password_hash, role) VALUES (?, ?, ?, ?)"
  );
  const result = stmt.run(patientId, username, passwordHash, role);
  return Number(result.lastInsertRowid);
}

export function updateUser(
  id: number,
  patientId: string | null,
  username: string,
  passwordHash: string,
  role: "patient" | "staff" | "admin"
): void {
  const stmt = db.prepare(
    "UPDATE users SET patient_id = ?, username = ?, password_hash = ?, role = ? WHERE id = ?"
  );
  stmt.run(patientId, username, passwordHash, role, id);
}

export function deleteUser(id: number): void {
  const stmt = db.prepare("DELETE FROM users WHERE id = ?");
  stmt.run(id);
}

