import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync(":memory:");

interface OrderRow {
  id: number;
  user_id: number;
  meal_selections: string;
  quantities: string;
  timestamp: string;
  status: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS orders (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id INTEGER NOT NULL,
    meal_selections TEXT NOT NULL,
    quantities TEXT NOT NULL,
    timestamp TEXT NOT NULL,
    status TEXT NOT NULL
  );
`;

db.exec(createTableSql);

export function getAllOrders(): OrderRow[] {
  const stmt = db.prepare(`SELECT * FROM orders;`);
  return stmt.all() as unknown as OrderRow[];
}

export function getOrderById(id: number): OrderRow | undefined {
  const stmt = db.prepare(`SELECT * FROM orders WHERE id = ?;`);
  return stmt.get(id) as unknown as OrderRow | undefined;
}

export function insertOrder(
  userId: number,
  mealSelections: string,
  quantities: string,
  timestamp: string,
  status: string
): number {
  const stmt = db.prepare(
    `INSERT INTO orders (user_id, meal_selections, quantities, timestamp, status) VALUES (?, ?, ?, ?, ?);`
  );
  const result = stmt.run(userId, mealSelections, quantities, timestamp, status);
  return Number(result.lastInsertRowid);
}

export function updateOrder(
  id: number,
  userId: number,
  mealSelections: string,
  quantities: string,
  timestamp: string,
  status: string
): void {
  const stmt = db.prepare(
    `UPDATE orders SET user_id = ?, meal_selections = ?, quantities = ?, timestamp = ?, status = ? WHERE id = ?;`
  );
  stmt.run(userId, mealSelections, quantities, timestamp, status, id);
}

export function deleteOrder(id: number): void {
  const stmt = db.prepare(`DELETE FROM orders WHERE id = ?;`);
  stmt.run(id);
}

