import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check role-based access for specific routes
  const protectedPaths = [
    "/admin",
    "/api/meal-management",
    "/api/order-management",
    "/api/inventory-management"
  ];

  const isProtectedPath = protectedPaths.some(path => 
    req.path.startsWith(path) || 
    req.path === path
  );

  if (!isProtectedPath) {
    next();
    return;
  }

  // Check if user is authenticated and has proper role
  const authHeader = req.headers.authorization;

  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized: Missing or invalid token" });
    return;
  }

  const token = authHeader.substring(7); // Remove "Bearer " prefix

  // Verify JWT signature
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: "Server configuration error: JWT_SECRET not set" });
    return;
  }

  try {
    // Simple verification - in a real app, use a proper JWT library
    const [payload, signature] = token.split(".");

    if (!payload || !signature) {
      res.status(401).json({ error: "Unauthorized: Invalid token format" });
      return;
    }

    // Create expected signature
    const expectedSignature = createHmac("sha256", secret)
      .update(payload)
      .digest("base64url");

    // Use timingSafeEqual to prevent timing attacks
    const signatureBuffer = Buffer.from(signature, "base64url");
    const expectedBuffer = Buffer.from(expectedSignature, "base64url");

    if (!timingSafeEqual(signatureBuffer, expectedBuffer)) {
      res.status(401).json({ error: "Unauthorized: Invalid token signature" });
      return;
    }

    // Decode payload (simplified - in reality, parse base64url)
    const decodedPayload = JSON.parse(Buffer.from(payload, "base64url").toString());

    // Check role
    const userRole = decodedPayload.role;

    if (!userRole) {
      res.status(401).json({ error: "Unauthorized: Role not specified in token" });
      return;
    }

    // Admin routes require admin role
    if (req.path.startsWith("/admin") || 
        req.path.startsWith("/api/meal-management") ||
        req.path.startsWith("/api/order-management") ||
        req.path.startsWith("/api/inventory-management")) {

      if (userRole !== "admin") {
        res.status(403).json({ error: "Forbidden: Admin access required" });
        return;
      }
    }

    // Patient routes should only allow order placement
    if (req.path.startsWith("/api/orders")) {
      if (userRole !== "patient") {
        res.status(403).json({ error: "Forbidden: Patient access required" });
        return;
      }
    }

    // If we get here, user is authorized
    next();
  } catch (error) {
    res.status(401).json({ error: "Unauthorized: Invalid token" });
  }
}

