import { useEffect, useState } from "react";

interface Meal {
  id: string;
  name: string;
  description: string;
  price: number;
  available: boolean;
}

interface Order {
  id: string;
  mealId: string;
  quantity: number;
  status: 'pending' | 'confirmed' | 'preparing' | 'ready' | 'delivered';
  createdAt: string;
}

export function UserDashboard() {
  const [meals, setMeals] = useState<Meal[]>([]);
  const [orders, setOrders] = useState<Order[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [selectedMealId, setSelectedMealId] = useState<string>('');
  const [quantity, setQuantity] = useState(1);

  useEffect(() => {
    const fetchData = async () => {
      try {
        const [mealsResponse, ordersResponse] = await Promise.all([
          fetch('/api/meal-management-service/meals'),
          fetch('/api/order-management-service/')
        ]);

        if (!mealsResponse.ok || !ordersResponse.ok) {
          throw new Error('Failed to fetch data');
        }

        const mealsData = await mealsResponse.json();
        const ordersData = await ordersResponse.json();

        setMeals(mealsData);
        setOrders(ordersData);
      } catch (err) {
        setError(err instanceof Error ? err.message : 'An unknown error occurred');
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, []);

  const handlePlaceOrder = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!selectedMealId) return;

    try {
      const response = await fetch('/api/order-management-service/', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({
          mealId: selectedMealId,
          quantity
        })
      });

      if (!response.ok) {
        throw new Error('Failed to place order');
      }

      // Refresh data
      const ordersResponse = await fetch('/api/order-management-service/');
      const ordersData = await ordersResponse.json();
      setOrders(ordersData);

      // Reset form
      setSelectedMealId('');
      setQuantity(1);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: '800px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1 style={{ textAlign: 'center' }}>User Dashboard</h1>

      <section style={{ marginBottom: '30px' }}>
        <h2>Available Meals</h2>
        {meals.length === 0 ? (
          <p>No meals available.</p>
        ) : (
          <div style={{ display: 'flex', flexWrap: 'wrap', gap: '15px' }}>
            {meals
              .filter(meal => meal.available)
              .map(meal => (
                <div key={meal.id} style={{ border: '1px solid #ccc', borderRadius: '8px', padding: '15px', width: '200px' }}>
                  <h3>{meal.name}</h3>
                  <p>{meal.description}</p>
