export function OrderForm() {
  const [meals, setMeals] = useState<Meal[]>([]);
  const [orderItems, setOrderItems] = useState<OrderItem[]>([]);
  const [deliveryDetails, setDeliveryDetails] = useState({
    name: "",
    address: "",
    phone: "",
  });
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const fetchMeals = async () => {
      try {
        const response = await fetch("/api/meal-management-service/meals");
        if (!response.ok) throw new Error("Failed to fetch meals");
        const data = await response.json();
        setMeals(data);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
      } finally {
        setLoading(false);
      }
    };

    fetchMeals();
  }, []);

  const handleQuantityChange = (mealId: string, quantity: number) => {
    if (quantity < 0) return;

    setOrderItems(prev => {
      const existingItem = prev.find(item => item.mealId === mealId);
      if (existingItem) {
        return prev.map(item => 
          item.mealId === mealId ? { ...item, quantity } : item
        );
      } else {
        return [...prev, { mealId, quantity }];
      }
    });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    try {
      const response = await fetch("/api/order-management-service/", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          items: orderItems,
          deliveryDetails,
        }),
      });

      if (!response.ok) throw new Error("Failed to submit order");

      // Reset form after successful submission
      setOrderItems([]);
      setDeliveryDetails({ name: "", address: "", phone: "" });
      alert("Order submitted successfully!");
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;

  if (error) return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;

  return (
    <div style={{
      maxWidth: "600px",
      margin: "0 auto",
      padding: "20px",
      fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif",
    }}>
      <h1 style={{ textAlign: "center" }}>Order Meals</h1>

      <form onSubmit={handleSubmit}>
        <div style={{ marginBottom: "20px" }}>
          <h2>Delivery Details</h2>
          <input
            type="text"
            placeholder="Full Name"
            value={deliveryDetails.name}
            onChange={(e) => setDeliveryDetails({...deliveryDetails, name: e.target.value})}
            style={{ width: "100%", padding: "10px", marginBottom: "10px", borderRadius: "4px", border: "1px solid #ccc" }}
            required
          />
          <input
            type="text"
            placeholder="Address"
            value={deliveryDetails.address}
            onChange={(e) => setDeliveryDetails({...deliveryDetails, address: e.target.value})}
            style={{ width: "100%", padding: "10px", marginBottom: "10px", borderRadius: "4px", border: "1px solid #ccc" }}
            required
          />
          <input
            type="text"
            placeholder="Phone Number"
            value={deliveryDetails.phone}
            onChange={(e) => setDeliveryDetails({...deliveryDetails, phone: e.target.value})}
            style={{ width: "100%", padding: "10px", marginBottom: "10px", borderRadius: "4px", border: "1px solid #ccc" }}
            required
          />
        </div>

        <h2>Menu</h2>
        {meals.length === 0 ? (
          <p>No meals available.</p>
        ) : (
          <div style={{ display: "flex", flexDirection: "column", gap: "15px" }}>
            {meals.map(meal => (
              <div key={meal.id} style={{
                border: "1px solid #ddd",
                borderRadius: "8px",
                padding: "15px",
                display: "flex",
                justifyContent: "space-between",
                alignItems: "center",
                flexWrap: "wrap",
              }}>
                <div style={{ flex: "1", minWidth: "200px" }}>
                  <h3>{meal.name}</h3>
                  <p>{meal.description}</p>
                  <p>${meal.price.toFixed(2)}</p>
                </div>
                <div style={{ display: "flex", alignItems: "center", gap: "10px" }}>
                  <label>Quantity:</label>
                  <input
                    type="number"
                    min="0"
                    value={orderItems.find(item => item.mealId === meal.id)?.quantity || 0}
                    onChange={(e) => handleQuantityChange(meal.id, parseInt(e.target.value) || 0)}
                    style={{ width: "60px", padding: "5px", borderRadius: "4px", border: "1px solid #ccc" }}
                  />
                </div>
              </div>
            ))}
          </div>
        )}

        <button 
          type="submit" 
          style={{
            marginTop: "20px",
            padding: "12px 20px",
            backgroundColor: "#007bff",
            color: "white",
            border: "none",
            borderRadius: "4px",
            cursor: "pointer",
            width: "100%",
            fontSize: "16px",
          }}
        >
          Submit Order
        </button>
      </form>
    </div>
  );
