import { Router, type Request, type Response } from "express";
import { getAllUsers, insertUser } from "../db/users-table";

export const router = Router();

// Register a new user
router.post("/register", (req: Request, res: Response) => {
  const { username, passwordHash, role, patientId } = req.body;

  // Validate input
  if (!username || !passwordHash || !role) {
    return res.status(400).json({ error: "Username, password hash, and role are required" });
  }

  // Check if user already exists
  const existingUser = getAllUsers().find(u => u.username === username);
  if (existingUser) {
    return res.status(409).json({ error: "Username already exists" });
  }

  // Insert new user
  const userId = insertUser(patientId || null, username, passwordHash, role);

  res.status(201).json({ id: userId, username, role });
});

// Login user
router.post("/login", (req: Request, res: Response) => {
  const { username, passwordHash } = req.body;

  // Validate input
  if (!username || !passwordHash) {
    return res.status(400).json({ error: "Username and password hash are required" });
  }

  // Find user
  const user = getAllUsers().find(u => u.username === username && u.password_hash === passwordHash);
  if (!user) {
    return res.status(401).json({ error: "Invalid credentials" });
  }

  // Return user info (excluding password)
