import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync(":memory:");

interface Meal {
  id: number;
  name: string;
  description: string;
  price: number;
  category: string;
  available: boolean;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS meals (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    description TEXT,
    price REAL NOT NULL,
    category TEXT NOT NULL,
    available BOOLEAN NOT NULL
  )
`;

db.exec(createTableSql);

export function getAllMeals(): Meal[] {
  const stmt = db.prepare(`SELECT * FROM meals`);
  return stmt.all() as unknown as Meal[];
}

export function getMealById(id: number): Meal | undefined {
  const stmt = db.prepare(`SELECT * FROM meals WHERE id = ?`);
  return stmt.get(id) as unknown as Meal | undefined;
}

export function insertMeal(meal: Omit<Meal, "id">): number {
  const stmt = db.prepare(
    `INSERT INTO meals (name, description, price, category, available) VALUES (?, ?, ?, ?, ?)`
  );
  const result = stmt.run(meal.name, meal.description, meal.price, meal.category, meal.available);
  return Number(result.lastInsertRowid);
}

export function updateMeal(id: number, meal: Partial<Omit<Meal, "id">>): boolean {
  const fields = [];
  const values = [];

  if (meal.name !== undefined) {
    fields.push("name = ?");
    values.push(meal.name);
  }

  if (meal.description !== undefined) {
    fields.push("description = ?");
    values.push(meal.description);
  }

  if (meal.price !== undefined) {
    fields.push("price = ?");
    values.push(meal.price);
  }

  if (meal.category !== undefined) {
    fields.push("category = ?");
    values.push(meal.category);
  }

  if (meal.available !== undefined) {
    fields.push("available = ?");
    values.push(meal.available);
  }

  if (fields.length === 0) {
    return false;
  }

  values.push(id);

  const sql = `UPDATE meals SET ${fields.join(", ")} WHERE id = ?`;
  const stmt = db.prepare(sql);
  stmt.run(values);

  return true;
}

export function deleteMeal(id: number): boolean {
  const stmt = db.prepare(`DELETE FROM meals WHERE id = ?`);
  const result = stmt.run(id);
  return result.changes > 0;
}

