import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

const ADMIN_PATHS = ["/admin", "/admin/"];
const ADMIN_METHODS = ["POST", "PUT", "DELETE"];

function isPathAdmin(path: string): boolean {
  return ADMIN_PATHS.some(adminPath => 
    path === adminPath || path.startsWith(adminPath + "/")
  );
}

function isAdminRequest(req: Request): boolean {
  return (
    ADMIN_METHODS.includes(req.method) &&
    isPathAdmin(req.path)
  );
}

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Skip validation for non-admin requests
  if (!isAdminRequest(req)) {
    next();
    return;
  }

  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized: Missing or invalid token" });
    return;
  }

  const token = authHeader.substring(7);
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: "Server configuration error: JWT_SECRET not set" });
    return;
  }

  // Simple token verification (in a real app, use proper JWT library)
  const [header, payload, signature] = token.split(".");

  if (!header || !payload || !signature) {
    res.status(401).json({ error: "Unauthorized: Invalid token format" });
    return;
  }

  try {
    const expectedSignature = createHmac("sha256", secret)
      .update(`${header}.${payload}`)
      .digest("base64url");

    const signatureBuffer = Buffer.from(signature, "base64url");
    const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");

    if (!timingSafeEqual(signatureBuffer, expectedSignatureBuffer)) {
      res.status(401).json({ error: "Unauthorized: Invalid token signature" });
      return;
    }

    // Basic role check - in a real app, decode the payload to check roles
    const decodedPayload = JSON.parse(Buffer.from(payload, "base64url").toString());

    if (decodedPayload.role !== "admin") {
      res.status(403).json({ error: "Forbidden: Insufficient permissions" });
      return;
    }

    next();
  } catch (error) {
    res.status(401).json({ error: "Unauthorized: Invalid token" });
  }
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process POST requests to /login endpoint
  if (req.method !== "POST" || req.path !== "/login") {
    next();
    return;
  }

  const jwtSecret = process.env.JWT_SECRET;

  if (!jwtSecret) {
    res.status(500).json({ error: "Server configuration error: JWT_SECRET not set" });
    return;
  }

  const authHeader = req.headers.authorization;

  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Missing or invalid authorization header" });
    return;
  }

  const token = authHeader.substring(7); // Remove 'Bearer '

  try {
    // Basic token structure validation
    const parts = token.split(".");
    if (parts.length !== 3) {
      res.status(401).json({ error: "Invalid token format" });
      return;
    }

    const [header, payload, signature] = parts;

    // Verify signature using HMAC-SHA256
    const expectedSignature = createHmac("sha256", jwtSecret)
      .update(`${header}.${payload}`)
      .digest("base64url");

    // Use timingSafeEqual to prevent timing attacks
    const signatureBuffer = Buffer.from(signature, "base64url");
    const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");

    if (!timingSafeEqual(signatureBuffer, expectedSignatureBuffer)) {
      res.status(401).json({ error: "Invalid token signature" });
      return;
    }

    // If we get here, the token is valid
    next();
  } catch (error) {
    res.status(401).json({ error: "Token verification failed" });
  }
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only validate POST, PUT, PATCH, DELETE requests
  if (!['POST', 'PUT', 'PATCH', 'DELETE'].includes(req.method)) {
    next();
    return;
  }

  // Skip validation for health check endpoints
  if (req.path === '/health') {
    next();
    return;
  }

  // Validate request body for potential injection attacks
  if (req.body) {
    validateRequestBody(req.body);
  }

  // Validate query parameters
  if (req.query) {
    validateQueryParams(req.query);
  }

  next();
}

function validateRequestBody(body: any): void {
  if (typeof body === 'object' && body !== null) {
    Object.entries(body).forEach(([key, value]) => {
      // Check for potentially dangerous characters
      if (typeof value === 'string') {
        // Reject if contains common SQL injection patterns
        if (value.match(/(union|select|insert|update|delete|drop|create|alter|exec|execute)/i)) {
          throw new Error('Invalid input detected');
        }

        // Reject if contains common XSS patterns
        if (value.match(/<script.*?>.*?<\/script>/i)) {
          throw new Error('Invalid input detected');
        }
      }

      // Recursively validate nested objects
      if (typeof value === 'object' && value !== null) {
        validateRequestBody(value);
      }
    });
  }
}

function validateQueryParams(query: any): void {
  if (typeof query === 'object' && query !== null) {
    Object.entries(query).forEach(([key, value]) => {
      if (typeof value === 'string') {
        // Reject if contains common SQL injection patterns
        if (value.match(/(union|select|insert|update|delete|drop|create|alter|exec|execute)/i)) {
          throw new Error('Invalid input detected');
        }

        // Reject if contains common XSS patterns
        if (value.match(/<script.*?>.*?<\/script>/i)) {
          throw new Error('Invalid input detected');
        }
      }
    });
  }
}

