import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock user database
const users = new Map<string, { email: string; password: string; role: string }>();

// Helper to generate mock JWT token
const generateToken = () => {
  return `token_${Math.random().toString(36).substring(2, 15)}`;
};

// Register route
router.post('/register', (req: Request, res: Response) => {
  const { email, password, role = 'user' } = req.body;

  if (!email || !password) {
    return res.status(400).json({ error: 'Email and password are required' });
  }

  if (users.has(email)) {
    return res.status(400).json({ error: 'User already exists' });
  }

  users.set(email, { email, password, role });
  const token = generateToken();

  return res.status(201).json({ token, email, role });
});

// Login route
router.post('/login', (req: Request, res: Response) => {
  const { email, password } = req.body;

  if (!email || !password) {
    return res.status(400).json({ error: 'Email and password are required' });
  }

  const user = users.get(email);

  if (!user || user.password !== password) {
    return res.status(401).json({ error: 'Invalid credentials' });
  }

  const token = generateToken();
  return res.json({ token, email, role: user.role });
});

// Middleware to verify token (mock)
const authenticate = (req: Request, res: Response, next: Function) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'Access token required' });
  }

  // Mock verification - in real app, decode and validate JWT
  const user = Array.from(users.entries()).find(([_, u]) => 
    generateToken() === token
  );

  if (!user) {
    return res.status(401).json({ error: 'Invalid token' });
  }

  (req as any).userId = user[0];
  next();
};

// Get user profile
router.get('/profile', authenticate, (req: Request, res: Response) => {
  const userId = (req as any).userId;
  const user = users.get(userId);

  if (!user) {
    return res.status(404).json({ error: 'User not found' });
  }

  return res.json({ email: user.email, role: user.role });
});

// Update user role (admin only)
router.put('/role', authenticate, (req: Request, res: Response) => {
  const userId = (req as any).userId;
  const user = users.get(userId);

  if (!user) {
    return res.status(404).json({ error: 'User not found' });
  }

  if (user.role !== 'admin') {
    return res.status(403).json({ error: 'Admin access required' });
  }

  const { email, role } = req.body;

  if (!email || !role) {
    return res.status(400).json({ error: 'Email and role are required' });
  }

  const targetUser = users.get(email);

  if (!targetUser) {
    return res.status(404).json({ error: 'Target user not found' });
  }

  targetUser.role = role;
  users.set(email, targetUser);

  return res.json({ message: 'Role updated successfully' });
});

import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock database functions - in a real implementation these would connect to a database
const mockPolicies = [
  { id: "1", vehicleId: "V001", policyNumber: "P001", renewalDate: "2023-12-01", status: "active" },
  { id: "2", vehicleId: "V002", policyNumber: "P002", renewalDate: "2023-11-15", status: "pending" }
];

const findPolicyById = (id: string) => {
  return mockPolicies.find(policy => policy.id === id);
};

const createPolicy = (policyData: any) => {
  const newPolicy = {
    id: String(mockPolicies.length + 1),
    ...policyData
  };
  mockPolicies.push(newPolicy);
  return newPolicy;
};

const updatePolicy = (id: string, updateData: any) => {
  const index = mockPolicies.findIndex(policy => policy.id === id);
  if (index === -1) return null;

  mockPolicies[index] = { ...mockPolicies[index], ...updateData };
  return mockPolicies[index];
};

const deletePolicy = (id: string) => {
  const index = mockPolicies.findIndex(policy => policy.id === id);
  if (index === -1) return false;

  mockPolicies.splice(index, 1);
  return true;
};

// List all policies
router.get("/policies", (req: Request, res: Response) => {
  res.json(mockPolicies);
});

// Get a specific policy by ID
router.get("/policies/:id", (req: Request, res: Response) => {
  const policy = findPolicyById(req.params.id);
  if (!policy) {
    return res.status(404).json({ error: "Policy not found" });
  }
  res.json(policy);
});

// Create a new policy
router.post("/policies", (req: Request, res: Response) => {
  const { vehicleId, policyNumber, renewalDate, status } = req.body;

  if (!vehicleId || !policyNumber || !renewalDate || !status) {
    return res.status(400).json({ error: "Missing required fields: vehicleId, policyNumber, renewalDate, status" });
  }

  const newPolicy = createPolicy({ vehicleId, policyNumber, renewalDate, status });
  res.status(201).json(newPolicy);
});

// Update a policy
router.put("/policies/:id", (req: Request, res: Response) => {
  const { vehicleId, policyNumber, renewalDate, status } = req.body;

  const updatedPolicy = updatePolicy(req.params.id, { vehicleId, policyNumber, renewalDate, status });

  if (!updatedPolicy) {
    return res.status(404).json({ error: "Policy not found" });
  }

  res.json(updatedPolicy);
});

// Delete a policy
router.delete("/policies/:id", (req: Request, res: Response) => {
  const deleted = deletePolicy(req.params.id);

  if (!deleted) {
    return res.status(404).json({ error: "Policy not found" });
  }

  res.json({ message: "Policy deleted successfully" });
});

