export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply authorization checks to routes that require it
  const protectedPaths = [/^\/policies\/.+$/, /^\/users\/.+$/];
  const isProtectedPath = protectedPaths.some(path => path.test(req.path));

  if (!isProtectedPath) {
    next();
    return;
  }

  // Check if user is authenticated
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized: Missing or invalid token" });
    return;
  }

  const token = authHeader.substring(7);
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: "Server configuration error: JWT_SECRET not set" });
    return;
  }

  try {
    // Simple token validation - in a real app, you'd decode and verify the JWT properly
    const [userId, role] = token.split(":");

    if (!userId || !role) {
      res.status(401).json({ error: "Unauthorized: Invalid token format" });
      return;
    }

    // Verify token signature using HMAC-SHA256
    const expectedSignature = createHmac("sha256", secret)
      .update(userId + ":" + role)
      .digest("hex");

    const providedSignature = token.split(".")[1];

    if (!providedSignature) {
      res.status(401).json({ error: "Unauthorized: Invalid token format" });
      return;
    }

    const expectedBuffer = Buffer.from(expectedSignature, "hex");
    const providedBuffer = Buffer.from(providedSignature, "hex");

    if (expectedBuffer.length !== providedBuffer.length || 
        !timingSafeEqual(expectedBuffer, providedBuffer)) {
      res.status(401).json({ error: "Unauthorized: Invalid token signature" });
      return;
    }

    // Attach user info to request for downstream middleware/route handlers
    (req as any).user = { id: userId, role };

    // For policy-related routes, check ownership
    if (req.path.startsWith("/policies/")) {
      const policyId = req.path.split("/")[3];
      const userIdFromToken = userId;

      // In a real implementation, we would check if the user owns this policy
      // For now, we'll just allow access to all policies (simplified for example)
      // But in practice, you'd query the database to verify ownership

      // Example: if (policyOwnerId !== userIdFromToken) {
      //   return res.status(403).json({ error: "Forbidden: Access denied" });
      // }
    }

    next();
  } catch (error) {
    res.status(401).json({ error: "Unauthorized: Invalid token" });
  }
}

