        setPolicies(mockPolicies);
        setFilteredPolicies(mockPolicies);
      } catch (err) {
        setError("Failed to load policies");
      } finally {
        setLoading(false);
      }
    };

    fetchPolicies();
  }, []);

  useEffect(() => {
    let result = policies;

    if (searchTerm) {
      const term = searchTerm.toLowerCase();
      result = result.filter(policy => 
        policy.vehicleMake.toLowerCase().includes(term) ||
        policy.vehicleModel.toLowerCase().includes(term) ||
        policy.policyNumber.toLowerCase().includes(term)
      );
    }

    if (statusFilter !== "all") {
      result = result.filter(policy => policy.status === statusFilter);
    }

    setFilteredPolicies(result);
  }, [searchTerm, statusFilter, policies]);

  const getStatusColor = (status: Policy["status"]) => {
    switch (status) {
      case "active": return "#4ade80"; // green
      case "expired": return "#f87171"; // red
      case "upcoming": return "#fbbf24"; // yellow
      default: return "#94a3b8"; // gray
