export function CaseDetailPage({ caseId }: { caseId: string }) {
  const [caseDetail, setCaseDetail] = useState<CaseDetail | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const fetchCaseDetail = async () => {
      try {
        const response = await fetch(`/api/cases/${caseId}`);
        if (!response.ok) {
          throw new Error(`Failed to fetch case details: ${response.status}`);
        }
        const data = await response.json();
        setCaseDetail(data);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
      } finally {
        setLoading(false);
      }
    };

    fetchCaseDetail();
  }, [caseId]);

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
  }

  if (!caseDetail) {
    return <div style={{ textAlign: "center", padding: "20px" }}>No case found</div>;
  }

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ fontSize: "24px", marginBottom: "10px" }}>{caseDetail.title}</h1>
      <p style={{ fontSize: "16px", marginBottom: "20px", color: "#666" }}>
        Case Number: {caseDetail.caseNumber}
      </p>

      <div style={{ marginBottom: "20px", padding: "15px", border: "1px solid #ddd", borderRadius: "8px" }}>
        <h2 style={{ fontSize: "18px", marginBottom: "10px" }}>Case Details</h2>
        <p><strong>Description:</strong> {caseDetail.description}</p>
        <p><strong>Filing Date:</strong> {caseDetail.filingDate}</p>
        <p><strong>Status:</strong> {caseDetail.status}</p>
      </div>

      <div style={{ marginBottom: "20px" }}>
        <h2 style={{ fontSize: "18px", marginBottom: "10px" }}>Parties</h2>
        {caseDetail.parties.length === 0 ? (
          <p>No parties listed</p>
        ) : (
          <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
            {caseDetail.parties.map((party) => (
              <div key={party.id} style={{ padding: "10px", border: "1px solid #ddd", borderRadius: "4px" }}>
                <strong>{party.name}</strong> - {party.role}
              </div>
            ))}
          </div>
        )}
      </div>

      <div>
        <h2 style={{ fontSize: "18px", marginBottom: "10px" }}>Hearings</h2>
        {caseDetail.hearings.length === 0 ? (
          <p>No hearings scheduled</p>
