            {caseDetail.hearings.map((hearing) => (
              <div key={hearing.id} style={{ padding: "15px", border: "1px solid #ddd", borderRadius: "8px" }}>
                <div style={{ display: "flex", justifyContent: "space-between" }}>
                  <span><strong>Date:</strong> {hearing.date}</span>
