const mockCakeTypes = [
  { id: 1, name: "Chocolate Fudge", description: "Rich chocolate cake with fudge frosting", price: 25.99, available: true },
  { id: 2, name: "Vanilla Dream", description: "Classic vanilla cake with cream frosting", price: 22.50, available: true },
];

const mockCustomizationOptions = [
  { id: 1, name: "Fruit Toppings", options: ["Strawberries", "Blueberries", "Raspberries"] },
  { id: 2, name: "Cake Size", options: ["8 inch", "12 inch", "16 inch"] },
];

const getCakeTypes = () => Promise.resolve(mockCakeTypes);
const getCakeTypeById = (id: number) => {
  const cake = mockCakeTypes.find(c => c.id === id);
  return Promise.resolve(cake || null);
};
const createCakeType = (cakeData: any) => {
  const newCake = {
    id: mockCakeTypes.length + 1,
    ...cakeData,
    available: cakeData.available !== undefined ? cakeData.available : true
  };
  mockCakeTypes.push(newCake);
  return Promise.resolve(newCake);
};
const updateCakeType = (id: number, cakeData: any) => {
  const index = mockCakeTypes.findIndex(c => c.id === id);
  if (index === -1) return Promise.resolve(null);
  mockCakeTypes[index] = { ...mockCakeTypes[index], ...cakeData };
  return Promise.resolve(mockCakeTypes[index]);
};
const deleteCakeType = (id: number) => {
  const index = mockCakeTypes.findIndex(c => c.id === id);
  if (index === -1) return Promise.resolve(false);
  mockCakeTypes.splice(index, 1);
  return Promise.resolve(true);
};

