import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock data structures to simulate database operations
const orders = [] as Array<{
  id: string;
  customerId: string;
  items: Array<{ cakeType: string; quantity: number; customization: string }>;
  total: number;
  deliveryDate: string;
  status: 'pending' | 'confirmed' | 'shipped' | 'delivered';
}>;

const customers = [] as Array<{ id: string; name: string; email: string }>;

// Helper function to calculate total price
const calculateTotal = (items: Array<{ cakeType: string; quantity: number; customization: string }>): number => {
  // Base prices for different cake types
  const basePrices = {
    chocolate: 25,
    vanilla: 20,
    redVelvet: 30
  };

  return items.reduce((total, item) => {
    const basePrice = basePrices[item.cakeType as keyof typeof basePrices] || 0;
    return total + (basePrice * item.quantity);
  }, 0);
};

// GET /orders - List all orders
router.get('/orders', (req: Request, res: Response) => {
  res.json(orders);
});

// GET /orders/:id - Get a specific order by ID
router.get('/orders/:id', (req: Request, res: Response) => {
  const orderId = req.params.id;
  const order = orders.find(o => o.id === orderId);

  if (!order) {
    return res.status(404).json({ error: 'Order not found' });
  }

  res.json(order);
});

// POST /orders - Create a new order
router.post('/orders', (req: Request, res: Response) => {
  const { customerId, items, deliveryDate } = req.body;

  if (!customerId || !items || !deliveryDate) {
    return res.status(400).json({ error: 'Missing required fields: customerId, items, deliveryDate' });
  }

  const total = calculateTotal(items);

  const newOrder = {
    id: `order-${Date.now()}`,
    customerId,
    items,
    total,
    deliveryDate,
    status: 'pending' as const
  };

  orders.push(newOrder);

  res.status(201).json(newOrder);
});

// PUT /orders/:id - Update an existing order
router.put('/orders/:id', (req: Request, res: Response) => {
  const orderId = req.params.id;
  const orderIndex = orders.findIndex(o => o.id === orderId);

  if (orderIndex === -1) {
    return res.status(404).json({ error: 'Order not found' });
  }

  const { customerId, items, deliveryDate, status } = req.body;

  if (!customerId || !items || !deliveryDate) {
    return res.status(400).json({ error: 'Missing required fields: customerId, items, deliveryDate' });
  }

  const updatedOrder = {
    ...orders[orderIndex],
    customerId,
    items,
    deliveryDate,
    total: calculateTotal(items),
    status: status || 'pending'
  };

  orders[orderIndex] = updatedOrder;

  res.json(updatedOrder);
});

// DELETE /orders/:id - Delete an order
router.delete('/orders/:id', (req: Request, res: Response) => {
  const orderId = req.params.id;
  const orderIndex = orders.findIndex(o => o.id === orderId);

  if (orderIndex === -1) {
    return res.status(404).json({ error: 'Order not found' });
  }

  orders.splice(orderIndex, 1);

  res.json({ message: 'Order deleted successfully' });
});

// POST /orders/:id/pay - Process payment for an order
router.post('/orders/:id/pay', (req: Request, res: Response) => {
  const orderId = req.params.id;
  const order = orders.find(o => o.id === orderId);

  if (!order) {
    return res.status(404).json({ error: 'Order not found' });
  }

  // Simulate payment processing
  const paymentSuccess = Math.random() > 0.2; // 80% success rate

  if (!paymentSuccess) {
    return res.status(400).json({ error: 'Payment processing failed' });
  }

  // Update order status to confirmed after successful payment
  const updatedOrder = {
    ...order,
    status: 'confirmed' as const
  };

  const orderIndex = orders.findIndex(o => o.id === orderId);
  orders[orderIndex] = updatedOrder;

  res.json({ message: 'Payment processed successfully', order: updatedOrder });
});

import { Router, type Request, type Response } from "express";

export const router = Router();

// In-memory storage for carts (in a real app, this would be a database)
const carts: Map<string, any[]> = new Map();

// Helper to get or create a cart for a user
const getUserCart = (userId: string): any[] => {
  if (!carts.has(userId)) {
    carts.set(userId, []);
  }
  return carts.get(userId)!;
};

// Add item to cart
router.post("/cart/:userId/items", (req: Request, res: Response) => {
  const { userId } = req.params;
  const { itemId, quantity } = req.body;

  if (!itemId || quantity === undefined || quantity <= 0) {
    return res.status(400).json({ error: "Item ID and valid quantity required" });
  }

  const userCart = getUserCart(userId);
  const existingItemIndex = userCart.findIndex(item => item.itemId === itemId);

  if (existingItemIndex >= 0) {
    userCart[existingItemIndex].quantity += quantity;
  } else {
    userCart.push({ itemId, quantity });
  }

  return res.status(201).json({ message: "Item added to cart", cart: userCart });
});

// Remove item from cart
router.delete("/cart/:userId/items/:itemId", (req: Request, res: Response) => {
  const { userId, itemId } = req.params;

  const userCart = getUserCart(userId);
  const itemIndex = userCart.findIndex(item => item.itemId === itemId);

  if (itemIndex < 0) {
    return res.status(404).json({ error: "Item not found in cart" });
  }

  userCart.splice(itemIndex, 1);
  return res.json({ message: "Item removed from cart", cart: userCart });
});

// Get cart items
router.get("/cart/:userId", (req: Request, res: Response) => {
  const { userId } = req.params;
  const userCart = getUserCart(userId);
  return res.json({ items: userCart });
});

// Clear cart
router.delete("/cart/:userId", (req: Request, res: Response) => {
  const { userId } = req.params;
  carts.set(userId, []);
  return res.json({ message: "Cart cleared" });
});

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process POST requests to /login endpoint
  if (req.method !== "POST" || req.path !== "/login") {
    next();
    return;
  }

  const jwtSecret = process.env.JWT_SECRET;
  if (!jwtSecret) {
    res.status(500).json({ error: "Internal server error" });
    return;
  }

  // In a real implementation, we would verify the JWT token here
  // For now, we'll just simulate the verification process
  // This is a placeholder implementation

  // Simulate token verification
  const token = req.headers.authorization?.split(" ")[1];
  if (!token) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  // Basic token structure validation
  const parts = token.split(".");
  if (parts.length !== 3) {
    res.status(401).json({ error: "Invalid token format" });
    return;
  }

  try {
    // Decode the payload (base64url)
    const payload = Buffer.from(parts[1], "base64").toString("utf-8");
    const payloadObj = JSON.parse(payload);

    // Verify signature
    const signature = parts[2];
    const expectedSignature = createHmac("sha256", jwtSecret)
      .update(`${parts[0]}.${parts[1]}`)
      .digest("base64url");

    // Use timingSafeEqual to prevent timing attacks
    const isValid = timingSafeEqual(
      Buffer.from(signature, "base64url"),
      Buffer.from(expectedSignature, "base64url")
    );

    if (!isValid) {
      res.status(401).json({ error: "Invalid token" });
      return;
    }

    // If we get here, the token is valid
    // In a real implementation, we would set the user in the request object
    // For example: req.user = payloadObj;

    next();
  } catch (error) {
    res.status(401).json({ error: "Invalid token" });
  }
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply role-based access control to specific routes
  const adminPaths = ["/admin", "/staff"];
  const isAdminRoute = adminPaths.some(path => req.path.startsWith(path));

  // Skip validation for non-admin routes
  if (!isAdminRoute) {
    next();
    return;
  }

  // Check if user has required role
  const userRole = req.headers["x-user-role"] as string | undefined;

  // For staff-only routes, ensure user is staff
  if (req.path.startsWith("/staff") && userRole !== "staff") {
    res.status(403).json({ error: "Access denied: Staff only" });
    return;
  }

  // For admin-only routes, ensure user is admin
  if (req.path.startsWith("/admin") && userRole !== "admin") {
    res.status(403).json({ error: "Access denied: Admin only" });
    return;
  }

  // If we reach here, user has proper role or path doesn't require role checking
  next();
}

