import { useEffect, useState } from "react";

interface Cake {
  id: number;
  name: string;
  basePrice: number;
  customizationOptions: {
    flavor: string;
    frosting: string;
    decorations: string[];
  };
}

interface CartItem {
  cake: Cake;
  quantity: number;
}

export function ShoppingCart() {
  const [cartItems, setCartItems] = useState<CartItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    // Simulate fetching cart items from API
    const fetchCartItems = async () => {
      try {
        // In a real app, this would be an actual API call
        // const response = await fetch('/api/cart');
        // const items = await response.json();

        // Mock data for demonstration
        const mockItems: CartItem[] = [
          {
            cake: {
              id: 1,
              name: "Chocolate Fudge Cake",
              basePrice: 25,
              customizationOptions: {
                flavor: "Rich Chocolate",
                frosting: "Ganache",
                decorations: ["Candied Violets", "Gold Leaf"]
              }
            },
            quantity: 2
          },
          {
            cake: {
              id: 2,
              name: "Vanilla Dream Cake",
              basePrice: 20,
              customizationOptions: {
                flavor: "Classic Vanilla",
                frosting: "Buttercream",
                decorations: ["Fresh Berries"]
              }
            },
            quantity: 1
          }
        ];

        setCartItems(mockItems);
        setLoading(false);
      } catch (err) {
        setError("Failed to load cart items");
        setLoading(false);
      }
    };

    fetchCartItems();
  }, []);

  const calculateTotal = () => {
    return cartItems.reduce((total, item) => {
      const customizationPrice = item.cake.customizationOptions.decorations.length * 5;
      return total + (item.cake.basePrice + customizationPrice) * item.quantity;
    }, 0);
  };

  const handleQuantityChange = (id: number, newQuantity: number) => {
    if (newQuantity < 1) return;

    setCartItems(prevItems => 
      prevItems.map(item => 
        item.cake.id === id ? { ...item, quantity: newQuantity } : item
      )
    );
  };

  const removeItem = (id: number) => {
    setCartItems(prevItems => prevItems.filter(item => item.cake.id !== id));
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
  }

  if (cartItems.length === 0) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Your cart is empty</div>;
  }

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Your Shopping Cart</h1>

      <div style={{ marginBottom: "20px" }}>
        {cartItems.map(item => (
          <div key={item.cake.id} style={{ border: "1px solid #ddd", borderRadius: "8px", padding: "15px", marginBottom: "15px" }}>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
              <div>
                <h3>{item.cake.name}</h3>
                <p>Flavor: {item.cake.customizationOptions.flavor}</p>
                <p>Frosting: {item.cake.customizationOptions.frosting}</p>
                <p>Decorations: {item.cake.customizationOptions.decorations.join(", ")}</p>
              </div>
              <div style={{ textAlign: "right" }}>
                <div style={{ display: "flex", alignItems: "center", gap: "10px" }}>
                  <button 
                    onClick={() => handleQuantityChange(item.cake.id, item.quantity - 1)}
                    disabled={item.quantity <= 1}
                    style={{ padding: "5px 10px", backgroundColor: "#f0f0f0", border: "none", borderRadius: "4px" }}
                  >
                    -
                  </button>
                  <span style={{ minWidth: "30px", textAlign: "center" }}>{item.quantity}</span>
                  <button 
                    onClick={() => handleQuantityChange(item.cake.id, item.quantity + 1)}
                    style={{ padding: "5px 10px", backgroundColor: "#f0f0f0", border: "none", borderRadius: "4px" }}
                  >
                    +
                  </button>
                </div>
                <p style={{ marginTop: "10px", fontWeight: "bold" }}>
                  ${(item.cake.basePrice + item.cake.customizationOptions.decorations.length * 5) * item.quantity}
                </p>
              </div>
            </div>
            <button 
              onClick={() => removeItem(item.cake.id)}
              style={{ 
                marginTop: "10px", 
                padding: "5px 10px", 
                backgroundColor: "#ff4d4d", 
                color: "white", 
                border: "none", 
                borderRadius: "4px" 
              }}
            >
              Remove
            </button>
          </div>
        ))}
      </div>

      <div style={{ 
        border: "1px solid #ddd", 
        borderRadius: "8px", 
        padding: "15px", 
        backgroundColor: "#f9f9f9" 
      }}>
        <div style={{ display: "flex", justifyContent: "space-between", marginBottom: "10px" }}>
          <span>Total:</span>
          <span style={{ fontWeight: "bold" }}>${calculateTotal()}</span>
        </div>
        <button 
          style={{ 
            width: "100%", 
            padding: "12px", 
            backgroundColor: "#4CAF50", 
            color: "white", 
            border: "none", 
            borderRadius: "4px", 
            fontSize: "16px", 
            fontWeight: "bold" 
          }}
        >
          Proceed to Checkout
        </button>
      </div>
    </div>
  );
}

import { useEffect, useState } from "react";

interface Order {
  id: string;
  status: "pending" | "processing" | "shipped" | "delivered";
  deliveryAddress: string;
  estimatedArrival: string;
}

export function OrderTrackingPage() {
  const [order, setOrder] = useState<Order | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    // Simulate fetching order data
    const fetchOrder = async () => {
      try {
        // In a real app, this would be an API call
        // const response = await fetch(`/api/orders/${orderId}`);
        // const data = await response.json();

        // Mock data for demonstration
        await new Promise(resolve => setTimeout(resolve, 500));
        const mockOrder: Order = {
          id: "ORD-12345",
          status: "shipped",
          deliveryAddress: "123 Main St, Apt 4B, New York, NY 10001",
          estimatedArrival: "2023-06-15T14:30:00Z"
        };

        setOrder(mockOrder);
      } catch (err) {
        setError("Failed to load order details. Please try again later.");
      } finally {
        setLoading(false);
      }
    };

    fetchOrder();
  }, []);

  if (loading) {
    return (
      <div style={{
        fontFamily: 'system-ui, sans-serif',
        maxWidth: '600px',
        margin: '0 auto',
        padding: '20px'
      }}>
        <h1>Order Tracking</h1>
        <p>Loading...</p>
      </div>
    );
  }

  if (error) {
    return (
      <div style={{
        fontFamily: 'system-ui, sans-serif',
        maxWidth: '600px',
        margin: '0 auto',
        padding: '20px'
      }}>
        <h1>Order Tracking</h1>
        <p>{error}</p>
      </div>
    );
  }

  if (!order) {
    return (
      <div style={{
        fontFamily: 'system-ui, sans-serif',
        maxWidth: '600px',
        margin: '0 auto',
        padding: '20px'
      }}>
        <h1>Order Tracking</h1>
        <p>No order found.</p>
      </div>
    );
  }

  const statusText = {
    pending: "Pending",
    processing: "Processing",
    shipped: "Shipped",
    delivered: "Delivered"
  };

  const formatDate = (dateString: string) => {
    const date = new Date(dateString);
    return date.toLocaleDateString('en-US', {
      weekday: 'long',
      year: 'numeric',
      month: 'long',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    });
  };

  return (
    <div style={{
      fontFamily: 'system-ui, sans-serif',
      maxWidth: '600px',
      margin: '0 auto',
      padding: '20px'
    }}>
      <h1>Order Tracking</h1>
      <div style={{
        backgroundColor: '#f8f9fa',
        borderRadius: '8px',
        padding: '20px',
        marginBottom: '20px'
      }}>
        <h2>Order #{order.id}</h2>
        <p><strong>Status:</strong> {statusText[order.status]}</p>
        <p><strong>Delivery Address:</strong></p>
        <p>{order.deliveryAddress}</p>
        <p><strong>Estimated Arrival:</strong> {formatDate(order.estimatedArrival)}</p>
      </div>

      <div style={{
        backgroundColor: '#e9ecef',
        borderRadius: '8px',
        padding: '20px'
      }}>
        <h3>Delivery Progress</h3>
        <div style={{ display: 'flex', justifyContent: 'space-between', position: 'relative' }}>
          <div style={{ textAlign: 'center', zIndex: 1 }}>
            <div style={{
              width: '20px',
              height: '20px',
              borderRadius: '50%',
              backgroundColor: order.status !== 'pending' ? '#28a745' : '#ccc',
              margin: '0 auto 5px'
            }}></div>
            <span>Pending</span>
          </div>
          <div style={{ textAlign: 'center', zIndex: 1 }}>
            <div style={{
              width: '20px',
              height: '20px',
              borderRadius: '50%',
              backgroundColor: order.status !== 'pending' && order.status !== 'processing' ? '#28a745' : '#ccc',
              margin: '0 auto 5px'
            }}></div>
            <span>Processing</span>
          </div>
          <div style={{ textAlign: 'center', zIndex: 1 }}>
            <div style={{
              width: '20px',
              height: '20px',
              borderRadius: '50%',
              backgroundColor: order.status === 'shipped' || order.status === 'delivered' ? '#28a745' : '#ccc',
              margin: '0 auto 5px'
            }}></div>
            <span>Shipped</span>
          </div>
          <div style={{ textAlign: 'center', zIndex: 1 }}>
            <div style={{
              width: '20px',
              height: '20px',
              borderRadius: '50%',
              backgroundColor: order.status === 'delivered' ? '#28a745' : '#ccc',
              margin: '0 auto 5px'
            }}></div>
            <span>Delivered</span>
          </div>
          <div style={{
            position: 'absolute',
            top: '10px',
            left: '0',
            right: '0',
            height: '2px',
            backgroundColor: '#dee2e6',
            zIndex: 0
          }}></div>
        </div>
      </div>
    </div>
  );
}

