import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock user database
const users = [
  { id: "1", username: "admin", password: "admin123", role: "admin" },
  { id: "2", username: "employee1", password: "pass123", role: "user" },
  { id: "3", username: "employee2", password: "pass456", role: "user" }
];

// Helper to generate mock JWT token
const generateToken = (userId: string): string => {
  return `token_${userId}`;
};

// Register route
router.post("/register", (req: Request, res: Response) => {
  const { username, password, role = "user" } = req.body;

  if (!username || !password) {
    return res.status(400).json({ error: "Username and password are required" });
  }

  // Check if user already exists
  const existingUser = users.find(user => user.username === username);
  if (existingUser) {
    return res.status(400).json({ error: "User already exists" });
  }

  // Create new user (mock)
  const newUser = {
    id: `${users.length + 1}`,
    username,
    password,
    role
  };

  users.push(newUser);

  const token = generateToken(newUser.id);
  return res.status(201).json({ token, user: { id: newUser.id, username, role } });
});

// Login route
router.post("/login", (req: Request, res: Response) => {
  const { username, password } = req.body;

  if (!username || !password) {
    return res.status(400).json({ error: "Username and password are required" });
  }

  const user = users.find(u => u.username === username && u.password === password);

  if (!user) {
    return res.status(401).json({ error: "Invalid credentials" });
  }

  const token = generateToken(user.id);
  return res.json({ token, user: { id: user.id, username, role: user.role } });
});

// Middleware to verify token (mock implementation)
const authenticateToken = (req: Request, res: Response, next: Function) => {
  const authHeader = req.headers["authorization"];
  const token = authHeader && authHeader.split(" ")[1];

  if (!token) {
    return res.status(401).json({ error: "Access token required" });
  }

  // Mock token verification
  const userId = token.replace("token_", "");
  if (!users.some(u => u.id === userId)) {
    return res.status(403).json({ error: "Invalid token" });
  }

  // Attach user ID to request object
  (req as any).userId = userId;
  next();
};

// Middleware to check role (admin only)
const requireAdmin = (req: Request, res: Response, next: Function) => {
  const userId = (req as any).userId;
  const user = users.find(u => u.id === userId);

  if (!user || user.role !== "admin") {
    return res.status(403).json({ error: "Admin access required" });
  }

  next();
};

// Get user profile (protected route)
router.get("/profile", authenticateToken, (req: Request, res: Response) => {
  const userId = (req as any).userId;
  const user = users.find(u => u.id === userId);

  if (!user) {
    return res.status(404).json({ error: "User not found" });
  }

  return res.json({ id: user.id, username: user.username, role: user.role });
});

// Update user profile (protected route)
router.put("/profile", authenticateToken, (req: Request, res: Response) => {
  const userId = (req as any).userId;
  const user = users.find(u => u.id === userId);

  if (!user) {
    return res.status(404).json({ error: "User not found" });
  }

  const { username, password } = req.body;

  if (username) user.username = username;
  if (password) user.password = password;

  return res.json({ id: user.id, username: user.username, role: user.role });
});

// Delete user profile (protected route)
router.delete("/profile", authenticateToken, (req: Request, res: Response) => {
  const userId = (req as any).userId;
  const userIndex = users.findIndex(u => u.id === userId);

  if (userIndex === -1) {
    return res.status(404).json({ error: "User not found" });
  }

  users.splice(userIndex, 1);
  return res.json({ message: "User deleted successfully" });
});

// Admin-only route to get all users
router.get("/users", authenticateToken, requireAdmin, (req: Request, res: Response) => {
  const userList = users.map(({ password, ...user }) => user);
  return res.json(userList);
});

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

const JWT_SECRET = process.env.JWT_SECRET;

function verifyToken(token: string): boolean {
  if (!JWT_SECRET) {
    return false;
  }

  const parts = token.split(".");
  if (parts.length !== 3) {
    return false;
  }

  const [header, payload, signature] = parts;

  const expectedSignature = createHmac("sha256", JWT_SECRET)
    .update(`${header}.${payload}`)
    .digest("base64url");

  try {
    const expectedBytes = Buffer.from(expectedSignature, "base64url");
    const actualBytes = Buffer.from(signature, "base64url");
    return timingSafeEqual(expectedBytes, actualBytes);
  } catch {
    return false;
  }
}

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply role-based access control to specific routes
  if (!(req.path.startsWith("/admin") && (req.method === "POST" || req.method === "PUT" || req.method === "DELETE"))) {
    return next();
  }

  const authHeader = req.headers.authorization;

  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    return res.status(401).json({ error: "Unauthorized" });
  }

  const token = authHeader.substring(7);

  if (!verifyToken(token)) {
    return res.status(401).json({ error: "Invalid token" });
  }

  // Decode token to extract role (simplified for this example)
  try {
    const payload = JSON.parse(Buffer.from(token.split(".")[1], "base64url").toString());
    const userRole = payload.role;

    if (userRole !== "administrator") {
      return res.status(403).json({ error: "Forbidden" });
    }

    next();
  } catch {
    return res.status(401).json({ error: "Invalid token" });
  }
}

