import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

const JWT_SECRET = process.env.JWT_SECRET;

function verifyToken(token: string): boolean {
  if (!JWT_SECRET) {
    return false;
  }

  const parts = token.split(".");
  if (parts.length !== 3) {
    return false;
  }

  const [header, payload, signature] = parts;

  const expectedSignature = createHmac("sha256", JWT_SECRET)
    .update(`${header}.${payload}`)
    .digest("base64url");

  try {
    const expectedBytes = Buffer.from(expectedSignature, "base64url");
    const actualBytes = Buffer.from(signature, "base64url");
    return timingSafeEqual(expectedBytes, actualBytes);
  } catch {
    return false;
  }
}

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply role-based access control to specific routes
  if (!(req.path.startsWith("/admin") && (req.method === "POST" || req.method === "PUT" || req.method === "DELETE"))) {
    return next();
  }

  const authHeader = req.headers.authorization;

  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    return res.status(401).json({ error: "Unauthorized" });
  }

  const token = authHeader.substring(7);

  if (!verifyToken(token)) {
    return res.status(401).json({ error: "Invalid token" });
  }

  // Decode token to extract role (simplified for this example)
  try {
    const payload = JSON.parse(Buffer.from(token.split(".")[1], "base64url").toString());
    const userRole = payload.role;

    if (userRole !== "administrator") {
      return res.status(403).json({ error: "Forbidden" });
    }

    next();
  } catch {
    return res.status(401).json({ error: "Invalid token" });
  }
}

