export function RouteLogList() {
  const [routeLogs, setRouteLogs] = useState<RouteLog[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [startDate, setStartDate] = useState("");
  const [endDate, setEndDate] = useState("");
  const [driverName, setDriverName] = useState("");

  useEffect(() => {
    fetchRouteLogs();
  }, []);

  const fetchRouteLogs = async () => {
    try {
      setLoading(true);
      const response = await fetch(`/api/route-logs?startDate=${startDate}&endDate=${endDate}&driverName=${driverName}`);
      if (!response.ok) {
        throw new Error(`Failed to fetch route logs: ${response.status} ${response.statusText}`);
      }
      const data = await response.json();
      setRouteLogs(data);
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleSearch = (e: React.FormEvent) => {
    e.preventDefault();
    fetchRouteLogs();
  };

  const formatDate = (dateString: string) => {
    const options: Intl.DateTimeFormatOptions = { year: "numeric", month: "short", day: "numeric" };
    return new Date(dateString).toLocaleDateString(undefined, options);
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Route Logs</h1>

      <form onSubmit={handleSearch} style={{ marginBottom: "20px", display: "flex", flexDirection: "column", gap: "10px" }}>
        <div style={{ display: "flex", flexDirection: "row", gap: "10px", flexWrap: "wrap" }}>
          <input
            type="date"
            value={startDate}
            onChange={(e) => setStartDate(e.target.value)}
            style={{ flex: 1, minWidth: "150px" }}
          />
          <input
            type="date"
            value={endDate}
            onChange={(e) => setEndDate(e.target.value)}
            style={{ flex: 1, minWidth: "150px" }}
          />
          <input
            type="text"
            placeholder="Driver Name"
            value={driverName}
            onChange={(e) => setDriverName(e.target.value)}
            style={{ flex: 1, minWidth: "150px" }}
          />
          <button type="submit" style={{ flex: 1, minWidth: "100px", padding: "8px", backgroundColor: "#007bff", color: "white", border: "none", borderRadius: "4px", cursor: "pointer" }}>
            Search
          </button>
        </div>
      </form>

      {routeLogs.length === 0 ? (
        <div style={{ textAlign: "center", padding: "20px" }}>No route logs found.</div>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
          {routeLogs.map((log) => (
            <div key={log.id} style={{ border: "1px solid #ccc", borderRadius: "8px", padding: "15px", backgroundColor: "#f9f9f9" }}>
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                <div>
                  <h3 style={{ margin: "0 0 5px 0" }}>{log.driverName}</h3>
                  <p style={{ margin: "0 0 5px 0" }}>
                    {formatDate(log.startDate)} - {formatDate(log.endDate)}
                  </p>
                  <p style={{ margin: "0", color: "#666" }}>{log.status}</p>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

