import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock user data storage
const users = [
  { id: 1, username: "admin", password: "admin123", role: "admin" },
  { id: 2, username: "driver1", password: "driver123", role: "driver" },
  { id: 3, username: "user1", password: "user123", role: "user" }
];

// User registration
router.post("/register", (req: Request, res: Response) => {
  const { username, password, role } = req.body;

  // Validate input
  if (!username || !password || !role) {
    return res.status(400).json({ error: "Username, password, and role are required" });
  }

  // Check if user already exists
  const existingUser = users.find(user => user.username === username);
  if (existingUser) {
    return res.status(400).json({ error: "User already exists" });
  }

  // Create new user
  const newUser = {
    id: users.length + 1,
    username,
    password,
    role
  };

  users.push(newUser);
  res.status(201).json(newUser);
});

// User login
router.post("/login", (req: Request, res: Response) => {
  const { username, password } = req.body;

  // Validate input
  if (!username || !password) {
    return res.status(400).json({ error: "Username and password are required" });
  }

  // Find user
  const user = users.find(u => u.username === username && u.password === password);
  if (!user) {
    return res.status(401).json({ error: "Invalid credentials" });
  }

  // Return user info (in a real app, this would include a JWT token)
  res.json({
    id: user.id,
    username: user.username,
    role: user.role
  });
});

// Role-based access control middleware
const authorize = (roles: string[]) => {
  return (req: Request, res: Response, next: Function) => {
    // In a real app, this would check the JWT token
    const userRole = req.headers.role as string;

    if (!userRole || !roles.includes(userRole)) {
      return res.status(403).json({ error: "Access denied" });
    }

    next();
  };
};

// Protected route example for admin only
router.get("/admin", authorize(["admin"]), (req: Request, res: Response) => {
  res.json({ message: "Admin access granted" });
});

// Protected route example for drivers and admins
router.get("/driver", authorize(["driver", "admin"]), (req: Request, res: Response) => {
  res.json({ message: "Driver or admin access granted" });
});

// Protected route example for users, drivers and admins
router.get("/user", authorize(["user", "driver", "admin"]), (req: Request, res: Response) => {
  res.json({ message: "User, driver or admin access granted" });
});

