import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply role-based access control to specific routes
  const protectedPaths = [
    "/admin",
    "/driver",
    "/customer"
  ];

  const isProtectedPath = protectedPaths.some(path => 
    req.path.startsWith(path)
  );

  if (!isProtectedPath) {
    next();
    return;
  }

  // Check if user has proper role for the path
  const userRole = req.headers["x-user-role"] as string | undefined;

  if (!userRole) {
    res.status(401).json({ error: "Unauthorized: Missing role header" });
    return;
  }

  // Validate role based on path
  if (req.path.startsWith("/admin") && userRole !== "admin") {
    res.status(403).json({ error: "Forbidden: Admin access required" });
    return;
  }

  if (req.path.startsWith("/driver") && userRole !== "driver") {
    res.status(403).json({ error: "Forbidden: Driver access required" });
    return;
  }

  if (req.path.startsWith("/customer") && userRole !== "customer") {
    res.status(403).json({ error: "Forbidden: Customer access required" });
    return;
  }

  next();
}

