import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

// Define rate limit configuration
const MAX_REQUESTS = 100;
const TIME_WINDOW_MS = 15 * 60 * 1000; // 15 minutes

// In-memory storage for tracking requests
const requestCounts: Map<string, { count: number; windowStart: number }> = new Map();

/**
 * Express middleware to rate limit API requests
 */
export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply rate limiting to POST requests to the booking endpoint
  if (req.method !== "POST" || !req.path.startsWith("/bookings")) {
    next();
    return;
  }

  const clientIP = getClientIP(req);
  const now = Date.now();

  // Initialize or update request count for this client
  const clientData = requestCounts.get(clientIP) || { count: 0, windowStart: now };

  // Reset counter if time window has passed
  if (now - clientData.windowStart > TIME_WINDOW_MS) {
    clientData.count = 0;
    clientData.windowStart = now;
  }

  // Increment request count
  clientData.count += 1;

  // Update storage
  requestCounts.set(clientIP, clientData);

  // Check if rate limit exceeded
  if (clientData.count > MAX_REQUESTS) {
    res.status(429).json({
      error: "Rate limit exceeded",
      message: "Too many requests from this client"
    });
    return;
  }

  next();
}

/**
 * Helper function to get client IP address
 */
function getClientIP(req: Request): string {
  return (
    req.headers["x-forwarded-for"]?.toString().split(",")[0].trim() ||
    req.connection.remoteAddress ||
    req.socket.remoteAddress ||
    (req.connection as any).socket?.remoteAddress ||
    ""
  );
}

