  res.json(checklistItems);
});

// Get a specific checklist item by ID
router.get("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const item = checklistItems.find(i => i.id === id);

  if (!item) {
    return res.status(404).json({ error: "Checklist item not found" });
  }

  res.json(item);
});

// Create a new checklist item
router.post("/", (req: Request, res: Response) => {
  const { title } = req.body;

  if (!title) {
    return res.status(400).json({ error: "Title is required" });
  }

  const newItem = {
    id: checklistItems.length > 0 ? Math.max(...checklistItems.map(i => i.id)) + 1 : 1,
    title,
    completed: false
  };

  checklistItems.push(newItem);
  res.status(201).json(newItem);
});

// Update a checklist item
router.put("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const { title, completed } = req.body;

  const itemIndex = checklistItems.findIndex(i => i.id === id);

  if (itemIndex === -1) {
    return res.status(404).json({ error: "Checklist item not found" });
  }

  if (title !== undefined) {
    checklistItems[itemIndex].title = title;
  }

  if (completed !== undefined) {
    checklistItems[itemIndex].completed = completed;
  }

  res.json(checklistItems[itemIndex]);
});

// Delete a checklist item
router.delete("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const itemIndex = checklistItems.findIndex(i => i.id === id);

  if (itemIndex === -1) {
    return res.status(404).json({ error: "Checklist item not found" });
  }

  checklistItems.splice(itemIndex, 1);
  res.json({ message: "Checklist item deleted successfully" });
});

