}

import { FC, useState } from "react";

interface WeddingFormData {
  name: string;
  date: string;
  location: string;
  guestCount: number | null;
}

export function WeddingForm() {
  const [formData, setFormData] = useState<WeddingFormData>({
    name: "",
    date: "",
    location: "",
    guestCount: null,
  });

  const [isSubmitting, setIsSubmitting] = useState(false);
  const [submitSuccess, setSubmitSuccess] = useState(false);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
    const { name, value } = e.target;

    if (name === "guestCount") {
      setFormData({
        ...formData,
        guestCount: value ? Number(value) : null,
      });
    } else {
      setFormData({
        ...formData,
        [name]: value,
      });
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);

    try {
      // In a real app, this would make an API call
      // await fetch('/api/weddings', { method: 'POST', body: JSON.stringify(formData) })

      // Simulate API delay
      await new Promise(resolve => setTimeout(resolve, 500));

      setSubmitSuccess(true);
      // Reset form after successful submission
      setFormData({
        name: "",
        date: "",
        location: "",
        guestCount: null,
      });

      // Reset success message after 3 seconds
      setTimeout(() => setSubmitSuccess(false), 3000);
    } catch (error) {
      console.error("Error submitting wedding form:", error);
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div style={styles.container}>
      <h1 style={styles.title}>Add Wedding Details</h1>

      <form onSubmit={handleSubmit} style={styles.form}>
        <div style={styles.inputGroup}>
          <label htmlFor="name" style={styles.label}>Wedding Name</label>
          <input
            type="text"
            id="name"
            name="name"
            value={formData.name}
            onChange={handleChange}
            style={styles.input}
            required
          />
        </div>

        <div style={styles.inputGroup}>
          <label htmlFor="date" style={styles.label}>Date</label>
          <input
            type="date"
            id="date"
            name="date"
            value={formData.date}
            onChange={handleChange}
            style={styles.input}
            required
          />
        </div>

        <div style={styles.inputGroup}>
          <label htmlFor="location" style={styles.label}>Location</label>
          <input
            type="text"
            id="location"
            name="location"
            value={formData.location}
            onChange={handleChange}
            style={styles.input}
            required
          />
        </div>

        <div style={styles.inputGroup}>
          <label htmlFor="guestCount" style={styles.label}>Guest Count</label>
          <input
            type="number"
            id="guestCount"
            name="guestCount"
            value={formData.guestCount || ""}
            onChange={handleChange}
            style={styles.input}
            min="0"
          />
        </div>

        <button
          type="submit"
          disabled={isSubmitting}
          style={styles.submitButton}
        >
          {isSubmitting ? "Saving..." : "Save Wedding Details"}
        </button>

        {submitSuccess && (
          <p style={styles.successMessage}>Wedding details saved successfully!</p>
        )}
      </form>
    </div>
  );
}

