import { useEffect, useState } from "react";

interface Task {
  id: number;
  title: string;
  description: string;
  status: 'not-started' | 'in-progress' | 'completed';
  dueDate: string;
}

export function Checklists() {
  const [checklists, setChecklists] = useState<Task[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchChecklists();
  }, []);

  const fetchChecklists = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/checklists');
      if (!response.ok) {
        throw new Error('Failed to fetch checklists');
      }
      const data = await response.json();
      setChecklists(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  const updateTaskStatus = async (id: number, status: Task['status']) => {
    try {
      const response = await fetch(`/api/checklists/${id}`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ status }),
      });

      if (!response.ok) {
        throw new Error('Failed to update task status');
      }

      // Refresh the checklist after updating
      fetchChecklists();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  const deleteTask = async (id: number) => {
    try {
      const response = await fetch(`/api/checklists/${id}`, {
        method: 'DELETE',
      });

      if (!response.ok) {
        throw new Error('Failed to delete task');
      }

      // Refresh the checklist after deleting
      fetchChecklists();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: '800px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1 style={{ textAlign: 'center' }}>Wedding Checklists</h1>

      {checklists.length === 0 ? (
        <p style={{ textAlign: 'center', padding: '20px' }}>No tasks found. Add some tasks to get started!</p>
      ) : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
          {checklists.map(task => (
            <div 
              key={task.id} 
              style={{ 
                border: '1px solid #ccc', 
                borderRadius: '8px', 
                padding: '15px', 
                backgroundColor: '#f9f9f9'
              }}
            >
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}>
                <div>
                  <h3 style={{ margin: '0 0 10px 0' }}>{task.title}</h3>
                  <p style={{ margin: '0 0 10px 0', color: '#555' }}>{task.description}</p>
                  <p style={{ margin: '0 0 10px 0', color: '#555' }}>
                    Due: {new Date(task.dueDate).toLocaleDateString()}
                  </p>
                </div>
                <div style={{ display: 'flex', flexDirection: 'column', gap: '5px' }}>
                  <select
                    value={task.status}
                    onChange={(e) => updateTaskStatus(task.id, e.target.value as Task['status'])}
                    style={{ padding: '5px', borderRadius: '4px', border: '1px solid #ccc' }}
                  >
                    <option value="not-started">Not Started</option>
                    <option value="in-progress">In Progress</option>
                    <option value="completed">Completed</option>
                  </select>
                  <button 
                    onClick={() => deleteTask(task.id)}
                    style={{ 
                      padding: '5px 10px', 
                      backgroundColor: '#ff4d4d', 
                      color: 'white', 
                      border: 'none', 
                      borderRadius: '4px', 
                      cursor: 'pointer'
                    }}
                  >
                    Delete
                  </button>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

