import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply role-based access control to protected routes
  const protectedPaths = ["/admin", "/staff"];
  const isProtectedPath = protectedPaths.some(path =>
    req.path.startsWith(path)
  );

  if (!isProtectedPath) {
    next();
    return;
  }

  // Check if user has required role
  const userRole = req.headers["x-user-role"] as string | undefined;

  if (!userRole) {
    res.status(401).json({ error: "Unauthorized: Missing role header" });
    return;
  }

  // Validate role
  const validRoles = ["admin", "staff"];
  if (!validRoles.includes(userRole)) {
    res.status(403).json({ error: "Forbidden: Invalid role" });
    return;
  }

  // For admin-only routes
  if (req.path.startsWith("/admin") && userRole !== "admin") {
    res.status(403).json({ error: "Forbidden: Admin access required" });
    return;
  }

  // For staff-only routes
  if (req.path.startsWith("/staff") && userRole !== "staff") {
    res.status(403).json({ error: "Forbidden: Staff access required" });
    return;
  }

  // If we reach here, user has proper access
  next();
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process POST requests to /login endpoint
  if (req.method !== "POST" || req.path !== "/login") {
    next();
    return;
  }

  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: "Server configuration error" });
    return;
  }

  // In a real implementation, we would verify the JWT token here
  // For now, we'll just check that the secret exists
  // This is a placeholder for actual JWT verification logic

  // Simulate token verification
  const token = req.headers.authorization?.split(" ")[1];

  if (!token) {
    res.status(401).json({ error: "No token provided" });
    return;
  }

  try {
    // This is a simplified example - in reality, you'd decode and verify the JWT
    // using proper JWT libraries or manual verification with HMAC-SHA256

    // Example verification logic (simplified):
    const [header, payload, signature] = token.split(".");

    // Create expected signature
    const expectedSignature = createHmac("sha256", secret)
      .update(`${header}.${payload}`)
      .digest("base64url");

    // Use timingSafeEqual to prevent timing attacks
    const signatureBuffer = Buffer.from(signature, "base64url");
    const expectedBuffer = Buffer.from(expectedSignature, "base64url");

    if (!timingSafeEqual(signatureBuffer, expectedBuffer)) {
      res.status(401).json({ error: "Invalid token" });
      return;
    }

    // If we get here, token is valid
    next();
  } catch (error) {
    res.status(401).json({ error: "Invalid token format" });
  }
}

