    e.preventDefault();
    try {
      const url = editingId 
        ? `/api/students/${editingId}`
        : "/api/students";
      const method = editingId ? "PUT" : "POST";

      const response = await fetch(url, {
        method,
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(formData),
