              style={{ 
                backgroundColor: "#28a745", 
                color: "white", 
                border: "none", 
                padding: "10px 20px", 
                borderRadius: "4px", 
                cursor: "pointer" 
              }}
            >
              {editingId ? "Update Student" : "Add Student"}
            </button>
            <button 
              type="button"
              onClick={resetForm}
              style={{ 
                backgroundColor: "#6c757d", 
                color: "white", 
                border: "none", 
