  { id: 2, employeeId: 102, checkIn: "2023-05-01T09:00:00Z", checkOut: null }
];

const findRecordById = (id: number) => {
  return mockAttendanceRecords.find(record => record.id === id);
};

const findRecordsByEmployeeId = (employeeId: number) => {
  return mockAttendanceRecords.filter(record => record.employeeId === employeeId);
};

// Get all attendance records
router.get("/", (req: Request, res: Response) => {
  res.json(mockAttendanceRecords);
});

// Get a specific attendance record by ID
router.get("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid record ID" });
  }

  const record = findRecordById(id);

  if (!record) {
    return res.status(404).json({ error: "Attendance record not found" });
  }

  res.json(record);
});

// Create a new attendance record (check-in)
router.post("/check-in", (req: Request, res: Response) => {
  const { employeeId, checkIn } = req.body;

  if (!employeeId || !checkIn) {
    return res.status(400).json({ error: "Employee ID and check-in time are required" });
  }

  const newRecord = {
    id: mockAttendanceRecords.length + 1,
    employeeId,
    checkIn,
    checkOut: null
  };

  mockAttendanceRecords.push(newRecord);

  res.status(201).json(newRecord);
});

// Update an attendance record (check-out)
router.put("/check-out/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const { checkOut } = req.body;

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid record ID" });
  }

  if (!checkOut) {
    return res.status(400).json({ error: "Check-out time is required" });
  }

  const recordIndex = mockAttendanceRecords.findIndex(record => record.id === id);

  if (recordIndex === -1) {
    return res.status(404).json({ error: "Attendance record not found" });
  }

  mockAttendanceRecords[recordIndex].checkOut = checkOut;

  res.json(mockAttendanceRecords[recordIndex]);
});

// Get attendance records for a specific employee
router.get("/employee/:employeeId", (req: Request, res: Response) => {
  const employeeId = Number(req.params.employeeId);

  if (isNaN(employeeId)) {
    return res.status(400).json({ error: "Invalid employee ID" });
  }

  const records = findRecordsByEmployeeId(employeeId);

  res.json(records);
});

