import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply role-based access control to attendance-related routes
  if (!req.path.startsWith("/attendance")) {
    next();
    return;
  }

  // Check if user has required role
  const userRole = req.headers["x-user-role"] as string | undefined;

  // For GET requests to attendance records, allow all roles
  if (req.method === "GET" && req.path.startsWith("/attendance/")) {
    next();
    return;
  }

  // For POST, PUT, DELETE to attendance records, require admin role
  if (req.method === "POST" || req.method === "PUT" || req.method === "DELETE") {
    if (userRole === "admin") {
      next();
      return;
    } else {
      res.status(403).json({ error: "Forbidden: Insufficient permissions" });
      return;
    }
  }

  // Allow GET requests to root /attendance endpoint for all roles
  if (req.method === "GET" && req.path === "/attendance") {
    next();
    return;
  }

  // For all other attendance-related requests, require admin role
  if (userRole !== "admin") {
    res.status(403).json({ error: "Forbidden: Insufficient permissions" });
    return;
  }

  next();
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check authentication for login POST requests
  if (req.method !== "POST" || req.path !== "/login") {
    next();
    return;
  }

  const jwtSecret = process.env.JWT_SECRET;

  if (!jwtSecret) {
    res.status(500).json({ error: "Server configuration error" });
    return;
  }

  const authHeader = req.headers.authorization;

  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Missing or invalid authorization header" });
    return;
  }

  const token = authHeader.substring(7); // Remove 'Bearer '

  try {
    // Simple token validation - in a real system, you'd decode and verify
    // the JWT signature properly using a library like jsonwebtoken
    const [header, payload, signature] = token.split(".");

    if (!header || !payload || !signature) {
      res.status(401).json({ error: "Invalid token format" });
      return;
    }

    // Verify signature using HMAC-SHA256
    const expectedSignature = createHmac("sha256", jwtSecret)
      .update(`${header}.${payload}`)
      .digest("base64url");

    // Use timingSafeEqual to prevent timing attacks
    const signatureBuffer = Buffer.from(signature, "base64url");
    const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");

    if (!timingSafeEqual(signatureBuffer, expectedSignatureBuffer)) {
      res.status(401).json({ error: "Invalid token signature" });
      return;
    }

    // If we get here, token is valid - proceed to next middleware
    next();
  } catch (error) {
    res.status(401).json({ error: "Authentication failed" });
  }
}

import { useEffect, useState } from "react";

interface AttendanceRecord {
  id: number;
  date: string;
  checkIn: string;
  checkOut: string | null;
}

interface CurrentStatus {
  isClockedIn: boolean;
  lastCheckIn?: string;
}

export function EmployeeDashboard() {
  const [attendanceRecords, setAttendanceRecords] = useState<AttendanceRecord[]>([]);
  const [currentStatus, setCurrentStatus] = useState<CurrentStatus | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchAttendanceData();
  }, []);

  const fetchAttendanceData = async () => {
    try {
      setLoading(true);
      const [recordsResponse, statusResponse] = await Promise.all([
        fetch('/api/attendance'),
        fetch('/api/attendance/status')
      ]);

      if (!recordsResponse.ok || !statusResponse.ok) {
        throw new Error('Failed to fetch data');
      }

      const records = await recordsResponse.json();
      const status = await statusResponse.json();

      setAttendanceRecords(records);
      setCurrentStatus(status);
    } catch (err) {
      setError('Failed to load attendance data');
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const handleCheckIn = async () => {
    try {
      const response = await fetch('/api/attendance/checkin', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({})
      });

      if (!response.ok) {
        throw new Error('Failed to check in');
      }

      fetchAttendanceData();
    } catch (err) {
      setError('Failed to check in');
      console.error(err);
    }
  };

  const handleCheckOut = async () => {
    try {
      const response = await fetch('/api/attendance/checkout', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({})
      });

      if (!response.ok) {
        throw new Error('Failed to check out');
      }

      fetchAttendanceData();
    } catch (err) {
      setError('Failed to check out');
      console.error(err);
    }
  };

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: '800px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1 style={{ textAlign: 'center' }}>Employee Dashboard</h1>

      <div style={{ marginBottom: '30px', padding: '20px', backgroundColor: '#f5f5f5', borderRadius: '8px' }}>
        <h2>Current Status</h2>
        {currentStatus ? (
          <p>
            {currentStatus.isClockedIn 
              ? `Clocked in at ${currentStatus.lastCheckIn}` 
              : 'Not clocked in'}
          </p>
        ) : (
          <p>Unable to determine status</p>
        )}

        <div style={{ marginTop: '15px', display: 'flex', gap: '10px', flexWrap: 'wrap' }}>
          {!currentStatus?.isClockedIn && (
            <button 
              onClick={handleCheckIn}
              style={{ 
                padding: '10px 20px', 
                backgroundColor: '#4CAF50', 
                color: 'white', 
                border: 'none', 
                borderRadius: '4px', 
                cursor: 'pointer' 
              }}
            >
              Check In
            </button>
          )}

          {currentStatus?.isClockedIn && (
            <button 
              onClick={handleCheckOut}
              style={{ 
                padding: '10px 20px', 
                backgroundColor: '#f44336', 
                color: 'white', 
                border: 'none', 
                borderRadius: '4px', 
                cursor: 'pointer' 
              }}
            >
              Check Out
            </button>
          )}
        </div>
      </div>

      <div>
        <h2>Attendance Records</h2>
        {attendanceRecords.length === 0 ? (
          <p style={{ textAlign: 'center', padding: '20px' }}>No attendance records found.</p>
        ) : (
          <div style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
            {attendanceRecords.map(record => (
              <div 
                key={record.id} 
                style={{ 
                  padding: '15px', 
                  border: '1px solid #ddd', 
                  borderRadius: '8px', 
                  backgroundColor: '#fff' 
                }}
              >
                <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                  <span><strong>Date:</strong> {record.date}</span>
                </div>
                <div style={{ display: 'flex', justifyContent: 'space-between', marginTop: '10px' }}>
                  <span><strong>Check In:</strong> {record.checkIn}</span>
                  <span><strong>Check Out:</strong> {record.checkOut || 'Not checked out'}</span>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

import { useEffect, useState } from "react";

interface AttendanceRecord {
  id: number;
  employeeId: number;
  employeeName: string;
  date: string;
  checkIn: string;
  checkOut: string;
}

export function AttendanceRecordsList() {
  const [records, setRecords] = useState<AttendanceRecord[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState("");
  const [currentPage, setCurrentPage] = useState(1);
  const [recordsPerPage] = useState(10);

  useEffect(() => {
    fetchAttendanceRecords();
  }, []);

  const fetchAttendanceRecords = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/attendance-records');
      if (!response.ok) {
        throw new Error('Failed to fetch attendance records');
      }
      const data = await response.json();
      setRecords(data);
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  const filteredRecords = records.filter(record =>
    record.employeeName.toLowerCase().includes(searchTerm.toLowerCase()) ||
    record.date.includes(searchTerm)
  );

  const indexOfLastRecord = currentPage * recordsPerPage;
  const indexOfFirstRecord = indexOfLastRecord - recordsPerPage;
  const currentRecords = filteredRecords.slice(indexOfFirstRecord, indexOfLastRecord);

  const totalPages = Math.ceil(filteredRecords.length / recordsPerPage);

  const handleSearchChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setSearchTerm(e.target.value);
    setCurrentPage(1);
  };

  const paginate = (pageNumber: number) => setCurrentPage(pageNumber);

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Attendance Records</h1>

      <div style={{ marginBottom: "20px" }}>
        <input
          type="text"
          placeholder="Search by employee name or date..."
          value={searchTerm}
          onChange={handleSearchChange}
          style={{ width: "100%", padding: "10px", borderRadius: "4px", border: "1px solid #ccc" }}
        />
      </div>

      {currentRecords.length === 0 ? (
        <p style={{ textAlign: "center", padding: "20px" }}>No attendance records found.</p>
      ) : (
        <>
          <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
            {currentRecords.map(record => (
              <div key={record.id} style={{
                border: "1px solid #ddd",
                borderRadius: "8px",
                padding: "15px",
                backgroundColor: "#f9f9f9"
              }}>
                <div style={{ display: "flex", justifyContent: "space-between", marginBottom: "5px" }}>
                  <strong>{record.employeeName}</strong>
                  <span>{record.date}</span>
                </div>
                <div style={{ display: "flex", justifyContent: "space-between", marginTop: "5px" }}>
                  <span>Check-in: {record.checkIn}</span>
                  <span>Check-out: {record.checkOut}</span>
                </div>
              </div>
            ))}
          </div>

          <div style={{ display: "flex", justifyContent: "center", marginTop: "20px", gap: "5px" }}>
            {Array.from({ length: totalPages }, (_, i) => i + 1).map(page => (
              <button
                key={page}
                onClick={() => paginate(page)}
                style={{
                  padding: "8px 12px",
                  border: "1px solid #ccc",
                  backgroundColor: page === currentPage ? "#007bff" : "white",
                  color: page === currentPage ? "white" : "black",
                  borderRadius: "4px",
                  cursor: "pointer"
                }}
              >
                {page}
              </button>
            ))}
          </div>
        </>
      )}
    </div>
  );
}

