// Mock database functions - in a real app these would come from a database module
const mockDatabase = {
  getAllPosts: async () => [
    { id: 1, title: "First Post", content: "Content of first post", published: true },
    { id: 2, title: "Second Post", content: "Content of second post", published: false }
  ],
  getPostById: async (id: number) => {
    const posts = await mockDatabase.getAllPosts();
    return posts.find(post => post.id === id) || null;
  },
  createPost: async (post: { title: string; content: string; published: boolean }) => {
    const posts = await mockDatabase.getAllPosts();
    const newId = posts.length > 0 ? Math.max(...posts.map(p => p.id)) + 1 : 1;
    return { id: newId, ...post };
  },
  updatePost: async (id: number, updates: Partial<{ title: string; content: string; published: boolean }>) => {
    const posts = await mockDatabase.getAllPosts();
    const index = posts.findIndex(post => post.id === id);
    if (index === -1) return null;
    posts[index] = { ...posts[index], ...updates };
    return posts[index];
  },
  deletePost: async (id: number) => {
    const posts = await mockDatabase.getAllPosts();
    const index = posts.findIndex(post => post.id === id);
    if (index === -1) return false;
    posts.splice(index, 1);
    return true;
  }
};

