import type { Request, Response, NextFunction } from "express";
import { createHash, scrypt, randomBytes, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // This middleware is designed to hash passwords during user registration
  // It should only process POST requests to the /register endpoint
  if (req.method !== "POST" || req.path !== "/register") {
    next();
    return;
  }

  // Check if password exists in request body
  if (!req.body || typeof req.body.password !== "string") {
    next();
    return;
  }

  const password = req.body.password;

  // Generate a salt
  const salt = randomBytes(16).toString("hex");

  // Hash the password with scrypt (industry standard)
  scrypt(password, salt, 64, (err, derivedKey) => {
    if (err) {
      next(err);
      return;
    }

    // Store the salt and hashed password in the request body
    req.body.hashedPassword = derivedKey.toString("hex");
    req.body.salt = salt;

    next();
  });
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process POST requests to /login endpoint
  if (req.method !== "POST" || req.path !== "/login") {
    next();
    return;
  }

  const jwtSecret = process.env.JWT_SECRET;

  if (!jwtSecret) {
    res.status(500).json({ error: "Server configuration error" });
    return;
  }

  const authHeader = req.headers.authorization;

  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Missing or invalid authorization header" });
    return;
  }

  const token = authHeader.substring(7); // Remove 'Bearer '

  try {
    // Basic token structure validation
    const parts = token.split(".");
    if (parts.length !== 3) {
      res.status(401).json({ error: "Invalid token format" });
      return;
    }

    const [header, payload, signature] = parts;

    // Verify signature using HMAC-SHA256
    const expectedSignature = createHmac("sha256", jwtSecret)
      .update(`${header}.${payload}`)
      .digest("base64url");

    // Use timingSafeEqual to prevent timing attacks
    const signatureBuffer = Buffer.from(signature, "base64url");
    const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");

    if (!timingSafeEqual(signatureBuffer, expectedSignatureBuffer)) {
      res.status(401).json({ error: "Invalid token signature" });
      return;
    }

    // If we get here, token is valid
    next();
  } catch (error) {
    res.status(401).json({ error: "Token verification failed" });
  }
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process POST, PUT, PATCH requests that contain a body
  if (!['POST', 'PUT', 'PATCH'].includes(req.method) || !req.body) {
    return next();
  }

  // Validate and sanitize input fields
  if (req.body.title !== undefined) {
    req.body.title = sanitizeString(req.body.title);
  }

  if (req.body.content !== undefined) {
    req.body.content = sanitizeString(req.body.content);
  }

  if (req.body.author !== undefined) {
    req.body.author = sanitizeString(req.body.author);
  }

  next();
}

function sanitizeString(input: unknown): string {
  if (typeof input !== 'string') {
    return '';
  }

  // Remove potentially dangerous characters
  return input
    .replace(/<script[^>]*>.*?<\/script>/gi, '')
    .replace(/<[^>]*>/g, '')
    .trim();
}

