import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync("./help-exchange.db");

interface UserRow {
  id: number;
  name: string;
  email: string;
  password_hash: string;
  neighborhood: string;
  skills: string;
  contact_details: string;
}

const createUsersTable = `
  CREATE TABLE IF NOT EXISTS users (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    email TEXT UNIQUE NOT NULL,
    password_hash TEXT NOT NULL,
    neighborhood TEXT NOT NULL,
    skills TEXT,
    contact_details TEXT
  );
`;

db.exec(createUsersTable);

export function getAllUsers(): UserRow[] {
  const stmt = db.prepare("SELECT * FROM users");
  return stmt.all() as unknown as UserRow[];
}

export function getUserById(id: number): UserRow | undefined {
  const stmt = db.prepare("SELECT * FROM users WHERE id = ?");
  return stmt.get(id) as unknown as UserRow | undefined;
}

export function insertUser(
  name: string,
  email: string,
  passwordHash: string,
  neighborhood: string,
  skills: string,
  contactDetails: string
): number {
  const stmt = db.prepare(
    "INSERT INTO users (name, email, password_hash, neighborhood, skills, contact_details) VALUES (?, ?, ?, ?, ?, ?)"
  );
  const result = stmt.run(name, email, passwordHash, neighborhood, skills, contactDetails);
  return Number(result.lastInsertRowid);
}

export function updateUser(
  id: number,
  name: string,
  email: string,
  passwordHash: string,
  neighborhood: string,
  skills: string,
  contactDetails: string
): void {
  const stmt = db.prepare(
    "UPDATE users SET name = ?, email = ?, password_hash = ?, neighborhood = ?, skills = ?, contact_details = ? WHERE id = ?"
  );
  stmt.run(name, email, passwordHash, neighborhood, skills, contactDetails, id);
}

export function deleteUser(id: number): void {
  const stmt = db.prepare("DELETE FROM users WHERE id = ?");
  stmt.run(id);
}

