}

export function UserDashboard() {
  const [activeRequests, setActiveRequests] = useState<HelpRequest[]>([]);
  const [helpOffers, setHelpOffers] = useState<HelpRequest[]>([]);
  const [notifications, setNotifications] = useState<Notification[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const fetchData = async () => {
      try {
        setLoading(true);
        // Fetch active requests
        const activeReqResponse = await fetch("/api/help-request-api/help-requests?status=open");
        const activeRequestsData = await activeReqResponse.json();
        setActiveRequests(activeRequestsData);

        // Fetch help offers
        const helpOfferResponse = await fetch("/api/help-request-api/help-requests?status=matched");
        const helpOffersData = await helpOfferResponse.json();
        setHelpOffers(helpOffersData);

        // Fetch notifications
        const notificationResponse = await fetch("/api/notification-service/help-request");
        const notificationsData = await notificationResponse.json();
        setNotifications(notificationsData);

        setLoading(false);
      } catch (err) {
        setError("Failed to load dashboard data");
        setLoading(false);
      }
    };

    fetchData();
  }, []);

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Your Dashboard</h1>

      <section style={{ marginBottom: "30px" }}>
        <h2>Active Requests</h2>
        {activeRequests.length === 0 ? (
          <p>No active requests found.</p>
        ) : (
          <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
            {activeRequests.map((req) => (
              <div key={req.id} style={{ border: "1px solid #ccc", borderRadius: "8px", padding: "15px" }}>
                <h3>{req.title}</h3>
                <p>{req.description}</p>
                <p>Status: {req.status}</p>
                <p>Created: {new Date(req.createdAt).toLocaleDateString()}</p>
              </div>
            ))}
          </div>
        )}
      </section>

      <section style={{ marginBottom: "30px" }}>
        <h2>Available Help</h2>
        {helpOffers.length === 0 ? (
          <p>No available help found.</p>
        ) : (
          <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
            {helpOffers.map((offer) => (
              <div key={offer.id} style={{ border: "1px solid #ccc", borderRadius: "8px", padding: "15px" }}>
                <h3>{offer.title}</h3>
                <p>{offer.description}</p>
                <p>Status: {offer.status}</p>
