import { Router, type Request, type Response } from "express";
import { getAllHelpRequests, getHelpRequestById, createHelpRequest, updateHelpRequest, deleteHelpRequest } from "../db/help-requests-table";

export const router = Router();

// GET /help-requests - Get all help requests
router.get("/help-requests", (req: Request, res: Response) => {
  try {
    const helpRequests = getAllHelpRequests();
    res.json(helpRequests);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch help requests" });
  }
});

// GET /help-requests/:id - Get a specific help request by ID
router.get("/help-requests/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid ID format" });
    }

    const helpRequest = getHelpRequestById(id);
    if (!helpRequest) {
      return res.status(404).json({ error: "Help request not found" });
    }

    res.json(helpRequest);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch help request" });
  }
});

// POST /help-requests - Create a new help request
router.post("/help-requests", (req: Request, res: Response) => {
  try {
    const { title, description, category, location, urgency, status, created_at } = req.body;

    if (!title || !description || !category || !location || !urgency || !status || !created_at) {
      return res.status(400).json({ error: "Missing required fields" });
    }

    const newHelpRequest = createHelpRequest(title, description, category, location, urgency, status, created_at);
    res.status(201).json(newHelpRequest);
  } catch (error) {
    res.status(500).json({ error: "Failed to create help request" });
  }
});

// PUT /help-requests/:id - Update an existing help request
router.put("/help-requests/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid ID format" });
    }

    const { title, description, category, location, urgency, status } = req.body;

    if (!title || !description || !category || !location || !urgency || !status) {
      return res.status(400).json({ error: "Missing required fields" });
    }

    const updatedHelpRequest = updateHelpRequest(id, title, description, category, location, urgency, status);

    if (!updatedHelpRequest) {
      return res.status(404).json({ error: "Help request not found" });
    }

    res.json(updatedHelpRequest);
  } catch (error) {
    res.status(500).json({ error: "Failed to update help request" });
  }
});

// DELETE /help-requests/:id - Delete a help request
router.delete("/help-requests/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid ID format" });
    }

    const deletedRows = deleteHelpRequest(id);

    if (deletedRows === 0) {
      return res.status(404).json({ error: "Help request not found" });
    }

    res.json({ message: "Help request deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to delete help request" });
  }
});

