import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";
import { router as authRouter } from "../routes/authentication-service";
import { router as helpRequestRouter } from "../routes/help-request-api";
import { router as userProfileRouter } from "../routes/user-profile-api";
import { router as messagingRouter } from "../routes/messaging-api";
import { router as notificationRouter } from "../routes/notification-service";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Skip authentication for authentication routes
  if (
    req.path.startsWith(authRouter["_router"].stack[0].route?.path || "/") ||
    req.path.startsWith("/auth")
  ) {
    return next();
  }

  // Check if the request is for protected routes
  const protectedPaths = [
    helpRequestRouter["_router"].stack.map(layer => layer.route?.path).filter(Boolean),
    userProfileRouter["_router"].stack.map(layer => layer.route?.path).filter(Boolean),
    messagingRouter["_router"].stack.map(layer => layer.route?.path).filter(Boolean),
    notificationRouter["_router"].stack.map(layer => layer.route?.path).filter(Boolean)
  ].flat().filter(Boolean);

  const isProtectedPath = protectedPaths.some(path => 
    req.path === path || 
    (req.path.startsWith(path) && path !== "/")
  );

  if (!isProtectedPath) {
    return next();
  }

  // Get token from headers
  const token = req.header("Authorization")?.replace("Bearer ", "");

  if (!token) {
    return res.status(401).json({ message: "Access denied. No token provided." });
  }

  // Verify token signature
  const secret = process.env.JWT_SECRET;
  if (!secret) {
    return res.status(500).json({ message: "Server configuration error." });
  }

  const [payload, signature] = token.split(".");
  if (!payload || !signature) {
    return res.status(401).json({ message: "Invalid token." });
  }

  const expectedSignature = createHmac("sha256", secret)
    .update(payload)
    .digest("base64url");

  try {
    const signatureBuffer = Buffer.from(signature, "base64url");
    const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");

    if (!timingSafeEqual(signatureBuffer, expectedSignatureBuffer)) {
      return res.status(401).json({ message: "Invalid token." });
    }
  } catch (err) {
    return res.status(401).json({ message: "Invalid token." });
  }

  // Decode payload to check role
  try {
    const payloadJson = Buffer.from(payload, "base64url").toString("utf-8");
    const { role } = JSON.parse(payloadJson);

    // Admin access required for some routes
    if (req.method === "POST" && req.path.includes("/admin")) {
      if (role !== "admin") {
        return res.status(403).json({ message: "Admin access required." });
      }
    }

    next();
  } catch (err) {
    return res.status(401).json({ message: "Invalid token." });
  }
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";
import { router as authRouter } from "../routes/authentication-service";
import { router as helpRequestRouter } from "../routes/help-request-api";
import { router as userProfileRouter } from "../routes/user-profile-api";
import { router as messagingRouter } from "../routes/messaging-api";
import { router as notificationRouter } from "../routes/notification-service";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Skip authentication for authentication routes
  if (req.path.startsWith("/auth") || 
      req.path.startsWith("/login") || 
      req.path.startsWith("/register")) {
    return next();
  }

  // Skip authentication for public help request routes
  if (req.path.startsWith("/help-requests")) {
    return next();
  }

  // Skip authentication for public user profile routes
  if (req.path.startsWith("/users/")) {
    return next();
  }

  // Skip authentication for public messaging routes
  if (req.path.startsWith("/messages")) {
    return next();
  }

  // Skip authentication for public notification routes
  if (req.path.startsWith("/notifications")) {
    return next();
  }

  // For protected routes, check for authorization header
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    return res.status(401).json({ error: "Unauthorized: Missing or invalid token" });
  }

  const token = authHeader.substring(7); // Remove "Bearer " prefix
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    return res.status(401).json({ error: "Unauthorized: Server configuration error" });
  }

  try {
    // Simple token validation - in a real app, you'd decode and verify the JWT signature
    const [header, payload, signature] = token.split(".");
    if (!header || !payload || !signature) {
      return res.status(401).json({ error: "Unauthorized: Invalid token" });
    }

    // Reconstruct the signature for verification
    const expectedSignature = createHmac("sha256", secret)
      .update(`${header}.${payload}`)
      .digest("base64url");

    // Use timingSafeEqual to prevent timing attacks
    const signatureBuffer = Buffer.from(signature, "base64url");
    const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");

    if (!timingSafeEqual(signatureBuffer, expectedSignatureBuffer)) {
      return res.status(401).json({ error: "Unauthorized: Invalid token" });
    }

    // If we get here, the token is valid
    next();
  } catch (error) {
    return res.status(401).json({ error: "Unauthorized: Invalid token" });
  }
}

