      try {
        const response = await fetch(`/api/vehicles`);
        if (!response.ok) {
          throw new Error(`Failed to fetch vehicles: ${response.status}`);
        }
        const data = await response.json();
        setVehicles(data);
        setLoading(false);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
        setLoading(false);
      }
