}

export function FuelLogListPage() {
  const [fuelLogs, setFuelLogs] = useState<FuelLog[]>([]);
  const [vehicles, setVehicles] = useState<Vehicle[]>([]);
  const [searchTerm, setSearchTerm] = useState("");
  const [selectedVehicle, setSelectedVehicle] = useState<number | "">("");
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<Error | null>(null);

  useEffect(() => {
    const fetchData = async () => {
      try {
        // Simulate API calls
        await new Promise(resolve => setTimeout(resolve, 500));

        // Mock data for demonstration
        const mockVehicles: Vehicle[] = [
          { id: 1, make: "Toyota", model: "Camry", year: 2020 },
          { id: 2, make: "Honda", model: "Civic", year: 2019 },
          { id: 3, make: "Ford", model: "F-150", year: 2021 }
        ];

        const mockFuelLogs: FuelLog[] = [
          { id: 1, vehicleId: 1, date: "2023-06-15", amount: 45, pricePerLiter: 1.45, totalCost: 65.25 },
          { id: 2, vehicleId: 1, date: "2023-07-20", amount: 50, pricePerLiter: 1.50, totalCost: 75.00 },
          { id: 3, vehicleId: 2, date: "2023-08-10", amount: 30, pricePerLiter: 1.60, totalCost: 48.00 },
          { id: 4, vehicleId: 3, date: "2023-09-05", amount: 60, pricePerLiter: 1.40, totalCost: 84.00 }
        ];

        setVehicles(mockVehicles);
        setFuelLogs(mockFuelLogs);
        setLoading(false);
      } catch (err) {
        setError(err instanceof Error ? err : new Error("Unknown error"));
        setLoading(false);
      }
    };

    fetchData();
  }, []);

  const filteredLogs = fuelLogs.filter(log => {
    const matchesSearch = log.date.toLowerCase().includes(searchTerm.toLowerCase()) ||
                          log.amount.toString().includes(searchTerm) ||
                          log.totalCost.toString().includes(searchTerm);

    const matchesVehicle = selectedVehicle === "" || log.vehicleId === selectedVehicle;

    return matchesSearch && matchesVehicle;
  });

  const getVehicleName = (vehicleId: number) => {
    const vehicle = vehicles.find(v => v.id === vehicleId);
    return vehicle ? `${vehicle.make} ${vehicle.model}` : "Unknown Vehicle";
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>Error: {error.message}</div>;
  }

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Fuel Log List</h1>

      <div style={{ marginBottom: "20px", display: "flex", flexDirection: "column", gap: "10px" }}>
        <input
          type="text"
          placeholder="Search by date, amount, or cost..."
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          style={{ width: "100%", padding: "10px", borderRadius: "4px", border: "1px solid #ccc" }}
        />

        <select
          value={selectedVehicle}
          onChange={(e) => setSelectedVehicle(e.target.value ? Number(e.target.value) : "")}
          style={{ width: "100%", padding: "10px", borderRadius: "4px", border: "1px solid #ccc" }}
        >
          <option value="">All Vehicles</option>
          {vehicles.map(vehicle => (
            <option key={vehicle.id} value={vehicle.id}>
              {vehicle.make} {vehicle.model} ({vehicle.year})
            </option>
          ))}
        </select>
      </div>

      {filteredLogs.length === 0 ? (
        <div style={{ textAlign: "center", padding: "20px" }}>
          No fuel logs found.
        </div>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
          {filteredLogs.map(log => (
            <div 
              key={log.id} 
              style={{ 
                border: "1px solid #ddd", 
                borderRadius: "8px", 
                padding: "15px", 
                backgroundColor: "#f9f9f9"
              }}
            >
              <div style={{ display: "flex", justifyContent: "space-between", marginBottom: "10px" }}>
                <strong>{getVehicleName(log.vehicleId)}</strong>
                <span>{new Date(log.date).toLocaleDateString()}</span>
              </div>

              <div style={{ display: "flex", justifyContent: "space-between", marginBottom: "10px" }}>
                <span>Amount: {log.amount} liters</span>
                <span>Price per liter: ${log.pricePerLiter.toFixed(2)}</span>
              </div>

              <div style={{ display: "flex", justifyContent: "space-between" }}>
                <span>Total Cost: ${log.totalCost.toFixed(2)}</span>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

