import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock user database
const users = [
  {
    id: 1,
    email: "patient@example.com",
    password: "hashed-password-patient",
    role: "patient"
  },
  {
    id: 2,
    email: "doctor@example.com",
    password: "hashed-password-doctor",
    role: "doctor"
  }
];

// Mock session store
const sessions = new Map<string, { userId: number; role: string }>();

// User registration endpoint
router.post("/register", (req: Request, res: Response) => {
  const { email, password, role } = req.body;

  // Validate input
  if (!email || !password || !role) {
    return res.status(400).json({ error: "Email, password, and role are required" });
  }

  // Check if user already exists
  const existingUser = users.find(user => user.email === email);
  if (existingUser) {
    return res.status(400).json({ error: "User already exists" });
  }

  // Create new user
  const newUser = {
    id: users.length + 1,
    email,
    password,
    role
  };

  users.push(newUser);

  return res.status(201).json({ message: "User registered successfully" });
});

// User login endpoint
router.post("/login", (req: Request, res: Response) => {
  const { email, password } = req.body;

  // Validate input
  if (!email || !password) {
    return res.status(400).json({ error: "Email and password are required" });
  }

  // Find user
  const user = users.find(u => u.email === email && u.password === password);
  if (!user) {
    return res.status(401).json({ error: "Invalid credentials" });
  }

  // Generate session token
  const token = `session-${Math.random().toString(36).substring(2, 15)}`;
  sessions.set(token, { userId: user.id, role: user.role });

  return res.json({ token, role: user.role });
});

// Session validation endpoint
router.get("/validate", (req: Request, res: Response) => {
  const token = req.headers.authorization?.split(" ")[1];

  if (!token) {
    return res.status(401).json({ error: "No token provided" });
  }

  const session = sessions.get(token);
  if (!session) {
    return res.status(401).json({ error: "Invalid token" });
  }

  return res.json({ valid: true, userId: session.userId, role: session.role });
});

