import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync("internship_tracker.db");

interface Application {
  id: number;
  student_id: number;
  company_name: string;
  position: string;
  application_date: string;
  deadline: string;
  status: string;
  notes: string;
  created_at: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS applications (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    student_id INTEGER NOT NULL,
    company_name TEXT NOT NULL,
    position TEXT NOT NULL,
    application_date TEXT NOT NULL,
    deadline TEXT NOT NULL,
    status TEXT NOT NULL,
    notes TEXT,
    created_at TEXT NOT NULL
  )
`;

db.exec(createTableSql);

export function getAllApplications(): Application[] {
  const stmt = db.prepare("SELECT * FROM applications ORDER BY created_at DESC");
  return stmt.all() as unknown as Application[];
}

export function getApplicationById(id: number): Application | undefined {
  const stmt = db.prepare(
    "SELECT * FROM applications WHERE id = ?"
  );
  return stmt.get(id) as unknown as Application | undefined;
}

export function createApplication(application: Omit<Application, "id" | "created_at">): number {
  const stmt = db.prepare(
    "INSERT INTO applications (student_id, company_name, position, application_date, deadline, status, notes, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?)"
  );
  const result = stmt.run(
    application.student_id,
    application.company_name,
    application.position,
    application.application_date,
    application.deadline,
    application.status,
    application.notes,
    new Date().toISOString()
  );
  return Number(result.lastInsertRowid);
}

export function updateApplication(
  id: number,
  application: Partial<Omit<Application, "id" | "created_at">>
): boolean {
  const fields = [];
  const values = [];

  if (application.student_id !== undefined) {
    fields.push("student_id = ?");
    values.push(application.student_id);
  }

  if (application.company_name !== undefined) {
    fields.push("company_name = ?");
    values.push(application.company_name);
  }

  if (application.position !== undefined) {
    fields.push("position = ?");
    values.push(application.position);
  }

  if (application.application_date !== undefined) {
    fields.push("application_date = ?");
    values.push(application.application_date);
  }

  if (application.deadline !== undefined) {
    fields.push("deadline = ?");
    values.push(application.deadline);
  }

  if (application.status !== undefined) {
    fields.push("status = ?");
    values.push(application.status);
  }

  if (application.notes !== undefined) {
    fields.push("notes = ?");
    values.push(application.notes);
  }

  if (fields.length === 0) {
    return false;
  }

  values.push(id);

  const sql = `UPDATE applications SET ${fields.join(", ")} WHERE id = ?`;
  const stmt = db.prepare(sql);
  const result = stmt.run(...values);

  return result.changes > 0;
}

export function deleteApplication(id: number): boolean {
  const stmt = db.prepare("DELETE FROM applications WHERE id = ?");
  const result = stmt.run(id);
  return result.changes > 0;
}

