import { Router, type Request, type Response } from "express";
import {
  getAllApplications,
  getApplicationById,
  createApplication,
  updateApplication,
  deleteApplication
} from "../db/applications-table";

export const router = Router();

// GET /api/applications - Get all applications
router.get("/", (req: Request, res: Response) => {
  try {
    const applications = getAllApplications();
    res.json(applications);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch applications" });
  }
});

// GET /api/applications/:id - Get a specific application by ID
router.get("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid application ID" });
    }

    const application = getApplicationById(id);
    if (!application) {
      return res.status(404).json({ error: "Application not found" });
    }

    res.json(application);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch application" });
  }
});

// POST /api/applications - Create a new application
router.post("/", (req: Request, res: Response) => {
  try {
    const { student_id, company_name, position, status, applied_date, notes } = req.body;

    // Validate required fields
    if (!student_id || !company_name || !position || !status) {
      return res.status(400).json({ error: "Missing required fields: student_id, company_name, position, status" });
    }

    const newApplicationId = createApplication({
      student_id,
      company_name,
      position,
      status,
      applied_date,
      notes
    });

    // Fetch the created application to send back
    const createdApplication = getApplicationById(newApplicationId);
    if (!createdApplication) {
      return res.status(500).json({ error: "Failed to retrieve created application" });
    }

    res.status(201).json(createdApplication);
  } catch (error) {
    res.status(500).json({ error: "Failed to create application" });
  }
});

// PUT /api/applications/:id - Update an existing application
router.put("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid application ID" });
    }

    const { student_id, company_name, position, status, applied_date, notes } = req.body;

    const updated = updateApplication(id, {
      student_id,
      company_name,
      position,
      status,
      applied_date,
      notes
    });

    if (!updated) {
      return res.status(404).json({ error: "Application not found" });
    }

    const updatedApplication = getApplicationById(id);
    if (!updatedApplication) {
      return res.status(500).json({ error: "Failed to retrieve updated application" });
    }

    res.json(updatedApplication);
  } catch (error) {
    res.status(500).json({ error: "Failed to update application" });
  }
});

// DELETE /api/applications/:id - Delete an application
router.delete("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid application ID" });
    }

    const deleted = deleteApplication(id);
    if (!deleted) {
      return res.status(404).json({ error: "Application not found" });
    }

    res.json({ message: "Application deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to delete application" });
  }
});

