import { useEffect, useState } from "react";

interface Application {
  id: string;
  company: string;
  position: string;
  deadline: string;
  status: "pending" | "accepted" | "rejected";
}

export function StudentDashboard() {
  const [applications, setApplications] = useState<Application[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchApplications();
  }, []);

  const fetchApplications = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/application-api/applications");
      if (!response.ok) {
        throw new Error(`Failed to fetch applications: ${response.status}`);
      }
      const data = await response.json();
      setApplications(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const getStatusColor = (status: Application["status"]) => {
    switch (status) {
      case "pending":
        return "#FFD700";
      case "accepted":
        return "#32CD32";
      case "rejected":
        return "#FF6347";
      default:
        return "#808080";
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return (
      <div style={{ textAlign: "center", padding: "20px", color: "red" }}>
        Error: {error}
      </div>
    );
  }

  return (
    <div
      style={{
        fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif",
        maxWidth: "800px",
        margin: "0 auto",
        padding: "20px",
      }}
    >
      <h1 style={{ textAlign: "center" }}>My Applications</h1>

      {applications.length === 0 ? (
        <p style={{ textAlign: "center", color: "#666" }}>
          You don't have any applications yet.
        </p>
      ) : (
        <div
          style={{
            display: "flex",
            flexDirection: "column",
            gap: "15px",
          }}
        >
          {applications.map((app) => (
            <div
              key={app.id}
              style={{
                border: "1px solid #ddd",
                borderRadius: "8px",
                padding: "15px",
                backgroundColor: "#f9f9f9",
              }}
            >
              <div style={{ display: "flex", justifyContent: "space-between" }}>
                <h3 style={{ margin: "0 0 10px 0" }}>{app.company}</h3>
                <span
                  style={{
                    backgroundColor: getStatusColor(app.status),
                    color: "white",
                    padding: "4px 8px",
                    borderRadius: "4px",
                    fontSize: "0.9em",
                  }}
                >
                  {app.status.charAt(0).toUpperCase() + app.status.slice(1)}
                </span>
              </div>
              <p style={{ margin: "0 0 10px 0" }}>
                Position: {app.position}
              </p>
              <p style={{ margin: "0 0 10px 0" }}>
                Deadline: {new Date(app.deadline).toLocaleDateString()}
              </p>
            </div>
          ))}
        </div>
      )}

      <div style={{ marginTop: "30px", textAlign: "center" }}>
        <button
          onClick={() => {
            // In a real app, this would navigate to a form page
            alert("Navigate to application form");
          }}
          style={{
            backgroundColor: "#007bff",
            color: "white",
            border: "none",
            padding: "10px 20px",
            borderRadius: "4px",
            cursor: "pointer",
            fontSize: "1rem",
          }}
        >
          Add New Application
        </button>
      </div>
    </div>
  );
}

import { useState } from "react";

export function ApplicationForm() {
  const [formData, setFormData] = useState({
    companyName: "",
    position: "",
    applicationDate: "",
    deadline: "",
    status: "",
    notes: ""
  });

  const [isSubmitting, setIsSubmitting] = useState(false);
  const [submitError, setSubmitError] = useState<null | string>(null);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);
    setSubmitError(null);

    try {
      const response = await fetch("/api/student-api/applications", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(formData)
      });

      if (!response.ok) {
        throw new Error(`Failed to submit application: ${response.status} ${response.statusText}`);
      }

      // Reset form after successful submission
      setFormData({
        companyName: "",
        position: "",
        applicationDate: "",
        deadline: "",
        status: "",
        notes: ""
      });
    } catch (error) {
      setSubmitError(error instanceof Error ? error.message : "An unknown error occurred");
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div style={{
      fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, 'Open Sans', 'Helvetica Neue', sans-serif",
      maxWidth: "600px",
      margin: "0 auto",
      padding: "20px"
    }}>
      <h1 style={{ textAlign: "center" }}>New Internship Application</h1>

      <form onSubmit={handleSubmit} style={{ display: "flex", flexDirection: "column", gap: "15px" }}>
        <div>
          <label htmlFor="companyName" style={{ display: "block", marginBottom: "5px" }}>Company Name *</label>
          <input
            id="companyName"
            name="companyName"
            type="text"
            value={formData.companyName}
            onChange={handleChange}
            required
            style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
          />
        </div>

        <div>
          <label htmlFor="position" style={{ display: "block", marginBottom: "5px" }}>Position *</label>
          <input
            id="position"
            name="position"
            type="text"
            value={formData.position}
            onChange={handleChange}
            required
            style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
          />
        </div>

        <div>
          <label htmlFor="applicationDate" style={{ display: "block", marginBottom: "5px" }}>Application Date *</label>
          <input
            id="applicationDate"
            name="applicationDate"
            type="date"
            value={formData.applicationDate}
            onChange={handleChange}
            required
            style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
          />
        </div>

        <div>
          <label htmlFor="deadline" style={{ display: "block", marginBottom: "5px" }}>Deadline *</label>
          <input
            id="deadline"
            name="deadline"
            type="date"
            value={formData.deadline}
            onChange={handleChange}
            required
            style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
          />
        </div>

        <div>
          <label htmlFor="status" style={{ display: "block", marginBottom: "5px" }}>Status *</label>
          <select
            id="status"
            name="status"
            value={formData.status}
            onChange={handleChange}
            required
            style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
          >
            <option value="">Select Status</option>
            <option value="applied">Applied</option>
            <option value="interviewing">Interviewing</option>
            <option value="offer">Offer Received</option>
            <option value="rejected">Rejected</option>
            <option value="accepted">Accepted</option>
          </select>
        </div>

        <div>
          <label htmlFor="notes" style={{ display: "block", marginBottom: "5px" }}>Notes</label>
          <textarea
            id="notes"
            name="notes"
            value={formData.notes}
            onChange={handleChange}
            rows={4}
            style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
          />
        </div>

        <button
          type="submit"
          disabled={isSubmitting}
          style={{
            backgroundColor: "#007bff",
            color: "white",
            border: "none",
            padding: "10px 15px",
            borderRadius: "4px",
            cursor: isSubmitting ? "not-allowed" : "pointer",
            fontSize: "16px"
          }}
        >
          {isSubmitting ? "Submitting..." : "Submit Application"}
        </button>

        {submitError && (
          <div style={{ color: "red", marginTop: "10px" }}>
            Error: {submitError}
          </div>
        )}
      </form>
    </div>
  );
}

