  createTrip: (tripData: any): Promise<any> => {
    const newTrip = { id: String(mockDatabase.trips.length + 1), ...tripData };
    mockDatabase.trips.push(newTrip);
    return Promise.resolve(newTrip);
  },

  updateTrip: (id: string, tripData: any): Promise<any | null> => {
    const index = mockDatabase.trips.findIndex(t => t.id === id);
    if (index === -1) return Promise.resolve(null);

    mockDatabase.trips[index] = { ...mockDatabase.trips[index], ...tripData };
    return Promise.resolve(mockDatabase.trips[index]);
  },

  deleteTrip: (id: string): Promise<boolean> => {
    const initialLength = mockDatabase.trips.length;
    mockDatabase.trips = mockDatabase.trips.filter(t => t.id !== id);
    return Promise.resolve(mockDatabase.trips.length < initialLength);
  }
};

