import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Skip validation for non-protected routes
  if (req.method === "GET" && req.path === "/") {
    return next();
  }

  // Only protect POST, PUT, DELETE methods
  if (!['POST', 'PUT', 'DELETE'].includes(req.method)) {
    return next();
  }

  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    return res.status(401).json({ error: "Unauthorized" });
  }

  const token = authHeader.substring(7);
  const secret = process.env.JWT_SECRET;
  if (!secret) {
    return res.status(401).json({ error: "Unauthorized" });
  }

  try {
    const [payload, signature] = token.split(".");
    if (!payload || !signature) {
      return res.status(401).json({ error: "Unauthorized" });
    }

    const expectedSignature = createHmac("sha256", secret)
      .update(payload)
      .digest("base64url");

    const signatureBuffer = Buffer.from(signature, "base64url");
    const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");

    if (!timingSafeEqual(signatureBuffer, expectedSignatureBuffer)) {
      return res.status(401).json({ error: "Unauthorized" });
    }

    // Decode payload to check role
    const decodedPayload = JSON.parse(Buffer.from(payload, "base64url").toString());
    const userRole = decodedPayload.role;

    if (!userRole) {
      return res.status(401).json({ error: "Unauthorized" });
    }

    // Allow customers to view and book
    if (userRole === "customer" && (req.path.includes("/bookings") || req.path.includes("/trips"))) {
      return next();
    }

    // Allow staff to manage trips and bookings
    if (userRole === "staff" && (req.path.includes("/bookings") || req.path.includes("/trips"))) {
      return next();
    }

    return res.status(401).json({ error: "Unauthorized" });
  } catch (err) {
    return res.status(401).json({ error: "Unauthorized" });
  }
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process POST requests to /login endpoint
  if (req.method !== "POST" || req.path !== "/login") {
    next();
    return;
  }

  const jwtSecret = process.env.JWT_SECRET;

  if (!jwtSecret) {
    res.status(500).json({ error: "Internal server error" });
    return;
  }

  // Mock implementation - in a real scenario, we would verify the JWT token
  // For now, we'll just check if the request has a valid token header
  const authHeader = req.headers.authorization;

  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const token = authHeader.substring(7); // Remove 'Bearer '

  // In a real implementation, we would verify the token signature here
  // This is a simplified mock version
  try {
    // Simulate token verification
    const expectedSignature = createHmac("sha256", jwtSecret)
      .update(token.split(".")[0] + "." + token.split(".")[1])
      .digest();

    const actualSignature = Buffer.from(token.split(".")[2], "base64");

    if (actualSignature.length !== expectedSignature.length) {
      res.status(401).json({ error: "Unauthorized" });
      return;
    }

    const isEqual = timingSafeEqual(expectedSignature, actualSignature);

    if (!isEqual) {
      res.status(401).json({ error: "Unauthorized" });
      return;
    }
  } catch (error) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  next();
}

