import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";
import jwt from "jsonwebtoken";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only protect POST /api/bookings and PUT /api/bookings routes
  if (!(req.method === "POST" && req.path === "/api/bookings") && 
      !(req.method === "PUT" && req.path === "/api/bookings")) {
    return next();
  }

  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    return res.status(401).json({ error: "Unauthorized: Missing or invalid token" });
  }

  const token = authHeader.substring(7);

  const secret = process.env.JWT_SECRET;
  if (!secret) {
    return res.status(500).json({ error: "Internal Server Error: JWT secret not configured" });
  }

  try {
    // Verify the token using the secret
    const decoded = jwt.verify(token, secret);

    // Check if the token has the required structure
    if (typeof decoded !== "object" || decoded === null || !("userId" in decoded)) {
      return res.status(401).json({ error: "Unauthorized: Invalid token format" });
    }

    // Attach the user ID to the request object
    (req as any).userId = decoded.userId;

    next();
  } catch (err) {
    // Handle invalid signature or expired token
    if (err instanceof Error && err.message.includes("invalid signature")) {
      return res.status(401).json({ error: "Unauthorized: Invalid token signature" });
    }

    return res.status(401).json({ error: "Unauthorized: Invalid token" });
  }
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply role-based access control to specific routes
  const adminPaths = ["/admin", "/admin/"];
  const isAdminRoute = adminPaths.some(path => 
    req.path === path || req.path.startsWith(path + "/")
  );

  // Skip validation for non-admin routes
  if (!isAdminRoute) {
    next();
    return;
  }

  // Check if user has required role
  const userRole = req.headers["x-user-role"] as string | undefined;

  // If no role header, deny access
  if (!userRole) {
    res.status(403).json({ error: "Access denied: role required" });
    return;
  }

  // Check if user is admin
  if (userRole !== "admin") {
    res.status(403).json({ error: "Access denied: admin role required" });
    return;
  }

  // User has proper role, proceed
  next();
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Skip validation for GET requests without body
  if (req.method === "GET" && !req.body) {
    return next();
  }

  // Validate and sanitize input data
  if (req.body) {
    sanitizeBody(req.body);
  }

  // Validate query parameters
  if (req.query) {
    sanitizeQuery(req.query);
  }

  next();
}

function sanitizeBody(body: any): void {
  if (typeof body === "object" && body !== null) {
    for (const key in body) {
      if (typeof body[key] === "string") {
        // Remove script tags
        body[key] = body[key].replace(/<script[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>/gi, '');
        // Remove SQL injection patterns
        body[key] = body[key].replace(/(union|select|insert|update|delete|drop|create|alter|exec|execute)\b/gi, '');
      } else if (typeof body[key] === "object") {
        sanitizeBody(body[key]);
      }
    }
  }
}

function sanitizeQuery(query: any): void {
  if (typeof query === "object" && query !== null) {
    for (const key in query) {
      if (typeof query[key] === "string") {
        // Remove script tags
        query[key] = query[key].replace(/<script[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>/gi, '');
        // Remove SQL injection patterns
        query[key] = query[key].replace(/(union|select|insert|update|delete|drop|create|alter|exec|execute)\b/gi, '');
      }
    }
  }
}

