import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Skip validation for GET requests without body
  if (req.method === "GET" && !req.body) {
    return next();
  }

  // Validate and sanitize input data
  if (req.body) {
    sanitizeBody(req.body);
  }

  // Validate query parameters
  if (req.query) {
    sanitizeQuery(req.query);
  }

  next();
}

function sanitizeBody(body: any): void {
  if (typeof body === "object" && body !== null) {
    for (const key in body) {
      if (typeof body[key] === "string") {
        // Remove script tags
        body[key] = body[key].replace(/<script[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>/gi, '');
        // Remove SQL injection patterns
        body[key] = body[key].replace(/(union|select|insert|update|delete|drop|create|alter|exec|execute)\b/gi, '');
      } else if (typeof body[key] === "object") {
        sanitizeBody(body[key]);
      }
    }
  }
}

function sanitizeQuery(query: any): void {
  if (typeof query === "object" && query !== null) {
    for (const key in query) {
      if (typeof query[key] === "string") {
        // Remove script tags
        query[key] = query[key].replace(/<script[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>/gi, '');
        // Remove SQL injection patterns
        query[key] = query[key].replace(/(union|select|insert|update|delete|drop|create|alter|exec|execute)\b/gi, '');
      }
    }
  }
}

