import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";
import jwt from "jsonwebtoken";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only protect POST /api/bookings and PUT /api/bookings routes
  if (!(req.method === "POST" && req.path === "/api/bookings") && 
      !(req.method === "PUT" && req.path === "/api/bookings")) {
    return next();
  }

  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    return res.status(401).json({ error: "Unauthorized: Missing or invalid token" });
  }

  const token = authHeader.substring(7);

  const secret = process.env.JWT_SECRET;
  if (!secret) {
    return res.status(500).json({ error: "Internal Server Error: JWT secret not configured" });
  }

  try {
    // Verify the token using the secret
    const decoded = jwt.verify(token, secret);

    // Check if the token has the required structure
    if (typeof decoded !== "object" || decoded === null || !("userId" in decoded)) {
      return res.status(401).json({ error: "Unauthorized: Invalid token format" });
    }

    // Attach the user ID to the request object
    (req as any).userId = decoded.userId;

    next();
  } catch (err) {
    // Handle invalid signature or expired token
    if (err instanceof Error && err.message.includes("invalid signature")) {
      return res.status(401).json({ error: "Unauthorized: Invalid token signature" });
    }

    return res.status(401).json({ error: "Unauthorized: Invalid token" });
  }
}

