    return {
      id: item.id,
      name: inventoryItem.name,
      quantity: item.quantity,
      price: inventoryItem.price,
      total: itemTotal
    };
  });

  const newBill = {
    id: bills.length + 1,
    items: billItems,
    total,
    timestamp: new Date().toISOString()
  };

  bills.push(newBill);

