// Define types for our application
interface Product {
  id: number;
  name: string;
  price: number;
}

interface CartItem {
  product: Product;
  quantity: number;
}

export function BillingPage() {
  // State management
  const [products, setProducts] = useState<Product[]>([]);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [selectedProduct, setSelectedProduct] = useState<number>(0);
  const [quantity, setQuantity] = useState<number>(1);
  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);

  // Fetch products from API
  useEffect(() => {
    const fetchProducts = async () => {
      try {
        // Simulate API call
        await new Promise(resolve => setTimeout(resolve, 500));

        // Mock data - in a real app this would be an API call
        const mockProducts: Product[] = [
          { id: 1, name: "Cotton Fabric", price: 15.99 },
          { id: 2, name: "Silk Fabric", price: 25.50 },
          { id: 3, name: "Wool Yarn", price: 8.75 },
          { id: 4, name: "Linen Fabric", price: 12.25 },
          { id: 5, name: "Denim Fabric", price: 18.00 }
        ];

        setProducts(mockProducts);
        setLoading(false);
      } catch (err) {
        setError("Failed to load products");
        setLoading(false);
      }
    };

    fetchProducts();
  }, []);

  // Add item to cart
  const addToCart = () => {
    if (selectedProduct === 0 || quantity <= 0) return;

    const product = products.find(p => p.id === selectedProduct);
    if (!product) return;

    setCart(prevCart => {
      const existingItem = prevCart.find(item => item.product.id === selectedProduct);

      if (existingItem) {
        return prevCart.map(item => 
          item.product.id === selectedProduct 
            ? { ...item, quantity: item.quantity + quantity } 
            : item
        );
      } else {
        return [...prevCart, { product, quantity }];
      }
    });

    // Reset selection
    setSelectedProduct(0);
    setQuantity(1);
  };

  // Remove item from cart
  const removeFromCart = (productId: number) => {
    setCart(prevCart => prevCart.filter(item => item.product.id !== productId));
  };

  // Calculate total amount
  const calculateTotal = (): number => {
    return cart.reduce((total, item) => {
      return total + (item.product.price * item.quantity);
    }, 0);
  };

  // Generate bill
  const generateBill = () => {
    if (cart.length === 0) return;

    alert(`\n--- BILL ---\n${cart.map(item => `${item.product.name}: ${item.quantity} x $${item.product.price.toFixed(2)} = $${(item.product.price * item.quantity).toFixed(2)}`).join('\n')}\n\nTOTAL: $${calculateTotal().toFixed(2)}\n--- END BILL ---`);

    // Clear cart after bill generation
    setCart([]);
  };

  // Render loading state
  if (loading) {
    return (
      <div style={{
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        height: "100vh",
        fontFamily: "system-ui, sans-serif"
      }}>
        <p>Loading...</p>
      </div>
    );
  }

  // Render error state
  if (error) {
    return (
      <div style={{
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        height: "100vh",
        fontFamily: "system-ui, sans-serif"
      }}>
        <p>{error}</p>
      </div>
    );
  }

  return (
    <div style={{
      maxWidth: "800px",
      margin: "0 auto",
      padding: "20px",
      fontFamily: "system-ui, sans-serif"
    }}>
      <h1 style={{ textAlign: "center" }}>Textile Shop Billing</h1>

      <div style={{ marginBottom: "30px" }}>
        <h2>Products</h2>
        <div style={{ display: "flex", flexWrap: "wrap", gap: "10px" }}>
          {products.map(product => (
            <div 
              key={product.id}
              style={{
                border: "1px solid #ccc",
                borderRadius: "8px",
                padding: "10px",
                minWidth: "150px",
                textAlign: "center"
              }}
            >
              <div><strong>{product.name}</strong></div>
              <div>${product.price.toFixed(2)}</div>
            </div>
          ))}
        </div>
      </div>

      <div style={{ marginBottom: "30px" }}>
        <h2>Add to Cart</h2>
        <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
          <select
            value={selectedProduct}
            onChange={(e) => setSelectedProduct(Number(e.target.value))}
            style={{ padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
          >
            <option value="0">Select Product</option>
            {products.map(product => (
              <option key={product.id} value={product.id}>{product.name}</option>
            ))}
          </select>

          <input
            type="number"
            min="1"
            value={quantity}
            onChange={(e) => setQuantity(Number(e.target.value))}
            style={{ padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
          />

          <button
            onClick={addToCart}
            disabled={!selectedProduct || quantity <= 0}
            style={{
              padding: "10px",
              backgroundColor: "#007bff",
              color: "white",
              border: "none",
              borderRadius: "4px",
              cursor: "pointer"
            }}
          >
            Add to Cart
          </button>
        </div>
      </div>

      <div style={{ marginBottom: "30px" }}>
        <h2>Shopping Cart</h2>

        {cart.length === 0 ? (
          <p>No items in cart</p>
        ) : (
          <>
            <div style={{ marginBottom: "10px" }}>
              {cart.map(item => (
                <div 
                  key={item.product.id}
                  style={{
                    display: "flex",
                    justifyContent: "space-between",
                    alignItems: "center",
                    padding: "10px",
                    borderBottom: "1px solid #eee"
                  }}
                >
                  <span>
                    {item.product.name} - ${item.product.price.toFixed(2)} x {item.quantity}
                  </span>
                  <button
                    onClick={() => removeFromCart(item.product.id)}
                    style={{
                      padding: "5px 10px",
                      backgroundColor: "#dc3545",
                      color: "white",
                      border: "none",
                      borderRadius: "4px",
                      cursor: "pointer"
                    }}
                  >
                    Remove
                  </button>
                </div>
              ))}
            </div>

            <div style={{
              display: "flex",
              justifyContent: "space-between",
              alignItems: "center",
              padding: "10px",
              backgroundColor: "#f8f9fa",
              borderRadius: "4px",
              fontWeight: "bold"
            }}>
              <span>Total: ${calculateTotal().toFixed(2)}</span>
              <button
                onClick={generateBill}
                style={{
                  padding: "10px 20px",
                  backgroundColor: "#28a745",
                  color: "white",
                  border: "none",
                  borderRadius: "4px",
                  cursor: "pointer"
                }}
              >
                Generate Bill
              </button>
            </div>
          </>
        )}
      </div>
    </div>
  );
}

import { useEffect, useState } from "react";

interface InventoryItem {
  id: number;
  name: string;
  quantity: number;
  price: number;
}

interface Sale {
  id: number;
  itemName: string;
  quantity: number;
  total: number;
  date: string;
}

export function DashboardPage() {
  const [inventory, setInventory] = useState<InventoryItem[]>([]);
  const [sales, setSales] = useState<Sale[]>([]);
  const [lowStockItems, setLowStockItems] = useState<InventoryItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const fetchData = async () => {
      try {
        // Simulate API calls
        await new Promise(resolve => setTimeout(resolve, 500));

        // Mock inventory data
        const mockInventory: InventoryItem[] = [
          { id: 1, name: "Cotton Fabric", quantity: 50, price: 15.99 },
          { id: 2, name: "Silk Fabric", quantity: 20, price: 45.50 },
          { id: 3, name: "Wool Yarn", quantity: 10, price: 8.75 },
          { id: 4, name: "Linen Fabric", quantity: 30, price: 22.00 },
        ];

        // Mock sales data
        const mockSales: Sale[] = [
          { id: 1, itemName: "Cotton Fabric", quantity: 5, total: 79.95, date: "2023-05-15" },
          { id: 2, itemName: "Silk Fabric", quantity: 2, total: 91.00, date: "2023-05-16" },
          { id: 3, itemName: "Wool Yarn", quantity: 3, total: 26.25, date: "2023-05-17" },
        ];

        // Mock low stock items
        const mockLowStock: InventoryItem[] = [
          { id: 3, name: "Wool Yarn", quantity: 10, price: 8.75 },
        ];

        setInventory(mockInventory);
        setSales(mockSales);
        setLowStockItems(mockLowStock);
        setLoading(false);
      } catch (err) {
        setError("Failed to fetch dashboard data");
        setLoading(false);
      }
    };

    fetchData();
  }, []);

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
  }

  const totalInventoryValue = inventory.reduce(
    (sum, item) => sum + item.quantity * item.price,
    0
  );

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center", marginBottom: "30px" }}>Dashboard</h1>

      <div style={{ display: "flex", flexDirection: "column", gap: "20px" }}>
        {/* Stats Cards */}
        <div style={{ display: "flex", flexWrap: "wrap", gap: "20px" }}>
          <div style={{ flex: "1 1 200px", padding: "20px", border: "1px solid #ddd", borderRadius: "8px", backgroundColor: "#f9f9f9" }}>
            <h2>Total Inventory Value</h2>
            <p style={{ fontSize: "24px", fontWeight: "bold", color: "#2c5e1a" }}>${totalInventoryValue.toFixed(2)}</p>
          </div>

          <div style={{ flex: "1 1 200px", padding: "20px", border: "1px solid #ddd", borderRadius: "8px", backgroundColor: "#f9f9f9" }}>
            <h2>Recent Sales</h2>
            <p style={{ fontSize: "24px", fontWeight: "bold", color: "#2c5e1a" }}>{sales.length}</p>
          </div>

          <div style={{ flex: "1 1 200px", padding: "20px", border: "1px solid #ddd", borderRadius: "8px", backgroundColor: "#f9f9f9" }}>
            <h2>Low Stock Items</h2>
            <p style={{ fontSize: "24px", fontWeight: "bold", color: "#d97706" }}>{lowStockItems.length}</p>
          </div>
        </div>

        {/* Recent Sales */}
        <div style={{ padding: "20px", border: "1px solid #ddd", borderRadius: "8px", backgroundColor: "#f9f9f9" }}>
          <h2>Recent Sales</h2>
          {sales.length > 0 ? (
            <table style={{ width: "100%", borderCollapse: "collapse" }}>
              <thead>
                <tr style={{ borderBottom: "1px solid #ddd" }}>
                  <th style={{ textAlign: "left", padding: "10px" }}>Item</th>
                  <th style={{ textAlign: "left", padding: "10px" }}>Quantity</th>
                  <th style={{ textAlign: "left", padding: "10px" }}>Total</th>
                  <th style={{ textAlign: "left", padding: "10px" }}>Date</th>
                </tr>
              </thead>
              <tbody>
                {sales.map(sale => (
                  <tr key={sale.id} style={{ borderBottom: "1px solid #eee" }}>
                    <td style={{ padding: "10px" }}>{sale.itemName}</td>
                    <td style={{ padding: "10px" }}>{sale.quantity}</td>
                    <td style={{ padding: "10px" }}>${sale.total.toFixed(2)}</td>
                    <td style={{ padding: "10px" }}>{sale.date}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          ) : (
            <p>No recent sales</p>
          )}
        </div>

        {/* Low Stock Alerts */}
        <div style={{ padding: "20px", border: "1px solid #ddd", borderRadius: "8px", backgroundColor: "#f9f9f9" }}>
          <h2>Low Stock Alerts</h2>
          {lowStockItems.length > 0 ? (
            <ul style={{ listStyle: "none", padding: 0 }}>
              {lowStockItems.map(item => (
                <li key={item.id} style={{ padding: "10px", borderBottom: "1px solid #eee" }}>
                  <span style={{ fontWeight: "bold" }}>{item.name}</span> - Only {item.quantity} left
                </li>
              ))}
            </ul>
          ) : (
            <p>No low stock items</p>
          )}
        </div>
      </div>
    </div>
  );
}

import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock database functions - in a real app these would come from a database module
const mockDatabase = {
  getAllItems: () => Promise.resolve([
    { id: 1, name: "Cotton Fabric", quantity: 100, price: 15.99 },
    { id: 2, name: "Silk Fabric", quantity: 50, price: 45.50 }
  ]),
  getItemById: (id: number) => Promise.resolve({ id, name: "Cotton Fabric", quantity: 100, price: 15.99 }),
  createItem: (item: any) => Promise.resolve({ id: 3, ...item }),
  updateItem: (id: number, item: any) => Promise.resolve({ id, ...item }),
  deleteItem: (id: number) => Promise.resolve(true)
};

// GET /inventory - List all items
router.get("/", async (req: Request, res: Response) => {
  try {
    const items = await mockDatabase.getAllItems();
    res.json(items);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch items" });
  }
});

// GET /inventory/:id - Get a specific item by ID
router.get("/:id", async (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid ID format" });
    }
    const item = await mockDatabase.getItemById(id);
    if (!item) {
      return res.status(404).json({ error: "Item not found" });
    }
    res.json(item);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch item" });
  }
});

// POST /inventory - Create a new item
router.post("/", async (req: Request, res: Response) => {
  try {
    const { name, quantity, price } = req.body;
    if (!name || quantity === undefined || price === undefined) {
      return res.status(400).json({ error: "Name, quantity, and price are required" });
    }
    const newItem = await mockDatabase.createItem({
      name,
      quantity: Number(quantity),
      price: Number(price)
    });
    res.status(201).json(newItem);
  } catch (error) {
    res.status(500).json({ error: "Failed to create item" });
  }
});

// PUT /inventory/:id - Update an existing item
router.put("/:id", async (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid ID format" });
    }
    const { name, quantity, price } = req.body;
    if (!name || quantity === undefined || price === undefined) {
      return res.status(400).json({ error: "Name, quantity, and price are required" });
    }
    const updatedItem = await mockDatabase.updateItem(id, {
      name,
      quantity: Number(quantity),
      price: Number(price)
    });
    if (!updatedItem) {
      return res.status(404).json({ error: "Item not found" });
    }
    res.json(updatedItem);
  } catch (error) {
    res.status(500).json({ error: "Failed to update item" });
  }
});

// DELETE /inventory/:id - Delete an item
router.delete("/:id", async (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid ID format" });
    }
    const deleted = await mockDatabase.deleteItem(id);
    if (!deleted) {
      return res.status(404).json({ error: "Item not found" });
    }
    res.json({ message: "Item deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to delete item" });
  }
});

import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock user database
const users = [
  { id: 1, email: "parent@example.com", password: "parent123", role: "parent" },
  { id: 2, email: "staff@example.com", password: "staff123", role: "staff" }
];

// Registration endpoint
router.post("/register", (req: Request, res: Response) => {
  const { email, password, role } = req.body;

  // Validate input
  if (!email || !password || !role) {
    return res.status(400).json({ error: "Email, password, and role are required" });
  }

  // Check if user already exists
  const existingUser = users.find(user => user.email === email);
  if (existingUser) {
    return res.status(400).json({ error: "User already exists" });
  }

  // Create new user
  const newUser = {
    id: users.length + 1,
    email,
    password,
    role
  };

  users.push(newUser);

  return res.status(201).json(newUser);
});

// Login endpoint
router.post("/login", (req: Request, res: Response) => {
  const { email, password } = req.body;

  // Validate input
  if (!email || !password) {
    return res.status(400).json({ error: "Email and password are required" });
  }

  // Find user
  const user = users.find(u => u.email === email && u.password === password);
  if (!user) {
    return res.status(401).json({ error: "Invalid credentials" });
  }

  // Return user info (in a real app, this would be a JWT token)
  return res.json({
    email: user.email,
    role: user.role
  });
});

// Role-based access control middleware
const authorize = (roles: string[]) => {
  return (req: Request, res: Response, next: Function) => {
    // In a real app, this would check the JWT token
    const userRole = req.headers.role as string;

    if (!userRole || !roles.includes(userRole)) {
      return res.status(403).json({ error: "Access denied" });
    }

    next();
  };
};

// Protected route examples
router.get("/parent-dashboard", authorize(["parent"]), (req: Request, res: Response) => {
  return res.json({ message: "Parent dashboard accessed successfully" });
});

router.get("/staff-dashboard", authorize(["staff"]), (req: Request, res: Response) => {
  return res.json({ message: "Staff dashboard accessed successfully" });
});

import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock database - in a real app this would be a proper database
const mockDatabase: { children: Array<{ id: string; name: string; age: number; medicalInfo: string; attendance: never[] }> } = {
  children: [
    { id: "1", name: "Alice Smith", age: 4, medicalInfo: "Allergic to peanuts", attendance: [] },
    { id: "2", name: "Bob Johnson", age: 5, medicalInfo: "None", attendance: [] }
  ]
};

// Get all children
router.get("/children", (req: Request, res: Response) => {
  res.json(mockDatabase.children);
});

// Get a specific child by ID
router.get("/children/:id", (req: Request, res: Response) => {
  const childId = req.params.id;
  const child = mockDatabase.children.find(c => c.id === childId);

  if (!child) {
    return res.status(404).json({ error: "Child not found" });
  }

  res.json(child);
});

// Create a new child
router.post("/children", (req: Request, res: Response) => {
  const { name, age, medicalInfo } = req.body;

  // Validate required fields
  if (!name || !age || !medicalInfo) {
    return res.status(400).json({ error: "Name, age, and medicalInfo are required" });
  }

  // Create new child object
  const newChild = {
    id: Date.now().toString(),
    name,
    age: Number(age),
    medicalInfo,
    attendance: []
  };

  // Add to mock database
  mockDatabase.children.push(newChild);

  // Return created child with 201 status
  res.status(201).json(newChild);
});

// Update a child by ID
router.put("/children/:id", (req: Request, res: Response) => {
  const childId = req.params.id;
  const { name, age, medicalInfo } = req.body;

  // Find child index
  const childIndex = mockDatabase.children.findIndex(c => c.id === childId);

  if (childIndex === -1) {
    return res.status(404).json({ error: "Child not found" });
  }

  // Validate required fields
  if (!name || !age || !medicalInfo) {
    return res.status(400).json({ error: "Name, age, and medicalInfo are required" });
  }

  // Update child
  const updatedChild = {
    ...mockDatabase.children[childIndex],
    name,
    age: Number(age),
    medicalInfo
  };

  mockDatabase.children[childIndex] = updatedChild;

  res.json(updatedChild);
});

// Delete a child by ID
router.delete("/children/:id", (req: Request, res: Response) => {
  const childId = req.params.id;
  const childIndex = mockDatabase.children.findIndex(c => c.id === childId);

  if (childIndex === -1) {
    return res.status(404).json({ error: "Child not found" });
  }

  // Remove child from array
  mockDatabase.children.splice(childIndex, 1);

  res.json({ message: "Child deleted successfully" });
});

import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock implementations for messaging functionality
// In a real app, these would call actual database functions

const messages = [
  {
    id: "1",
    senderId: "parent1",
    recipientId: "staff1",
    content: "Hello, I'm concerned about my child's behavior.",
    timestamp: new Date().toISOString(),
    read: false
  },
  {
    id: "2",
    senderId: "staff1",
    recipientId: "parent1",
    content: "I've noticed some issues too. Let's discuss during drop-off.",
    timestamp: new Date().toISOString(),
    read: true
  }
];

// Get all messages for a user
router.get("/messages/:userId", (req: Request, res: Response) => {
  const userId = req.params.userId;

  if (!userId) {
    return res.status(400).json({ error: "User ID is required" });
  }

  const userMessages = messages.filter(
    msg => msg.senderId === userId || msg.recipientId === userId
  );

  return res.json(userMessages);
});

// Get a specific message by ID
router.get("/messages/:id", (req: Request, res: Response) => {
  const messageId = req.params.id;

  if (!messageId) {
    return res.status(400).json({ error: "Message ID is required" });
  }

  const message = messages.find(msg => msg.id === messageId);

  if (!message) {
    return res.status(404).json({ error: "Message not found" });
  }

  return res.json(message);
});

// Create a new message
router.post("/messages", (req: Request, res: Response) => {
  const { senderId, recipientId, content } = req.body;

  if (!senderId || !recipientId || !content) {
    return res.status(400).json({ error: "Sender ID, recipient ID, and content are required" });
  }

  const newMessage = {
    id: `${messages.length + 1}`,
    senderId,
    recipientId,
    content,
    timestamp: new Date().toISOString(),
    read: false
  };

  messages.push(newMessage);

  return res.status(201).json(newMessage);
});

// Update a message (mark as read)
router.put("/messages/:id", (req: Request, res: Response) => {
  const messageId = req.params.id;
  const { read } = req.body;

  if (!messageId) {
    return res.status(400).json({ error: "Message ID is required" });
  }

  const messageIndex = messages.findIndex(msg => msg.id === messageId);

  if (messageIndex === -1) {
    return res.status(404).json({ error: "Message not found" });
  }

  if (read !== undefined) {
    messages[messageIndex].read = read;
  }

  return res.json(messages[messageIndex]);
});

// Delete a message
router.delete("/messages/:id", (req: Request, res: Response) => {
  const messageId = req.params.id;

  if (!messageId) {
    return res.status(400).json({ error: "Message ID is required" });
  }

  const messageIndex = messages.findIndex(msg => msg.id === messageId);

  if (messageIndex === -1) {
    return res.status(404).json({ error: "Message not found" });
  }

  messages.splice(messageIndex, 1);

  return res.json({ message: "Message deleted successfully" });
});

