export const router = Router();

// Mock event data structure
interface Event {
  id: string;
  title: string;
  description: string;
  date: string;
  time: string;
  location: string;
  attendees: string[];
}

// Mock in-memory storage
let events: Event[] = [];
let nextId = 1;

// Get all events
router.get("/", (req: Request, res: Response) => {
  res.json(events);
});

// Get event by ID
router.get("/:id", (req: Request, res: Response) => {
  const id = req.params.id;
  const event = events.find(e => e.id === id);

  if (!event) {
    return res.status(404).json({ message: "Event not found" });
  }

  res.json(event);
});

// Create new event
router.post("/", (req: Request, res: Response) => {
  const { title, description, date, time, location } = req.body;

  // Validate required fields
  if (!title || !date || !time || !location) {
    return res.status(400).json({ message: "Title, date, time, and location are required" });
  }

  const newEvent: Event = {
    id: nextId.toString(),
    title,
    description: description || "",
    date,
    time,
    location,
    attendees: []
  };

  events.push(newEvent);
  nextId++;

  res.status(201).json(newEvent);
});

// Update event
router.put("/:id", (req: Request, res: Response) => {
  const id = req.params.id;
  const { title, description, date, time, location } = req.body;

  const eventIndex = events.findIndex(e => e.id === id);

  if (eventIndex === -1) {
    return res.status(404).json({ message: "Event not found" });
  }

  // Validate required fields
  if (!title || !date || !time || !location) {
    return res.status(400).json({ message: "Title, date, time, and location are required" });
  }

  events[eventIndex] = {
    ...events[eventIndex],
    title,
    description: description || events[eventIndex].description,
    date,
    time,
    location
  };

  res.json(events[eventIndex]);
});

// Delete event
router.delete("/:id", (req: Request, res: Response) => {
  const id = req.params.id;
  const eventIndex = events.findIndex(e => e.id === id);

  if (eventIndex === -1) {
    return res.status(404).json({ message: "Event not found" });
  }

  events.splice(eventIndex, 1);

  res.json({ message: "Event deleted successfully" });
});

// Add attendee to event
router.post("/:id/attendees", (req: Request, res: Response) => {
  const id = req.params.id;
  const { attendeeId } = req.body;

  if (!attendeeId) {
    return res.status(400).json({ message: "Attendee ID is required" });
  }

  const event = events.find(e => e.id === id);

  if (!event) {
    return res.status(404).json({ message: "Event not found" });
  }

  if (!event.attendees.includes(attendeeId)) {
    event.attendees.push(attendeeId);
  }

  res.json(event);
});

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply RBAC to protected routes
  const protectedPaths = [
    /^\/api\/children\/.+/, // /api/children/:id
    /^\/api\/parents\/.+/, // /api/parents/:id
    /^\/api\/staff\/.+/, // /api/staff/:id
    /^\/api\/reports\/.+/, // /api/reports/:id
  ];

  const isProtectedPath = protectedPaths.some(path => path.test(req.path));

  if (!isProtectedPath) {
    next();
    return;
  }

  // Check if user has proper role access
  const authHeader = req.headers.authorization;

  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized: Missing or invalid token" });
    return;
  }

  const token = authHeader.substring(7); // Remove 'Bearer '

  try {
    // Decode token (basic decoding, not verification)
    const payload = JSON.parse(Buffer.from(token.split(".")[1], "base64").toString());

    // Verify token signature
    const secret = process.env.JWT_SECRET;

    if (!secret) {
      res.status(500).json({ error: "Server configuration error: JWT_SECRET not set" });
      return;
    }

    const expectedSignature = createHmac("sha256", secret)
      .update(`${token.split(".")[0]}.${token.split(".")[1]}`)
      .digest();

    const actualSignature = Buffer.from(token.split(".")[2], "base64");

    if (actualSignature.length !== expectedSignature.length || 
        !timingSafeEqual(actualSignature, expectedSignature)) {
      res.status(401).json({ error: "Unauthorized: Invalid token signature" });
      return;
    }

    // Extract user info from token
    const { userId, role, childId } = payload;

    // Staff can access all data
    if (role === "staff") {
      next();
      return;
    }

    // Parents can only access their own child's data
    if (role === "parent" && childId) {
      const requestedChildId = req.params.id || req.params.childId;

      if (requestedChildId && requestedChildId === childId) {
        next();
        return;
      }

      res.status(403).json({ error: "Forbidden: Access denied to this child's data" });
      return;
    }

    // Default deny
    res.status(403).json({ error: "Forbidden: Insufficient permissions" });
    return;
  } catch (error) {
    res.status(401).json({ error: "Unauthorized: Invalid token format" });
    return;
  }
}

