import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock database functions - in a real app these would connect to a database
const mockDatabase = {
  getAllRoutes: async () => [
    { id: 1, name: "Route A", stops: ["Stop 1", "Stop 2"], driver: "John Doe" },
    { id: 2, name: "Route B", stops: ["Stop 3", "Stop 4"], driver: "Jane Smith" }
  ],
  getRouteById: async (id: number) => {
    const routes = await mockDatabase.getAllRoutes();
    return routes.find(route => route.id === id) || null;
  },
  createRoute: async (routeData: any) => {
    const routes = await mockDatabase.getAllRoutes();
    const newId = routes.length > 0 ? Math.max(...routes.map(r => r.id)) + 1 : 1;
    const newRoute = { id: newId, ...routeData };
    return newRoute;
  },
  updateRoute: async (id: number, routeData: any) => {
    const routes = await mockDatabase.getAllRoutes();
    const index = routes.findIndex(route => route.id === id);
    if (index === -1) return null;
    routes[index] = { ...routes[index], ...routeData };
    return routes[index];
  },
  deleteRoute: async (id: number) => {
    const routes = await mockDatabase.getAllRoutes();
    const initialLength = routes.length;
    const filteredRoutes = routes.filter(route => route.id !== id);
    return filteredRoutes.length < initialLength;
  }
};

// GET /api/routes - List all routes
router.get("/", async (req: Request, res: Response) => {
  try {
    const routes = await mockDatabase.getAllRoutes();
    return res.json(routes);
  } catch (error) {
    return res.status(500).json({ error: "Internal server error" });
  }
});

// GET /api/routes/:id - Get a specific route by ID
router.get("/:id", async (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid route ID" });
    }
    const route = await mockDatabase.getRouteById(id);
    if (!route) {
      return res.status(404).json({ error: "Route not found" });
    }
    return res.json(route);
  } catch (error) {
    return res.status(500).json({ error: "Internal server error" });
  }
});

// POST /api/routes - Create a new route
router.post("/", async (req: Request, res: Response) => {
  try {
    const { name, stops, driver } = req.body;
    if (!name || !stops || !driver) {
      return res.status(400).json({ error: "Name, stops, and driver are required" });
    }
    const newRoute = await mockDatabase.createRoute({ name, stops, driver });
    return res.status(201).json(newRoute);
  } catch (error) {
    return res.status(500).json({ error: "Internal server error" });
  }
