  // Only protect POST, PUT, DELETE requests to admin routes
  if (!(req.method === "POST" || req.method === "PUT" || req.method === "DELETE") || 
      !req.path.startsWith("/admin")) {
    return next();
  }

  // Check for authorization header
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    return res.status(401).json({ error: "Unauthorized" });
  }

  const token = authHeader.substring(7); // Remove "Bearer " prefix

  // Verify token signature
  if (!verifyToken(token)) {
    return res.status(401).json({ error: "Invalid token" });
  }

  // In a real implementation, we would decode the token here
  // and check if the user has admin role
  // For now, we'll assume valid tokens have admin access

  // Allow access for valid tokens
  return next();
}

