    display: "flex",
    gap: "10px",
    marginTop: "10px"
  };

  if (loading) return <div style={containerStyle}>Loading...</div>;
  if (error) return <div style={containerStyle}>Error: {error}</div>;

  return (
    <div style={containerStyle}>
      <h1>Bus Routes Management</h1>

      <form onSubmit={editingId ? handleUpdate : handleSubmit} style={formStyle}>
        <input
          type="text"
          name="name"
          placeholder="Route Name"
          value={formData.name}
          onChange={handleChange}
          style={inputStyle}
        />
        <textarea
          name="stops"
          placeholder="Stops (comma separated)"
          value={formData.stops}
          onChange={handleChange}
          style={inputStyle}
        />
        <input
          type="text"
          name="driver"
          placeholder="Driver Name"
          value={formData.driver}
          onChange={handleChange}
          style={inputStyle}
        />
        <div>
          <button type="submit" style={buttonStyle}>
            {editingId ? "Update Route" : "Add Route"}
          </button>
          {editingId && (
            <button type="button" onClick={cancelEditing} style={cancelButtonStyle}>
              Cancel
            </button>
          )}
        </div>
      </form>

      <h2>Existing Routes</h2>
      <div style={routesContainerStyle}>
        {routes.length === 0 ? (
          <p>No routes found.</p>
        ) : (
          routes.map(route => (
            <div key={route.id} style={routeCardStyle}>
              <h3>{route.name}</h3>
              <p><strong>Stops:</strong> {route.stops.join(", ")}</p>
              <p><strong>Driver:</strong> {route.driver}</p>
              <div style={buttonGroupStyle}>
                <button onClick={() => startEditing(route)} style={buttonStyle}>Edit</button>
                <button onClick={() => handleDelete(route.id)} style={cancelButtonStyle}>Delete</button>
              </div>
            </div>
          ))
        )}
      </div>
    </div>
  );
}

import { useEffect, useState } from "react";

interface Student {
  id: number;
  name: string;
  grade: string;
  address: string;
  parentPhone: string;
}

export function StudentsManagement() {
  const [students, setStudents] = useState<Student[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [formData, setFormData] = useState<Omit<Student, "id">>({ 
    name: "", 
    grade: "", 
    address: "", 
    parentPhone: ""
  });
  const [editingId, setEditingId] = useState<number | null>(null);

  useEffect(() => {
    fetchStudents();
  }, []);

  const fetchStudents = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/students");
      if (!response.ok) throw new Error("Failed to fetch students");
      const data = await response.json();
      setStudents(data);
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
    const { name, value } = e.target;
    setFormData({ ...formData, [name]: value });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const response = await fetch("/api/students", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(formData),
      });
      if (!response.ok) throw new Error("Failed to add student");
      await fetchStudents();
      setFormData({ name: "", grade: "", address: "", parentPhone: "" });
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleEdit = (student: Student) => {
    setEditingId(student.id);
    setFormData({ 
      name: student.name, 
      grade: student.grade, 
      address: student.address, 
      parentPhone: student.parentPhone
    });
  };

  const handleUpdate = async (e: React.FormEvent) => {
    e.preventDefault();
    if (editingId === null) return;
    try {
      const response = await fetch(`/api/students/${editingId}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(formData),
      });
      if (!response.ok) throw new Error("Failed to update student");
      await fetchStudents();
      setEditingId(null);
      setFormData({ name: "", grade: "", address: "", parentPhone: "" });
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleDelete = async (id: number) => {
    try {
      const response = await fetch(`/api/students/${id}`, {
        method: "DELETE",
