      <form onSubmit={editingId ? handleUpdate : handleSubmit} style={{ marginBottom: "30px", padding: "20px", border: "1px solid #ccc", borderRadius: "8px" }}>
        <h2>{editingId ? "Edit Student" : "Add New Student"}</h2>
        <div style={{ marginBottom: "15px" }}>
