  amount: number;
  status: "paid" | "pending" | "overdue";
  dueDate: string;
  paymentDate?: string;
}

interface FeeFormData {
  studentId: string;
  amount: string;
  dueDate: string;
}

export function FeesManagement() {
  const [fees, setFees] = useState<Fee[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
