      <div style={{ marginBottom: "20px", display: "flex", justifyContent: "center" }}>
        <button
          onClick={() => setShowForm(!showForm)}
          style={{
            backgroundColor: "#007bff",
            color: "white",
            border: "none",
            borderRadius: "4px",
            padding: "10px 15px",
            cursor: "pointer",
          }}
        >
          {showForm ? "Cancel" : "Add New Fee"}
        </button>
      </div>

      {showForm && (
        <form
          onSubmit={handleSubmit}
          style={{
            backgroundColor: "#f8f9fa",
            padding: "20px",
            borderRadius: "8px",
            marginBottom: "20px",
            border: "1px solid #dee2e6",
          }}
        >
          <div style={{ marginBottom: "15px" }}>
            <label htmlFor="studentId" style={{ display: "block", marginBottom: "5px" }}>
              Student ID
            </label>
            <input
              type="text"
              id="studentId"
              name="studentId"
              value={formData.studentId}
              onChange={handleInputChange}
              required
              style={{
                width: "100%",
                padding: "8px",
                borderRadius: "4px",
                border: "1px solid #ced4da",
              }}
            />
          </div>

          <div style={{ marginBottom: "15px" }}>
            <label htmlFor="amount" style={{ display: "block", marginBottom: "5px" }}>
              Amount ($)
            </label>
            <input
              type="number"
              id="amount"
              name="amount"
              value={formData.amount}
              onChange={handleInputChange}
              required
              min="0"
              step="0.01"
              style={{
                width: "100%",
                padding: "8px",
                borderRadius: "4px",
                border: "1px solid #ced4da",
              }}
            />
          </div>

          <div style={{ marginBottom: "15px" }}>
            <label htmlFor="dueDate" style={{ display: "block", marginBottom: "5px" }}>
              Due Date
            </label>
            <input
              type="date"
              id="dueDate"
              name="dueDate"
              value={formData.dueDate}
              onChange={handleInputChange}
              required
              style={{
                width: "100%",
                padding: "8px",
                borderRadius: "4px",
                border: "1px solid #ced4da",
              }}
            />
          </div>

          <button
            type="submit"
            style={{
              backgroundColor: "#28a745",
              color: "white",
              border: "none",
              borderRadius: "4px",
              padding: "10px 15px",
              cursor: "pointer",
            }}
          >
            Create Fee
          </button>
        </form>
      )}

      <h2>Fees History</h2>
      {fees.length === 0 ? (
        <p style={{ textAlign: "center", padding: "20px" }}>No fees found.</p>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
          {fees.map((fee) => (
            <div
              key={fee.id}
              style={{
                backgroundColor: "#fff",
                border: "1px solid #dee2e6",
                borderRadius: "8px",
                padding: "15px",
                display: "flex",
                justifyContent: "space-between",
                alignItems: "center",
                flexWrap: "wrap",
              }}
            >
              <div style={{ flex: 1, minWidth: "200px" }}>
                <strong>Student ID:</strong> {fee.studentId}<br />
                <strong>Amount:</strong> ${fee.amount.toFixed(2)}<br />
                <strong>Status:</strong> {fee.status}<br />
                <strong>Due Date:</strong> {new Date(fee.dueDate).toLocaleDateString()}<br />
                {fee.paymentDate && (
                  <>
                    <strong>Payment Date:</strong> {new Date(fee.paymentDate).toLocaleDateString()}<br />
                  </>
                )}
              </div>
              <div style={{ marginLeft: "10px" }}>
                {fee.status !== "paid" && (
                  <button
                    onClick={() => handlePayment(fee.id)}
                    style={{
                      backgroundColor: "#ffc107",
                      color: "black",
                      border: "none",
                      borderRadius: "4px",
                      padding: "8px 12px",
                      cursor: "pointer",
                    }}
                  >
                    Mark as Paid
                  </button>
                )}
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

const JWT_SECRET = process.env.JWT_SECRET;

function verifyToken(token: string): boolean {
  if (!JWT_SECRET) return false;

  // Simple JWT structure validation
  const parts = token.split(".");
  if (parts.length !== 3) return false;

  const [header, payload, signature] = parts;

  // Create expected signature
  const expectedSignature = createHmac("sha256", JWT_SECRET)
    .update(`${header}.${payload}`)
    .digest("base64url");

  // Use timingSafeEqual to prevent timing attacks
  try {
    const expectedBuffer = Buffer.from(expectedSignature, "base64url");
    const actualBuffer = Buffer.from(signature, "base64url");
    return timingSafeEqual(expectedBuffer, actualBuffer);
  } catch {
    return false;
  }
}

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only protect POST, PUT, DELETE requests to admin routes
  if (!(req.method === "POST" || req.method === "PUT" || req.method === "DELETE") || 
      !req.path.startsWith("/admin")) {
    return next();
  }

  // Check for authorization header
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    return res.status(401).json({ error: "Unauthorized" });
  }

  const token = authHeader.substring(7); // Remove "Bearer " prefix

  // Verify token signature
  if (!verifyToken(token)) {
    return res.status(401).json({ error: "Invalid token" });
  }

  // In a real implementation, we would decode the token here
  // and check if the user has admin role
  // For now, we'll assume valid tokens have admin access

  // Allow access for valid tokens
  return next();
}

import { useEffect, useState } from "react";

interface Route {
  id: number;
  name: string;
  stops: string[];
  driver: string;
}

export function RoutesManagement() {
  const [routes, setRoutes] = useState<Route[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const [editingId, setEditingId] = useState<number | null>(null);
  const [formData, setFormData] = useState({
    name: "",
    stops: "",
    driver: ""
  });

  // Fetch routes
  useEffect(() => {
    const fetchRoutes = async () => {
      try {
        const response = await fetch("/api/routes");
        if (!response.ok) throw new Error("Failed to fetch routes");
        const data = await response.json();
        setRoutes(data);
        setLoading(false);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
        setLoading(false);
      }
    };

    fetchRoutes();
  }, []);

  // Handle form input changes
  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  // Handle form submission
  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const response = await fetch("/api/routes", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          name: formData.name,
          stops: formData.stops.split(",").map(stop => stop.trim()),
          driver: formData.driver
        })
      });

      if (!response.ok) throw new Error("Failed to add route");

      // Refresh routes
      const updatedResponse = await fetch("/api/routes");
      const updatedData = await updatedResponse.json();
      setRoutes(updatedData);

      // Reset form
      setFormData({ name: "", stops: "", driver: "" });
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  // Handle update
  const handleUpdate = async (e: React.FormEvent) => {
    e.preventDefault();
    if (editingId === null) return;

    try {
      const response = await fetch(`/api/routes/${editingId}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          name: formData.name,
          stops: formData.stops.split(",").map(stop => stop.trim()),
          driver: formData.driver
        })
      });

      if (!response.ok) throw new Error("Failed to update route");

      // Refresh routes
      const updatedResponse = await fetch("/api/routes");
      const updatedData = await updatedResponse.json();
      setRoutes(updatedData);

      // Reset form
      setEditingId(null);
      setFormData({ name: "", stops: "", driver: "" });
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  // Handle delete
  const handleDelete = async (id: number) => {
    try {
      const response = await fetch(`/api/routes/${id}`, {
        method: "DELETE"
      });

      if (!response.ok) throw new Error("Failed to delete route");

      // Refresh routes
      const updatedResponse = await fetch("/api/routes");
      const updatedData = await updatedResponse.json();
      setRoutes(updatedData);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  // Set form data for editing
  const startEditing = (route: Route) => {
    setEditingId(route.id);
    setFormData({
      name: route.name,
      stops: route.stops.join(", "),
      driver: route.driver
    });
  };

  // Cancel editing
  const cancelEditing = () => {
    setEditingId(null);
    setFormData({ name: "", stops: "", driver: "" });
  };

  // Styles
  const containerStyle: React.CSSProperties = {
    maxWidth: "800px",
    margin: "0 auto",
    padding: "20px",
    fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif"
  };

  const formStyle: React.CSSProperties = {
    marginBottom: "20px",
    display: "flex",
    flexDirection: "column",
    gap: "10px"
  };

  const inputStyle: React.CSSProperties = {
    padding: "10px",
    borderRadius: "4px",
    border: "1px solid #ccc",
    width: "100%",
    boxSizing: "border-box"
  };

  const buttonStyle: React.CSSProperties = {
    padding: "10px 15px",
    borderRadius: "4px",
    border: "none",
    backgroundColor: "#007bff",
    color: "white",
    cursor: "pointer"
  };

  const cancelButtonStyle: React.CSSProperties = {
    ...buttonStyle,
    backgroundColor: "#6c757d"
  };

  const routesContainerStyle: React.CSSProperties = {
    display: "flex",
    flexWrap: "wrap",
    gap: "15px"
  };

  const routeCardStyle: React.CSSProperties = {
    border: "1px solid #ddd",
    borderRadius: "8px",
    padding: "15px",
    width: "100%",
    boxSizing: "border-box",
    backgroundColor: "#f9f9f9"
  };

  const buttonGroupStyle: React.CSSProperties = {
    display: "flex",
    gap: "10px",
    marginTop: "10px"
  };

  if (loading) return <div style={containerStyle}>Loading...</div>;
  if (error) return <div style={containerStyle}>Error: {error}</div>;

  return (
    <div style={containerStyle}>
      <h1>Bus Routes Management</h1>

      <form onSubmit={editingId ? handleUpdate : handleSubmit} style={formStyle}>
        <input
          type="text"
          name="name"
          placeholder="Route Name"
          value={formData.name}
          onChange={handleChange}
          style={inputStyle}
        />
        <textarea
          name="stops"
          placeholder="Stops (comma separated)"
          value={formData.stops}
          onChange={handleChange}
          style={inputStyle}
        />
        <input
          type="text"
          name="driver"
          placeholder="Driver Name"
          value={formData.driver}
          onChange={handleChange}
          style={inputStyle}
        />
        <div>
          <button type="submit" style={buttonStyle}>
            {editingId ? "Update Route" : "Add Route"}
          </button>
          {editingId && (
            <button type="button" onClick={cancelEditing} style={cancelButtonStyle}>
              Cancel
