            <div key={route.id} style={routeCardStyle}>
              <h3>{route.name}</h3>
              <p><strong>Stops:</strong> {route.stops.join(", ")}</p>
              <p><strong>Driver:</strong> {route.driver}</p>
              <div style={buttonGroupStyle}>
                <button onClick={() => startEditing(route)} style={buttonStyle}>Edit</button>
                <button onClick={() => handleDelete(route.id)} style={cancelButtonStyle}>Delete</button>
              </div>
            </div>
          ))
        )}
      </div>
    </div>
  );
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

const JWT_SECRET = process.env.JWT_SECRET;

function verifyToken(token: string): boolean {
  if (!JWT_SECRET) return false;

  // Simple JWT structure validation
  const parts = token.split(".");
  if (parts.length !== 3) return false;

  const [header, payload, signature] = parts;

  // Create expected signature
  const expectedSignature = createHmac("sha256", JWT_SECRET)
    .update(`${header}.${payload}`)
    .digest("base64url");

  // Use timingSafeEqual to prevent timing attacks
  try {
    const expectedBuffer = Buffer.from(expectedSignature, "base64url");
    const actualBuffer = Buffer.from(signature, "base64url");
    return timingSafeEqual(expectedBuffer, actualBuffer);
  } catch {
    return false;
  }
}

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only protect POST, PUT, DELETE requests to admin routes
  if (!(req.method === "POST" || req.method === "PUT" || req.method === "DELETE") || 
      !req.path.startsWith("/admin")) {
    return next();
  }

  // Check for authorization header
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    return res.status(401).json({ error: "Unauthorized" });
  }

  const token = authHeader.substring(7); // Remove "Bearer " prefix

  // Verify token signature
  if (!verifyToken(token)) {
    return res.status(401).json({ error: "Invalid token" });
  }

  // In a real implementation, we would decode the token here
  // and check if the user has admin role
  // For now, we'll assume valid tokens have admin access

  // Allow access for valid tokens
  return next();
}

