  lastName: string;
  dateOfBirth: string;
  gender: string;
  bloodType: string;
  phoneNumber: string;
  email: string;
  address: string;
  lastDonationDate: string | null;
  medicalHistory: string | null;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS donors (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    firstName TEXT NOT NULL,
    lastName TEXT NOT NULL,
    dateOfBirth TEXT NOT NULL,
    gender TEXT NOT NULL,
    bloodType TEXT NOT NULL,
    phoneNumber TEXT NOT NULL,
    email TEXT NOT NULL,
    address TEXT NOT NULL,
    lastDonationDate TEXT,
    medicalHistory TEXT
  )
`;

db.exec(createTableSql);

export function getAllDonors(): Donor[] {
  const stmt = db.prepare("SELECT * FROM donors");
  return stmt.all() as unknown as Donor[];
}

export function getDonorById(id: number): Donor | undefined {
  const stmt = db.prepare("SELECT * FROM donors WHERE id = ?");
  return stmt.get(id) as unknown as Donor | undefined;
}

export function insertDonor(donor: Omit<Donor, "id">): number {
  const stmt = db.prepare(
    "INSERT INTO donors (firstName, lastName, dateOfBirth, gender, bloodType, phoneNumber, email, address, lastDonationDate, medicalHistory) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)"
  );
  const result = stmt.run(
    donor.firstName,
    donor.lastName,
    donor.dateOfBirth,
    donor.gender,
    donor.bloodType,
    donor.phoneNumber,
    donor.email,
    donor.address,
    donor.lastDonationDate,
    donor.medicalHistory
  );
  return Number(result.lastInsertRowid);
}

export function updateDonor(id: number, donor: Partial<Donor>): boolean {
  const fields = [];
  const values = [];

  if (donor.firstName !== undefined) {
    fields.push("firstName = ?");
    values.push(donor.firstName);
  }

  if (donor.lastName !== undefined) {
    fields.push("lastName = ?");
    values.push(donor.lastName);
  }

  if (donor.dateOfBirth !== undefined) {
    fields.push("dateOfBirth = ?");
    values.push(donor.dateOfBirth);
  }

  if (donor.gender !== undefined) {
    fields.push("gender = ?");
    values.push(donor.gender);
  }

  if (donor.bloodType !== undefined) {
    fields.push("bloodType = ?");
    values.push(donor.bloodType);
  }

  if (donor.phoneNumber !== undefined) {
    fields.push("phoneNumber = ?");
    values.push(donor.phoneNumber);
  }

  if (donor.email !== undefined) {
    fields.push("email = ?");
    values.push(donor.email);
  }

  if (donor.address !== undefined) {
    fields.push("address = ?");
    values.push(donor.address);
  }

  if (donor.lastDonationDate !== undefined) {
    fields.push("lastDonationDate = ?");
    values.push(donor.lastDonationDate);
  }

  if (donor.medicalHistory !== undefined) {
    fields.push("medicalHistory = ?");
    values.push(donor.medicalHistory);
  }

  if (fields.length === 0) {
    return false;
  }

  values.push(id);

  const sql = `UPDATE donors SET ${fields.join(", ")} WHERE id = ?`;
  const stmt = db.prepare(sql);
  stmt.run(...values);

  return true;
}

export function deleteDonor(id: number): boolean {
  const stmt = db.prepare("DELETE FROM donors WHERE id = ?");
  const result = stmt.run(id);
  return result.changes > 0;
}

