import { Router, type Request, type Response } from "express";
import { 
  getAllDonors,
  getDonorById,
  insertDonor,
  updateDonor,
  deleteDonor
} from "../db/donors-table";

export const router = Router();

// GET /donors - Get all donors
router.get("/donors", (req: Request, res: Response) => {
  try {
    const donors = getAllDonors();
    res.json(donors);
  } catch (error) {
    res.status(500).json({ error: "Internal server error" });
  }
});

// GET /donors/:id - Get a donor by ID
router.get("/donors/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid donor ID" });
    }

    const donor = getDonorById(id);
    if (!donor) {
      return res.status(404).json({ error: "Donor not found" });
    }

    res.json(donor);
  } catch (error) {
    res.status(500).json({ error: "Internal server error" });
  }
});

// POST /donors - Create a new donor
router.post("/donors", (req: Request, res: Response) => {
  try {
    const { 
      firstName, 
      lastName, 
      email, 
      phone, 
      address, 
      bloodType, 
      dateOfBirth 
    } = req.body;

    if (!firstName || !lastName || !email || !phone || !address || !bloodType || !dateOfBirth) {
      return res.status(400).json({ error: "Missing required fields" });
    }

    const newDonor = {
      firstName,
      lastName,
      email,
      phone,
      address,
      bloodType,
      dateOfBirth
    };

    const donorId = insertDonor(newDonor);

    res.status(201).json({ id: donorId, ...newDonor });
  } catch (error) {
    res.status(500).json({ error: "Internal server error" });
  }
});

// PUT /donors/:id - Update a donor
router.put("/donors/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid donor ID" });
    }

    const donor = getDonorById(id);
    if (!donor) {
      return res.status(404).json({ error: "Donor not found" });
    }

    const { 
      firstName, 
      lastName, 
      email, 
      phone, 
      address, 
      bloodType, 
      dateOfBirth 
    } = req.body;

    const updatedDonor = {
      firstName: firstName ?? donor.firstName,
      lastName: lastName ?? donor.lastName,
      email: email ?? donor.email,
      phone: phone ?? donor.phone,
      address: address ?? donor.address,
      bloodType: bloodType ?? donor.bloodType,
      dateOfBirth: dateOfBirth ?? donor.dateOfBirth
    };

    const success = updateDonor(id, updatedDonor);

    if (!success) {
      return res.status(500).json({ error: "Failed to update donor" });
    }

    res.json({ id, ...updatedDonor });
  } catch (error) {
    res.status(500).json({ error: "Internal server error" });
  }
});

