import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply role-based access control to protected routes
  const protectedPaths = ["/donors", "/admin"];
  const isProtectedPath = protectedPaths.some(path =>
    req.path.startsWith(path)
  );

  // Skip validation for non-protected paths
  if (!isProtectedPath) {
    next();
    return;
  }

  // Check if user has required role
  const userRole = req.headers["x-user-role"] as string | undefined;

  // For admin routes, require admin role
  if (req.path.startsWith("/admin") && userRole !== "admin") {
    res.status(403).json({ error: "Access denied: Admin role required" });
    return;
  }

  // For donor routes, require either donor or admin role
  if (req.path.startsWith("/donors") && userRole !== "donor" && userRole !== "admin") {
    res.status(403).json({ error: "Access denied: Donor or Admin role required" });
    return;
  }

  // If we reach here, user has appropriate role
  next();
}

