import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

const SESSION_TIMEOUT = 30 * 60 * 1000; // 30 minutes
const JWT_SECRET = process.env.JWT_SECRET;

// Helper to check if a path should be protected
function shouldProtectPath(path: string): boolean {
  // Only protect API routes, not static assets or health checks
  return path.startsWith("/api/") && !path.includes("health");
}

// Helper to extract token from Authorization header
function extractToken(req: Request): string | null {
  const authHeader = req.header("Authorization");
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    return null;
  }
  return authHeader.substring(7); // Remove "Bearer " prefix
}

// Helper to verify JWT signature
function verifyTokenSignature(token: string): boolean {
  if (!JWT_SECRET) {
    return false;
  }

  try {
    const [header, payload, signature] = token.split(".");
    if (!header || !payload || !signature) {
      return false;
    }

    const expectedSignature = createHmac("sha256", JWT_SECRET)
      .update(`${header}.${payload}`)
      .digest("base64url");

    const signatureBuffer = Buffer.from(signature, "base64url");
    const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");

    return timingSafeEqual(signatureBuffer, expectedSignatureBuffer);
  } catch {
    return false;
  }
}

// Helper to parse JWT payload
function parsePayload(payload: string): Record<string, unknown> | null {
  try {
    const decoded = Buffer.from(payload, "base64url").toString("utf8");
    return JSON.parse(decoded);
  } catch {
    return null;
  }
}

// Helper to check if token has expired
function isTokenExpired(payload: Record<string, unknown>): boolean {
  const exp = payload.exp as number | undefined;
  if (typeof exp !== "number") {
    return true;
  }
  return Date.now() >= exp * 1000;
}

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Skip session management for non-API routes or health checks
  if (!shouldProtectPath(req.path)) {
    next();
    return;
  }

  const token = extractToken(req);
  if (!token) {
    res.status(401).json({ error: "Unauthorized: Missing token" });
    return;
  }

  // Verify token signature
  if (!verifyTokenSignature(token)) {
    res.status(401).json({ error: "Unauthorized: Invalid token" });
    return;
  }

  // Parse payload
  const [_, payloadStr] = token.split(".");
  const payload = parsePayload(payloadStr);
  if (!payload) {
    res.status(401).json({ error: "Unauthorized: Invalid token payload" });
    return;
  }

  // Check expiration
  if (isTokenExpired(payload)) {
    res.status(401).json({ error: "Unauthorized: Token expired" });
    return;
  }

  // Token is valid, attach user info to request
  (req as any).user = payload;

  next();
}

import { useEffect, useState } from "react";

interface Donor {
  id: number;
  firstName: string;
  lastName: string;
  email: string;
  phone: string;
  bloodType: string;
  lastDonationDate?: string;
}

interface Donation {
  id: number;
  donorId: number;
  donationDate: string;
  units: number;
}

export function DonorManagementPage() {
  const [donors, setDonors] = useState<Donor[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState("");
  const [showForm, setShowForm] = useState(false);
  const [editingDonor, setEditingDonor] = useState<Donor | null>(null);

  // Form state
  const [formData, setFormData] = useState({
    firstName: "",
    lastName: "",
    email: "",
    phone: "",
    bloodType: "",
  });

  useEffect(() => {
    fetchDonors();
  }, []);

  const fetchDonors = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/donor-api/donors");
      if (!response.ok) throw new Error("Failed to fetch donors");
      const data = await response.json();
      setDonors(data);
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleSearch = (e: React.ChangeEvent<HTMLInputElement>) => {
    setSearchTerm(e.target.value);
  };

  const filteredDonors = donors.filter(donor =>
    donor.firstName.toLowerCase().includes(searchTerm.toLowerCase()) ||
    donor.lastName.toLowerCase().includes(searchTerm.toLowerCase()) ||
    donor.email.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    try {
      const response = editingDonor
        ? await fetch(`/api/donor-api/donors/${editingDonor.id}`, {
            method: "PUT",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify(formData),
          })
        : await fetch("/api/donor-api/donors", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify(formData),
          });

      if (!response.ok) throw new Error("Failed to save donor");

      // Reset form
      setFormData({
        firstName: "",
        lastName: "",
        email: "",
        phone: "",
        bloodType: "",
      });

      setShowForm(false);
      setEditingDonor(null);
      await fetchDonors();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleEdit = (donor: Donor) => {
    setEditingDonor(donor);
    setFormData({
      firstName: donor.firstName,
      lastName: donor.lastName,
      email: donor.email,
      phone: donor.phone,
      bloodType: donor.bloodType,
    });
    setShowForm(true);
  };

  const handleDelete = async (id: number) => {
    try {
      const response = await fetch(`/api/donor-api/donors/${id}`, {
        method: "DELETE",
      });
      if (!response.ok) throw new Error("Failed to delete donor");
      await fetchDonors();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleCancel = () => {
    setShowForm(false);
    setEditingDonor(null);
    setFormData({
      firstName: "",
      lastName: "",
      email: "",
      phone: "",
      bloodType: "",
    });
  };

  if (loading) return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;

  return (
    <div style={containerStyle}>
      <h1 style={{ textAlign: "center", marginBottom: "20px" }}>Donor Management</h1>

      <div style={{ marginBottom: "20px", display: "flex", gap: "10px" }}>
        <input
          type="text"
          placeholder="Search donors..."
          value={searchTerm}
          onChange={handleSearch}
          style={{ flex: 1, padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
        />
        <button 
          onClick={() => {
            setShowForm(true);
            setEditingDonor(null);
            setFormData({
              firstName: "",
              lastName: "",
              email: "",
              phone: "",
              bloodType: "",
            });
          }}
          style={{ padding: "8px 16px", backgroundColor: "#007bff", color: "white", border: "none", borderRadius: "4px", cursor: "pointer" }}
        >
          Add New Donor
        </button>
      </div>

      {error && <div style={{ color: "red", marginBottom: "20px" }}>{error}</div>}

      {showForm ? (
        <form onSubmit={handleSubmit} style={{ marginBottom: "20px", padding: "15px", border: "1px solid #ddd", borderRadius: "4px" }}>
          <h3>{editingDonor ? "Edit Donor" : "Add New Donor"}</h3>
          <div style={{ marginBottom: "10px" }}>
            <input
              type="text"
              placeholder="First Name"
              value={formData.firstName}
              onChange={(e) => setFormData({...formData, firstName: e.target.value})}
              style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
              required
            />
          </div>
          <div style={{ marginBottom: "10px" }}>
            <input
              type="text"
              placeholder="Last Name"
              value={formData.lastName}
              onChange={(e) => setFormData({...formData, lastName: e.target.value})}
              style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
              required
            />
          </div>
          <div style={{ marginBottom: "10px" }}>
            <input
              type="email"
              placeholder="Email"
              value={formData.email}
              onChange={(e) => setFormData({...formData, email: e.target.value})}
              style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
              required
            />
          </div>
          <div style={{ marginBottom: "10px" }}>
            <input
              type="text"
              placeholder="Phone"
              value={formData.phone}
              onChange={(e) => setFormData({...formData, phone: e.target.value})}
              style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
              required
            />
          </div>
          <div style={{ marginBottom: "10px" }}>
            <select
              value={formData.bloodType}
              onChange={(e) => setFormData({...formData, bloodType: e.target.value})}
              style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
              required
            >
              <option value="">Select Blood Type</option>
              <option value="A+">A+</option>
              <option value="A-">A-</option>
              <option value="B+">B+</option>
              <option value="B-">B-</option>
              <option value="AB+">AB+</option>
              <option value="AB-">AB-</option>
              <option value="O+">O+</option>
              <option value="O-">O-</option>
            </select>
          </div>
          <div style={{ display: "flex", gap: "10px" }}>
            <button 
              type="submit" 
              style={{ padding: "8px 16px", backgroundColor: "#28a745", color: "white", border: "none", borderRadius: "4px", cursor: "pointer" }}
            >
              Save
            </button>
            <button 
              type="button" 
              onClick={handleCancel}
              style={{ padding: "8px 16px", backgroundColor: "#6c757d", color: "white", border: "none", borderRadius: "4px", cursor: "pointer" }}
            >
              Cancel
            </button>
          </div>
        </form>
      ) : null}

      {filteredDonors.length === 0 ? (
        <p style={{ textAlign: "center", padding: "20px" }}>No donors found.</p>
      ) : (
        <div style={{ display: "flex", flexWrap: "wrap", gap: "15px" }}>
          {filteredDonors.map(donor => (
            <div key={donor.id} style={{
              border: "1px solid #ddd",
              borderRadius: "4px",
              padding: "15px",
              width: "100%",
              maxWidth: "300px",
              boxSizing: "border-box"
            }}>
              <h3>{donor.firstName} {donor.lastName}</h3>
              <p>Email: {donor.email}</p>
              <p>Phone: {donor.phone}</p>
              <p>Blood Type: {donor.bloodType}</p>
              {donor.lastDonationDate && (
                <p>Last Donation: {new Date(donor.lastDonationDate).toLocaleDateString()}</p>
              )}
              <div style={{ marginTop: "10px", display: "flex", gap: "5px" }}>
                <button 
                  onClick={() => handleEdit(donor)}
                  style={{ padding: "4px 8px", backgroundColor: "#17a2b8", color: "white", border: "none", borderRadius: "4px", cursor: "pointer" }}
                >
                  Edit
                </button>
                <button 
                  onClick={() => handleDelete(donor.id)}
                  style={{ padding: "4px 8px", backgroundColor: "#dc3545", color: "white", border: "none", borderRadius: "4px", cursor: "pointer" }}
                >
                  Delete
                </button>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

