  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const fetchDonationsAndDonors = async () => {
      try {
        const [donationsResponse, donorsResponse] = await Promise.all([
          fetch("/api/donation-api/"),
          fetch("/api/donor-api/donors")
        ]);

        if (!donationsResponse.ok || !donorsResponse.ok) {
          throw new Error("Failed to fetch data");
        }

        const donationsData = await donationsResponse.json();
        const donorsData = await donorsResponse.json();

        setDonations(donationsData);
        setDonors(donorsData);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
      } finally {
        setLoading(false);
      }
    };

    fetchDonationsAndDonors();
  }, []);

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
