          <div 
            key={donation.id} 
            style={{ 
              border: "1px solid #ccc", 
              borderRadius: "8px", 
              padding: "15px", 
              backgroundColor: "#f9f9f9"
            }}
          >
            <div style={{ display: "flex", justifyContent: "space-between", marginBottom: "10px" }}>
              <strong>{getDonorName(donation.donorId)}</strong>
