import { useEffect, useState } from "react";

interface BloodInventory {
  id: string;
  bloodType: string;
  quantity: number;
  expirationDate: string;
}

export function InventoryDashboard() {
  const [inventory, setInventory] = useState<BloodInventory[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchInventory();
  }, []);

  const fetchInventory = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/inventory-api/");
      if (!response.ok) {
        throw new Error(`Failed to fetch inventory: ${response.status}`);
      }
      const data = await response.json();
      setInventory(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return (
      <div style={{ textAlign: "center", padding: "20px", color: "red" }}>
        Error: {error}
      </div>
    );
  }

  if (inventory.length === 0) {
    return (
      <div style={{ textAlign: "center", padding: "20px" }}>
        No blood inventory found.
      </div>
    );
  }

  // Group inventory by blood type
  const groupedByType = inventory.reduce((acc, item) => {
    if (!acc[item.bloodType]) {
      acc[item.bloodType] = [];
    }
    acc[item.bloodType].push(item);
    return acc;
  }, {} as Record<string, BloodInventory[]>);

  return (
    <div
      style={{
        maxWidth: "800px",
        margin: "0 auto",
        padding: "20px",
        fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif",
      }}
    >
      <h1 style={{ textAlign: "center" }}>Blood Inventory Dashboard</h1>
      <div style={{ display: "flex", flexDirection: "column", gap: "20px" }}>
        {Object.entries(groupedByType).map(([type, items]) => (
          <div key={type} style={{ border: "1px solid #ccc", borderRadius: "8px", padding: "15px" }}>
            <h2 style={{ margin: "0 0 10px 0", color: "#333" }}>{type}</h2>
            <div style={{ display: "flex", flexWrap: "wrap", gap: "10px" }}>
              {items.map((item) => (
                <div
                  key={item.id}
                  style={{
                    border: "1px solid #eee",
                    borderRadius: "6px",
                    padding: "10px",
                    minWidth: "150px",
                    flex: "1 1 200px",
                  }}
                >
                  <p style={{ margin: "5px 0" }}>
                    <strong>Quantity:</strong> {item.quantity}
                  </p>
                  <p style={{ margin: "5px 0" }}>
                    <strong>Expires:</strong> {new Date(item.expirationDate).toLocaleDateString()}
                  </p>
                </div>
              ))}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

