import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync("./delivery-dashboard.db");

interface UserRow {
  id: number;
  username: string;
  password_hash: string;
  email: string;
  role: string;
  permissions: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS users (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    username TEXT UNIQUE NOT NULL,
    password_hash TEXT NOT NULL,
    email TEXT UNIQUE NOT NULL,
    role TEXT NOT NULL,
    permissions TEXT NOT NULL
  )
`;

db.exec(createTableSql);

export function getAllUsers(): UserRow[] {
  const stmt = db.prepare("SELECT * FROM users");
  return stmt.all() as unknown as UserRow[];
}

export function getUserById(id: number): UserRow | undefined {
  const stmt = db.prepare("SELECT * FROM users WHERE id = ?");
  return stmt.get(id) as unknown as UserRow | undefined;
}

export function insertUser(
  username: string,
  passwordHash: string,
  email: string,
  role: string,
  permissions: string
): number {
  const stmt = db.prepare(
    "INSERT INTO users (username, password_hash, email, role, permissions) VALUES (?, ?, ?, ?, ?)"
  );
  const result = stmt.run(username, passwordHash, email, role, permissions);
  return Number(result.lastInsertRowid);
}

export function updateUser(
  id: number,
  username: string,
  passwordHash: string,
  email: string,
  role: string,
  permissions: string
): void {
  const stmt = db.prepare(
    "UPDATE users SET username = ?, password_hash = ?, email = ?, role = ?, permissions = ? WHERE id = ?"
  );
  stmt.run(username, passwordHash, email, role, permissions, id);
}

export function deleteUser(id: number): void {
  const stmt = db.prepare("DELETE FROM users WHERE id = ?");
  stmt.run(id);
}

