    const { orderId, status, estimatedDeliveryDate, actualDeliveryDate, driverId } = req.body;

    // Validate required fields
    if (!orderId || !status || !estimatedDeliveryDate || !driverId) {
      return res.status(400).json({ error: "Missing required fields: orderId, status, estimatedDeliveryDate, driverId" });
