      orderId,
      status,
      estimatedDeliveryDate,
      actualDeliveryDate,
      driverId
    };

    const id = insertDelivery(newDelivery);
    res.status(201).json({ ...newDelivery, id });
  } catch (error) {
    res.status(500).json({ error: "Failed to create delivery" });
  }
});

