import { useEffect, useState } from "react";

interface Delivery {
  id: string;
  trackingNumber: string;
  status: string;
  deliveryDetails: string;
  updatedAt: string;
}

interface User {
  id: string;
  name: string;
}

export function DeliveryTracking() {
  const [deliveries, setDeliveries] = useState<Delivery[]>([]);
  const [users, setUsers] = useState<User[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const [newDelivery, setNewDelivery] = useState({
    trackingNumber: "",
    status: "",
    deliveryDetails: ""
  });

  const [editingId, setEditingId] = useState<string | null>(null);
  const [editForm, setEditForm] = useState({
    trackingNumber: "",
    status: "",
    deliveryDetails: ""
  });

  useEffect(() => {
    fetchDeliveries();
    fetchUsers();
  }, []);

  const fetchDeliveries = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/delivery-management-api/deliveries");
      if (!response.ok) throw new Error("Failed to fetch deliveries");
      const data = await response.json();
      setDeliveries(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const fetchUsers = async () => {
    try {
      const response = await fetch("/api/authentication-service/users");
      if (!response.ok) throw new Error("Failed to fetch users");
      const data = await response.json();
      setUsers(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleCreate = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const response = await fetch("/api/delivery-management-api/deliveries", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(newDelivery)
      });
      if (!response.ok) throw new Error("Failed to create delivery");
      await fetchDeliveries();
      setNewDelivery({ trackingNumber: "", status: "", deliveryDetails: "" });
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleUpdate = async (id: string) => {
    try {
      const response = await fetch(`/api/delivery-management-api/deliveries/${id}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(editForm)
      });
      if (!response.ok) throw new Error("Failed to update delivery");
      await fetchDeliveries();
      setEditingId(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleDelete = async (id: string) => {
    try {
      const response = await fetch(`/api/delivery-management-api/deliveries/${id}`, {
        method: "DELETE"
      });
      if (!response.ok) throw new Error("Failed to delete delivery");
      await fetchDeliveries();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  if (error) return <div style={{ color: "red", textAlign: "center", padding: "20px" }}>{error}</div>;

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Delivery Tracking</h1>

      <div style={{ marginBottom: "30px", padding: "20px", backgroundColor: "#f5f5f5", borderRadius: "8px" }}>
        <h2>Create New Delivery</h2>
        <form onSubmit={handleCreate}>
          <div style={{ marginBottom: "10px" }}>
            <input
              type="text"
              placeholder="Tracking Number"
              value={newDelivery.trackingNumber}
              onChange={(e) => setNewDelivery({...newDelivery, trackingNumber: e.target.value})}
              style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
            />
          </div>
          <div style={{ marginBottom: "10px" }}>
            <input
              type="text"
              placeholder="Status"
              value={newDelivery.status}
              onChange={(e) => setNewDelivery({...newDelivery, status: e.target.value})}
              style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
            />
          </div>
          <div style={{ marginBottom: "10px" }}>
            <textarea
              placeholder="Delivery Details"
              value={newDelivery.deliveryDetails}
              onChange={(e) => setNewDelivery({...newDelivery, deliveryDetails: e.target.value})}
              style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc", boxSizing: "border-box" }}
            />
          </div>
          <button type="submit" style={{ backgroundColor: "#007bff", color: "white", border: "none", padding: "10px 20px", borderRadius: "4px", cursor: "pointer" }}>Add Delivery</button>
        </form>
      </div>

      <h2>Current Deliveries</h2>
      {deliveries.length === 0 ? (
        <p style={{ textAlign: "center", padding: "20px" }}>No deliveries found.</p>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: "15px" }}>
          {deliveries.map((delivery) => (
            <div key={delivery.id} style={{ border: "1px solid #ddd", borderRadius: "8px", padding: "15px" }}>
              {editingId === delivery.id ? (
                <div>
                  <input
                    type="text"
                    value={editForm.trackingNumber}
                    onChange={(e) => setEditForm({...editForm, trackingNumber: e.target.value})}
                    style={{ width: "100%", marginBottom: "10px", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
                  />
                  <input
                    type="text"
                    value={editForm.status}
                    onChange={(e) => setEditForm({...editForm, status: e.target.value})}
                    style={{ width: "100%", marginBottom: "10px", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
                  />
                  <textarea
                    value={editForm.deliveryDetails}
                    onChange={(e) => setEditForm({...editForm, deliveryDetails: e.target.value})}
                    style={{ width: "100%", marginBottom: "10px", padding: "8px", borderRadius: "4px", border: "1px solid #ccc", boxSizing: "border-box" }}
                  />
                  <div style={{ display: "flex", gap: "10px" }}>
                    <button onClick={() => handleUpdate(delivery.id)} style={{ backgroundColor: "#28a745", color: "white", border: "none", padding: "8px 12px", borderRadius: "4px", cursor: "pointer" }}>Save</button>
                    <button onClick={() => setEditingId(null)} style={{ backgroundColor: "#6c757d", color: "white", border: "none", padding: "8px 12px", borderRadius: "4px", cursor: "pointer" }}>Cancel</button>
                  </div>
                </div>
              ) : (
                <div>
                  <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                    <div>
                      <h3>{delivery.trackingNumber}</h3>
                      <p><strong>Status:</strong> {delivery.status}</p>
                      <p><strong>Details:</strong> {delivery.deliveryDetails}</p>
                      <p><strong>Last Updated:</strong> {new Date(delivery.updatedAt).toLocaleString()}</p>
                    </div>
                    <div style={{ display: "flex", gap: "5px" }}>
                      <button onClick={() => {
                        setEditingId(delivery.id);
                        setEditForm({
                          trackingNumber: delivery.trackingNumber,
                          status: delivery.status,
                          deliveryDetails: delivery.deliveryDetails
                        });
                      }} style={{ backgroundColor: "#17a2b8", color: "white", border: "none", padding: "6px 10px", borderRadius: "4px", cursor: "pointer" }}>Edit</button>
                      <button onClick={() => handleDelete(delivery.id)} style={{ backgroundColor: "#dc3545", color: "white", border: "none", padding: "6px 10px", borderRadius: "4px", cursor: "pointer" }}>Delete</button>
                    </div>
                  </div>
                </div>
              )}
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

