import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";
import { router as deliveryManagementRouter } from "../routes/delivery-management-api";
import { router as authServiceRouter } from "../routes/authentication-service";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Skip validation for non-protected routes
  const isDeliveryRoute = req.path.startsWith("/delivery") || req.path.startsWith("/admin");
  const isAuthRoute = req.path.startsWith("/auth");

  if (!isDeliveryRoute && !isAuthRoute) {
    next();
    return;
  }

  // Check for authorization header
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized: Missing or invalid token" });
    return;
  }

  const token = authHeader.substring(7);

  // Validate token signature
  const secret = process.env.JWT_SECRET;
  if (!secret) {
    res.status(500).json({ error: "Server configuration error: JWT_SECRET not set" });
    return;
  }

  const [payload, signature] = token.split(".");
  if (!payload || !signature) {
    res.status(401).json({ error: "Unauthorized: Invalid token format" });
    return;
  }

  // Recreate signature for verification
  const expectedSignature = createHmac("sha256", secret)
    .update(payload)
    .digest("base64url");

  // Use timingSafeEqual to prevent timing attacks
  const expectedBuffer = Buffer.from(expectedSignature);
  const actualBuffer = Buffer.from(signature);

  if (expectedBuffer.length !== actualBuffer.length || 
      !timingSafeEqual(expectedBuffer, actualBuffer)) {
    res.status(401).json({ error: "Unauthorized: Invalid token signature" });
    return;
  }

  // Decode payload (simplified for example)
  try {
    const decodedPayload = JSON.parse(Buffer.from(payload, "base64url").toString());
    const userRole = decodedPayload.role;

    // Define role-based access rules
    if (isDeliveryRoute) {
      // Only allow admin and dispatcher roles to access delivery routes
      if (userRole !== "admin" && userRole !== "dispatcher") {
        res.status(403).json({ error: "Forbidden: Insufficient permissions" });
        return;
      }
    }

    if (isAuthRoute) {
      // Only allow admin role to access auth routes
      if (userRole !== "admin") {
        res.status(403).json({ error: "Forbidden: Insufficient permissions" });
        return;
      }
    }

    // If we reach here, the user has proper permissions
    next();
  } catch (err) {
    res.status(401).json({ error: "Unauthorized: Invalid token payload" });
  }
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";
import { router as deliveryManagementRouter } from "../routes/delivery-management-api";
import { router as authenticationServiceRouter } from "../routes/authentication-service";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only protect POST requests to authentication routes
  if (!(req.method === "POST" && req.path.startsWith("/auth"))) {
    return next();
  }

  const jwtSecret = process.env.JWT_SECRET;

  if (!jwtSecret) {
    return res.status(500).json({ error: "Internal server error" });
  }

  const authHeader = req.headers.authorization;

  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    return res.status(401).json({ error: "Unauthorized" });
  }

  const token = authHeader.substring(7);

  try {
    // Simple token verification (in a real app, you'd decode and verify)
    const expectedSignature = createHmac("sha256", jwtSecret)
      .update(token.split(".")[0] + "." + token.split(".")[1])
      .digest();

    const actualSignature = Buffer.from(token.split(".")[2], "base64");

    if (actualSignature.length !== expectedSignature.length) {
      return res.status(401).json({ error: "Unauthorized" });
    }

    const isEqual = timingSafeEqual(expectedSignature, actualSignature);

    if (!isEqual) {
      return res.status(401).json({ error: "Unauthorized" });
