import type { Request, Response, NextFunction } from "express";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only validate POST, PUT, PATCH requests with a body
  if (!['POST', 'PUT', 'PATCH'].includes(req.method)) {
    return next();
  }

  // Skip validation for static asset routes
  if (req.path.startsWith('/static/') || req.path.startsWith('/assets/')) {
    return next();
  }

  // Validate body exists and is an object
  if (typeof req.body !== 'object' || req.body === null) {
    return res.status(400).json({ error: 'Invalid input: Body must be an object' });
  }

  // Validate all keys are strings
  const keys = Object.keys(req.body);
  for (const key of keys) {
    if (typeof key !== 'string') {
      return res.status(400).json({ error: 'Invalid input: Keys must be strings' });
    }
  }

  // Validate all values are strings, numbers, booleans, or null
  const values = Object.values(req.body);
  for (const value of values) {
    if (!(typeof value === 'string' || typeof value === 'number' || typeof value === 'boolean' || value === null)) {
      return res.status(400).json({ error: 'Invalid input: Values must be strings, numbers, booleans, or null' });
    }
  }

  next();
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

const rateLimitMap = new Map<string, { count: number; resetTime: number }>();
const RATE_LIMIT = 100;
const TIME_WINDOW = 15 * 60 * 1000; // 15 minutes

function isValidToken(token: string): boolean {
  const secret = process.env.JWT_SECRET;
  if (!secret) return false;

  try {
    const [header, payload, signature] = token.split(".");
    if (!header || !payload || !signature) return false;

    const expectedSignature = createHmac("sha256", secret)
      .update(`${header}.${payload}`)
      .digest("base64url");

    const signatureBuffer = Buffer.from(signature, "base64url");
    const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");

    return timingSafeEqual(signatureBuffer, expectedSignatureBuffer);
  } catch {
    return false;
  }
}

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Skip authentication and rate limiting for health check endpoint
  if (req.path === "/health" && req.method === "GET") {
    return next();
  }

  // Rate limiting
  const clientIP = req.ip || "unknown";
  const now = Date.now();
  const clientData = rateLimitMap.get(clientIP) || { count: 0, resetTime: now + TIME_WINDOW };

  if (now > clientData.resetTime) {
    clientData.count = 0;
    clientData.resetTime = now + TIME_WINDOW;
  }

  if (clientData.count >= RATE_LIMIT) {
    return res.status(429).json({ error: "Rate limit exceeded" });
  }

  clientData.count++;
  rateLimitMap.set(clientIP, clientData);

  // Token validation for protected routes
  if (
    req.path.startsWith("/api/") &&
    (req.method === "POST" ||
      req.method === "PUT" ||
      req.method === "DELETE")
  ) {
    const authHeader = req.headers.authorization;
    if (!authHeader || !authHeader.startsWith("Bearer ")) {
      return res.status(401).json({ error: "Missing or invalid authorization header" });
    }

    const token = authHeader.substring(7); // Remove "Bearer " prefix
    if (!isValidToken(token)) {
      return res.status(401).json({ error: "Invalid token" });
    }
  }

  next();
}

