export function AlumniProfilePage({
  alumniId
}: {
  alumniId: string;
}) {
  const [profile, setProfile] = useState<AlumniProfile | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const fetchProfile = async () => {
      try {
        const response = await fetch(`/api/alumni/${alumniId}`);
        if (!response.ok) {
          throw new Error(`Failed to fetch profile: ${response.status}`);
        }
        const data = await response.json();
        setProfile(data);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
      } finally {
        setLoading(false);
      }
    };

    fetchProfile();
  }, [alumniId]);

  if (loading) return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;

  if (error) return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;

  if (!profile) return <div style={{ textAlign: "center", padding: "20px" }}>No profile found</div>;

  const handleDelete = async () => {
    if (!window.confirm("Are you sure you want to delete this profile?")) return;

    try {
      const response = await fetch(`/api/alumni/${alumniId}`, {
        method: "DELETE"
      });

      if (!response.ok) {
        throw new Error(`Failed to delete profile: ${response.status}`);
      }

      // In a real app, we might redirect to a list page or show success message
      alert("Profile deleted successfully");
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center", marginBottom: "30px" }}>{profile.name}'s Profile</h1>

      <div style={{ marginBottom: "30px", padding: "20px", borderRadius: "8px", backgroundColor: "#f5f5f5" }}>
        <h2>Contact Information</h2>
        <p><strong>Email:</strong> {profile.email}</p>
        <p><strong>Phone:</strong> {profile.phone}</p>
        <p><strong>Location:</strong> {profile.location}</p>
      </div>

      <div style={{ marginBottom: "30px", padding: "20px", borderRadius: "8px", backgroundColor: "#f5f5f5" }}>
        <h2>Bio</h2>
        <p>{profile.bio}</p>
      </div>

      <div style={{ marginBottom: "30px", padding: "20px", borderRadius: "8px", backgroundColor: "#f5f5f5" }}>
        <h2>Career History</h2>
        {profile.careerHistory.length === 0 ? (
          <p>No career history available</p>
        ) : (
          <ul style={{ listStyle: "none", padding: 0 }}>
            {profile.careerHistory.map((job) => (
              <li key={job.id} style={{ marginBottom: "15px", padding: "10px", border: "1px solid #ddd", borderRadius: "4px" }}>
                <strong>{job.company}</strong> - {job.position}
                <br />
                {job.startDate} to {job.endDate}
              </li>
            ))}
          </ul>
        )}
      </div>

      <div style={{ marginBottom: "30px", padding: "20px", borderRadius: "8px", backgroundColor: "#f5f5f5" }}>
        <h2>Interests</h2>
        {profile.interests.length === 0 ? (
          <p>No interests listed</p>
        ) : (
          <div style={{ display: "flex", flexWrap: "wrap", gap: "10px" }}>
            {profile.interests.map((interest, index) => (
              <span key={index} style={{ backgroundColor: "#e0e0e0", padding: "5px 10px", borderRadius: "15px" }}>
                {interest}
              </span>
            ))}
          </div>
        )}
