import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check role-based access for POST, PUT, DELETE requests
  if (req.method !== "POST" && req.method !== "PUT" && req.method !== "DELETE") {
    next();
    return;
  }

  // For simplicity, we'll assume all requests go through this middleware
  // and we'll check the role from headers or session

  // Get the user role from the request (this could come from a JWT or session)
  const userRole = req.headers["x-user-role"] as string || "viewer";

  // Define allowed roles for different actions
  const allowedRoles: Record<string, string[]> = {
    "POST": ["admin", "staff"],
    "PUT": ["admin", "staff"],
    "DELETE": ["admin"]
  };

  // Check if the user has permission to perform the action
  const allowedRolesForMethod = allowedRoles[req.method] || [];

  if (!allowedRolesForMethod.includes(userRole)) {
    res.status(403).json({ error: "Forbidden: Insufficient permissions" });
    return;
  }

  next();
}

