const mockAlbums = [
  { id: "1", title: "Vacation 2023", description: "Beach photos" },
  { id: "2", title: "Family Reunion", description: "Birthday party" }
];

const findAlbumById = (id: string) => {
  return mockAlbums.find(album => album.id === id);
};

const createAlbum = (title: string, description: string) => {
  const newAlbum = {
    id: String(mockAlbums.length + 1),
    title,
    description
  };
  mockAlbums.push(newAlbum);
  return newAlbum;
};

const deleteAlbum = (id: string) => {
  const index = mockAlbums.findIndex(album => album.id === id);
  if (index !== -1) {
    mockAlbums.splice(index, 1);
    return true;
  }
  return false;
};

// GET /albums - List all albums
router.get("/albums", (req: Request, res: Response) => {
  res.json(mockAlbums);
});

// GET /albums/:id - Get one album by ID
router.get("/albums/:id", (req: Request, res: Response) => {
  const album = findAlbumById(req.params.id);
  if (!album) {
    return res.status(404).json({ error: "Album not found" });
  }
  res.json(album);
});

// POST /albums - Create a new album
router.post("/albums", (req: Request, res: Response) => {
  const { title, description } = req.body;

  if (!title || !description) {
    return res.status(400).json({ error: "Title and description are required" });
