import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only protect POST requests to /login endpoint
  if (!(req.method === "POST" && req.path === "/login")) {
    next();
    return;
  }

  // Check if JWT_SECRET is set
  const secret = process.env.JWT_SECRET;
  if (!secret) {
    res.status(500).json({ error: "Server configuration error" });
    return;
  }

  // Check if request has body with email and password
  if (!req.body || !req.body.email || !req.body.password) {
    res.status(400).json({ error: "Email and password required" });
    return;
  }

  // In a real implementation, we would verify credentials here
  // For now, we'll just simulate successful authentication
  // This is a placeholder - actual implementation would check user DB
  const expectedSignature = createHmac("sha256", secret)
    .update(`${req.body.email}:${req.body.password}`)
    .digest();

  // Simulate a valid token signature for demonstration purposes
  const validSignature = createHmac("sha256", secret)
    .update(`test@example.com:test123`)
    .digest();

  try {
    const isEqual = timingSafeEqual(expectedSignature, validSignature);
    if (!isEqual) {
      res.status(401).json({ error: "Invalid credentials" });
      return;
    }
  } catch {
    res.status(401).json({ error: "Invalid credentials" });
    return;
  }

  next();
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply role-based access control to specific routes
  const protectedPaths = ["/admin", "/api/admin"];
  const isProtectedPath = protectedPaths.some(path =>
    req.path.startsWith(path)
  );

  if (!isProtectedPath) {
    next();
    return;
  }

  // Check if user has admin role
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const token = authHeader.substring(7); // Remove "Bearer " prefix
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: "Server configuration error" });
    return;
  }

  // Simple token validation (in a real app, you'd decode and verify properly)
  const expectedToken = createHmac("sha256", secret)
    .update(req.method + req.path)
    .digest("hex");

  const tokenBuffer = Buffer.from(token);
  const expectedBuffer = Buffer.from(expectedToken);

  try {
    if (tokenBuffer.length !== expectedBuffer.length ||
        !timingSafeEqual(tokenBuffer, expectedBuffer)) {
      res.status(403).json({ error: "Forbidden" });
      return;
    }
  } catch (err) {
    res.status(403).json({ error: "Forbidden" });
    return;
  }

  next();
}

