import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply role-based access control to POST, PUT, DELETE requests
  if (!['POST', 'PUT', 'DELETE'].includes(req.method)) {
    next();
    return;
  }

  // Define allowed roles for different routes
  const roleMap: Record<string, string[]> = {
    '/api/stock': ['admin'],
    '/api/users': ['admin'],
    '/api/farm': ['admin', 'staff']
  };

  // Get the route path
  const path = req.path;

  // Find matching route pattern
  let matchedPath: string | undefined;
  for (const routePath in roleMap) {
    if (path.startsWith(routePath)) {
      matchedPath = routePath;
      break;
    }
  }

  // If no matching route found, allow access
  if (!matchedPath) {
    next();
    return;
  }

  // Get required roles for this route
  const requiredRoles = roleMap[matchedPath];

  // Check if user has valid role
  const userRole = req.headers['x-user-role'] as string | undefined;

  if (!userRole || !requiredRoles.includes(userRole)) {
    res.status(403).json({ error: 'Forbidden: Insufficient permissions' });
    return;
  }

  // If user has required role, proceed
  next();
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process POST requests to /login endpoint
  if (req.method !== "POST" || req.path !== "/login") {
    next();
    return;
  }

  const jwtSecret = process.env.JWT_SECRET;

  if (!jwtSecret) {
    res.status(500).json({ error: "Server configuration error" });
    return;
  }

  const authHeader = req.headers.authorization;

  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Missing or invalid authorization header" });
    return;
  }

  const token = authHeader.substring(7); // Remove 'Bearer '

  try {
    // Basic token structure validation
    const parts = token.split(".");
    if (parts.length !== 3) {
      res.status(401).json({ error: "Invalid token format" });
      return;
    }

    const [header, payload, signature] = parts;

    // Verify signature using HMAC-SHA256
    const expectedSignature = createHmac("sha256", jwtSecret)
      .update(`${header}.${payload}`)
      .digest("base64url");

    // Use timingSafeEqual to prevent timing attacks
    const signatureBuffer = Buffer.from(signature, "base64url");
    const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");

    if (!timingSafeEqual(signatureBuffer, expectedSignatureBuffer)) {
      res.status(401).json({ error: "Invalid token signature" });
      return;
    }

    // If we get here, the token is valid
    next();
  } catch (error) {
    res.status(401).json({ error: "Token verification failed" });
  }
}

import type { Request, Response, NextFunction } from "express";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only validate POST, PUT, PATCH requests that have a body
  if (!['POST', 'PUT', 'PATCH'].includes(req.method) || !req.body) {
    return next();
  }

  // Validate stock item fields
  if (req.path === '/stock') {
    const { name, quantity, price } = req.body;

    if (!name || typeof name !== 'string' || name.trim() === '') {
      return res.status(400).json({ error: 'Name is required and must be a non-empty string' });
    }

    if (quantity === undefined || quantity === null || isNaN(quantity) || quantity < 0) {
      return res.status(400).json({ error: 'Quantity must be a valid non-negative number' });
    }

    if (price === undefined || price === null || isNaN(price) || price < 0) {
      return res.status(400).json({ error: 'Price must be a valid non-negative number' });
    }
  }

  // Validate user fields
  if (req.path === '/users') {
    const { username, email } = req.body;

    if (!username || typeof username !== 'string' || username.trim() === '') {
      return res.status(400).json({ error: 'Username is required and must be a non-empty string' });
    }

    if (!email || typeof email !== 'string' || !email.includes('@')) {
      return res.status(400).json({ error: 'Email is required and must be a valid email address' });
    }
  }

  next();
}

