  breed: string;
  quantity: number;
  age: number;
  healthStatus: string;
  location: string;
}

export function StockEntryForm() {
  const [formData, setFormData] = useState<StockEntry>({
    breed: "",
    quantity: 0,
    age: 0,
    healthStatus: "healthy",
    location: "",
  });

  const [isSubmitting, setIsSubmitting] = useState(false);
  const [submitSuccess, setSubmitSuccess] = useState(false);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>) => {
    const { name, value } = e.target;
    setFormData({
      ...formData,
      [name]: name === "quantity" || name === "age" ? Number(value) : value,
    });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);
    setSubmitSuccess(false);

    try {
      // In a real app, this would make an API call
      // await fetch('/api/stock', { method: 'POST', body: JSON.stringify(formData) })

      // Simulate API call
      await new Promise(resolve => setTimeout(resolve, 500));

      setSubmitSuccess(true);
      setFormData({
        breed: "",
        quantity: 0,
        age: 0,
        healthStatus: "healthy",
        location: "",
      });
    } catch (error) {
      console.error("Failed to add stock entry", error);
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div style={{
      maxWidth: "600px",
      margin: "0 auto",
      padding: "20px",
      fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif",
    }}>
      <h1 style={{ textAlign: "center" }}>Add New Poultry Stock</h1>

      {submitSuccess && (
        <div style={{
          backgroundColor: "#d4edda",
          color: "#155724",
          padding: "15px",
          borderRadius: "5px",
          marginBottom: "20px",
        }}>
          Stock entry added successfully!
        </div>
      )}

      <form onSubmit={handleSubmit} style={{ display: "flex", flexDirection: "column", gap: "15px" }}>
        <div>
          <label htmlFor="breed" style={{ display: "block", marginBottom: "5px" }}>
            Breed *
          </label>
          <input
            type="text"
            id="breed"
            name="breed"
            value={formData.breed}
            onChange={handleChange}
            required
            style={{
              width: "100%",
              padding: "10px",
              borderRadius: "5px",
              border: "1px solid #ccc",
            }}
          />
        </div>

        <div>
          <label htmlFor="quantity" style={{ display: "block", marginBottom: "5px" }}>
            Quantity *
          </label>
          <input
            type="number"
            id="quantity"
            name="quantity"
            value={formData.quantity}
            onChange={handleChange}
            min="0"
            required
            style={{
              width: "100%",
              padding: "10px",
              borderRadius: "5px",
              border: "1px solid #ccc",
            }}
          />
        </div>

        <div>
          <label htmlFor="age" style={{ display: "block", marginBottom: "5px" }}>
            Age (weeks) *
          </label>
          <input
            type="number"
            id="age"
            name="age"
            value={formData.age}
            onChange={handleChange}
            min="0"
            required
            style={{
              width: "100%",
              padding: "10px",
              borderRadius: "5px",
              border: "1px solid #ccc",
            }}
          />
        </div>

        <div>
          <label htmlFor="healthStatus" style={{ display: "block", marginBottom: "5px" }}>
            Health Status *
          </label>
          <select
            id="healthStatus"
            name="healthStatus"
            value={formData.healthStatus}
            onChange={handleChange}
            required
            style={{
              width: "100%",
              padding: "10px",
              borderRadius: "5px",
              border: "1px solid #ccc",
            }}
          >
            <option value="healthy">Healthy</option>
            <option value="sick">Sick</option>
            <option value="recovering">Recovering</option>
          </select>
        </div>

        <div>
          <label htmlFor="location" style={{ display: "block", marginBottom: "5px" }}>
            Location *
          </label>
          <input
            type="text"
            id="location"
            name="location"
            value={formData.location}
            onChange={handleChange}
            required
            style={{
              width: "100%",
              padding: "10px",
              borderRadius: "5px",
              border: "1px solid #ccc",
            }}
          />
        </div>

        <button
          type="submit"
          disabled={isSubmitting}
          style={{
            backgroundColor: "#28a745",
            color: "white",
            padding: "12px 20px",
            border: "none",
            borderRadius: "5px",
            cursor: isSubmitting ? "not-allowed" : "pointer",
            fontSize: "16px",
            fontWeight: "bold",
          }}
        >
          {isSubmitting ? "Adding..." : "Add Stock Entry"}
        </button>
      </form>
    </div>
  );
}

