import type { Request, Response, NextFunction } from "express";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only validate POST, PUT, PATCH requests that have a body
  if (!['POST', 'PUT', 'PATCH'].includes(req.method) || !req.body) {
    return next();
  }

  // Validate stock item fields
  if (req.path === '/stock') {
    const { name, quantity, price } = req.body;

    if (!name || typeof name !== 'string' || name.trim() === '') {
      return res.status(400).json({ error: 'Name is required and must be a non-empty string' });
    }

    if (quantity === undefined || quantity === null || isNaN(quantity) || quantity < 0) {
      return res.status(400).json({ error: 'Quantity must be a valid non-negative number' });
    }

    if (price === undefined || price === null || isNaN(price) || price < 0) {
      return res.status(400).json({ error: 'Price must be a valid non-negative number' });
    }
  }

  // Validate user fields
  if (req.path === '/users') {
    const { username, email } = req.body;

    if (!username || typeof username !== 'string' || username.trim() === '') {
      return res.status(400).json({ error: 'Username is required and must be a non-empty string' });
    }

    if (!email || typeof email !== 'string' || !email.includes('@')) {
      return res.status(400).json({ error: 'Email is required and must be a valid email address' });
    }
  }

  next();
}

import { useEffect, useState } from "react";

interface Poultry {
  id: number;
  species: string;
  breed: string;
  quantity: number;
  lastFed: string;
}

const API_BASE_URL = "http://localhost:3000";

export function StockListPage() {
  const [poultryStock, setPoultryStock] = useState<Poultry[]>([]);
  const [filteredStock, setFilteredStock] = useState<Poultry[]>([]);
  const [searchTerm, setSearchTerm] = useState("");
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchStock();
  }, []);

  const fetchStock = async () => {
    try {
      const response = await fetch(`${API_BASE_URL}/poultry`);
      if (!response.ok) {
        throw new Error(`HTTP error! Status: ${response.status}`);
      }
      const data = await response.json();
      setPoultryStock(data);
      setFilteredStock(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    const filtered = poultryStock.filter(item =>
      item.species.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.breed.toLowerCase().includes(searchTerm.toLowerCase())
    );
    setFilteredStock(filtered);
  }, [searchTerm, poultryStock]);

  const handleSearchChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setSearchTerm(e.target.value);
  };

  const handleDelete = async (id: number) => {
    try {
      const response = await fetch(`${API_BASE_URL}/poultry/${id}`, {
        method: "DELETE",
      });
      if (!response.ok) {
        throw new Error(`HTTP error! Status: ${response.status}`);
      }
      // Refresh the list after deletion
      fetchStock();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const styles: Record<string, React.CSSProperties> = {
    container: {
      fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif",
      maxWidth: "800px",
      margin: "0 auto",
      padding: "20px",
    },
    header: {
      textAlign: "center",
      marginBottom: "20px",
    },
    searchContainer: {
      marginBottom: "20px",
    },
    searchInput: {
      width: "100%",
      padding: "10px",
      marginBottom: "10px",
      borderRadius: "4px",
      border: "1px solid #ccc",
      boxSizing: "border-box",
    },
    stockList: {
      display: "flex",
      flexDirection: "column",
      gap: "10px",
    },
    stockItem: {
      border: "1px solid #ddd",
      borderRadius: "8px",
      padding: "15px",
      display: "flex",
      justifyContent: "space-between",
      alignItems: "center",
    },
    stockInfo: {
      flex: "1",
    },
    stockActions: {
      display: "flex",
      gap: "10px",
    },
    deleteButton: {
      backgroundColor: "#ff4d4d",
      color: "white",
      border: "none",
      borderRadius: "4px",
      padding: "8px 12px",
      cursor: "pointer",
    },
    noResults: {
      textAlign: "center",
      padding: "20px",
      fontStyle: "italic",
    },
  };

  if (loading) {
    return (
      <div style={styles.container}>
        <h1 style={styles.header}>Poultry Stock</h1>
        <p>Loading...</p>
      </div>
    );
  }

  if (error) {
    return (
      <div style={styles.container}>
        <h1 style={styles.header}>Poultry Stock</h1>
        <p>Error: {error}</p>
      </div>
    );
  }

  return (
    <div style={styles.container}>
      <h1 style={styles.header}>Poultry Stock</h1>
      <div style={styles.searchContainer}>
        <input
          type="text"
          placeholder="Search by species or breed..."
          value={searchTerm}
          onChange={handleSearchChange}
          style={styles.searchInput}
        />
      </div>
      <div style={styles.stockList}>
        {filteredStock.length > 0 ? (
          filteredStock.map((item) => (
            <div key={item.id} style={styles.stockItem}>
              <div style={styles.stockInfo}>
                <strong>{item.species}</strong> - {item.breed} ({item.quantity})
                <br />
                Last Fed: {item.lastFed}
              </div>
              <div style={styles.stockActions}>
                <button
                  onClick={() => handleDelete(item.id)}
                  style={styles.deleteButton}
                >
                  Delete
                </button>
              </div>
            </div>
          ))
        ) : (
          <p style={styles.noResults}>No poultry stock found.</p>
        )}
      </div>
    </div>
  );
}

