import { useEffect, useState } from "react";

interface SleepEntry {
  id: number;
  date: string;
  duration: number;
  quality: number;
}

export function SleepList() {
  const [sleepEntries, setSleepEntries] = useState<SleepEntry[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [startDate, setStartDate] = useState("");
  const [endDate, setEndDate] = useState("");
  const [qualityFilter, setQualityFilter] = useState<number | "">("");

  useEffect(() => {
    fetchSleepEntries();
  }, []);

  const fetchSleepEntries = async () => {
    try {
      setLoading(true);
      const response = await fetch(`/api/sleep`);
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }
      const data = await response.json();
      setSleepEntries(data);
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const filteredEntries = sleepEntries.filter(entry => {
    const entryDate = new Date(entry.date);
    const start = startDate ? new Date(startDate) : null;
    const end = endDate ? new Date(endDate) : null;

    const dateMatch = (!start || entryDate >= start) && (!end || entryDate <= end);
    const qualityMatch = qualityFilter === "" || entry.quality === qualityFilter;

    return dateMatch && qualityMatch;
  });

  if (loading) return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;

  if (error) return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1>Sleep History</h1>

      <div style={{ marginBottom: "20px", display: "flex", flexDirection: "column", gap: "10px" }}>
        <div style={{ display: "flex", gap: "10px", flexWrap: "wrap" }}>
          <input
            type="date"
            placeholder="Start Date"
            value={startDate}
            onChange={(e) => setStartDate(e.target.value)}
            style={{ flex: "1", minWidth: "150px" }}
          />
          <input
            type="date"
            placeholder="End Date"
            value={endDate}
            onChange={(e) => setEndDate(e.target.value)}
            style={{ flex: "1", minWidth: "150px" }}
          />
          <select
            value={qualityFilter}
            onChange={(e) => setQualityFilter(e.target.value === "" ? "" : Number(e.target.value))}
            style={{ flex: "1", minWidth: "150px" }}
          >
            <option value="">All Qualities</option>
            <option value="1">1 - Poor</option>
            <option value="2">2 - Fair</option>
            <option value="3">3 - Good</option>
            <option value="4">4 - Very Good</option>
            <option value="5">5 - Excellent</option>
          </select>
        </div>

        <button 
          onClick={() => {
            setStartDate("");
            setEndDate("");
            setQualityFilter("");
          }}
          style={{ 
            backgroundColor: "#007bff", 
            color: "white", 
            border: "none", 
            borderRadius: "4px", 
            padding: "8px 16px", 
            cursor: "pointer" 
          }}
        >
          Clear Filters
        </button>
      </div>

      {filteredEntries.length === 0 ? (
        <div style={{ textAlign: "center", padding: "20px" }}>
          No sleep entries found.
        </div>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
          {filteredEntries.map(entry => (
            <div 
              key={entry.id} 
              style={{ 
                border: "1px solid #ddd", 
                borderRadius: "8px", 
                padding: "15px", 
                backgroundColor: "#f9f9f9" 
              }}
            >
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                <div>
                  <h3>{new Date(entry.date).toLocaleDateString()}</h3>
                  <p>Duration: {entry.duration} hours</p>
                  <p>Quality: {entry.quality}/5</p>
                </div>
                <div style={{ display: "flex", gap: "5px" }}>
                  <span style={{ 
                    backgroundColor: entry.quality >= 4 ? "#d4edda" : entry.quality >= 3 ? "#fff3cd" : "#f8d7da", 
                    color: entry.quality >= 4 ? "#155724" : entry.quality >= 3 ? "#856404" : "#721c24", 
                    padding: "4px 8px", 
                    borderRadius: "4px" 
                  }}>
                    {entry.quality >= 4 ? "Excellent" : entry.quality >= 3 ? "Good" : "Poor"}
                  </span>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

import { useEffect, useState } from "react";

export function Profile() {
  const [userData, setUserData] = useState<{
    name: string;
    email: string;
    sleepGoal: number;
  } | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [formData, setFormData] = useState({
    name: "",
    email: "",
    sleepGoal: 0,
  });

  useEffect(() => {
    const fetchProfile = async () => {
      try {
        const response = await fetch("/api/user/profile", {
          method: "GET",
          headers: {
            "Content-Type": "application/json",
          },
        });

        if (!response.ok) {
          throw new Error(`Failed to fetch profile: ${response.status}`);
        }

        const data = await response.json();
        setUserData(data);
        setFormData({
          name: data.name,
          email: data.email,
          sleepGoal: data.sleepGoal,
        });
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
      } finally {
        setLoading(false);
      }
    };

    fetchProfile();
  }, []);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setFormData((prev) => ({
      ...prev,
      [name]: name === "sleepGoal" ? Number(value) : value,
    }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const response = await fetch("/api/user/profile", {
        method: "PUT",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify(formData),
      });

      if (!response.ok) {
        throw new Error(`Failed to update profile: ${response.status}`);
      }

      const updatedData = await response.json();
      setUserData(updatedData);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return (
      <div style={{ textAlign: "center", padding: "20px", color: "red" }}>
        Error: {error}
      </div>
    );
  }

  if (!userData) {
    return (
      <div style={{ textAlign: "center", padding: "20px" }}>
        No profile data available.
      </div>
    );
  }

  return (
    <div
      style={{
        maxWidth: "600px",
        margin: "0 auto",
        padding: "20px",
        fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif",
      }}
    >
      <h1 style={{ textAlign: "center" }}>Profile Settings</h1>
      <form onSubmit={handleSubmit}>
        <div style={{ marginBottom: "15px" }}>
          <label htmlFor="name" style={{ display: "block", marginBottom: "5px" }}>
            Name:
          </label>
          <input
            type="text"
            id="name"
            name="name"
            value={formData.name}
            onChange={handleChange}
            style={{
              width: "100%",
              padding: "8px",
              borderRadius: "4px",
              border: "1px solid #ccc",
            }}
          />
        </div>
        <div style={{ marginBottom: "15px" }}>
          <label htmlFor="email" style={{ display: "block", marginBottom: "5px" }}>
            Email:
          </label>
          <input
            type="email"
            id="email"
            name="email"
            value={formData.email}
            onChange={handleChange}
            style={{
              width: "100%",
              padding: "8px",
              borderRadius: "4px",
              border: "1px solid #ccc",
            }}
          />
        </div>
        <div style={{ marginBottom: "15px" }}>
          <label htmlFor="sleepGoal" style={{ display: "block", marginBottom: "5px" }}>
