    { id: 1, guestName: "John Doe", rating: 5, comment: "Great experience!", hostelId: 1 },
    { id: 2, guestName: "Jane Smith", rating: 4, comment: "Good service.", hostelId: 1 }
  ]),
  getById: (id: number): Promise<any | null> => Promise.resolve(
    id === 1 ? { id: 1, guestName: "John Doe", rating: 5, comment: "Great experience!", hostelId: 1 } : null
  ),
  create: (feedback: any): Promise<any> => Promise.resolve({
    ...feedback,
    id: Date.now()
  }),
  update: (id: number, feedback: any): Promise<any | null> => Promise.resolve(
    id === 1 ? { id, ...feedback } : null
  ),
  delete: (id: number): Promise<boolean> => Promise.resolve(id === 1)
};

// GET /api/feedback - Retrieve all feedback
router.get("/", async (req: Request, res: Response) => {
  try {
    const feedback = await mockFeedbackDatabase.getAll();
    res.json(feedback);
  } catch (error) {
    res.status(500).json({ error: "Failed to retrieve feedback" });
  }
});

// GET /api/feedback/:id - Retrieve feedback by ID
router.get("/:id", async (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid feedback ID" });
  }

  try {
    const feedback = await mockFeedbackDatabase.getById(id);
    if (!feedback) {
      return res.status(404).json({ error: "Feedback not found" });
    }
    res.json(feedback);
  } catch (error) {
    res.status(500).json({ error: "Failed to retrieve feedback" });
  }
});

// POST /api/feedback - Create new feedback
router.post("/", async (req: Request, res: Response) => {
  const { guestName, rating, comment, hostelId } = req.body;

  // Validate required fields
  if (!guestName || !rating || !comment || !hostelId) {
    return res.status(400).json({ error: "Missing required fields: guestName, rating, comment, hostelId" });
  }

  // Validate rating is between 1 and 5
  if (rating < 1 || rating > 5) {
    return res.status(400).json({ error: "Rating must be between 1 and 5" });
  }

  try {
    const newFeedback = await mockFeedbackDatabase.create({
      guestName,
      rating,
      comment,
      hostelId
    });
    res.status(201).json(newFeedback);
  } catch (error) {
    res.status(500).json({ error: "Failed to create feedback" });
  }
});

// PUT /api/feedback/:id - Update feedback by ID
router.put("/:id", async (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const { guestName, rating, comment, hostelId } = req.body;

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid feedback ID" });
  }

  // Validate required fields
  if (!guestName || !rating || !comment || !hostelId) {
    return res.status(400).json({ error: "Missing required fields: guestName, rating, comment, hostelId" });
  }

  // Validate rating is between 1 and 5
  if (rating < 1 || rating > 5) {
    return res.status(400).json({ error: "Rating must be between 1 and 5" });
  }

  try {
    const updatedFeedback = await mockFeedbackDatabase.update(id, {
      guestName,
      rating,
      comment,
      hostelId
    });

    if (!updatedFeedback) {
      return res.status(404).json({ error: "Feedback not found" });
    }

    res.json(updatedFeedback);
  } catch (error) {
    res.status(500).json({ error: "Failed to update feedback" });
  }
});

// DELETE /api/feedback/:id - Delete feedback by ID
router.delete("/:id", async (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid feedback ID" });
  }

  try {
    const deleted = await mockFeedbackDatabase.delete(id);

    if (!deleted) {
      return res.status(404).json({ error: "Feedback not found" });
    }

    res.json({ message: "Feedback deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to delete feedback" });
  }
});

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

const JWT_SECRET = process.env.JWT_SECRET;

function isValidToken(token: string): boolean {
  if (!JWT_SECRET) return false;

  const parts = token.split(".");
  if (parts.length !== 3) return false;

  const [header, payload, signature] = parts;

  const expectedSignature = createHmac("sha256", JWT_SECRET)
    .update(`${header}.${payload}`)
    .digest("base64url");

  try {
    const expectedBuffer = Buffer.from(expectedSignature, "base64url");
    const actualBuffer = Buffer.from(signature, "base64url");
    return timingSafeEqual(expectedBuffer, actualBuffer);
  } catch {
    return false;
  }
}

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check role-based access for specific routes
  const isMenuRoute = req.path.startsWith("/menu") && (req.method === "POST" || req.method === "PUT" || req.method === "DELETE");
  const isFeedbackRoute = req.path.startsWith("/feedback") && req.method === "POST";

  if (!isMenuRoute && !isFeedbackRoute) {
    next();
    return;
  }

  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized: Missing or invalid authorization header" });
    return;
  }

  const token = authHeader.substring(7); // Remove "Bearer " prefix

  if (!isValidToken(token)) {
    res.status(401).json({ error: "Unauthorized: Invalid token" });
    return;
  }

  // Decode the token to extract role (simplified decoding)
  const payload = token.split(".")[1];
  const decodedPayload = Buffer.from(payload, "base64url").toString("utf-8");
  const { role } = JSON.parse(decodedPayload);

  // Check if user has required role
  if (isMenuRoute && role !== "staff") {
    res.status(403).json({ error: "Forbidden: Staff only" });
    return;
  }

  if (isFeedbackRoute && role !== "guest") {
    res.status(403).json({ error: "Forbidden: Guests only" });
    return;
  }

  next();
}

import type { Request, Response, NextFunction } from "express";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only validate POST and PUT requests to specific routes
  if ((req.method !== "POST" && req.method !== "PUT") || 
      (!req.path.startsWith("/menu") && !req.path.startsWith("/feedback"))) {
    next();
    return;
  }

  // Validate menu data
  if (req.path.startsWith("/menu")) {
    const { title, description, price, category } = req.body;

    if (!title || typeof title !== "string" || title.trim() === "") {
      return res.status(400).json({ error: "Title is required and must be a non-empty string" });
    }

    if (typeof description !== "string") {
      return res.status(400).json({ error: "Description must be a string" });
    }

    if (typeof price !== "number" || price < 0) {
      return res.status(400).json({ error: "Price must be a non-negative number" });
    }

    if (typeof category !== "string") {
      return res.status(400).json({ error: "Category must be a string" });
    }
  }

  // Validate feedback data
  if (req.path.startsWith("/feedback")) {
    const { content, rating } = req.body;

    if (!content || typeof content !== "string" || content.trim() === "") {
      return res.status(400).json({ error: "Content is required and must be a non-empty string" });
    }

    if (typeof rating !== "number" || rating < 1 || rating > 5) {
      return res.status(400).json({ error: "Rating must be a number between 1 and 5" });
    }
  }

  next();
}

