// Mock database functions - in a real implementation these would connect to a database
const mockTasks = [
  { id: 1, description: "Clean room 101", status: "pending", assignedTo: "John Doe", dueDate: "2023-05-15" },
  { id: 2, description: "Restock supplies", status: "completed", assignedTo: "Jane Smith", dueDate: "2023-05-10" }
];

const findTaskById = (id: number) => {
  return mockTasks.find(task => task.id === id);
};

const createTask = (task: Omit<Task, "id">) => {
  const newTask = {
    id: mockTasks.length > 0 ? Math.max(...mockTasks.map(t => t.id)) + 1 : 1,
    ...task
  };
  mockTasks.push(newTask);
  return newTask;
};

const updateTask = (id: number, updates: Partial<Task>) => {
  const index = mockTasks.findIndex(task => task.id === id);
  if (index === -1) return null;
  mockTasks[index] = { ...mockTasks[index], ...updates };
  return mockTasks[index];
};

const deleteTask = (id: number) => {
  const index = mockTasks.findIndex(task => task.id === id);
  if (index === -1) return false;
  mockTasks.splice(index, 1);
  return true;
};

