import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply RBAC to housekeeping task routes
  if (!req.path.startsWith("/api/housekeeping/tasks")) {
    next();
    return;
  }

  // Check HTTP method for authorization rules
  const allowedMethods = ["GET", "POST", "PUT", "DELETE"];
  if (!allowedMethods.includes(req.method)) {
    next();
    return;
  }

  // For demonstration purposes, we'll assume a simple role check
  // In a real implementation, this would extract roles from a token or session

  // Mock role extraction - in reality this would come from a verified token
  const userRole = req.headers["x-user-role"] as string || "guest";

  // Define role permissions
  const permissions: Record<string, string[]> = {
    admin: ["GET", "POST", "PUT", "DELETE"],
    supervisor: ["GET", "POST", "PUT", "DELETE"],
    staff: ["GET", "POST", "PUT"],
    guest: ["GET"]
  };

  // Check if user has permission for this action
  const userPermissions = permissions[userRole] || [];

  if (!userPermissions.includes(req.method)) {
    res.status(403).json({ error: "Forbidden: Insufficient permissions" });
    return;
  }

  next();
}

