import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply role-based access control to POST requests to /attendance
  if (req.method !== "POST" || !req.path.startsWith("/attendance")) {
    next();
    return;
  }

  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized: Missing or invalid authorization header" });
    return;
  }

  const token = authHeader.substring(7); // Remove "Bearer " prefix
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: "Internal Server Error: JWT_SECRET not configured" });
    return;
  }

  // Simple token validation - in a real app, you'd decode and verify the JWT signature
  // For this example, we'll just check if the token matches a known pattern
  const expectedSignature = createHmac("sha256", secret)
    .update(token.split(".")[0] || "")
    .digest("hex");

  const tokenSignature = token.split(".")[1] || "";

  try {
    const expectedBuffer = Buffer.from(expectedSignature, "hex");
    const actualBuffer = Buffer.from(tokenSignature, "hex");

    if (expectedBuffer.length !== actualBuffer.length ||
        !timingSafeEqual(expectedBuffer, actualBuffer)) {
      res.status(401).json({ error: "Unauthorized: Invalid token signature" });
      return;
    }
  } catch (err) {
    res.status(401).json({ error: "Unauthorized: Invalid token format" });
    return;
  }

  // Check if user has required role
  const userRole = getUserRoleFromToken(token);
  if (!userRole) {
    res.status(401).json({ error: "Unauthorized: User role not found" });
    return;
  }

  // Allow only staff members to access attendance endpoints
  if (userRole !== "staff") {
    res.status(403).json({ error: "Forbidden: Insufficient permissions" });
    return;
  }

  next();
}

function getUserRoleFromToken(token: string): string | null {
  // In a real implementation, this would decode the JWT and extract the role claim
  // For this example, we'll simulate a role extraction
  try {
    const payload = token.split(".")[1];
    if (!payload) return null;
    const decodedPayload = Buffer.from(payload, "base64").toString("utf-8");
    const parsedPayload = JSON.parse(decodedPayload);
    return parsedPayload.role || null;
  } catch {
    return null;
  }
}

