import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

const SESSION_TIMEOUT = 30 * 60 * 1000; // 30 minutes
const ACTIVE_SESSIONS = new Map<string, { expiresAt: number }>();

function isValidToken(token: string): boolean {
  const secret = process.env.JWT_SECRET;
  if (!secret) {
    return false;
  }

  try {
    const [header, payload, signature] = token.split(".");
    if (!header || !payload || !signature) {
      return false;
    }

    const expectedSignature = createHmac("sha256", secret)
      .update(`${header}.${payload}`)
      .digest("base64url");

    const signatureBuffer = Buffer.from(signature, "base64url");
    const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");

    return timingSafeEqual(signatureBuffer, expectedSignatureBuffer);
  } catch {
    return false;
  }
}

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only handle POST /login and GET /logout requests
  if (req.method === "POST" && req.path === "/login") {
    // Handle login logic
    const authHeader = req.headers.authorization;
    if (!authHeader || !authHeader.startsWith("Bearer ")) {
      return res.status(401).json({ error: "Missing or invalid authorization header" });
    }

    const token = authHeader.substring(7); // Remove "Bearer " prefix
    if (!isValidToken(token)) {
      return res.status(401).json({ error: "Invalid token" });
    }

    // Store session
    ACTIVE_SESSIONS.set(token, { expiresAt: Date.now() + SESSION_TIMEOUT });
    return res.status(200).json({ message: "Login successful" });
  }

  if (req.method === "GET" && req.path === "/logout") {
    // Handle logout logic
    const authHeader = req.headers.authorization;
    if (!authHeader || !authHeader.startsWith("Bearer ")) {
      return res.status(401).json({ error: "Missing or invalid authorization header" });
    }

    const token = authHeader.substring(7); // Remove "Bearer " prefix
    ACTIVE_SESSIONS.delete(token);
    return res.status(200).json({ message: "Logout successful" });
  }

  // For all other requests, check if session is valid
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    return res.status(401).json({ error: "Missing or invalid authorization header" });
  }

  const token = authHeader.substring(7); // Remove "Bearer " prefix
  const session = ACTIVE_SESSIONS.get(token);

  if (!session) {
    return res.status(401).json({ error: "Invalid token" });
  }

  if (Date.now() > session.expiresAt) {
    ACTIVE_SESSIONS.delete(token);
    return res.status(401).json({ error: "Session expired" });
  }

  // Refresh session timeout
  ACTIVE_SESSIONS.set(token, { expiresAt: Date.now() + SESSION_TIMEOUT });

  next();
}

