}

export function FeatureRequestListPage() {
  const [featureRequests, setFeatureRequests] = useState<FeatureRequest[]>([]);
  const [filteredRequests, setFilteredRequests] = useState<FeatureRequest[]>([]);
  const [searchTerm, setSearchTerm] = useState("");
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchFeatureRequests();
  }, []);

  const fetchFeatureRequests = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/feature-requests');
      if (!response.ok) {
        throw new Error('Failed to fetch feature requests');
      }
      const data = await response.json();
      setFeatureRequests(data);
      setFilteredRequests(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    const filtered = featureRequests.filter(request =>
      request.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
      request.description.toLowerCase().includes(searchTerm.toLowerCase())
    );
    setFilteredRequests(filtered);
  }, [searchTerm, featureRequests]);

  const handleSearchChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setSearchTerm(e.target.value);
  };

  const handleVote = async (id: number) => {
    try {
      const response = await fetch(`/api/feature-requests/${id}/vote`, {
        method: 'POST',
      });
      if (!response.ok) {
        throw new Error('Failed to vote');
