import { Router, type Request, type Response } from "express";

export const router = Router();

// In-memory storage for votes - in a real app this would be a database
const votes: Record<string, { userId: string; voteType: "up" | "down" }[]> = {};

// Get all votes for a feature
router.get("/feature/:featureId", (req: Request, res: Response) => {
  const featureId = req.params.featureId;

  if (!featureId) {
    return res.status(400).json({ error: "Feature ID is required" });
  }

  const featureVotes = votes[featureId] || [];

  // Calculate vote counts
  const upvotes = featureVotes.filter(vote => vote.voteType === "up").length;
  const downvotes = featureVotes.filter(vote => vote.voteType === "down").length;

  return res.json({
    featureId,
    upvotes,
    downvotes,
    totalVotes: featureVotes.length
  });
});

// Cast a vote for a feature
router.post("/feature/:featureId/vote", (req: Request, res: Response) => {
  const featureId = req.params.featureId;
  const { userId, voteType } = req.body;

  if (!featureId || !userId || !voteType) {
    return res.status(400).json({ error: "Feature ID, user ID, and vote type are required" });
  }

  if (voteType !== "up" && voteType !== "down") {
    return res.status(400).json({ error: "Vote type must be either 'up' or 'down'" });
  }

  if (!votes[featureId]) {
    votes[featureId] = [];
  }

  // Remove any existing vote by this user for this feature
  votes[featureId] = votes[featureId].filter(vote => vote.userId !== userId);

  // Add the new vote
  votes[featureId].push({ userId, voteType });

  return res.status(201).json({ message: "Vote recorded successfully" });
});

// Get a specific user's vote for a feature
router.get("/feature/:featureId/user/:userId", (req: Request, res: Response) => {
  const featureId = req.params.featureId;
  const userId = req.params.userId;

  if (!featureId || !userId) {
    return res.status(400).json({ error: "Feature ID and user ID are required" });
  }

  const featureVotes = votes[featureId] || [];
  const userVote = featureVotes.find(vote => vote.userId === userId);

  if (!userVote) {
    return res.status(404).json({ error: "User has not voted for this feature" });
  }

  return res.json({
    featureId,
    userId,
    voteType: userVote.voteType
  });
});

// Update a user's vote for a feature
router.put("/feature/:featureId/user/:userId", (req: Request, res: Response) => {
  const featureId = req.params.featureId;
  const userId = req.params.userId;
  const { voteType } = req.body;

  if (!featureId || !userId || !voteType) {
    return res.status(400).json({ error: "Feature ID, user ID, and vote type are required" });
  }

  if (voteType !== "up" && voteType !== "down") {
    return res.status(400).json({ error: "Vote type must be either 'up' or 'down'" });
  }

  if (!votes[featureId]) {
    votes[featureId] = [];
  }

  // Find and replace existing vote
  const voteIndex = votes[featureId].findIndex(vote => vote.userId === userId);

  if (voteIndex === -1) {
    return res.status(404).json({ error: "User has not voted for this feature" });
  }

  votes[featureId][voteIndex] = { userId, voteType };

  return res.json({ message: "Vote updated successfully" });
});

// Delete a user's vote for a feature
router.delete("/feature/:featureId/user/:userId", (req: Request, res: Response) => {
  const featureId = req.params.featureId;
  const userId = req.params.userId;

  if (!featureId || !userId) {
    return res.status(400).json({ error: "Feature ID and user ID are required" });
  }

  if (!votes[featureId]) {
    return res.status(404).json({ error: "Feature not found" });
  }

  const initialLength = votes[featureId].length;
  votes[featureId] = votes[featureId].filter(vote => vote.userId !== userId);

  if (votes[featureId].length === initialLength) {
    return res.status(404).json({ error: "User has not voted for this feature" });
  }

  return res.json({ message: "Vote deleted successfully" });
});

import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock user data - in a real app this would come from a database
const users = [
  { id: 1, username: "admin", password: "admin123", role: "admin" },
  { id: 2, username: "user1", password: "pass123", role: "user" }
];

// Mock session data - in a real app this would be stored in a session store
const sessions = new Map<string, { userId: number; role: string; expires: Date }>();

// Login endpoint
router.post("/login", (req: Request, res: Response) => {
  const { username, password } = req.body;

  if (!username || !password) {
    return res.status(400).json({ error: "Username and password are required" });
  }

  const user = users.find(u => u.username === username && u.password === password);

  if (!user) {
    return res.status(401).json({ error: "Invalid credentials" });
  }

  // Create a mock session ID
  const sessionId = Math.random().toString(36).substring(2, 15);
  const expires = new Date();
  expires.setHours(expires.getHours() + 1); // Session expires in 1 hour

  sessions.set(sessionId, {
    userId: user.id,
    role: user.role,
    expires
  });

  res.cookie("sessionId", sessionId, { httpOnly: true, maxAge: 3600000 }); // 1 hour
  res.json({ id: user.id, username: user.username, role: user.role });
});

// Logout endpoint
router.post("/logout", (req: Request, res: Response) => {
  const sessionId = req.cookies.sessionId;

  if (sessionId) {
    sessions.delete(sessionId);
    res.clearCookie("sessionId");
  }

  res.json({ message: "Logged out successfully" });
});

// Get current user endpoint
router.get("/me", (req: Request, res: Response) => {
  const sessionId = req.cookies.sessionId;

  if (!sessionId) {
    return res.status(401).json({ error: "Not authenticated" });
  }

  const session = sessions.get(sessionId);

  if (!session) {
    return res.status(401).json({ error: "Session not found" });
  }

  // Check if session has expired
  if (new Date() > session.expires) {
    sessions.delete(sessionId);
    return res.status(401).json({ error: "Session expired" });
  }

  const user = users.find(u => u.id === session.userId);

  if (!user) {
    return res.status(401).json({ error: "User not found" });
  }

  res.json({ id: user.id, username: user.username, role: user.role });
});

// Admin-only endpoint example
router.get("/admin", (req: Request, res: Response) => {
  const sessionId = req.cookies.sessionId;

  if (!sessionId) {
    return res.status(401).json({ error: "Not authenticated" });
  }

  const session = sessions.get(sessionId);

  if (!session) {
    return res.status(401).json({ error: "Session not found" });
  }

  if (session.role !== "admin") {
    return res.status(403).json({ error: "Access denied" });
  }

  res.json({ message: "Admin access granted" });
});

